func record_encounter_attempt(kind: StringName, encounter_id: int) -> int:
	var key := "%s:%d" % [String(kind), encounter_id]
	var next := mini(32_767, int(_encounter_attempts.get(key, 0)) + 1)
	_encounter_attempts[key] = next
	return next

func thief_encounter_type_flags(encounter: ThiefEncounterDefinition) -> Array[bool]:
	var key := str(encounter.id)
	if not _thief_encounter_type_flags.has(key):
		return encounter.type_flags()
	var result: Array[bool] = []
	for value: Variant in _thief_encounter_type_flags[key]:
		result.append(bool(value))
	return result

func set_thief_encounter_type_flags(encounter: ThiefEncounterDefinition, flags: Array[bool]) -> bool:
	if encounter == null or flags.size() != 10:
		return false
	_thief_encounter_type_flags[str(encounter.id)] = flags.duplicate()
	return true

func set_scenario_program_override(source_program_id: String, target_program_id: String) -> bool:
	if source_program_id.is_empty() or target_program_id.is_empty():
		return false
	_scenario_program_overrides[source_program_id] = target_program_id
	return true

func shop_quantity(shop: ShopDefinition, stock_index: int) -> int:
	var key := "%s:%d" % [shop.id, stock_index]
	return int(_shop_overrides.get(key, shop.quantity(stock_index)))

func set_shop_quantity(shop: ShopDefinition, stock_index: int, quantity: int) -> bool:
	if shop == null or stock_index < 0 or stock_index >= shop.item_ids().size():
		return false
	_shop_overrides["%s:%d" % [shop.id, stock_index]] = clampi(quantity, 0, 32_767)
	return true

func shop_buyback_quantity(shop_id: String, item_id: String) -> int:
	var shop_items: Variant = _shop_buyback_overrides.get(shop_id, {})
	return int(shop_items.get(item_id, 0)) if shop_items is Dictionary else 0

func record_journal_message(message_id: int) -> bool:
	if not journal_message_id_is_valid(message_id):
		return false
	_journal_message_ids[message_id] = true
	return true

func adjust_quest_value(quest_id: int, amount: int) -> int:
	if not set_quest_value(quest_id, quest_value(quest_id) + amount):
		return 0
	return quest_value(quest_id)

func set_quest_value(quest_id: int, value: int) -> bool:
	if quest_id < 0 or quest_id >= 100:
		return false
	_quest_values[quest_id] = clampi(value, -32_768, 32_767)
	return true

func eliminate_simple_option(encounter_id: int, option_index: int) -> bool:
	if encounter_id < 0 or option_index < 0 or option_index > 3:
		return false
	_eliminated_simple_options["%d:%d" % [encounter_id, option_index]] = true
	return true

func decay_positive() -> Array[int]:
	var expired: Array[int] = []
	for index: int in _values.size():
		if _values[index] <= 0:
			continue
		_values[index] -= 1
		if _values[index] == 0:
			expired.append(index)
	return expired

static func from_data(data: Variant, expected_count: int = 0) -> ConditionSet:
	if not data is Dictionary or not data.has("count") or not data.has("values"):
		return null
	var count := _integer(data["count"])
	if count < 1 or (expected_count > 0 and count != expected_count) or not data["values"] is Array or data["values"].size() != count:
		return null
	var result := ConditionSet.new(count)
	for index: int in count:
		var amount := _signed_integer(data["values"][index])
		if amount < -32_768 or amount > 32_767:
			return null
		result._values[index] = amount
	return result

static func _integer(input: Variant) -> int:
	if input is int:
		return input
	if input is float and is_equal_approx(input, round(input)):
		return int(input)
	return -1

static func _signed_integer(input: Variant) -> int:
	if input is int:
		return input
	if input is float and is_equal_approx(input, round(input)):
		return int(input)
	return -100_000

func rollback_instance_ids(checkpoint: int) -> bool:
	if checkpoint < 0 or checkpoint > _instance_counter:
		return false
	_instance_counter = checkpoint
	return true

func journal_message_ids() -> Array[int]:
	var result: Array[int] = []
	for value: Variant in _journal_message_ids.keys():
		result.append(int(value))
	result.sort()
	return result

func set_selected_character_ids(ids: Array[String]) -> bool:
	var known: Dictionary = {}
	for character: CharacterState in party.characters():
		known[character.id] = true
	var unique: Array[String] = []
	for id: String in ids:
		if not known.has(id) or unique.has(id):
			return false
		unique.append(id)
	_selected_character_ids = unique
	return true

func selected_characters(living_only: bool = false) -> Array[CharacterState]:
	var result: Array[CharacterState] = []
	for id: String in _selected_character_ids:
		var character := party.character_by_id(id)
		if character != null and (not living_only or character.current_health > 0):
			result.append(character)
	return result

func next_instance_id(prefix: String) -> String:
	_instance_counter += 1
	return "%s.%d" % [prefix, _instance_counter]

static func from_data(data: Variant) -> CombatReactionState:
	if not data is Dictionary or data.size() not in [10, 11]:
		return null
	if data.size() == 11 and not data.has("autoSwitchToMelee"):
		return null
	for field: String in ["kind", "moverId", "origin", "destination", "movementCost", "phase", "attackerIds", "originHostileIds", "nextAttackerIndex", "moverKilled"]:
		if not data.has(field):
			return null
	if not data["kind"] is String or data["kind"] not in [String(CHARACTER_MOVE), String(MONSTER_MOVE), String(MONSTER_RETREAT), String(MONSTER_CONTACT)] or not data["moverId"] is String or data["moverId"].is_empty() or not data["phase"] is String or data["phase"] not in [String(GUARD_BEFORE), String(WITHDRAWAL), String(GUARD_AFTER)] or not data["attackerIds"] is Array or not data["originHostileIds"] is Array or not data["moverKilled"] is bool:
		return null
	if data.has("autoSwitchToMelee") and not data["autoSwitchToMelee"] is bool:
		return null
	var auto_switch: bool = bool(data.get("autoSwitchToMelee", false))
	if auto_switch and (data["kind"] != String(CHARACTER_MOVE) or data["phase"] != String(GUARD_BEFORE)):
		return null
	var source_origin := _coordinate(data["origin"])
	var source_destination := _coordinate(data["destination"])
	var cost := _integer(data["movementCost"])
	var attacker_index := _integer(data["nextAttackerIndex"])
	var stationary_contact: bool = data["kind"] == String(MONSTER_CONTACT) and source_destination == source_origin
	if source_origin.x < 0 or source_destination.x < 0 or absi(source_destination.x - source_origin.x) > 1 or absi(source_destination.y - source_origin.y) > 1 or (source_destination == source_origin and not stationary_contact) or (stationary_contact and cost != 0) or cost < 0 or attacker_index < 0 or attacker_index > data["attackerIds"].size():
		return null
	if data["kind"] == String(MONSTER_CONTACT) and data["phase"] != String(GUARD_AFTER):
		return null
	if data["kind"] in [String(MONSTER_MOVE), String(MONSTER_RETREAT)] and data["phase"] not in [String(WITHDRAWAL), String(GUARD_AFTER)]:
		return null
	if data["kind"] not in [String(CHARACTER_MOVE), String(MONSTER_RETREAT)] and not data["originHostileIds"].is_empty():
		return null
	var attacker_ids: Array[String] = []
	var seen: Dictionary = {}
	for entry: Variant in data["attackerIds"]:
		if not entry is String or entry.is_empty() or entry == data["moverId"] or seen.has(entry):
			return null
		seen[entry] = true
		attacker_ids.append(entry)
	var origin_hostile_ids: Array[String] = []
	var hostile_seen: Dictionary = {}
	for entry: Variant in data["originHostileIds"]:
		if not entry is String or entry.is_empty() or entry == data["moverId"] or hostile_seen.has(entry):
			return null
		hostile_seen[entry] = true
		origin_hostile_ids.append(entry)
	var result := CombatReactionState.new(StringName(data["kind"]), data["moverId"], source_origin, source_destination, cost)
	result.phase = StringName(data["phase"])
	result._attacker_ids = attacker_ids
	result._origin_hostile_ids = origin_hostile_ids
	result.next_attacker_index = attacker_index
	result.mover_killed = data["moverKilled"]
	result.auto_switch_to_melee = auto_switch
	return result

func add_monster(monster: MonsterState) -> bool:
	if monster == null or monster_by_id(monster.id) != null:
		return false
	_monsters.append(monster)
	return true

func queue_fumbled_item(item: ItemInstance) -> bool:
	if item == null or not can_queue_fumbled_item():
		return false
	for queued: ItemInstance in _fumbled_items:
		if queued.id == item.id:
			return false
	item.equipped = false
	_fumbled_items.append(item)
	return true

func requeue_fumbled_item_first(item: ItemInstance) -> bool:
	if item == null or not can_queue_fumbled_item():
		return false
	for queued: ItemInstance in _fumbled_items:
		if queued.id == item.id:
			return false
	item.equipped = false
	_fumbled_items.push_front(item)
	return true

func remove_fumbled_item(instance_id: String) -> ItemInstance:
	for index: int in _fumbled_items.size():
		if _fumbled_items[index].id == instance_id:
			return _fumbled_items.pop_at(index)
	return null

func delay_active_actor() -> bool:
	if _turn_order.is_empty() or turn_index < 0 or turn_index >= _turn_order.size():
		return false
	active_turn = null
	undo_state = null
	if turn_index >= _turn_order.size() - 1:
		turn_index = 0
		round_number += 1
		_attacked_actor_ids.clear()
		return true
	var actor_id: String = _turn_order.pop_at(turn_index)
	_turn_order.append(actor_id)
	return false

func monster_by_id(monster_id: String) -> MonsterState:
	for monster: MonsterState in _monsters:
		if monster.id == monster_id:
			return monster
	return null

static func _coordinate(value: Variant) -> Vector2i:
	if not value is Array or value.size() != 2:
		return Vector2i(-1, -1)
	var x := _integer(value[0])
	var y := _integer(value[1])
	if x < 0 or x >= BattlefieldState.SIZE or y < 0 or y >= BattlefieldState.SIZE:
		return Vector2i(-1, -1)
	return Vector2i(x, y)

static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -100_000

func set_value(index: int, amount: int) -> bool:
	if index < 0 or index >= _values.size():
		return false
	_values[index] = clampi(amount, -32_768, 32_767)
	return true

static func from_data(data: Variant) -> BattlefieldState:
	if not data is Dictionary:
		return null
	for field: String in ["mapId", "sourceOrigin", "mapShift", "partyAnchor", "directionDegrees", "rolledDistance", "terrainTiles", "characterPositions", "monsterPositions", "monsterSizes"]:
		if not data.has(field):
			return null
	if not data["mapId"] is String or data["mapId"].is_empty() or not data["terrainTiles"] is Array or data["terrainTiles"].size() != CELL_COUNT:
		return null
	var origin := _parse_vector(data["sourceOrigin"])
	var shift := _parse_vector(data["mapShift"])
	var anchor := _parse_vector(data["partyAnchor"])
	var direction := _integer(data["directionDegrees"])
	var distance := _signed_integer(data["rolledDistance"])
	if origin == Vector2i(-100_000, -100_000) or shift == Vector2i(-100_000, -100_000) or anchor == Vector2i(-100_000, -100_000) or direction < 0 or direction > 360 or distance == -100_000:
		return null
	var tiles: Array[int] = []
	for value: Variant in data["terrainTiles"]:
		var tile := _integer(value)
		if tile < 0 or tile > 400:
			return null
		tiles.append(tile)
	var result := BattlefieldState.new(data["mapId"], tiles, origin, shift)
	if anchor != result.party_anchor:
		return null
	result.direction_degrees = direction
	result.rolled_distance = distance
	var characters: Variant = _parse_positions(data["characterPositions"])
	var monsters: Variant = _parse_positions(data["monsterPositions"])
	if characters == null or monsters == null or not data["monsterSizes"] is Dictionary:
		return null
	result._character_positions = characters
	result._monster_positions = monsters
	for actor_id: Variant in data["monsterSizes"]:
		var size := _integer(data["monsterSizes"][actor_id])
		if not actor_id is String or actor_id.is_empty() or not result._monster_positions.has(actor_id) or size < 0 or size > 3:
			return null
		result._monster_sizes[actor_id] = size
	if result._monster_sizes.size() != result._monster_positions.size() or not result._placements_are_valid():
		return null
	return result

static func footprint_cells(anchor: Vector2i, size: int) -> Array[Vector2i]:
	var result: Array[Vector2i] = [anchor]
	if size == 1 or size == 3:
		result.append(anchor + Vector2i.UP)
	if size > 1:
		result.append(anchor + Vector2i.LEFT)
	if size == 3:
		result.append(anchor + Vector2i(-1, -1))
	return result

func _placements_are_valid() -> bool:
	var occupied: Dictionary = {}
	for actor_id: Variant in _character_positions:
		if _monster_positions.has(actor_id):
			return false
		var coordinate := _coordinate(_character_positions[actor_id])
		if not contains(coordinate) or occupied.has(coordinate):
			return false
		occupied[coordinate] = true
	for actor_id: Variant in _monster_positions:
		var anchor := _coordinate(_monster_positions[actor_id])
		for coordinate: Vector2i in footprint_cells(anchor, int(_monster_sizes[actor_id])):
			if not contains(coordinate) or occupied.has(coordinate):
				return false
			occupied[coordinate] = true
	return true

static func _positions_data(source: Dictionary) -> Dictionary:
	var result: Dictionary = {}
	var ids: Array = source.keys()
	ids.sort()
	for actor_id: Variant in ids:
		result[String(actor_id)] = _vector_data(_coordinate(source[actor_id]))
	return result

static func _parse_positions(value: Variant) -> Variant:
	if not value is Dictionary:
		return null
	var result: Dictionary = {}
	for actor_id: Variant in value:
		var coordinate := _parse_vector(value[actor_id])
		if not actor_id is String or actor_id.is_empty() or coordinate == Vector2i(-100_000, -100_000) or result.has(actor_id):
			return null
		result[actor_id] = coordinate
	return result

static func _parse_vector(value: Variant) -> Vector2i:
	if not value is Array or value.size() != 2:
		return Vector2i(-100_000, -100_000)
	var x := _signed_integer(value[0])
	var y := _signed_integer(value[1])
	return Vector2i(-100_000, -100_000) if x == -100_000 or y == -100_000 else Vector2i(x, y)

static func _sorted_dictionary(source: Dictionary) -> Dictionary:
	var result: Dictionary = {}
	var keys: Array = source.keys()
	keys.sort()
	for key: Variant in keys:
		result[key] = source[key]
	return result

func actor_position(actor_id: String) -> Vector2i:
	if _character_positions.has(actor_id):
		return _coordinate(_character_positions[actor_id])
	return _coordinate(_monster_positions.get(actor_id))

func actor_ids() -> Array[String]:
	var result: Array[String] = []
	for actor_id: Variant in _character_positions:
		result.append(String(actor_id))
	for actor_id: Variant in _monster_positions:
		result.append(String(actor_id))
	result.sort()
	return result

func is_occupied(coordinate: Vector2i) -> bool:
	for value: Variant in _character_positions.values():
		if value == coordinate:
			return true
	for actor_id: Variant in _monster_positions:
		var anchor := _coordinate(_monster_positions[actor_id])
		for cell: Vector2i in footprint_cells(anchor, int(_monster_sizes.get(actor_id, 0))):
			if cell == coordinate:
				return true
	return false

static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

func actor_footprint_at(actor_id: String, anchor: Vector2i) -> Array[Vector2i]:
	var size := actor_size(actor_id)
	var result: Array[Vector2i] = []
	if size >= 0 and anchor.x >= 0:
		result = footprint_cells(anchor, size)
	return result

func actor_at(coordinate: Vector2i, excluding_actor_id: String = "") -> String:
	for actor_id: Variant in _character_positions:
		if actor_id != excluding_actor_id and _coordinate(_character_positions[actor_id]) == coordinate:
			return String(actor_id)
	for actor_id: Variant in _monster_positions:
		if actor_id == excluding_actor_id:
			continue
		if footprint_cells(_coordinate(_monster_positions[actor_id]), int(_monster_sizes.get(actor_id, 0))).has(coordinate):
			return String(actor_id)
	return ""

func place_character(actor_id: String, coordinate: Vector2i) -> bool:
	if actor_id.is_empty() or not contains(coordinate) or is_occupied(coordinate):
		return false
	_character_positions[actor_id] = coordinate
	return true

func place_monster(actor_id: String, coordinate: Vector2i, size: int) -> bool:
	if actor_id.is_empty() or size < 0 or size > 3:
		return false
	for cell: Vector2i in footprint_cells(coordinate, size):
		if not contains(cell) or is_occupied(cell):
			return false
	_monster_positions[actor_id] = coordinate
	_monster_sizes[actor_id] = size
	return true

func remove_monster(actor_id: String) -> void:
	_monster_positions.erase(actor_id)
	_monster_sizes.erase(actor_id)

func move_actor(actor_id: String, destination: Vector2i) -> bool:
	if not has_actor(actor_id):
		return false
	for coordinate: Vector2i in actor_footprint_at(actor_id, destination):
		if not contains(coordinate) or not actor_at(coordinate, actor_id).is_empty():
			return false
	if _character_positions.has(actor_id):
		_character_positions[actor_id] = destination
	else:
		_monster_positions[actor_id] = destination
	return true

func _init(binding_spell_id: String = "", power_level: int = 0) -> void:
	spell_id = binding_spell_id
	power = power_level

func to_data() -> Dictionary:
	return {
		"actorId": actor_id,
		"startPosition": [start_position.x, start_position.y],
		"round": round_number,
		"turnIndex": turn_index,
		"available": available,
	}

func _init(count: int = CHARACTER_COUNT) -> void:
	_values.resize(maxi(1, count))
	_values.fill(0)

func set_terrain(coordinate: Vector2i, tile: int) -> bool:
	if not contains(coordinate) or tile < 0 or tile > 400:
		return false
	_terrain_tiles[coordinate.y * SIZE + coordinate.x] = tile
	return true

static func from_data(data: Variant) -> FastSpellBindingState:
	if not data is Dictionary or data.size() != 2 or not data.get("spellId") is String:
		return null
	var parsed_power := _integer(data.get("power"))
	var parsed_spell_id: String = data["spellId"]
	if parsed_power < 0 or parsed_power > 7:
		return null
	if parsed_power == 0 and not parsed_spell_id.is_empty() or parsed_power > 0 and parsed_spell_id.is_empty():
		return null
	return FastSpellBindingState.new(parsed_spell_id, parsed_power)

static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

func take_next_attacker() -> String:
	if not has_next_attacker():
		return ""
	var result := _attacker_ids[next_attacker_index]
	next_attacker_index += 1
	return result

param()

$ErrorActionPreference = "Stop"
$toolRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$repoRoot = Split-Path -Parent (Split-Path -Parent $toolRoot)
$destinationRoot = Join-Path $repoRoot "src/presentation/assets/fonts"
$stagingRoot = Join-Path ([IO.Path]::GetTempPath()) ("realmz2-fonts-" + [Guid]::NewGuid().ToString("N"))
$googleFontsCommit = "2d85e20401920891efb7cd6272d6339685df2820"
$baseUri = "https://raw.githubusercontent.com/google/fonts/$googleFontsCommit/ofl"
$files = @(
    @{ Id = "font.narrative.alegreya.variable"; Uri = "$baseUri/alegreya/Alegreya%5Bwght%5D.ttf"; Target = "Alegreya-Variable.ttf"; License = "OFL-1.1" },
    @{ Id = "font.ui.alegreya_sans.regular"; Uri = "$baseUri/alegreyasans/AlegreyaSans-Regular.ttf"; Target = "AlegreyaSans-Regular.ttf"; License = "OFL-1.1" },
    @{ Id = "font.ui.alegreya_sans.bold"; Uri = "$baseUri/alegreyasans/AlegreyaSans-Bold.ttf"; Target = "AlegreyaSans-Bold.ttf"; License = "OFL-1.1" },
    @{ Id = "license.alegreya"; Uri = "$baseUri/alegreya/OFL.txt"; Target = "licenses/Alegreya-OFL.txt"; License = "OFL-1.1" },
    @{ Id = "license.alegreya_sans"; Uri = "$baseUri/alegreyasans/OFL.txt"; Target = "licenses/AlegreyaSans-OFL.txt"; License = "OFL-1.1" }
)
New-Item -ItemType Directory -Path $stagingRoot | Out-Null

try {
    $records = @()
    foreach ($definition in $files) {
        $target = Join-Path $stagingRoot ($definition.Target -replace "/", [IO.Path]::DirectorySeparatorChar)
        New-Item -ItemType Directory -Path (Split-Path -Parent $target) -Force | Out-Null
        Invoke-WebRequest -UseBasicParsing -Headers @{ "User-Agent" = "Realmz2-asset-sync" } -Uri $definition.Uri -OutFile $target
        if ((Get-Item -LiteralPath $target).Length -eq 0) {
            throw "Downloaded font asset is empty: $($definition.Target)"
        }
        $records += [ordered]@{
            id = $definition.Id
            path = "res://src/presentation/assets/fonts/$($definition.Target)"
            source_repository = "google/fonts"
            source_commit = $googleFontsCommit
            sha256 = (Get-FileHash -Algorithm SHA256 -LiteralPath $target).Hash.ToLowerInvariant()
            license = $definition.License
        }
    }
    $manifest = [ordered]@{
        schema_version = 1
        source_repository = "google/fonts"
        source_commit = $googleFontsCommit
        runtime_network_dependency = $false
        assets = $records
    }
    [IO.File]::WriteAllText(
        (Join-Path $stagingRoot "font-assets.json"),
        (($manifest | ConvertTo-Json -Depth 5) + [Environment]::NewLine),
        [Text.UTF8Encoding]::new($false)
    )

    New-Item -ItemType Directory -Path $destinationRoot -Force | Out-Null
    Copy-Item -Path (Join-Path $stagingRoot "*") -Destination $destinationRoot -Recurse -Force
    Write-Host "Bundled Alegreya fonts and OFL licenses from google/fonts $googleFontsCommit."
}
finally {
    if (Test-Path -LiteralPath $stagingRoot) {
        Remove-Item -LiteralPath $stagingRoot -Recurse -Force
    }
}

$ErrorActionPreference = "Stop"

$toolRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$repoRoot = Split-Path -Parent (Split-Path -Parent $toolRoot)
$manifestPath = Join-Path $repoRoot "src/presentation/assets/classic-application-media.json"
if (-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)) {
    throw "Classic application media manifest is missing"
}
$manifest = Get-Content -Raw -LiteralPath $manifestPath | ConvertFrom-Json
if ($manifest.schema_version -ne 1 -or $manifest.lookup -ne "scenario-first-application-fallback") {
    throw "Classic application media manifest contract is unsupported"
}
if ($manifest.source_commit -ne "491816ad60037394f92c428e99c004494d3c28b3" -or $manifest.license -ne "CC-BY-NC-SA-4.0" -or [string]::IsNullOrWhiteSpace($manifest.copyright) -or [string]::IsNullOrWhiteSpace($manifest.modification)) {
    throw "Classic application media provenance or license metadata is incomplete"
}
$ids = @{}
$keys = @{}
foreach ($asset in $manifest.assets) {
    if ($ids.ContainsKey($asset.id)) {
        throw "Duplicate application media asset ID: $($asset.id)"
