    $match = [regex]::Match($text, 'const\s+ROUTES:[\s\S]*?\n\]')
    Assert-Condition $match.Success "Could not find ROUTES in $Path."
    return @([regex]::Matches($match.Value, '"id":\s*&"([a-z-]+)"') | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique)
}

