class_name MapTopology
extends RefCounted

var width: int
var height: int
var _cells: Array[MapCell]
var _cells_by_coordinate: Dictionary = {}


func _init(map_width: int, map_height: int, map_cells: Array[MapCell]) -> void:
	width = map_width
	height = map_height
	_cells = map_cells.duplicate()
	for cell: MapCell in _cells:
		_cells_by_coordinate[cell.coordinate] = cell


func contains(coordinate: Vector2i) -> bool:
	return coordinate.x >= 0 and coordinate.y >= 0 and coordinate.x < width and coordinate.y < height


func cell_at(coordinate: Vector2i) -> MapCell:
	return _cells_by_coordinate.get(coordinate) as MapCell


func cells() -> Array[MapCell]:
	return _cells.duplicate()


func probe_entry(coordinate: Vector2i, move_direction: Vector2i, world_state: WorldState) -> TopologyMoveResult:
	var cell_probe := probe_land_entry(coordinate, world_state)
	if not cell_probe.allowed:
		return cell_probe
	var cell := cell_probe.target_cell
	var entry_direction_name := direction_name(move_direction)
	if not is_cardinal_direction(move_direction):
		return TopologyMoveResult.blocked(&"invalid_direction")
	var edge := cell.edge(entry_direction_name)
	if edge == null or not edge.passable:
		return TopologyMoveResult.blocked(&"edge_blocked")
	return TopologyMoveResult.permitted(cell, edge.door_id, edge.secret_id)


func probe_land_entry(coordinate: Vector2i, world_state: WorldState) -> TopologyMoveResult:
	var cell := cell_at(coordinate)
	if cell == null:
		return TopologyMoveResult.blocked(&"outside_map")
	if not cell.passable:
		return TopologyMoveResult.blocked(&"terrain_blocked", cell)
	var cell_secret := cell.feature_by_kind(&"secret")
	if cell_secret != null and cell_secret.orientation.is_empty() and not world_state.secret_is_discovered(cell_secret.id, cell_secret.initial_state == &"revealed"):
		return TopologyMoveResult.blocked(&"secret_hidden", cell)
	return TopologyMoveResult.permitted(cell)


func probe_movement(coordinate: Vector2i, move_direction: Vector2i, world_state: WorldState, level_type: StringName) -> TopologyMoveResult:
	if level_type == &"land":
		if not is_cardinal_direction(move_direction) and not is_diagonal_direction(move_direction):
			return TopologyMoveResult.blocked(&"invalid_direction")
		return probe_land_entry(coordinate, world_state)
	if not is_cardinal_direction(move_direction):
		return TopologyMoveResult.blocked(&"invalid_direction")
	return probe_entry(coordinate, move_direction, world_state)


func has_line_of_sight(from: Vector2i, to: Vector2i, world_state: WorldState) -> bool:
	if not contains(from) or not contains(to):
		return false
	var x := from.x
	var y := from.y
	var dx := absi(to.x - from.x)
	var dy := -absi(to.y - from.y)
	var step_x := 1 if from.x < to.x else -1
	var step_y := 1 if from.y < to.y else -1
	var error := dx + dy
	while x != to.x or y != to.y:
		var twice_error := 2 * error
		if twice_error >= dy:
			error += dy
			x += step_x
		if twice_error <= dx:
			error += dx
			y += step_y
		var cell := cell_at(Vector2i(x, y))
		if cell == null:
			return false
		if Vector2i(x, y) != to and _cell_blocks_los(cell, world_state):
			return false
	return true


func visible_cells(origin: Vector2i, radius: int, world_state: WorldState, use_los: bool) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	for cell: MapCell in _cells:
		if not use_los or origin.distance_squared_to(cell.coordinate) <= radius * radius and has_line_of_sight(origin, cell.coordinate, world_state):
			result.append(cell.coordinate)
	return result


func find_path(origin: Vector2i, destination: Vector2i, world_state: WorldState, level_type: StringName) -> Array[Vector2i]:
	if not contains(origin) or not contains(destination):
		return []
	if origin == destination:
		return []
	var frontier: Array[Vector2i] = [origin]
	var frontier_index := 0
	var previous: Dictionary = {origin: origin}
	var directions := land_directions() if level_type == &"land" else cardinal_directions()
	while frontier_index < frontier.size():
		var current := frontier[frontier_index]
		frontier_index += 1
		for move_direction: Vector2i in directions:
			var neighbor := current + move_direction
			if not contains(neighbor) or previous.has(neighbor):
				continue
			if not probe_movement(neighbor, move_direction, world_state, level_type).allowed:
				continue
			previous[neighbor] = current
			if neighbor == destination:
				return _reconstruct_path(origin, destination, previous)
			frontier.append(neighbor)
	return []


static func direction_name(direction: Vector2i) -> StringName:
	match direction:
		Vector2i.UP:
			return &"north"
		Vector2i.RIGHT:
			return &"east"
		Vector2i.DOWN:
			return &"south"
		Vector2i.LEFT:
			return &"west"
		Vector2i(-1, -1):
			return &"northwest"
		Vector2i(1, -1):
			return &"northeast"
		Vector2i(-1, 1):
			return &"southwest"
		Vector2i(1, 1):
			return &"southeast"
		_:
			return &""


static func is_cardinal_direction(direction: Vector2i) -> bool:
	return direction in [Vector2i.UP, Vector2i.RIGHT, Vector2i.DOWN, Vector2i.LEFT]


static func is_diagonal_direction(direction: Vector2i) -> bool:
	return absi(direction.x) == 1 and absi(direction.y) == 1


static func cardinal_directions() -> Array[Vector2i]:
	return [Vector2i.UP, Vector2i.RIGHT, Vector2i.DOWN, Vector2i.LEFT]


static func land_directions() -> Array[Vector2i]:
	return [Vector2i.UP, Vector2i(1, -1), Vector2i.RIGHT, Vector2i(1, 1), Vector2i.DOWN, Vector2i(-1, 1), Vector2i.LEFT, Vector2i(-1, -1)]


static func _cell_blocks_los(cell: MapCell, world_state: WorldState) -> bool:
	if not cell.blocks_los:
		return false
	for feature: MapFeature in cell.features():
		if feature.kind == &"door" and world_state.door_is_open(feature.id, feature.initial_state == &"open"):
			return false
		if feature.kind == &"secret" and world_state.secret_is_discovered(feature.id, feature.initial_state == &"revealed"):
			return false
	return true


static func _reconstruct_path(origin: Vector2i, destination: Vector2i, previous: Dictionary) -> Array[Vector2i]:
	var path: Array[Vector2i] = []
	var cursor := destination
	while cursor != origin:
		path.append(cursor)
		cursor = previous[cursor]
	path.reverse()
	return path

class_name WorldDefinition
extends RefCounted

var _maps_by_id: Dictionary = {}
var _transitions_by_source: Dictionary = {}
var _battle_terrain_sets: Dictionary = {}
var _player_maps_by_id: Dictionary = {}
var _player_maps_by_classic_id: Dictionary = {}


func _init(world_maps: Array[MapDefinition], transitions: Array[MapTransition] = [], battle_terrain_sets: Array[BattleTerrainSetDefinition] = [], player_map_definitions: Array[PlayerMapDefinition] = []) -> void:
	for map_definition: MapDefinition in world_maps:
		_maps_by_id[map_definition.id] = map_definition
	for transition: MapTransition in transitions:
		_transitions_by_source[_transition_key(transition.source_map_id, transition.source_edge)] = transition
	for terrain_set: BattleTerrainSetDefinition in battle_terrain_sets:
		_battle_terrain_sets[terrain_set.id] = terrain_set
	for player_map: PlayerMapDefinition in player_map_definitions:
		_player_maps_by_id[player_map.id] = player_map
		_player_maps_by_classic_id[player_map.classic_id] = player_map


func map_by_id(map_id: String) -> MapDefinition:
	return _maps_by_id.get(map_id) as MapDefinition


func map_ids() -> Array[String]:
	var ids: Array[String] = []
	for map_id: Variant in _maps_by_id.keys():
		ids.append(String(map_id))
	ids.sort()
	return ids


func map_by_type_and_index(level_type: StringName, level_index: int) -> MapDefinition:
	for value: Variant in _maps_by_id.values():
		var map := value as MapDefinition
		if map.level_type == level_type and map.level_index == level_index:
			return map
	return null


func battle_terrain_set_by_id(definition_id: String) -> BattleTerrainSetDefinition:
	return _battle_terrain_sets.get(definition_id) as BattleTerrainSetDefinition


func player_map_by_id(definition_id: String) -> PlayerMapDefinition:
	return _player_maps_by_id.get(definition_id) as PlayerMapDefinition


func player_map_by_classic_id(classic_id: int) -> PlayerMapDefinition:
	return _player_maps_by_classic_id.get(classic_id) as PlayerMapDefinition


func player_maps() -> Array[PlayerMapDefinition]:
	var result: Array[PlayerMapDefinition] = []
	for value: Variant in _player_maps_by_classic_id.values():
		result.append(value as PlayerMapDefinition)
	result.sort_custom(func(left: PlayerMapDefinition, right: PlayerMapDefinition) -> bool: return left.classic_id < right.classic_id)
	return result


func transition_from(map_id: String, edge: StringName) -> MapTransition:
	return _transitions_by_source.get(_transition_key(map_id, edge)) as MapTransition


func transition_target_coordinate(transition: MapTransition, source_coordinate: Vector2i) -> Vector2i:
	var target_map := map_by_id(transition.target_map_id)
	if target_map == null:
		return Vector2i(-1, -1)
	match transition.target_edge:
		&"north":
			return Vector2i(clampi(source_coordinate.x, 0, target_map.topology.width - 1), 0)
		&"east":
			return Vector2i(target_map.topology.width - 1, clampi(source_coordinate.y, 0, target_map.topology.height - 1))
		&"south":
			return Vector2i(clampi(source_coordinate.x, 0, target_map.topology.width - 1), target_map.topology.height - 1)
		&"west":
			return Vector2i(0, clampi(source_coordinate.y, 0, target_map.topology.height - 1))
		&"northwest":
			return Vector2i.ZERO
		&"northeast":
			return Vector2i(target_map.topology.width - 1, 0)
		&"southeast":
			return Vector2i(target_map.topology.width - 1, target_map.topology.height - 1)
		&"southwest":
			return Vector2i(0, target_map.topology.height - 1)
		_:
			return Vector2i(-1, -1)


func probe_movement(map_id: String, origin: Vector2i, direction: Vector2i, world_state: WorldState) -> WorldMovementResult:
	var source_map := map_by_id(map_id)
	if source_map == null:
		return WorldMovementResult.blocked(&"outside_map")
	if source_map.level_type == &"land":
		if not MapTopology.is_cardinal_direction(direction) and not MapTopology.is_diagonal_direction(direction):
			return WorldMovementResult.blocked(&"invalid_direction", source_map)
	elif not MapTopology.is_cardinal_direction(direction):
		return WorldMovementResult.blocked(&"invalid_direction", source_map)
	var target_map := source_map
	var target_coordinate := origin + direction
	var transition: MapTransition = null
	if not source_map.topology.contains(target_coordinate):
		var crossing := Vector2i(
			-1 if target_coordinate.x < 0 else (1 if target_coordinate.x >= source_map.topology.width else 0),
			-1 if target_coordinate.y < 0 else (1 if target_coordinate.y >= source_map.topology.height else 0)
		)
		transition = transition_from(source_map.id, MapTopology.direction_name(crossing))
		if transition == null:
			return WorldMovementResult.blocked(&"map_boundary", source_map)
		target_map = map_by_id(transition.target_map_id)
		if target_map == null:
			return WorldMovementResult.blocked(&"outside_map", source_map)
		target_coordinate = transition_target_coordinate(transition, target_coordinate)
	var topology_result := target_map.topology.probe_movement(target_coordinate, direction, world_state, source_map.level_type)
	if not topology_result.allowed:
		return WorldMovementResult.blocked(topology_result.reason, source_map, target_map, target_coordinate, topology_result)
	return WorldMovementResult.permitted(source_map, target_map, target_coordinate, transition, topology_result)


static func _transition_key(map_id: String, edge: StringName) -> String:
	return "%s:%s" % [map_id, String(edge)]

