class_name GameSessionController
extends Node

signal step_committed(step: SessionStep)

var _session: GameSession = GameSession.new()
var _current_view: GameView = _session.view()


func session() -> GameSession:
	return _session


func view() -> GameView:
	return _current_view


func replace_session(replacement: GameSession) -> void:
	assert(replacement != null, "A session replacement is required")
	_session = replacement
	_current_view = _session.view()


func start(content: RealmzContent, initial_seed: int) -> SessionStep:
	var replacement := GameSession.new()
	var step := replacement.start(content, initial_seed)
	if step.state != SessionStep.State.FAILED:
		replace_session(replacement)
	step_committed.emit(step)
	return step


func restore(content: RealmzContent, envelope: SaveEnvelope) -> SessionStep:
	var replacement := GameSession.new()
	var step := replacement.restore(content, envelope)
	if step.state != SessionStep.State.FAILED:
		replace_session(replacement)
	step_committed.emit(step)
	return step


func close() -> SessionStep:
	var step := _session.close()
	_current_view = _session.view()
	step_committed.emit(step)
	return step


func submit_intent(intent: PlayerIntent) -> SessionStep:
	var step: SessionStep = _session.submit_intent(intent)
	_current_view = _session.view()
	step_committed.emit(step)
	return step


func respond(response: InteractionResponse) -> SessionStep:
	var step: SessionStep = _session.respond(response)
	_current_view = _session.view()
	step_committed.emit(step)
	return step

extends RefCounted

const END_ADVENTURE_REQUEST_ID := "host.lifecycle.end-adventure"
const QUIT_APPLICATION_REQUEST_ID := "host.lifecycle.quit-application"
const SAVE_AND_END: StringName = &"save-and-end"
const END_WITHOUT_SAVING: StringName = &"end-without-saving"
const SAVE_AND_QUIT: StringName = &"save-and-quit"
const QUIT_WITHOUT_SAVING: StringName = &"quit-without-saving"
const CANCEL: StringName = &"cancel"


static func end_adventure_request(in_combat: bool) -> InteractionRequest:
	var options: Array[Dictionary] = []
	if not in_combat:
		options.append({"action": SAVE_AND_END, "label": "Save and end adventure"})
	options.append({"action": END_WITHOUT_SAVING, "label": "End adventure without saving"})
	options.append({"action": CANCEL, "label": "Cancel"})
	return InteractionRequest.new(END_ADVENTURE_REQUEST_ID, InteractionRequest.SESSION_LIFECYCLE, {
		"operation": "end-adventure",
		"prompt": "End the active adventure?",
		"inCombat": in_combat,
		"options": options,
	})


static func quit_application_request(has_active_session: bool, in_combat: bool) -> InteractionRequest:
	var options: Array[Dictionary] = []
	if has_active_session and not in_combat:
		options.append({"action": SAVE_AND_QUIT, "label": "Save and quit Realmz 2"})
	options.append({"action": QUIT_WITHOUT_SAVING, "label": "Quit Realmz 2"})
	options.append({"action": CANCEL, "label": "Cancel"})
	return InteractionRequest.new(QUIT_APPLICATION_REQUEST_ID, InteractionRequest.SESSION_LIFECYCLE, {
		"operation": "quit-application",
		"prompt": "Quit Realmz 2?",
		"hasActiveSession": has_active_session,
		"inCombat": in_combat,
		"options": options,
	})


static func response_action(request: InteractionRequest, response: InteractionResponse) -> StringName:
	if request == null or response == null or request.kind != InteractionRequest.SESSION_LIFECYCLE:
		return &""
	if response.request_id != request.request_id or response.kind != request.kind:
		return &""
	var action := StringName(response.payload.get("action", &""))
	for option: Dictionary in request.payload.get("options", []):
		if StringName(option.get("action", &"")) == action:
			return action
	return &""


static func allows_close(action: StringName, save_succeeded: bool = true) -> bool:
	if action == SAVE_AND_END:
		return save_succeeded
	return action == END_WITHOUT_SAVING


static func execute_end_adventure(action: StringName, save_operation: Callable, close_operation: Callable) -> Dictionary:
	if action == CANCEL:
		return {"state": &"cancelled", "step": null}
	if action == SAVE_AND_END:
		if not save_operation.is_valid() or not bool(save_operation.call()):
			return {"state": &"save-failed", "step": null}
	elif action != END_WITHOUT_SAVING:
		return {"state": &"invalid", "step": null}
	if not close_operation.is_valid():
		return {"state": &"close-failed", "step": null}
	var step: SessionStep = close_operation.call()
	if step == null or step.state == SessionStep.State.FAILED:
		return {"state": &"close-failed", "step": step}
	if step.state == SessionStep.State.WAITING_FOR_INTERACTION:
		return {"state": &"pending", "step": step}
	return {"state": &"closed", "step": step}


static func execute_quit(action: StringName, save_operation: Callable, quit_operation: Callable) -> StringName:
	if action == CANCEL:
		return &"cancelled"
	if action == SAVE_AND_QUIT:
		if not save_operation.is_valid() or not bool(save_operation.call()):
			return &"save-failed"
	elif action != QUIT_WITHOUT_SAVING:
		return &"invalid"
	if not quit_operation.is_valid():
		return &"quit-failed"
	quit_operation.call()
	return &"quit-requested"

class_name RealmzRngState
extends RefCounted

var generator_state: int
var draw_count: int


func _init(state_value: int, completed_draws: int) -> void:
	generator_state = state_value
	draw_count = completed_draws


func to_data() -> Dictionary:
	return {"generatorState": generator_state, "drawCount": draw_count}


static func from_data(data: Variant) -> RealmzRngState:
	if not data is Dictionary or not data.has("generatorState") or not data.has("drawCount"):
		return null
	var generator := _integer(data["generatorState"])
	var draws := _integer(data["drawCount"])
	if generator < 0 or draws < 0:
		return null
	if generator <= 0 or generator >= RealmzRng.MODULUS:
		return null
	return RealmzRngState.new(generator, draws)


static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

class_name RealmzRng
extends RefCounted

const MULTIPLIER: int = 16_807
const MODULUS: int = 2_147_483_647
const RAW_SCALE: int = 32_768

var _state: int
var _draw_count: int = 0
var _trace: Array[Dictionary] = []


func _init(initial_seed: int = 1) -> void:
	_state = _normalize_seed(initial_seed)


func draw(range_max: int, semantic_tag: StringName) -> int:
	if range_max <= 0 or range_max > 32_767:
		push_error("RealmzRng range must be between 1 and 32767.")
		return 0
	return _draw_scaled(range_max, semantic_tag)


func draw_classic(range_value: int, semantic_tag: StringName) -> int:
	if range_value < -32_768 or range_value > 32_767:
		push_error("Castle Rand range must fit a signed 16-bit value.")
		return 0
	return _draw_scaled(range_value, semantic_tag)


func _draw_scaled(range_value: int, semantic_tag: StringName) -> int:
	var raw: int = _next_raw()
	var positive_raw: int = -raw if raw < 0 else raw
	# C integer division truncates toward zero for Castle's signed Rand parameter.
	var result: int = 1 + int(float(positive_raw * range_value) / float(RAW_SCALE))
	_trace.append({
		"drawIndex": _draw_count,
		"tag": String(semantic_tag),
		"range": range_value,
		"raw": raw,
		"result": result,
	})
	_draw_count += 1
	return result


func draw_between(low: int, high: int, semantic_tag: StringName) -> int:
	if high < low or high - low + 1 > 32_767:
		push_error("RealmzRng inclusive range is invalid.")
		return low
	var result := draw(high - low + 1, semantic_tag) - 1 + low
	_trace[-1]["low"] = low
	_trace[-1]["high"] = high
	_trace[-1]["result"] = result
	return result


func snapshot() -> RealmzRngState:
	return RealmzRngState.new(_state, _draw_count)


func checkpoint() -> Dictionary:
	return {
		"generatorState": _state,
		"drawCount": _draw_count,
		"traceSize": _trace.size(),
		"sourcePosition": _source_position(),
	}


func rollback(checkpoint_data: Dictionary) -> bool:
	if not checkpoint_data.has("generatorState") or not checkpoint_data.has("drawCount") or not checkpoint_data.has("traceSize") or not checkpoint_data.has("sourcePosition"):
		return false
	var generator_state := int(checkpoint_data["generatorState"])
	var draw_count := int(checkpoint_data["drawCount"])
	var trace_size := int(checkpoint_data["traceSize"])
	if generator_state <= 0 or generator_state >= MODULUS or draw_count < 0 or trace_size < 0 or trace_size > _trace.size() or not _restore_source_position(checkpoint_data["sourcePosition"]):
		return false
	_state = generator_state
	_draw_count = draw_count
	_trace.resize(trace_size)
	return true


func restore(state: RealmzRngState) -> bool:
	if state == null or state.generator_state <= 0 or state.generator_state >= MODULUS or state.draw_count < 0:
		return false
	_state = state.generator_state
	_draw_count = state.draw_count
	_trace.clear()
	return true


func trace() -> Array[Dictionary]:
	return _trace.duplicate(true)


func _next_raw() -> int:
	_state = (_state * MULTIPLIER) % MODULUS
	var low_word: int = _state & 0xffff
	if low_word == 0x8000:
		return 0
	if low_word >= 0x8000:
		return low_word - 0x10000
	return low_word


func _source_position() -> Variant:
	return null


func _restore_source_position(value: Variant) -> bool:
	return value == null


static func _normalize_seed(initial_seed: int) -> int:
	var normalized: int = initial_seed % MODULUS
	if normalized < 0:
		normalized += MODULUS
	return 1 if normalized == 0 else normalized

