	var map := MapDefinition.new("dungeon.test", "Dungeon", &"dungeon", 0, MapTopology.new(30, 30, cells), false, false, -1, [], "terrain.dungeon")
	var terrain := _terrain_set("terrain.dungeon", -1, -1)
