class_name EncounterInteraction
extends InteractionComponent


func build(request: InteractionRequest) -> void:
	var actions: Variant = request.payload.get("actions", [])
	if not actions is Array:
		return
	for entry: Variant in actions:
		if not entry is Dictionary:
			continue
		var kind := String(entry.get("kind", ""))
		match kind:
			"choice":
				_add_bitmap_response(&"encounter.action", String(entry.get("label", "Choose")), {"action": "choice", "slot": int(entry.get("slot", 0))})
			"back":
				_add_bitmap_response(&"encounter.stop", String(entry.get("label", "Back out")), {"action": "back"})
			"word":
				_add_word_action(entry)
			"item":
				_add_catalog_action(request, "item", "classicItemId", "items", String(entry.get("label", "Use an item")))
			"spell":
				_add_catalog_action(request, "spell", "classicSpellId", "spells", String(entry.get("label", "Cast a spell")))
			"thief":
				_add_thief_action(request, entry)


func _add_word_action(entry: Dictionary) -> void:
	var word := LineEdit.new()
	word.placeholder_text = "Speak a word"
	add_child(word)
	var button := _bitmap_button(&"encounter.speak", String(entry.get("label", "Speak")))
	button.command_requested.connect(func(_command_id: StringName) -> void: payload_submitted.emit({"action": "word", "word": word.text}))
	add_child(button)


func _add_catalog_action(request: InteractionRequest, action: String, id_field: String, values_key: String, label: String) -> void:
	var catalog := OptionButton.new()
	var values: Variant = request.payload.get(values_key, [])
	if values is Array:
		for entry: Variant in values:
			if entry is Dictionary and entry.has(id_field):
				catalog.add_item(String(entry.get("name", "Option")))
				catalog.set_item_metadata(catalog.item_count - 1, int(entry[id_field]))
	add_child(catalog)
	var asset_id := &"encounter.items" if action == "item" else &"command.spells"
	var button := _bitmap_button(asset_id, label)
	button.disabled = catalog.item_count == 0
	button.tooltip_text = "No eligible options were supplied." if button.disabled else ""
	button.command_requested.connect(func(_command_id: StringName) -> void:
		if catalog.item_count > 0:
			var payload := {"action": action}
			payload[id_field] = int(catalog.get_selected_metadata())
			payload_submitted.emit(payload)
	)
	add_child(button)


func _add_thief_action(request: InteractionRequest, entry: Dictionary) -> void:
	var picker := character_option(request.payload.get("characters", []))
	add_child(picker)
	var button := _bitmap_button(&"encounter.skills", String(entry.get("label", "Thief action")))
	button.disabled = picker.item_count == 0
	button.tooltip_text = "No eligible character was supplied." if button.disabled else ""
	button.command_requested.connect(func(_command_id: StringName) -> void:
		if picker.item_count > 0:
			payload_submitted.emit({"action": "thief", "actionIndex": int(entry.get("actionIndex", 0)), "characterId": String(picker.get_selected_metadata())})
	)
	add_child(button)


func _add_bitmap_response(asset_id: StringName, label: String, payload: Dictionary) -> void:
	var row := HBoxContainer.new()
	var button := _bitmap_button(asset_id, label)
	button.command_requested.connect(func(_command_id: StringName) -> void: payload_submitted.emit(payload))
	row.add_child(button)
	var text := Label.new()
	text.text = label
	text.vertical_alignment = VERTICAL_ALIGNMENT_CENTER
	text.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
	text.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	row.add_child(text)
	add_child(row)


func _bitmap_button(asset_id: StringName, label: String) -> ClassicBitmapButton:
	var button := ClassicBitmapButton.new()
	button.configure({"id": asset_id, "asset_id": asset_id, "tooltip": label, "accelerator": ""}, 1)
	return button

class_name LevelUpInteraction
extends InteractionComponent


func build(request: InteractionRequest) -> void:
	var mode := String(request.payload.get("mode", ""))
	if mode == "result":
		_build_result(request.payload)
	elif mode == "spell-selection":
		_build_spell_selection(request.payload)
	else:
		add_hint("The level-up request is malformed.")


func _build_result(payload: Dictionary) -> void:
	var character_id := String(payload.get("characterId", ""))
	if character_id.is_empty() or not payload.get("gains") is Dictionary:
		add_hint("The level result is unavailable.")
		return
	var gains: Dictionary = payload["gains"]
	add_hint("%s reached level %d." % [String(payload.get("characterName", "Character")), int(payload.get("level", 0))])
	add_hint("Stamina +%d • Spell points +%d • To hit +%d • Magic resistance +%d" % [int(gains.get("stamina", 0)), int(gains.get("spellPoints", 0)), int(gains.get("toHit", 0)), int(gains.get("magicResistance", 0))])
	add_response("Continue", {"action": "continue", "characterId": character_id})


func _build_spell_selection(payload: Dictionary) -> void:
	var character_id := String(payload.get("characterId", ""))
	var spells: Variant = payload.get("spells", [])
	if character_id.is_empty() or not spells is Array:
		add_hint("The spell-selection request is unavailable.")
		return
	add_hint("Choose spells for %s. Available points: %d" % [String(payload.get("characterName", "Character")), int(payload.get("pointTotal", 0))])
	var checklist := ItemList.new()
	checklist.select_mode = ItemList.SELECT_MULTI
	checklist.custom_minimum_size.y = 260.0
	checklist.size_flags_vertical = Control.SIZE_EXPAND_FILL
	for value: Variant in spells:
		if not value is Dictionary:
			continue
		var spell: Dictionary = value
		checklist.add_item("%s • %d point%s" % [String(spell.get("name", "Spell")), int(spell.get("cost", 0)), "" if int(spell.get("cost", 0)) == 1 else "s"])
		checklist.set_item_metadata(checklist.item_count - 1, String(spell.get("id", "")))
		if bool(spell.get("selected", false)):
			checklist.select(checklist.item_count - 1, false)
	add_child(checklist)
	var confirm := Button.new()
	confirm.text = "Confirm spell selection"
	confirm.custom_minimum_size.y = 36.0
	confirm.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	confirm.pressed.connect(func() -> void:
		var selected_ids: Array[String] = []
		for index: int in checklist.get_selected_items():
			selected_ids.append(String(checklist.get_item_metadata(index)))
		payload_submitted.emit({"action": "confirm-spells", "characterId": character_id, "spellIds": selected_ids})
	)
	add_child(confirm)

extends InteractionComponent


func build(request: InteractionRequest) -> void:
	if request.kind != InteractionRequest.SESSION_LIFECYCLE:
		return
	var options: Variant = request.payload.get("options", [])
	if not options is Array:
		return
	for option: Variant in options:
		if not option is Dictionary:
			continue
		var action := StringName(option.get("action", &""))
		var label := String(option.get("label", "")).strip_edges()
		if action.is_empty() or label.is_empty():
			continue
		add_response(label, {"action": action})

class_name PlayerMapInteraction
