class_name SelectionInteraction
extends InteractionComponent

var _checks: Array[CheckButton] = []


func build(request: InteractionRequest) -> void:
	if request.kind == &"character_selection":
		_build_character_selection(request)
	else:
		_build_ally_selection(request)


func _build_character_selection(request: InteractionRequest) -> void:
	var required := int(request.payload.get("count", 1))
	var prompt := String(request.payload.get("prompt", ""))
	if not prompt.is_empty():
		add_hint(prompt)
	add_hint("Choose %d character%s." % [required, "" if required == 1 else "s"])
	var eligible: Variant = request.payload.get("eligible", [])
	if eligible is Array:
		for entry: Variant in eligible:
			if entry is Dictionary:
				_add_character_check(entry, false, false)
	var submit := Button.new()
	submit.text = "Choose"
	submit.pressed.connect(_submit_characters.bind(required))
	add_child(submit)


func _build_ally_selection(request: InteractionRequest) -> void:
	var maximum := int(request.payload.get("maximum", 0))
	var selected: Variant = request.payload.get("selectedIds", [])
	add_hint("Choose up to %d surviving allies. Required allies stay selected." % maximum)
	var candidates: Variant = request.payload.get("candidates", [])
	if candidates is Array:
		for entry: Variant in candidates:
			if not entry is Dictionary:
				continue
			var ally_id := String(entry.get("id", ""))
			var required := bool(entry.get("required", false))
			_add_character_check(entry, required or selected is Array and selected.has(ally_id), required)
	var submit := Button.new()
	submit.text = "Continue"
	submit.pressed.connect(_submit_allies.bind(maximum))
	add_child(submit)


func _add_character_check(entry: Dictionary, selected: bool, required: bool) -> void:
	var check := CheckButton.new()
	check.text = "%s • HP %d/%d%s" % [entry.get("name", "Character"), int(entry.get("currentHealth", 0)), int(entry.get("maximumHealth", entry.get("currentHealth", 0))), " • Required" if required else ""]
	check.set_meta("character_id", String(entry.get("id", "")))
	check.button_pressed = selected
	check.disabled = required
	_checks.append(check)
	add_child(check)


func _submit_characters(required: int) -> void:
	var ids := _selected_ids()
	if ids.size() != required:
		add_hint("Choose exactly %d character%s." % [required, "" if required == 1 else "s"])
		return
	payload_submitted.emit({"characterIds": ids})


func _submit_allies(maximum: int) -> void:
	var ids := _selected_ids()
	if ids.size() > maximum:
		add_hint("Choose no more than %d allies." % maximum)
		return
	payload_submitted.emit({"selectedIds": ids})


func _selected_ids() -> Array[String]:
	var ids: Array[String] = []
	for check: CheckButton in _checks:
		if check.button_pressed:
			ids.append(String(check.get_meta("character_id")))
	return ids

class_name ShopInteraction
extends InteractionComponent


func build(request: InteractionRequest) -> void:
	add_hint("Party gold: %d • Shop rate: %d%%" % [int(request.payload.get("partyGold", 0)), int(request.payload.get("inflationPercent", 100))])
	var picker := character_option(request.payload.get("characters", []))
	add_child(picker)
	add_hint("Buy")
	var stock: Variant = request.payload.get("stock", [])
	if stock is Array:
		for entry: Variant in stock:
			if not entry is Dictionary:
				continue
			var available := bool(entry.get("canBuy", int(entry.get("quantity", 0)) > 0)) and picker.item_count > 0
			var payload := {"action": "buy", "stockKey": String(entry.get("stockKey", "")), "stockIndex": int(entry.get("index", -1))}
			var button := Button.new()
			button.text = "%s • %d gold • %d left" % [entry.get("name", "Item"), int(entry.get("buyPrice", 0)), int(entry.get("quantity", 0))]
			button.disabled = not available
			button.tooltip_text = String(entry.get("buyReason", "No stock or eligible buyer.")) if not available else ""
			button.pressed.connect(func() -> void:
				if picker.item_count > 0:
					payload["characterId"] = String(picker.get_selected_metadata())
					payload_submitted.emit(payload)
			)
			add_child(button)
	add_hint("Sell")
	var characters: Variant = request.payload.get("characters", [])
	if characters is Array:
		for character: Variant in characters:
			if not character is Dictionary or not character.get("inventory", []) is Array:
				continue
			for item: Variant in character.get("inventory", []):
				if item is Dictionary:
					var owner_id := String(character.get("id", ""))
					var instance_id := String(item.get("instanceId", ""))
					add_response("Sell %s (%s) • %d gold" % [item.get("name", "Item"), character.get("name", "Character"), int(item.get("sellPrice", 0))], {"action": "sell", "characterId": owner_id, "instanceId": instance_id}, bool(item.get("canSell", false)), String(item.get("sellReason", "This item cannot be sold here.")))
					if not bool(item.get("identified", false)):
						add_response("Identify %s (%s) • %d gold" % [item.get("name", "Item"), character.get("name", "Character"), int(request.payload.get("identifyPrice", 20))], {"action": "identify", "characterId": owner_id, "instanceId": instance_id}, bool(item.get("canIdentify", false)), String(item.get("identifyReason", "Identification is unavailable.")))
	add_response("Leave shop", {"action": "leave"})

class_name TempleInteraction
extends InteractionComponent

var _characters: Array[Dictionary] = []
var _services: Array[Dictionary] = []
var _picker: OptionButton
var _summary: Label
var _service_buttons: Dictionary = {}
var _pooled_gold: int = 0


func build(request: InteractionRequest) -> void:
	var characters: Variant = request.payload.get("characters", [])
	if characters is Array:
		for character: Variant in characters:
			if character is Dictionary:
				_characters.append(character.duplicate(true))
	var services: Variant = request.payload.get("services", [])
	if services is Array:
		for service: Variant in services:
			if service is Dictionary:
				_services.append(service.duplicate(true))
	var pooled: Variant = request.payload.get("pooledWealth", {})
	_pooled_gold = int(pooled.get("gold", 0)) if pooled is Dictionary else 0
	add_hint("Temple services • %d%% rate • pooled gold %d" % [int(request.payload.get("costPercent", 100)), _pooled_gold])
	_picker = character_option(_characters)
	var selected_character_id := String(request.payload.get("selectedCharacterId", ""))
	for index: int in _picker.item_count:
		if String(_picker.get_item_metadata(index)) == selected_character_id:
			_picker.select(index)
			break
	_picker.item_selected.connect(func(_index: int) -> void: _refresh_selected_character())
	add_child(_picker)
	_summary = add_hint("")
	for service: Dictionary in _services:
		var service_id := String(service.get("id", ""))
		var button := Button.new()
		button.text = "%s • %d gold" % [service.get("label", "Service"), int(service.get("cost", 0))]
		button.custom_minimum_size.y = 36.0
		button.size_flags_horizontal = Control.SIZE_EXPAND_FILL
		button.pressed.connect(_submit_service.bind(service_id))
		add_child(button)
		_service_buttons[service_id] = button
	add_hint("Wealth")
	_add_temple_action("Pool party wealth", "pool")
	_add_temple_action("Share pooled wealth", "share")
	_add_temple_action("Leave temple", "leave")
	_refresh_selected_character()


func _submit_service(service_id: String) -> void:
	if _picker == null or _picker.item_count < 1:
		return
	payload_submitted.emit({"action": "service", "serviceId": service_id, "characterId": String(_picker.get_selected_metadata())})


func _add_temple_action(label: String, action: String) -> void:
	var button := Button.new()
	button.text = label
	button.custom_minimum_size.y = 36.0
	button.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	button.pressed.connect(_submit_temple_action.bind(action))
	add_child(button)


func _submit_temple_action(action: String) -> void:
	var payload := {"action": action}
	if _picker != null and _picker.item_count > 0:
		payload["selectedCharacterId"] = String(_picker.get_selected_metadata())
	payload_submitted.emit(payload)


func _refresh_selected_character() -> void:
	if _picker == null or _picker.item_count < 1:
		_summary.text = "No eligible character was supplied."
		for button: Button in _service_buttons.values():
			button.disabled = true
			button.tooltip_text = "No eligible character was supplied."
		return
	var character_id := String(_picker.get_selected_metadata())
	var character: Dictionary = {}
	for candidate: Dictionary in _characters:
		if candidate.get("id") == character_id:
			character = candidate
			break
	var condition_names: Array[String] = []
	var conditions: Variant = character.get("conditions", [])
	if conditions is Array:
		for condition: Variant in conditions:
			if condition is Dictionary:
				condition_names.append(String(condition.get("name", "Condition")))
	var condition_text := "None shown" if condition_names.is_empty() else ", ".join(condition_names)
	_summary.text = "%s • HP %d/%d • personal gold %d • load %d/%d\nConditions: %s" % [
		character.get("name", "Character"),
		int(character.get("currentHealth", 0)),
		int(character.get("maximumHealth", 0)),
		int(character.get("personalGold", 0)),
		int(character.get("load", 0)),
		int(character.get("maximumLoad", 0)),
		condition_text,
	]
	var available := int(character.get("availableGold", _pooled_gold + int(character.get("personalGold", 0))))
	for service: Dictionary in _services:
		var service_id := String(service.get("id", ""))
		var button: Button = _service_buttons.get(service_id)
		if button == null:
			continue
		var cost := int(service.get("cost", 0))
		button.disabled = cost > available
		button.tooltip_text = "Requires %d gold from the pool and selected character." % cost if button.disabled else String(service.get("description", ""))

class_name TextChoiceInteraction
