func add_hint(text: String) -> Label:
	var label := Label.new()
	label.text = text
	label.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
	label.add_theme_color_override("font_color", Color("d5b45d"))
	add_child(label)
	return label


func character_option(value: Variant) -> OptionButton:
	var picker := OptionButton.new()
	picker.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	if value is Array:
		for character: Variant in value:
			if character is Dictionary:
				picker.add_item(String(character.get("name", "Character")))
				picker.set_item_metadata(picker.item_count - 1, String(character.get("id", "")))
	return picker

func checkpoint() -> Dictionary:
	return {
		"generatorState": _state,
		"drawCount": _draw_count,
		"traceSize": _trace.size(),
		"sourcePosition": _source_position(),
	}

func _next_raw() -> int:
	_state = (_state * MULTIPLIER) % MODULUS
	var low_word: int = _state & 0xffff
	if low_word == 0x8000:
		return 0
	if low_word >= 0x8000:
		return low_word - 0x10000
	return low_word

func _init(state_value: int, completed_draws: int) -> void:
	generator_state = state_value
	draw_count = completed_draws

static func from_data(data: Variant) -> RealmzRngState:
	if not data is Dictionary or not data.has("generatorState") or not data.has("drawCount"):
		return null
	var generator := _integer(data["generatorState"])
	var draws := _integer(data["drawCount"])
	if generator < 0 or draws < 0:
		return null
	if generator <= 0 or generator >= RealmzRng.MODULUS:
		return null
	return RealmzRngState.new(generator, draws)

static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

func rollback(checkpoint_data: Dictionary) -> bool:
	if not checkpoint_data.has("generatorState") or not checkpoint_data.has("drawCount") or not checkpoint_data.has("traceSize") or not checkpoint_data.has("sourcePosition"):
		return false
	var generator_state := int(checkpoint_data["generatorState"])
	var draw_count := int(checkpoint_data["drawCount"])
	var trace_size := int(checkpoint_data["traceSize"])
	if generator_state <= 0 or generator_state >= MODULUS or draw_count < 0 or trace_size < 0 or trace_size > _trace.size() or not _restore_source_position(checkpoint_data["sourcePosition"]):
		return false
	_state = generator_state
	_draw_count = draw_count
	_trace.resize(trace_size)
	return true

func draw(range_max: int, semantic_tag: StringName) -> int:
	if range_max <= 0 or range_max > 32_767:
		push_error("RealmzRng range must be between 1 and 32767.")
		return 0
	return _draw_scaled(range_max, semantic_tag)

func draw_classic(range_value: int, semantic_tag: StringName) -> int:
	if range_value < -32_768 or range_value > 32_767:
		push_error("Castle Rand range must fit a signed 16-bit value.")
		return 0
	return _draw_scaled(range_value, semantic_tag)

func _draw_scaled(range_value: int, semantic_tag: StringName) -> int:
	var raw: int = _next_raw()
	var positive_raw: int = -raw if raw < 0 else raw
	# C integer division truncates toward zero for Castle's signed Rand parameter.
	var result: int = 1 + int(float(positive_raw * range_value) / float(RAW_SCALE))
	_trace.append({
		"drawIndex": _draw_count,
		"tag": String(semantic_tag),
		"range": range_value,
		"raw": raw,
		"result": result,
	})
	_draw_count += 1
	return result

