class_name InteractionRequest
extends RefCounted

var request_id: String
var kind: StringName
var payload: Dictionary

const ACKNOWLEDGE: StringName = &"acknowledge"
const AGE_UPDATE: StringName = &"age_update"
const YES_NO: StringName = &"yes_no"
const INDEXED_CHOICE: StringName = &"scenario_choice"
const ENCOUNTER_CHOICE: StringName = &"encounter_choice"
const CHARACTER_SELECTION: StringName = &"character_selection"
const ALLY_SELECTION: StringName = &"ally_selection"
const TREASURE_DISTRIBUTION: StringName = &"treasure_distribution"
const LEVEL_UP: StringName = &"level_up"
const WORD_AND_ACTION: StringName = &"complex_encounter"
const SHOP: StringName = &"shop_action"
const TEMPLE: StringName = &"temple_action"
const BANK: StringName = &"bank_action"
const POOLED_WEALTH_DEPARTURE: StringName = &"pooled_wealth_departure"
const COMBAT: StringName = &"combat_action"
const SESSION_LIFECYCLE: StringName = &"session_lifecycle"


func _init(id: String, request_kind: StringName, request_payload: Dictionary = {}) -> void:
	request_id = id
	kind = request_kind
	payload = request_payload.duplicate(true)


func to_data() -> Dictionary:
	return {"request_id": request_id, "kind": String(kind), "payload": payload.duplicate(true)}


func is_supported_kind() -> bool:
	return InteractionRequest.kind_is_supported(kind)


static func kind_is_supported(request_kind: StringName) -> bool:
	return request_kind in [ACKNOWLEDGE, AGE_UPDATE, YES_NO, INDEXED_CHOICE, ENCOUNTER_CHOICE, CHARACTER_SELECTION, ALLY_SELECTION, TREASURE_DISTRIBUTION, LEVEL_UP, WORD_AND_ACTION, SHOP, TEMPLE, BANK, POOLED_WEALTH_DEPARTURE, COMBAT, SESSION_LIFECYCLE]


static func acknowledge(id: String, prompt: String, message_id: int = 0) -> InteractionRequest:
	return InteractionRequest.new(id, ACKNOWLEDGE, {"prompt": prompt, "messageId": message_id, "presentation": "classic-textbox"})


static func age_update(id: String, update_payload: Dictionary) -> InteractionRequest:
	return InteractionRequest.new(id, AGE_UPDATE, update_payload)


static func yes_no(id: String, prompt: String, yes_label: String, no_label: String) -> InteractionRequest:
	return InteractionRequest.new(id, YES_NO, {"prompt": prompt, "yesLabel": yes_label, "noLabel": no_label})


static func indexed_choice(id: String, prompt: String, options: Array) -> InteractionRequest:
	return InteractionRequest.new(id, INDEXED_CHOICE, {"prompt": prompt, "options": options.duplicate(true)})


static func from_data(data: Variant) -> InteractionRequest:
	if not data is Dictionary:
		return null
	for field: String in ["request_id", "kind", "payload"]:
		if not data.has(field):
			return null
	if not data["request_id"] is String or data["request_id"].is_empty() or not data["kind"] is String or data["kind"].is_empty() or not data["payload"] is Dictionary:
		return null
	var request_kind := StringName(data["kind"])
	if not InteractionRequest.kind_is_supported(request_kind):
		return null
	return InteractionRequest.new(data["request_id"], request_kind, data["payload"])

func set_active_temple(cost_percent: int) -> bool:
	if cost_percent < -32_768 or cost_percent > 32_767:
		return false
	temple_available = true
	temple_cost_percent = cost_percent
	return true

func set_active_shop(shop_id: String, accept_ranges: Array[int]) -> bool:
	if shop_id.is_empty() or accept_ranges.size() != 4:
		return false
	active_shop_id = shop_id
	_shop_accept_ranges = accept_ranges.duplicate()
	return true

class_name RealmzArithmetic
extends RefCounted


func signed_16(value: int) -> int:
	var wrapped := value & 0xffff
	return wrapped - 0x10000 if wrapped >= 0x8000 else wrapped


func unsigned_16(value: int) -> int:
	return value & 0xffff


func signed_32(value: int) -> int:
	var wrapped := value & 0xffffffff
	return wrapped - 0x1_0000_0000 if wrapped >= 0x8000_0000 else wrapped


func percentage_succeeds(roll: int, chance: int, inclusive: bool = true) -> bool:
	return roll <= chance if inclusive else roll < chance


func pin(value: int, minimum: int, maximum: int) -> int:
	return clampi(value, minimum, maximum)

class_name PartySetupRules
extends RefCounted


static func difficulty_multiplier(difficulty: int) -> float:
	return 1.0 + float(clampi(difficulty, -2, 2)) * 0.33


static func experience_multiplier(recommended_levels: int, current_levels: int, difficulty: int) -> float:
	if recommended_levels <= 0 or current_levels <= 0:
		return 0.0
	return clampf(difficulty_multiplier(difficulty) * float(recommended_levels) / float(current_levels), 0.20, 2.50)


static func experience_percent(recommended_levels: int, current_levels: int, difficulty: int) -> int:
	return int(experience_multiplier(recommended_levels, current_levels, difficulty) * 100.0)


static func scale_experience(value: int, recommended_levels: int, current_levels: int, difficulty: int) -> int:
	return maxi(0, int(float(value) * experience_multiplier(recommended_levels, current_levels, difficulty)))


static func scale_experience_by_multiplier(value: int, multiplier: float) -> int:
	return maxi(0, int(float(value) * clampf(multiplier, 0.20, 2.50)))


static func scale_money(value: int, difficulty: int) -> int:
	return maxi(0, int(float(value) * difficulty_multiplier(difficulty)))

func morale_action(monster: MonsterState, definition: MonsterDefinition) -> StringName:
	if monster.current_health <= 0:
		return &"defeated"
	# Castle getup.c computes current/current before the thresholds; preserve the observable 100 percent result.
	var percent := 100
	var surrender_percent := monster.surrender_percent if monster.surrender_percent != 0 else definition.surrender_percent
	if percent < surrender_percent:
		return &"panic" if surrender_percent == 101 else &"surrender"
	if percent < definition.run_percent:
		return &"retreat"
	return &"fight"

