func _finish_completed(events: Array[DomainEvent]) -> SessionStep:
	_view_revision += 1
	return SessionStep.completed(_view_revision, events)


func _finish_waiting(request: InteractionRequest, events: Array[DomainEvent]) -> SessionStep:
	_view_revision += 1
	return SessionStep.waiting(_view_revision, request, events)


func _finish_failed(code: StringName, message: String, events: Array[DomainEvent]) -> SessionStep:
	_view_revision += 1
	return SessionStep.failed(_view_revision, code, message, events)


func _pending_interaction() -> InteractionRequest:
	return _session_interaction if _session_interaction != null else _scenario_vm.pending_request()


func _respond_session_interaction(response: InteractionResponse) -> SessionStep:
	if _session_continuation.get("kind") == "pooled-wealth-departure":
		return _respond_pooled_wealth_departure(response)
	if _session_continuation.get("kind") == "service-interaction":
		return _respond_runtime_service(response)
	if _session_continuation.get("kind") == "drop-item-confirmation":
		return _respond_drop_item(response)
	if _session_continuation.get("kind") == "item-use-target-selection":
		return _respond_item_use_target(response)
	if _session_continuation.get("kind") == "field-spell-target-selection":
		return _respond_field_spell_target(response)
	if _session_continuation.get("kind") == "scroll-target-selection":
		return _respond_scroll_target(response)
	if _session_continuation.get("kind") == "character-spell-confirmation":
		return _respond_character_spell_confirmation(response)
	if _session_continuation.get("kind") == "character-vault-publication":
		return _respond_character_vault_publication(response)
	if _session_continuation.get("kind") == "age-updates":
		return _respond_session_age_update(response)
	if _session_continuation.get("kind") == "combat-ally-selection":
		return _respond_session_ally_selection(response)
	if _session_continuation.get("kind") == "combat-fumble-recovery":
		return _respond_session_fumble_recovery(response)
	if _session_continuation.get("kind") == "combat-reward":
		return _respond_session_battle_reward(response)
	if _session_continuation.get("kind") == "combat-retreat-confirmation":
		return _respond_session_retreat(response)
	if response.kind != &"yes_no" or not response.payload.has("accepted") or not response.payload["accepted"] is bool:
		return SessionStep.failed(_view_revision, &"invalid_interaction_response", "The random encounter response must be a yes/no choice.")
	if _session_continuation.get("randomBattleStage", "") != "surprise-choice":
		return SessionStep.failed(_view_revision, &"invalid_session_continuation", "The random encounter choice has no matching continuation.")
	var map := _content.world.map_by_id(String(_session_continuation.get("mapId", "")))
	var region_id := String(_session_continuation.get("activeRandomRegionId", ""))
	var region: RandomEncounterRegion = null if map == null else map.random_region_by_id(region_id)
	if region == null:
		return SessionStep.failed(_view_revision, &"invalid_session_continuation", "The random encounter choice references unavailable content.")
	_session_interaction = null
	_session_continuation["activeRandomRegionId"] = ""
	_session_continuation["randomBattleStage"] = ""
	var events: Array[DomainEvent] = [DomainEvent.new(&"random_surprise_chosen", {"regionId": region.id, "accepted": response.payload["accepted"]})]
	if response.payload["accepted"]:
		return _start_random_battle(region, 1, events)
	_session_continuation["randomRegionIndex"] = int(_session_continuation["randomRegionIndex"]) - 1
	if region.only:
		if _session_continuation.get("kind") == "post-clock":
			return _complete_post_time(events)
		_session_continuation.clear()
		return _finish_completed(events)
	var next_step := _continue_random_regions(map, events)
	if next_step != null:
		return next_step
	if _session_continuation.get("kind") == "post-clock":
		return _complete_post_time(events)
	_session_continuation.clear()
	return _finish_completed(events)


func _respond_pooled_wealth_departure(response: InteractionResponse) -> SessionStep:
	var stage := String(_session_continuation.get("stage", ""))

	result.events = events
	return result


func character_item_spell_options(state: GameState, content: RealmzContent, caster_id: String) -> Array[CombatItemOptionView]:
	var result: Array[CombatItemOptionView] = []
	if state == null or state.combat == null or state.combat.active_actor_id() != caster_id:
		return result
	var caster := state.party.character_by_id(caster_id)
	if caster == null:
		return result
	for instance: ItemInstance in caster.inventory():
		var item := content.item_by_id(instance.definition_id)
		var spell := content.spell_by_classic_id(item.special_2) if item != null else null
		if item == null or spell == null or absi(item.special_1) == 8:
			continue
		if spell.target_type in [9, 10, 12]:
			if probe_character_item_spell(state, content, caster_id, "", instance.id).allowed:
				result.append(CombatItemOptionView.new(instance, item, spell, absi(item.special_1), null, _group_spell_target_label(spell.target_type), &"automatic"))
			continue
		if spell.target_type == 5:
			if probe_character_item_spell(state, content, caster_id, caster_id, instance.id).allowed:
				result.append(CombatItemOptionView.new(instance, item, spell, absi(item.special_1), _spell_target_view(state, content, caster_id)))
			continue
		for target: CombatSpellTargetView in _character_actor_spell_candidates(state, content, caster, spell, absi(item.special_1)):
			if probe_character_item_spell(state, content, caster_id, target.id, instance.id).allowed:
				result.append(CombatItemOptionView.new(instance, item, spell, absi(item.special_1), target))
	return result


func character_item_spell_unavailable_reason(state: GameState, content: RealmzContent, caster_id: String) -> String:
	if state == null or state.combat == null or state.combat.active_actor_id() != caster_id:
		return "Only the active character may use an item."
	var caster := state.party.character_by_id(caster_id)
	if caster == null or caster.inventory().is_empty():
		return "The active character carries no items."
	for instance: ItemInstance in caster.inventory():
		var item := content.item_by_id(instance.definition_id)
		var spell := content.spell_by_classic_id(item.special_2) if item != null else null
		if item != null and spell != null:
			var probe := probe_character_item_spell(state, content, caster_id, caster_id if spell.target_type == 5 else "", instance.id)
			if not probe.allowed:
				return probe.reason_text
	return "No carried item has a supported Classic combat use."


static func _inventory_instance(character: CharacterState, instance_id: String) -> ItemInstance:
	if character == null:
		return null
	for instance: ItemInstance in character.inventory():
		if instance.id == instance_id:
			return instance
	return null


static func _item_use_reason_code(instance: ItemInstance, item: ItemDefinition, spell: SpellDefinition) -> StringName:
	if instance == null or item == null:
		return &"unknown_item_instance"
	if instance.charges == 0:
		return &"item_has_no_charges"
	if item.special_2 <= 1100:
		return &"item_has_no_spell_effect"
	if spell == null:
		return &"unknown_item_spell"
	return &"item_cannot_be_used"


static func _item_used_event(caster_id: String, instance_id: String, item: ItemDefinition, spell: SpellDefinition, power_level: int, caster: CharacterState) -> DomainEvent:
	var remaining := -1
	var dropped := true
	for instance: ItemInstance in caster.inventory():
		if instance.id == instance_id:
			remaining = instance.charges
			dropped = false
			break
	return DomainEvent.new(&"item_used", {"characterId": caster_id, "instanceId": instance_id, "itemId": item.id, "spellId": spell.id, "power": power_level, "chargesRemaining": remaining, "droppedOnEmpty": dropped, "source": "classic"})


func cast_spell(state: GameState, content: RealmzContent, caster_id: String, target_id: String, spell_id: String, power_level: int, rng: RealmzRng, target_coordinate: Vector2i = Vector2i(-100_000, -100_000), rotation: int = 0, target_ids: Array[String] = []) -> CombatFlowResult:
	var probe := probe_character_spell_cast(state, content, caster_id, target_id, spell_id, power_level, target_coordinate, rotation, target_ids)
	if not probe.allowed:
		return CombatFlowResult.failed(probe.reason, probe.reason_text)
	var combat := state.combat
	var caster := state.party.character_by_id(caster_id)
	var spell := content.spell_by_id(spell_id)
	var cast_level := spell.classic_tier()
	if spell.target_type in [3, 4]:
		if target_coordinate == INVALID_COORDINATE:
			return CombatFlowResult.failed(&"area_target_required", "A fixed or power area spell requires a battlefield coordinate.")
		_prepare_character_turn(combat, caster)
		combat.invalidate_undo()
		return _cast_character_area_spell(state, content, caster, spell, power_level, cast_level, rng, target_coordinate, rotation)
	_prepare_character_turn(combat, caster)
	combat.invalidate_undo()
	if spell.target_type in [9, 10, 12]:
		return _cast_character_group_spell(state, content, caster, spell, power_level, cast_level, rng)
	if spell.target_type == 0:
		var selections: Array[SpellTargetSelection] = []
		for selected_id: String in target_ids:
			var repeated_selection := _spell_target_selection(state, content, selected_id)
			if repeated_selection == null:
				return CombatFlowResult.failed(&"spell_target_unavailable", "A selected repeated-spell target is unavailable.")
			selections.append(repeated_selection)
		var repeated := _rules.magic.resolve_character_repeated_spell(caster, selections, spell, power_level, cast_level, rng)
		if repeated == null or not repeated.cast:
			return CombatFlowResult.failed(&"spell_cast_failed", "The repeated-target spell could not be cast with the available spell points.")
		return _commit_character_multi_spell(state, content, caster, spell, power_level, cast_level, repeated, rng)
	var selection := _spell_target_selection(state, content, target_id)
	if selection == null:
		return CombatFlowResult.failed(&"spell_target_unavailable", "The selected combatant is unavailable.")
	var targeted := _rules.magic.resolve_character_targeted_spell(caster, selection, spell, power_level, cast_level, rng)
	if targeted == null or not targeted.cast:
		return CombatFlowResult.failed(&"spell_cast_failed", "The spell could not be cast with the available spell points.")
	return _commit_character_multi_spell(state, content, caster, spell, power_level, cast_level, targeted, rng)


func probe_character_scroll_cast(state: GameState, content: RealmzContent, caster_id: String, scroll_slot: int, target_id: String = "", target_coordinate: Vector2i = INVALID_COORDINATE, rotation: int = 0, target_ids: Array[String] = []) -> CombatSpellCastProbe:
	if state == null or content == null:
		return CombatSpellCastProbe.blocked(&"invalid_scroll_turn", "Scroll use requires an active game session.")
	var combat := state.combat
	if combat == null or combat.completed or combat.battlefield == null or combat.active_actor_id() != caster_id:
		return CombatSpellCastProbe.blocked(&"invalid_scroll_turn", "Only the active character may use a scroll in combat.")
	if not combat.pending_spell_death_macro_id().is_empty():
		return CombatSpellCastProbe.blocked(&"spell_death_macro_pending", "A spell-triggered monster death macro must complete before another combat action.")
	var caster := state.party.character_by_id(caster_id)
	if caster == null or caster.current_health <= 0 or caster.conditions.is_active(ConditionRules.ANIMATED):
		return CombatSpellCastProbe.blocked(&"scroll_user_unavailable", "The active character cannot use a scroll.")
	if not _has_equipped_scroll_case(caster, content):
		return CombatSpellCastProbe.blocked(&"scroll_case_not_equipped", "Equip a scroll case before using its spells.")
	var scroll := caster.scroll_at(scroll_slot)
	var spell := content.spell_by_id(scroll.spell_id) if scroll != null and not scroll.is_empty() else null
	if scroll_slot < 0 or scroll_slot >= 5 or scroll == null or scroll.is_empty() or spell == null or scroll.power < 1 or scroll.power > 7:
		return CombatSpellCastProbe.blocked(&"invalid_scroll_slot", "This scroll slot is empty or invalid.")
	if not spell.in_combat:
		return CombatSpellCastProbe.blocked(&"scroll_not_available_in_combat", "This scroll cannot be used in combat.")
	var repeated_target := spell.target_type == 0
	var group_target := spell.target_type in [9, 10, 12]
	var area_target := spell.target_type in [3, 4]
	var self_target := spell.target_type == 5
	var actor_target := not repeated_target and not group_target and not area_target
	var effective_target_id := caster_id if self_target else target_id
	if actor_target and _spell_target_selection(state, content, effective_target_id) == null:
		return CombatSpellCastProbe.blocked(&"invalid_scroll_target", "The selected combatant is unavailable.")
	var healing_spell := _is_source_backed_combat_healing_spell(spell)
	var ordinary_spell := spell.special == 0 and absi(spell.damage_type) >= 1 and absi(spell.damage_type) <= 6 and absi(spell.spell_class) != 9
	if spell.target_type not in [0, 1, 2, 3, 4, 5, 9, 10, 12] or (not ordinary_spell and not healing_spell):
		return CombatSpellCastProbe.blocked(&"unsupported_combat_scroll", "This scroll's Classic combat effect is not implemented yet.")
	if repeated_target and spell.size != 0:
		return CombatSpellCastProbe.blocked(&"repeated_open_space_spell_unresolved", "Classic target type 0 with nonzero size selects open-space footprints for summoning or special behavior, not ordinary actors.")
	if spell.queue_icon != 0:
		return CombatSpellCastProbe.blocked(&"queued_spell_field_unresolved", "This scroll creates a persistent Classic battlefield field whose collision lifecycle is not implemented.")
	if area_target and spell.can_rotate:
		return CombatSpellCastProbe.blocked(&"rotatable_area_spell_unresolved", "Classic rotatable area masks require a separate orientation-selection contract.")
	if area_target and rotation != 0:
		return CombatSpellCastProbe.blocked(&"invalid_area_rotation", "This non-rotating Classic area spell requires rotation zero.")
	if not healing_spell and spell.damage_min == 0 and spell.damage_max == 0 and spell.power_damage_min == 0 and spell.power_damage_max == 0:
		return CombatSpellCastProbe.blocked(&"unsupported_combat_scroll", "A zero-damage scroll requires its source-backed special-effect path.")
	var cast_level := spell.classic_tier()
	if cast_level < 0 or cast_level > 6:
		return CombatSpellCastProbe.blocked(&"invalid_classic_spell_tier", "The scroll spell ID does not encode a valid Classic tier.")

			character_targets.append(character)
	for monster: MonsterState in combat.monsters():
		if monster.current_health <= 0 or not combat.battlefield.has_actor(monster.id):
			continue
		if not _group_target_matches(spell.target_type, monster.traitor, caster.traitor):
			continue
		var definition := content.monster_by_id(monster.definition_id)
		if definition == null:
			return CombatFlowResult.failed(&"spell_target_unavailable", "A group spell target has no immutable monster definition.")
		monster_targets.append(monster)
		monster_definitions.append(definition)
	var group := _rules.magic.resolve_character_group_spell(caster, character_targets, monster_targets, monster_definitions, spell, power_level, cast_level, rng)
	if group == null or not group.cast:
		return CombatFlowResult.failed(&"spell_cast_failed", "The group spell could not be cast with the available spell points.")
	return _commit_character_multi_spell(state, content, caster, spell, power_level, cast_level, group, rng)


func _cast_character_area_spell(state: GameState, content: RealmzContent, caster: CharacterState, spell: SpellDefinition, power_level: int, cast_level: int, rng: RealmzRng, center: Vector2i, rotation: int) -> CombatFlowResult:
	var combat := state.combat
	var shape := _rules.spell_areas.shape_for(spell, power_level, rotation)
	var selected_ids: Dictionary = {}
	for offset: Vector2i in _rules.spell_areas.pattern(shape):
		var actor_id := combat.battlefield.actor_at(center + offset)
		if not actor_id.is_empty():
			selected_ids[actor_id] = true
	var character_targets: Array[CharacterState] = []
	var monster_targets: Array[MonsterState] = []
	var monster_definitions: Array[MonsterDefinition] = []
	for character: CharacterState in state.party.characters():
		if not selected_ids.has(character.id) or character.current_health <= 0 or not combat.battlefield.has_actor(character.id):
			continue
		if character.conditions.is_active(ConditionRules.REFLECTING_SPELLS):
			return CombatFlowResult.failed(&"area_spell_reflection_unresolved", "This area intersects a spell-reflecting character; Classic reflection targeting remains unresolved.")
		character_targets.append(character)
	for monster: MonsterState in combat.monsters():
		if not selected_ids.has(monster.id) or monster.current_health <= 0 or not combat.battlefield.has_actor(monster.id):
			continue
		if monster.conditions.is_active(ConditionRules.REFLECTING_SPELLS):
			return CombatFlowResult.failed(&"area_spell_reflection_unresolved", "This area intersects a spell-reflecting monster; Classic reflection targeting remains unresolved.")
		# spelltargets.c removes over-100 magic resistance before resolvespell.
		if monster.magic_resistance > 100:
			continue
		var definition := content.monster_by_id(monster.definition_id)
		if definition == null:
			return CombatFlowResult.failed(&"spell_target_unavailable", "An area spell target has no immutable monster definition.")
		monster_targets.append(monster)
		monster_definitions.append(definition)
	_prepare_character_turn(combat, caster)
	var area := _rules.magic.resolve_character_group_spell(caster, character_targets, monster_targets, monster_definitions, spell, power_level, cast_level, rng, true)
	if area == null or not area.cast:
		return CombatFlowResult.failed(&"spell_cast_failed", "The area spell could not be cast with the available spell points.")
	return _commit_character_multi_spell(state, content, caster, spell, power_level, cast_level, area, rng, center, shape)


func _commit_character_multi_spell(state: GameState, content: RealmzContent, caster: CharacterState, spell: SpellDefinition, power_level: int, cast_level: int, group: GroupSpellResolution, rng: RealmzRng, center: Vector2i = Vector2i(-100_000, -100_000), shape: int = 0, event_source: String = "classic", item_instance_id: String = "", count_spell_cast: bool = true) -> CombatFlowResult:
	var combat := state.combat
	if count_spell_cast:
		combat.active_turn.spell_cast_count += 1
	caster.attacks_remaining = _rules.arithmetic.signed_16(caster.attacks_remaining - 2)
	caster.movement = maxi(0, caster.movement - 12)
	var events: Array[DomainEvent] = []
	_append_spell_sound(events, spell.sound_start, "classic-combat-spell-start")
	_append_spell_cast_event(events, caster.id, spell, group, center, shape, event_source)
	for index: int in group.resolutions.size():
		var resolution := group.resolutions[index]
		var resolved_target_id := group.target_ids[index]
		var selected_target_id := group.selected_target_ids[index]
		var target_kind := group.target_kinds[index]
		var reflected := group.reflected_targets[index]
		if resolution.damage > 0 or (resolution.damage < 0 and target_kind == &"monster"):
			combat.mark_attacked(resolved_target_id)
		_append_spell_projectile_event(events, caster.id, resolved_target_id, spell, event_source)
		_append_spell_sound(events, spell.sound_end, "classic-combat-spell-result")
		var payload := {"actorId": caster.id, "targetId": resolved_target_id, "selectedTargetId": selected_target_id, "targetKind": String(target_kind), "spellId": spell.id, "targetType": spell.target_type, "power": power_level, "classicTier": cast_level, "reflected": reflected, "resisted": resolution.resisted, "saved": resolution.saved, "damage": resolution.damage, "healing": maxi(0, -resolution.damage), "duration": resolution.duration, "defeated": resolution.target_defeated, "source": event_source}
		_append_spell_presentation(payload, spell, index, group.resolutions.size(), resolution.target_defeated)
		if not item_instance_id.is_empty():
			payload["itemInstanceId"] = item_instance_id
		if shape > 0:
			payload["areaCenter"] = [center.x, center.y]
			payload["areaShape"] = shape
		events.append(DomainEvent.new(&"combat_spell_resolved", payload))
		if not resolution.target_defeated:
			continue
		if target_kind == &"character":
			_remove_defeated_position(combat, resolved_target_id, true)
		else:
			var defeated_monster := combat.monster_by_id(resolved_target_id)
			var defeated_definition := content.monster_by_id(defeated_monster.definition_id) if defeated_monster != null else null
			var queued := _queue_spell_death_macro(combat, defeated_monster, defeated_definition)
			_remove_defeated_position(combat, resolved_target_id, not queued)
	var advances_turn := not _character_can_continue(caster)
	if not combat.pending_spell_death_macro_id().is_empty():
		if not combat.begin_spell_death_macro_sequence(caster.id, advances_turn) or not _request_next_spell_death_macro(combat, content, events):
			return CombatFlowResult.failed(&"invalid_spell_death_macro_queue", "The multi-target spell death-macro queue could not retain its caster and source order.")
		return CombatFlowResult.succeeded(events)
	if advances_turn:
		_advance_turn(state, rng, events)
	if _finish_if_resolved(state, content, events):
		return CombatFlowResult.succeeded(events, true)
	_process_monster_turns(state, content, rng, events)
	return CombatFlowResult.succeeded(events, state.combat.completed)


static func _append_spell_sound(events: Array[DomainEvent], authored_sound_id: int, source: String) -> void:
	var native_sound_id := authored_sound_id + 600
	if native_sound_id == 0:
		return
	events.append(DomainEvent.new(&"sound_requested", {"soundId": absi(native_sound_id), "waitForCompletion": native_sound_id < 0, "source": source}))


static func _append_spell_cast_event(events: Array[DomainEvent], actor_id: String, spell: SpellDefinition, resolutions: GroupSpellResolution, center: Vector2i, shape: int, source: String) -> void:
	var target_id := resolutions.target_ids[0] if not resolutions.target_ids.is_empty() else ""
	var payload := {"actorId": actor_id, "targetId": target_id, "spellId": spell.id, "classicEffectResourceId": 11_992 + spell.look_start * 8, "source": source}
	if shape > 0:
		payload["areaCenter"] = [center.x, center.y]
		payload["areaShape"] = shape
	events.append(DomainEvent.new(&"combat_spell_cast", payload))


static func _append_spell_projectile_event(events: Array[DomainEvent], actor_id: String, target_id: String, spell: SpellDefinition, source: String) -> void:
	if not spell.target_type in [0, 1, 2, 5, 6, 7, 8, 11]:
		return
	events.append(DomainEvent.new(&"combat_spell_projectile", {"actorId": actor_id, "targetId": target_id, "spellId": spell.id, "classicBattleTileId": 200 + spell.look_start, "source": source}))


static func _append_spell_presentation(payload: Dictionary, spell: SpellDefinition, sequence_index: int, sequence_count: int, target_defeated: bool) -> void:
	payload["castSequenceIndex"] = sequence_index
	payload["castSequenceCount"] = sequence_count
	# resolvespell.c bypasses the ordinary eight-frame resolution effect when the
	# target dies, and group-body flashes (9/10) use a separate path.
	if target_defeated or spell.target_type in [9, 10]:
		return
	var first_resource_id := 12_032 if spell.look_end == 0 else 11_992 + spell.look_end * 8
	var effect_ids: Array[int] = []
	for frame_offset: int in 8:
		effect_ids.append(first_resource_id + frame_offset)
	payload["classicResolutionEffectResourceIds"] = effect_ids


func probe_character_spell_cast(state: GameState, content: RealmzContent, caster_id: String, target_id: String, spell_id: String, power_level: int, target_coordinate: Vector2i = INVALID_COORDINATE, rotation: int = 0, target_ids: Array[String] = []) -> CombatSpellCastProbe:
	if state == null or content == null:
		return CombatSpellCastProbe.blocked(&"invalid_spell_turn", "Spell casting requires an active game session.")
	var combat := state.combat
	if combat == null or combat.completed or combat.battlefield == null or combat.active_actor_id() != caster_id:
		return CombatSpellCastProbe.blocked(&"invalid_spell_turn", "The caster does not own an active combat turn.")
	if not combat.pending_spell_death_macro_id().is_empty():
		return CombatSpellCastProbe.blocked(&"spell_death_macro_pending", "A spell-triggered monster death macro must complete before another combat action.")
	var caster := state.party.character_by_id(caster_id)
	var spell := content.spell_by_id(spell_id)
	if caster == null or caster.current_health <= 0 or caster.traitor or spell == null or power_level < 1 or power_level > 7:
		return CombatSpellCastProbe.blocked(&"invalid_spell_target", "The spell, caster, power, or target is unavailable.")
	var repeated_target := spell.target_type == 0
	var group_target := spell.target_type in [9, 10, 12]
	var area_target := spell.target_type in [3, 4]
	var actor_target := not repeated_target and not group_target and not area_target
	var actor_selection := _spell_target_selection(state, content, target_id) if actor_target else null
	if actor_target and actor_selection == null:
		return CombatSpellCastProbe.blocked(&"invalid_spell_target", "The spell, caster, power, or target is unavailable.")
	if not caster.known_spells().has(spell.id):
		return CombatSpellCastProbe.blocked(&"spell_not_known", "The caster does not know '%s'." % spell.id)

func initiative_order(characters: Array[CharacterState], monsters: Array[MonsterState], surprise: int, rng: RealmzRng) -> Array[String]:
	var order: Array[String] = []
	for character: CharacterState in characters:
		if character.current_health > 0:
			order.append(character.id)
	for monster: MonsterState in monsters:
		if monster.current_health > 0:
			order.append(monster.id)
	if surprise > 0:
		return _party_first(order, characters)
	if surprise < 0:
		return _monsters_first(order, monsters)
	for index: int in range(order.size() - 1, 0, -1):
		var swap_index := rng.draw_between(0, index, &"combat.initiative.slot")
		var held := order[index]
		order[index] = order[swap_index]
		order[swap_index] = held
	for left: int in order.size():
		for right: int in range(left, order.size() - 1):
			if _agility(order[right + 1], characters, monsters) > _agility(order[right], characters, monsters):
				var held := order[right]
				order[right] = order[right + 1]
				order[right + 1] = held
	return order


func _attacker_condition_modifier(conditions: ConditionSet) -> int:
	var modifier := 0
	modifier -= absi(conditions.value(ConditionRules.TANGLED))
	modifier += 15 if conditions.is_active(ConditionRules.STRONG) else 0
	modifier -= 15 if conditions.is_active(ConditionRules.SLOW) else 0
	modifier -= 10 if conditions.is_active(ConditionRules.CONFUSED) else 0
	modifier -= 15 if conditions.is_active(ConditionRules.BLIND) else 0
	modifier += 5 if conditions.is_active(ConditionRules.MAGIC_AURA) else 0
	modifier -= 5 if conditions.is_active(ConditionRules.CURSED) else 0
	modifier -= absi(conditions.value(ConditionRules.HINDERED_ATTACKS))
	return modifier


func _defender_condition_modifier(conditions: ConditionSet, include_protection_from_evil: bool = true) -> int:
	var modifier := -2 * absi(conditions.value(ConditionRules.SHIELD_FROM_HITS))
	modifier += 10 if conditions.is_active(ConditionRules.CONFUSED) else 0
	modifier += 15 if conditions.is_active(ConditionRules.BLIND) else 0
	modifier += 15 if conditions.is_active(ConditionRules.SLOW) else 0
	modifier -= 5 if conditions.is_active(ConditionRules.MAGIC_AURA) else 0
	modifier += 5 if conditions.is_active(ConditionRules.CURSED) else 0
	modifier -= 10 if conditions.is_active(ConditionRules.INVISIBLE) else 0
	modifier += absi(conditions.value(ConditionRules.TANGLED))
	modifier += absi(conditions.value(ConditionRules.HINDERED_DEFENSE))
	modifier -= absi(conditions.value(ConditionRules.DEFENSE_BONUS))
	modifier -= 10 if include_protection_from_evil and conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL) else 0
	return modifier


func _agility(id: String, characters: Array[CharacterState], monsters: Array[MonsterState]) -> int:
	for character: CharacterState in characters:
		if character.id == id:
			return character.agility
	for monster: MonsterState in monsters:
		if monster.id == id:
			return monster.agility
	return 0


func _party_first(order: Array[String], characters: Array[CharacterState]) -> Array[String]:
	var party_ids: Dictionary = {}
	for character: CharacterState in characters:
		party_ids[character.id] = true
	var first: Array[String] = []
	var last: Array[String] = []
	for id: String in order:
		if party_ids.has(id):
			first.append(id)
		else:
			last.append(id)
	first.append_array(last)
	return first


func _monsters_first(order: Array[String], monsters: Array[MonsterState]) -> Array[String]:
	var monster_ids: Dictionary = {}
	for monster: MonsterState in monsters:
		monster_ids[monster.id] = true
	var first: Array[String] = []
	var last: Array[String] = []
	for id: String in order:
		if monster_ids.has(id):
			first.append(id)
		else:
			last.append(id)
	first.append_array(last)
	return first


static func _signed_16(value: int) -> int:
	var wrapped := value & 0xffff
	return wrapped - 0x10000 if wrapped >= 0x8000 else wrapped


static func _signed_32(value: int) -> int:
	var wrapped := value & 0xffffffff
	return wrapped - 0x100000000 if wrapped >= 0x80000000 else wrapped

	var attacks := attacker_definition.attacks()
	var attack := _monster_attack_row(attacks, attack_index)
	var damage := attacker_definition.damage_bonus + attacker.conditions.value(ConditionRules.ATTACK_BONUS)
	if attacker.conditions.is_active(ConditionRules.STRONG):
		damage += 3
	var effects: Array[Dictionary] = []
	var elemental_damage := 0
	if helpless:
		damage = defender.current_health
	elif attack_context.attacker_weapon != null:
		damage += attack_context.attacker_weapon.damage_bonus
		damage += rng.draw(maxi(1, attack_context.attacker_weapon.vs_small), &"combat.monster-attack.weapon-physical")
		elemental_damage = _roll_weapon_elements_monster(attack_context.attacker_weapon, defender, defender_definition, rng, effects)
		elemental_damage += _roll_monster_weapon_type_damage(attack_context.attacker_weapon, defender_definition, rng, effects)
	else:
		damage += rng.draw_between(attack.damage_min, attack.damage_max, &"combat.monster-attack.damage")
	damage = maxi(0, damage)
	var resolution := AttackResolution.new(true, defender.current_health - damage - elemental_damage <= 0, chance, roll, damage + elemental_damage)
	_with_monster_fumble_roll(resolution, fumble_roll)
	resolution.physical_damage = damage
	resolution.weapon_effects = effects
	if attack.special != 0:
		resolution.special_code = attack.special
		var potency_low := int(float(attacker.hit_dice) / 2.0)
		resolution.special_potency = maxi(1, rng.draw_between(potency_low, attacker.hit_dice, &"combat.monster-attack.special-potency"))
		if _is_status_special(attack.special):
			resolution.special_handled = true
			resolution.special_save_index = _status_save_index(attack.special)
			resolution.special_condition_index = _status_condition_index(attack.special)
			resolution.special_condition_before = defender.conditions.value(resolution.special_condition_index)
			resolution.special_condition_after = resolution.special_condition_before
		elif _is_resource_special(attack.special):
			resolution.special_handled = true
			resolution.special_save_index = _resource_save_index(attack.special)
			resolution.special_resource = &"spell_points" if attack.special == 8 else &"experience"
		elif attack.special == 17:
			resolution.special_handled = true
		elif attack.special == 10:
			resolution.special_handled = true
			resolution.special_save_index = 0
			resolution.special_allegiance_before = defender.traitor
			resolution.special_allegiance_after = defender.traitor
		elif _is_elemental_special(attack.special):
			resolution.special_handled = true
			resolution.special_save_index = attack.special - 10
			resolution.special_condition_index = _elemental_condition_index(attack.special)
			resolution.special_element = _elemental_name(attack.special)
		elif attack.special in [18, 19]:
			resolution.special_handled = true
			resolution.special_save_index = 7
			resolution.special_condition_index = ConditionRules.BLIND if attack.special == 18 else ConditionRules.TURNED_TO_STONE
		if defender.magic_resistance > 100:
			resolution.special_blocked = true
			resolution.special_block_reason = &"magic_resistance"
			resolution.hit = false
			resolution.damage = 0
			resolution.killed = false
			return resolution
	if _is_status_special(attack.special):
		_apply_monster_status_special(resolution, defender, defender_definition, rng)
	elif attack.special == 8:
		_apply_monster_spell_drain(resolution, attacker, defender, defender_definition, rng)
	elif attack.special == 9:
		resolution.special_blocked = true
		resolution.special_block_reason = &"party_target_only"
	elif attack.special == 10:
		_apply_monster_charm_special(resolution, attacker, defender, defender_definition, rng)
	elif _is_elemental_special(attack.special):
		_apply_monster_elemental_special(resolution, attack, defender, defender_definition, rng)
	elif attack.special == 17:
		resolution.special_handled = true
	elif attack.special in [18, 19]:
		_apply_monster_permanent_affliction(resolution, defender, defender_definition, rng)
	_apply_weapon_condition_monster(defender, condition_roll, resolution)
	if not resolution.physical_damage_skipped:
		defender.current_health -= damage + elemental_damage + resolution.special_damage_amount
		resolution.killed = defender.current_health <= 0
	return resolution


static func _blocked_monster_attack(reason: StringName, chance: int = 0, roll: int = 0) -> AttackResolution:
	var resolution := AttackResolution.new(false, false, chance, roll, 0)
	resolution.blocked = true
	resolution.block_reason = reason
	return resolution


static func _monster_fumble_roll(attacker: MonsterState, rng: RealmzRng, allow_fumbles: bool) -> int:
	return rng.draw(600 + 50 * attacker.hit_dice, &"combat.monster-attack.fumble") if allow_fumbles else 0


static func _monster_fumbled(weapon: ItemDefinition, roll: int) -> bool:
	return weapon != null and roll > 20 and roll < 35


static func _with_monster_fumble_roll(resolution: AttackResolution, roll: int) -> AttackResolution:
	if resolution != null:
		resolution.fumble_roll = roll
	return resolution


static func _monster_attack_base_chance(attacker: MonsterState, definition: MonsterDefinition, context: MonsterAttackContext) -> int:
	var chance := 50 + 5 * attacker.hit_dice + 5 * definition.damage_bonus
	chance += 20 if context.behind else 0
	chance += int(float(context.realmz_day) / 70.0)
	if context.attacker_weapon != null:
		chance += 5 * context.attacker_weapon.damage_bonus
		if context.attacker_weapon.special_1 == 121:
			chance += 5 * context.attacker_weapon.damage_bonus
	return chance


static func _monster_weapon_auto_hits(weapon: ItemDefinition) -> bool:
	return weapon != null and weapon.special_1 == 120


static func _monster_attack_row(attacks: Array[MonsterAttackDefinition], attack_index: int) -> MonsterAttackDefinition:
	if attacks.is_empty():
		return MonsterAttackDefinition.new(1, 1)
	var selected := attacks[clampi(attack_index, 0, attacks.size() - 1)]
	if selected.damage_min == 0:
		return attacks[0]
	return selected


static func _monster_required_weapon_reason(weapon: ItemDefinition, defender: MonsterDefinition) -> StringName:
	if defender.required_weapon == 0:
		return &""
	if weapon == null:
		if defender.required_weapon == -1:
			return &"classic_blunt_weapon_required"
		if defender.required_weapon == -2:
			return &"classic_sharp_weapon_required"
		return &"classic_specific_weapon_required"
	if defender.required_weapon == -1:
		return &"" if weapon.blunt == -1 else &"classic_blunt_weapon_required"
	if defender.required_weapon == -2:
		return &"" if weapon.blunt == -2 else &"classic_sharp_weapon_required"
	var required_item_id := defender.required_weapon & 0xff
	return &"" if weapon.classic_id == required_item_id else &"classic_specific_weapon_required"


static func _roll_monster_weapon_type_damage(weapon: ItemDefinition, defender: MonsterDefinition, rng: RealmzRng, effects: Array[Dictionary]) -> int:
	var total := 0
	var ranges: Array[int] = [weapon.vs_undead, weapon.vs_demon_devil, weapon.vs_evil]
	var names: Array[StringName] = [&"undead", &"demon-devil", &"evil"]
	var flags: Array[int] = [1, 2, 4]
	for index: int in 3:
		if ranges[index] == 0 or not defender.type_flag(flags[index]):
			continue
		var amount := rng.draw(ranges[index], StringName("combat.monster-attack.weapon-versus-%s" % names[index]))
		effects.append({"targetType": String(names[index]), "amount": amount})
		total += amount
	return total


func _apply_party_charm_special(resolution: AttackResolution, attacker: MonsterState, defender: CharacterState, rng: RealmzRng, save_bonus: int) -> void:
	resolution.special_handled = true
	resolution.special_save_index = 0
	resolution.special_save_chance = defender.save_value(0) + save_bonus

		if protected:
			effective = int(float(effective) / 2.0)
		var save_roll := rng.draw(100, StringName("combat.attack.weapon-%s-save" % names[index]))
		var save_chance := _monster_save_chance(defender, defender_definition, save_indexes[index])
		var saved := _monster_saved(defender, defender_definition, save_indexes[index], save_roll, save_chance)
		if saved:
			effective = int(float(effective) / 2.0)
		effects.append({"element": String(names[index]), "rolled": rolled, "saveIndex": save_indexes[index], "saveChance": save_chance, "saveRoll": save_roll, "saved": saved, "protected": protected, "amount": effective})
		total += effective
	return total


static func _roll_weapon_elements_character(weapon: ItemDefinition, defender: CharacterState, rng: RealmzRng, effects: Array[Dictionary]) -> int:
	var total := 0
	var ranges: Array[int] = [weapon.heat, weapon.cold, weapon.electric]
	var names: Array[StringName] = [&"fire", &"cold", &"electrical"]
	var save_indexes: Array[int] = [1, 2, 3]
	var conditions: Array[int] = [ConditionRules.FIRE_PROTECTION, ConditionRules.COLD_PROTECTION, ConditionRules.ELECTRICAL_PROTECTION]
	for index: int in 3:
		if ranges[index] == 0:
			continue
		var rolled := rng.draw(ranges[index], StringName("combat.attack.weapon-%s" % names[index]))
		var save_roll := rng.draw(100, StringName("combat.attack.weapon-%s-save" % names[index]))
		var save_chance := defender.save_value(save_indexes[index])
		var saved := save_roll <= save_chance
		var effective := int(float(rolled) / 2.0) if saved else rolled
		var protected := defender.conditions.is_active(conditions[index])
		if protected:
			effective = int(float(effective) / 2.0)
		effects.append({"element": String(names[index]), "rolled": rolled, "saveIndex": save_indexes[index], "saveChance": save_chance, "saveRoll": save_roll, "saved": saved, "protected": protected, "amount": effective})
		total += effective
	return total


func resolve_monster_attack(attacker: MonsterState, attacker_definition: MonsterDefinition, attack_index: int, defender: CharacterState, race: RaceDefinition, caste: CasteDefinition, rng: RealmzRng, charm_save_bonus: int = 0, context: MonsterAttackContext = null, allow_fumbles: bool = false) -> AttackResolution:
	if attacker == null or attacker_definition == null or defender == null or rng == null:
		return null
	var attack_context := context if context != null else MonsterAttackContext.new(null, 0, false, defender.luck)
	var invalid_weapon := _invalid_weapon_reason(attack_context.attacker_weapon)
	if not invalid_weapon.is_empty():
		return _blocked_monster_attack(invalid_weapon)
	var condition_roll := _roll_weapon_condition_character(attack_context.attacker_weapon, defender, rng)
	if condition_roll.get("blocked", false):
		return _blocked_monster_attack(StringName(condition_roll.get("reason", "invalid_weapon_condition")))
	var chance := _monster_attack_base_chance(attacker, attacker_definition, attack_context)
	chance += _attacker_condition_modifier(attacker.conditions)
	if attacker.conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL):
		chance += 10
	chance -= rng.draw_classic(attack_context.defender_luck, &"combat.monster-attack.defender-luck")
	chance -= attack_context.defender_armor if attack_context.defender_armor >= 0 else defender.armor
	chance += _defender_condition_modifier(defender.conditions, false)
	if attacker_definition.type_flag(4) and defender.conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL):
		chance -= 10
	chance = maxi(10, chance)
	var roll := rng.draw(100, &"combat.monster-attack.hit")
	var hit := roll <= chance or _monster_weapon_auto_hits(attack_context.attacker_weapon)
	var helpless := defender.conditions.is_active(ConditionRules.HELPLESS)
	if helpless:
		hit = true
	var fumble_roll := _monster_fumble_roll(attacker, rng, allow_fumbles)
	if _monster_fumbled(attack_context.attacker_weapon, fumble_roll):
		return _fumbled_attack(chance, roll, fumble_roll)
	if not hit:
		return _with_monster_fumble_roll(AttackResolution.new(false, false, chance, roll, 0), fumble_roll)
	var attacks := attacker_definition.attacks()
	var attack := _monster_attack_row(attacks, attack_index)
	var damage := attacker_definition.damage_bonus + attacker.conditions.value(ConditionRules.ATTACK_BONUS)
	if attacker.conditions.is_active(ConditionRules.STRONG):
		damage += 3
	var effects: Array[Dictionary] = []
	var elemental_damage := 0
	if helpless:
		damage = defender.current_health + rng.draw(10, &"combat.monster-attack.helpless-damage")
	elif attack_context.attacker_weapon != null:
		damage += attack_context.attacker_weapon.damage_bonus
		damage += rng.draw(maxi(1, attack_context.attacker_weapon.vs_small), &"combat.monster-attack.weapon-physical")
		elemental_damage = _roll_weapon_elements_character(attack_context.attacker_weapon, defender, rng, effects)
	else:
		damage += rng.draw_between(attack.damage_min, attack.damage_max, &"combat.monster-attack.damage")
	damage = maxi(0, damage)
	var resolution_physical_damage_reduction := 0
	if attack_context.party_dragon_hide and damage > 1:
		var damage_before_dragon_hide := damage
		damage = maxi(1, damage - 5)
		resolution_physical_damage_reduction = damage_before_dragon_hide - damage
	var resolution := AttackResolution.new(true, defender.current_health - damage - elemental_damage <= 0, chance, roll, damage + elemental_damage)
	_with_monster_fumble_roll(resolution, fumble_roll)
	resolution.physical_damage = damage
	resolution.physical_damage_reduction = resolution_physical_damage_reduction
	resolution.physical_feedback_sound_id = 694 if resolution_physical_damage_reduction > 0 else 0
	resolution.weapon_effects = effects
	if attack.special != 0:
		resolution.special_code = attack.special
		var potency_low := int(float(attacker.hit_dice) / 2.0)
		resolution.special_potency = maxi(1, rng.draw_between(potency_low, attacker.hit_dice, &"combat.monster-attack.special-potency"))
	if _is_status_special(attack.special):
		_apply_party_status_special(resolution, defender, rng)
	elif _is_resource_special(attack.special):
		_apply_party_resource_special(resolution, attacker, defender, rng)
	elif attack.special == 10:
		_apply_party_charm_special(resolution, attacker, defender, rng, charm_save_bonus)
	elif _is_elemental_special(attack.special):
		_apply_party_elemental_special(resolution, attack, defender, rng)
	elif attack.special == 17:
		resolution.special_handled = true
		resolution.special_save_index = 7
		resolution.special_save_chance = defender.save_value(7)
		resolution.special_save_roll = rng.draw(100, &"combat.monster-attack.special-save")
		resolution.special_saved = resolution.special_save_roll <= resolution.special_save_chance
		if not resolution.special_saved:
			resolution.special_applied = true
			var age_factor := _signed_16(attack.damage_max * attacker.hit_dice)
			resolution.special_age_days = int(float(race.max_age) * 0.01 * float(age_factor)) if race != null else 0
			if race != null and caste != null:
				resolution.aging = _characters.advance_age_days(defender, race, caste, resolution.special_age_days)
	elif attack.special in [18, 19]:
		_apply_party_permanent_affliction(resolution, defender, rng)
	resolution.damage_deferred = resolution.aging != null and resolution.aging.changed_group()
	if resolution.damage_deferred:
		_record_weapon_condition_character(defender, condition_roll, resolution)
	else:
		_apply_weapon_condition_character(defender, condition_roll, resolution)
	if not resolution.damage_deferred and not resolution.physical_damage_skipped:
		defender.current_health -= damage + elemental_damage + resolution.special_damage_amount
		resolution.killed = defender.current_health <= 0
	return resolution


func resolve_monster_attack_monster(attacker: MonsterState, attacker_definition: MonsterDefinition, attack_index: int, defender: MonsterState, defender_definition: MonsterDefinition, rng: RealmzRng, context: MonsterAttackContext = null, allow_fumbles: bool = false) -> AttackResolution:
	if attacker == null or attacker_definition == null or defender == null or defender_definition == null or rng == null:
		return null
	var attack_context := context if context != null else MonsterAttackContext.new()
	var invalid_weapon := _invalid_weapon_reason(attack_context.attacker_weapon)
	if not invalid_weapon.is_empty():
		return _blocked_monster_attack(invalid_weapon)
	var condition_roll := _roll_weapon_condition_monster(attack_context.attacker_weapon, defender, defender_definition, rng)
	if condition_roll.get("blocked", false):
		return _blocked_monster_attack(StringName(condition_roll.get("reason", "invalid_weapon_condition")))
	var chance := _monster_attack_base_chance(attacker, attacker_definition, attack_context)
	chance += _attacker_condition_modifier(attacker.conditions)
	if attacker.conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL):
		chance += 10
	chance -= defender.armor
	chance += _defender_condition_modifier(defender.conditions, false)
	if attacker_definition.type_flag(4) and defender.conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL):
		chance -= 10
	chance = maxi(10, chance)
	var roll := rng.draw(100, &"combat.monster-attack.hit")
	var hit := roll <= chance or _monster_weapon_auto_hits(attack_context.attacker_weapon)
	var helpless := defender.conditions.is_active(ConditionRules.HELPLESS)
	if helpless:
		hit = true
	var fumble_roll := _monster_fumble_roll(attacker, rng, allow_fumbles)
	if _monster_fumbled(attack_context.attacker_weapon, fumble_roll):
		return _fumbled_attack(chance, roll, fumble_roll)
	if not hit:
		return _with_monster_fumble_roll(AttackResolution.new(false, false, chance, roll, 0), fumble_roll)
	var weapon_requirement := _monster_required_weapon_reason(attack_context.attacker_weapon, defender_definition)
	if not weapon_requirement.is_empty():
		return _with_monster_fumble_roll(_blocked_monster_attack(weapon_requirement, chance, roll), fumble_roll)

	return {"roll": roll, "fumbled": true}


static func _fumbled_attack(chance: int, roll: int, fumble_roll: int) -> AttackResolution:
	var resolution := AttackResolution.new(false, false, chance, roll, 0)
	resolution.fumbled = true
	resolution.fumble_roll = fumble_roll
	return resolution


static func _with_fumble_observation(resolution: AttackResolution, fumble: Dictionary) -> AttackResolution:
	if resolution == null or fumble.is_empty():
		return resolution
	resolution.fumble_roll = int(fumble.get("roll", 0))
	resolution.fumble_block_reason = StringName(fumble.get("blockedReason", &""))
	return resolution


static func _magic_weapon_requirement_reason(attacker: CharacterState, equipment: CharacterCombatEquipment, defender: MonsterDefinition, hit: bool) -> StringName:
	if defender.magic_to_hit <= 0:
		return &""
	if equipment.is_armed():
		if hit and defender.magic_to_hit > equipment.melee_weapon.damage_bonus:
			return &"classic_magic_weapon_required"
		return &""
	if defender.magic_to_hit > attacker.level / 8:
		return &"classic_magic_weapon_required"
	return &""


static func _required_weapon_reason(equipment: CharacterCombatEquipment, defender: MonsterDefinition, hit: bool) -> StringName:
	if not hit or defender.required_weapon == 0:
		return &""
	if not equipment.is_armed():
		if defender.required_weapon == -1:
			return &"classic_blunt_weapon_required"
		if defender.required_weapon == -2:
			return &"classic_sharp_weapon_required"
		return &"classic_specific_weapon_required"
	if defender.required_weapon == -1:
		return &"" if equipment.melee_weapon.blunt == -1 else &"classic_blunt_weapon_required"
	if defender.required_weapon == -2:
		return &"" if equipment.melee_weapon.blunt == -2 else &"classic_sharp_weapon_required"
	# FD-COMBAT-003: Castle's minus-1024 comparison cannot match the shipped
	# 1..999 item IDs. Divinity defines this byte as the ordinary Item Number.
	var required_item_id := defender.required_weapon & 0xff
	return &"" if equipment.melee_weapon.classic_id == required_item_id else &"classic_specific_weapon_required"


static func _invalid_weapon_reason(weapon: ItemDefinition) -> StringName:
	if weapon == null:
		return &""
	if weapon.vs_small < 0 or weapon.vs_large < 0 or weapon.heat < 0 or weapon.cold < 0 or weapon.electric < 0 or weapon.vs_undead < 0 or weapon.vs_demon_devil < 0 or weapon.vs_evil < 0:
		return &"unsupported_negative_weapon_range"
	if weapon.special_1 == -10:
		if weapon.special_3 < 20 or weapon.special_3 >= 60:
			return &"invalid_weapon_condition"
		if weapon.special_2 == 1 and (weapon.special_4 < 0 or weapon.special_4 >= 8):
			return &"invalid_weapon_condition_save"
	return &""


func _roll_weapon_condition_monster(weapon: ItemDefinition, defender: MonsterState, defender_definition: MonsterDefinition, rng: RealmzRng) -> Dictionary:
	if weapon == null or weapon.special_1 != -10:
		return {}
	var result := {"index": weapon.special_3 - 20, "amount": weapon.special_5, "applies": false}
	match weapon.special_2:
		1:
			var roll := rng.draw(100, &"combat.attack.weapon-condition-save")
			var chance := _monster_save_chance(defender, defender_definition, weapon.special_4)
			result["saveIndex"] = weapon.special_4
			result["saveChance"] = chance
			result["saveRoll"] = roll
			result["applies"] = not _monster_saved(defender, defender_definition, weapon.special_4, roll, chance)
		2:
			var roll := rng.draw(100, &"combat.attack.weapon-condition-chance")
			result["chance"] = weapon.special_4
			result["roll"] = roll
			result["applies"] = roll <= weapon.special_4
		_:
			result["applies"] = true
	return result


static func _roll_weapon_condition_character(weapon: ItemDefinition, defender: CharacterState, rng: RealmzRng) -> Dictionary:
	if weapon == null or weapon.special_1 != -10:
		return {}
	var result := {"index": weapon.special_3 - 20, "amount": weapon.special_5, "applies": false}
	match weapon.special_2:
		1:
			var roll := rng.draw(100, &"combat.attack.weapon-condition-save")
			result["saveIndex"] = weapon.special_4
			result["saveChance"] = defender.save_value(weapon.special_4)
			result["saveRoll"] = roll
			result["applies"] = roll > defender.save_value(weapon.special_4)
		2:
			var roll := rng.draw(100, &"combat.attack.weapon-condition-chance")
			result["chance"] = weapon.special_4
			result["roll"] = roll
			result["applies"] = roll <= weapon.special_4
		_:
			result["applies"] = true
	return result


static func _apply_weapon_condition_monster(defender: MonsterState, condition_roll: Dictionary, resolution: AttackResolution) -> void:
	if condition_roll.is_empty() or not condition_roll.get("applies", false):
		return
	var index := int(condition_roll["index"])
	resolution.weapon_condition_index = index
	resolution.weapon_condition_before = defender.conditions.value(index)
	resolution.weapon_condition_after = resolution.weapon_condition_before
	if resolution.weapon_condition_before > -1:
		resolution.weapon_condition_after += int(condition_roll["amount"])
		defender.conditions.set_value(index, resolution.weapon_condition_after)


static func _apply_weapon_condition_character(defender: CharacterState, condition_roll: Dictionary, resolution: AttackResolution) -> void:
	_record_weapon_condition_character(defender, condition_roll, resolution)
	if resolution.weapon_condition_index >= 0:
		defender.conditions.set_value(resolution.weapon_condition_index, resolution.weapon_condition_after)


static func _record_weapon_condition_character(defender: CharacterState, condition_roll: Dictionary, resolution: AttackResolution) -> void:
	if condition_roll.is_empty() or not condition_roll.get("applies", false):
		return
	var index := int(condition_roll["index"])
	resolution.weapon_condition_index = index
	resolution.weapon_condition_before = defender.conditions.value(index)
	resolution.weapon_condition_after = resolution.weapon_condition_before
	if resolution.weapon_condition_before > -1:
		resolution.weapon_condition_after += int(condition_roll["amount"])


static func _roll_weapon_physical(weapon: ItemDefinition, defender_definition: MonsterDefinition, rng: RealmzRng) -> int:
	var damage := 0
	if defender_definition != null:
		if weapon.vs_undead != 0 and defender_definition.type_flag(1):
			damage += rng.draw(maxi(1, weapon.vs_undead), &"combat.attack.weapon-versus-undead")
		if weapon.vs_demon_devil != 0 and defender_definition.type_flag(2):
			damage += rng.draw(maxi(1, weapon.vs_demon_devil), &"combat.attack.weapon-versus-demon-devil")
		if weapon.vs_evil != 0 and defender_definition.type_flag(4):
			damage += rng.draw(maxi(1, weapon.vs_evil), &"combat.attack.weapon-versus-evil")
	# Castle's player melee path always uses the small-target weapon die, including Rand(0).
	damage += rng.draw(maxi(1, weapon.vs_small), &"combat.attack.weapon-physical")
	return damage


func _roll_weapon_elements_monster(weapon: ItemDefinition, defender: MonsterState, defender_definition: MonsterDefinition, rng: RealmzRng, effects: Array[Dictionary]) -> int:
	var total := 0
	var ranges: Array[int] = [weapon.heat, weapon.cold, weapon.electric]
	var names: Array[StringName] = [&"fire", &"cold", &"electrical"]
	var save_indexes: Array[int] = [1, 2, 3]
	var conditions: Array[int] = [ConditionRules.FIRE_PROTECTION, ConditionRules.COLD_PROTECTION, ConditionRules.ELECTRICAL_PROTECTION]
	for index: int in 3:
		if ranges[index] == 0 or defender_definition.spell_immune(save_indexes[index]):
			continue
		var rolled := rng.draw(ranges[index], StringName("combat.attack.weapon-%s" % names[index]))
		var effective := rolled
		var protected := defender.conditions.is_active(conditions[index])

class_name CombatRules
extends RefCounted

var _conditions: ConditionRules
var _characters: CharacterRules


func _init(condition_rules: ConditionRules, character_rules: CharacterRules) -> void:
	_conditions = condition_rules
	_characters = character_rules


func resolve_character_attack(attacker: CharacterState, equipment: CharacterCombatEquipment, defender: MonsterState, defender_definition: MonsterDefinition, rng: RealmzRng, realmz_day: int = 0, behind: bool = false, allow_fumbles: bool = false, can_queue_fumble: bool = true) -> AttackResolution:
	if attacker == null or equipment == null or not equipment.valid or defender == null or defender_definition == null or rng == null:
		return null
	var invalid_weapon := _invalid_weapon_reason(equipment.melee_weapon)
	if not invalid_weapon.is_empty():
		return _blocked_character_attack(invalid_weapon)
	var condition_roll := _roll_weapon_condition_monster(equipment.melee_weapon, defender, defender_definition, rng)
	if condition_roll.get("blocked", false):
		return _blocked_character_attack(StringName(condition_roll.get("reason", "invalid_weapon_condition")))
	var type_damage := 0
	var chance := 50 + attacker.to_hit + (20 if behind else 0) + 5 * equipment.equipped_damage_bonus
	if equipment.melee_weapon != null and equipment.melee_weapon.special_1 == 121:
		chance += 5 * equipment.melee_weapon.damage_bonus
	chance += _attacker_condition_modifier(attacker.conditions)
	if defender_definition.type_flag(4) and attacker.conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL):
		chance += 10
	chance += rng.draw_classic(equipment.effective_luck, &"combat.attack.luck")
	for index: int in 8:
		if defender_definition.type_flag(index):
			chance += 5 * attacker.special_value(index)
			type_damage += attacker.special_value(index)
	chance -= defender.armor
	chance += _defender_condition_modifier(defender.conditions, true)
	chance -= int(float(maxi(0, realmz_day)) / 120.0)
	chance = maxi(5, chance)
	var roll := rng.draw(100, &"combat.attack.hit")
	var hit := roll <= chance or defender.conditions.is_active(ConditionRules.HELPLESS)
	var fumble := _character_fumble(attacker, equipment, rng, allow_fumbles, can_queue_fumble)
	if fumble.get("fumbled", false):
		return _fumbled_attack(chance, roll, int(fumble["roll"]))
	var magic_requirement := _magic_weapon_requirement_reason(attacker, equipment, defender_definition, hit)
	if not magic_requirement.is_empty():
		return _with_fumble_observation(_blocked_character_attack(magic_requirement, chance, roll), fumble)
	var weapon_requirement := _required_weapon_reason(equipment, defender_definition, hit)
	if not weapon_requirement.is_empty():
		return _with_fumble_observation(_blocked_character_attack(weapon_requirement, chance, roll), fumble)
	if equipment.melee_weapon != null and equipment.melee_weapon.special_1 == 120:
		hit = true
	if not hit:
		return _with_fumble_observation(AttackResolution.new(false, false, chance, roll, 0), fumble)
	var reflected := defender.conditions.is_active(ConditionRules.REFLECTING_ATTACKS) and rng.draw(100, &"combat.attack.reflect") < 34
	var physical_damage := type_damage + equipment.effective_damage_bonus + attacker.conditions.value(ConditionRules.ATTACK_BONUS)
	if attacker.conditions.is_active(ConditionRules.STRONG):
		physical_damage += 3
	var effects: Array[Dictionary] = []
	var elemental_damage := 0
	if equipment.is_armed():
		if reflected:
			elemental_damage = _roll_weapon_elements_character(equipment.melee_weapon, attacker, rng, effects)
		else:
			elemental_damage = _roll_weapon_elements_monster(equipment.melee_weapon, defender, defender_definition, rng, effects)
		physical_damage += _roll_weapon_physical(equipment.melee_weapon, defender_definition if not reflected else null, rng)
	else:
		physical_damage += rng.draw(maxi(1, attacker.hand_to_hand), &"combat.attack.unarmed-damage")
	var critical_rolls: Array[int] = [rng.draw(100, &"combat.attack.sneak-critical"), rng.draw(100, &"combat.attack.major-wound-critical")]
	physical_damage = maxi(0, physical_damage)
	if not reflected and defender.conditions.is_active(ConditionRules.HELPLESS):
		physical_damage = defender.current_health
	elif reflected and attacker.conditions.is_active(ConditionRules.HELPLESS):
		physical_damage = attacker.current_health
	var total_damage := physical_damage + elemental_damage
	var resolution := AttackResolution.new(true, false, chance, roll, total_damage, reflected)
	_with_fumble_observation(resolution, fumble)
	resolution.physical_damage = physical_damage
	resolution.weapon_effects = effects
	resolution.critical_rolls = critical_rolls
	if reflected:
		_apply_weapon_condition_character(attacker, condition_roll, resolution)
		attacker.current_health -= total_damage
		resolution.killed = attacker.current_health <= 0
		return resolution
	_apply_weapon_condition_monster(defender, condition_roll, resolution)
	defender.current_health -= total_damage
	resolution.killed = defender.current_health <= 0
	return resolution


func resolve_character_attack_character(attacker: CharacterState, attacker_equipment: CharacterCombatEquipment, defender: CharacterState, defender_equipment: CharacterCombatEquipment, rng: RealmzRng, behind: bool = false, allow_fumbles: bool = false, can_queue_fumble: bool = true) -> AttackResolution:
	if attacker == null or attacker_equipment == null or not attacker_equipment.valid or defender == null or defender_equipment == null or not defender_equipment.valid or rng == null:
		return null
	var invalid_weapon := _invalid_weapon_reason(attacker_equipment.melee_weapon)
	if not invalid_weapon.is_empty():
		return _blocked_character_attack(invalid_weapon)
	var condition_roll := _roll_weapon_condition_character(attacker_equipment.melee_weapon, defender, rng)
	if condition_roll.get("blocked", false):
		return _blocked_character_attack(StringName(condition_roll.get("reason", "invalid_weapon_condition")))
	var chance := 50 + attacker.to_hit + (20 if behind else 0) + 5 * attacker_equipment.equipped_damage_bonus
	if attacker_equipment.melee_weapon != null and attacker_equipment.melee_weapon.special_1 == 121:
		chance += 5 * attacker_equipment.melee_weapon.damage_bonus
	chance += _attacker_condition_modifier(attacker.conditions)
	chance += rng.draw_classic(attacker_equipment.effective_luck, &"combat.attack.luck")
	chance -= defender_equipment.effective_armor
	chance += _defender_condition_modifier(defender.conditions, false)
	chance = maxi(5, chance)
	var roll := rng.draw(100, &"combat.attack.hit")
	var hit := roll <= chance or defender.conditions.is_active(ConditionRules.HELPLESS)
	var fumble := _character_fumble(attacker, attacker_equipment, rng, allow_fumbles, can_queue_fumble)
	if fumble.get("fumbled", false):
		return _fumbled_attack(chance, roll, int(fumble["roll"]))
	if attacker_equipment.melee_weapon != null and attacker_equipment.melee_weapon.special_1 == 120:
		hit = true
	if not hit:
		return _with_fumble_observation(AttackResolution.new(false, false, chance, roll, 0), fumble)
	var reflected := defender.conditions.is_active(ConditionRules.REFLECTING_ATTACKS) and rng.draw(100, &"combat.attack.reflect") < 34
	var target := attacker if reflected else defender
	var physical_damage := attacker_equipment.effective_damage_bonus + attacker.conditions.value(ConditionRules.ATTACK_BONUS)
	if attacker.conditions.is_active(ConditionRules.STRONG):
		physical_damage += 3
	var effects: Array[Dictionary] = []
	var elemental_damage := 0
	if attacker_equipment.is_armed():
		elemental_damage = _roll_weapon_elements_character(attacker_equipment.melee_weapon, target, rng, effects)
		physical_damage += _roll_weapon_physical(attacker_equipment.melee_weapon, null, rng)
	else:
		physical_damage += rng.draw(maxi(1, attacker.hand_to_hand), &"combat.attack.unarmed-damage")
	var critical_rolls: Array[int] = [rng.draw(100, &"combat.attack.sneak-critical"), rng.draw(100, &"combat.attack.major-wound-critical")]
	physical_damage = maxi(0, physical_damage)
	if target.conditions.is_active(ConditionRules.HELPLESS):
		physical_damage = target.current_health
	var total_damage := physical_damage + elemental_damage
	var resolution := AttackResolution.new(true, false, chance, roll, total_damage, reflected)
	_with_fumble_observation(resolution, fumble)
	resolution.physical_damage = physical_damage
	resolution.weapon_effects = effects
	resolution.critical_rolls = critical_rolls
	_apply_weapon_condition_character(target, condition_roll, resolution)
	target.current_health -= total_damage
	resolution.killed = target.current_health <= 0
	return resolution


static func _blocked_character_attack(reason: StringName, chance: int = 0, roll: int = 0) -> AttackResolution:
	var resolution := AttackResolution.new(false, false, chance, roll, 0)
	resolution.blocked = true
	resolution.block_reason = reason
	return resolution


static func _character_fumble(attacker: CharacterState, equipment: CharacterCombatEquipment, rng: RealmzRng, allow_fumbles: bool, can_queue_fumble: bool) -> Dictionary:
	if not allow_fumbles:
		return {}
	var roll := rng.draw(1000 + 100 * attacker.level, &"combat.attack.fumble")
	if roll <= 50 or roll >= 60 or not equipment.is_armed():
		return {"roll": roll}
	if not equipment.melee_weapon.cursed_item_id.is_empty():
		return {"roll": roll, "blockedReason": &"cursed_weapon"}
	if not can_queue_fumble:
		return {"roll": roll, "blockedReason": &"fumble_queue_full"}

	if repeated_target:
		if target_ids.size() > scroll.power:
			return CombatSpellCastProbe.blocked(&"too_many_scroll_targets", "A repeated scroll may select at most one distinct actor per power level.")
		var seen: Dictionary = {}
		for selected_id: String in target_ids:
			if selected_id.is_empty() or seen.has(selected_id):
				return CombatSpellCastProbe.blocked(&"invalid_repeated_scroll_targets", "Repeated scroll targets must be nonempty and distinct.")
			seen[selected_id] = true
			if _spell_target_selection(state, content, selected_id) == null:
				return CombatSpellCastProbe.blocked(&"invalid_scroll_target", "A selected repeated-scroll actor is unavailable.")
			if not _spell_actor_target_is_valid(state, content, caster.id, selected_id, spell, scroll.power):
				return CombatSpellCastProbe.blocked(&"scroll_target_unavailable", "A selected repeated-scroll actor is outside the Classic spell range or line of sight.")
		if target_ids.is_empty() and _character_actor_spell_candidates(state, content, caster, spell, scroll.power).is_empty():
			return CombatSpellCastProbe.blocked(&"scroll_target_unavailable", "No actor is available within this repeated scroll's Classic range and line of sight.")
	elif area_target:
		var shape := _rules.spell_areas.shape_for(spell, scroll.power, rotation)
		if _rules.spell_areas.pattern(shape).is_empty():
			return CombatSpellCastProbe.blocked(&"invalid_scroll_area_shape", "The scroll references an unavailable Classic Data AD area mask.")
		if target_coordinate != INVALID_COORDINATE:
			if not _rules.spell_areas.pattern_fits(target_coordinate, shape):
				return CombatSpellCastProbe.blocked(&"scroll_area_outside_battlefield", "The complete Classic area mask must remain inside the validated battlefield.")
			var map := content.world.map_by_id(combat.battlefield.map_id)
			var terrain_set := content.world.battle_terrain_set_by_id(map.battle_terrain_set_id) if map != null else null
			var maximum_range := absi(spell.range_min + spell.range_max * scroll.power)
			if terrain_set == null or not _rules.battlefield.coordinate_target_is_valid(combat.battlefield, terrain_set, caster.id, target_coordinate, maximum_range, spell.range_min + spell.range_max > 0):
				return CombatSpellCastProbe.blocked(&"scroll_target_unavailable", "The area center is outside the Classic spell range or line of sight.")
	elif group_target:
		var group_count := 0
		for character: CharacterState in state.party.characters():
			if character.current_health > 0 and combat.battlefield.has_actor(character.id) and _group_target_matches(spell.target_type, character.traitor, caster.traitor):
				group_count += 1
		for monster: MonsterState in combat.monsters():
			if monster.current_health > 0 and combat.battlefield.has_actor(monster.id) and _group_target_matches(spell.target_type, monster.traitor, caster.traitor):
				group_count += 1
		if group_count == 0:
			return CombatSpellCastProbe.blocked(&"scroll_target_unavailable", "The scroll has no available group target.")
	elif not _spell_actor_target_is_valid(state, content, caster.id, effective_target_id, spell, scroll.power):
		return CombatSpellCastProbe.blocked(&"scroll_target_unavailable", "The target is outside the Classic spell range or line of sight.")
	return CombatSpellCastProbe.permitted()


func use_combat_scroll(state: GameState, content: RealmzContent, caster_id: String, scroll_slot: int, target_id: String, rng: RealmzRng, target_coordinate: Vector2i = INVALID_COORDINATE, rotation: int = 0, target_ids: Array[String] = []) -> CombatFlowResult:
	var probe := probe_character_scroll_cast(state, content, caster_id, scroll_slot, target_id, target_coordinate, rotation, target_ids)
	if not probe.allowed:
		return CombatFlowResult.failed(probe.reason, probe.reason_text)
	var state_checkpoint := state.to_data()
	var rng_checkpoint := rng.checkpoint()
	var caster := state.party.character_by_id(caster_id)
	var scroll := caster.scroll_at(scroll_slot)
	var spell := content.spell_by_id(scroll.spell_id)
	var power_level := scroll.power
	var cast_level := spell.classic_tier()
	_prepare_character_turn(state.combat, caster)
	state.combat.invalidate_undo()
	var result: CombatFlowResult
	if spell.target_type in [3, 4]:
		var shape := _rules.spell_areas.shape_for(spell, power_level, rotation)
		var selected_ids: Dictionary = {}
		for offset: Vector2i in _rules.spell_areas.pattern(shape):
			var actor_id := state.combat.battlefield.actor_at(target_coordinate + offset)
			if not actor_id.is_empty():
				selected_ids[actor_id] = true
		var area_targets := _combat_spell_group_targets(state, content, caster, spell, selected_ids, true)
		if not bool(area_targets.get("ok", false)):
			return _rollback_combat_scroll(state, rng, state_checkpoint, rng_checkpoint, &"scroll_target_unavailable", String(area_targets.get("error", "A scroll target is unavailable.")))
		var area_characters: Array[CharacterState] = area_targets.get("characters", [])
		var area_monsters: Array[MonsterState] = area_targets.get("monsters", [])
		var area_definitions: Array[MonsterDefinition] = area_targets.get("definitions", [])
		var area := _rules.magic.resolve_character_group_spell(caster, area_characters, area_monsters, area_definitions, spell, power_level, cast_level, rng, true, false)
		if area == null or not area.cast:
			return _rollback_combat_scroll(state, rng, state_checkpoint, rng_checkpoint, &"scroll_spell_failed", "The area scroll could not be resolved.")
		result = _commit_character_multi_spell(state, content, caster, spell, power_level, cast_level, area, rng, target_coordinate, shape, "classic-scroll", "", false)
	elif spell.target_type in [9, 10, 12]:
		var group_targets := _combat_spell_group_targets(state, content, caster, spell)
		if not bool(group_targets.get("ok", false)):
			return _rollback_combat_scroll(state, rng, state_checkpoint, rng_checkpoint, &"scroll_target_unavailable", String(group_targets.get("error", "A scroll target is unavailable.")))
		var group_characters: Array[CharacterState] = group_targets.get("characters", [])
		var group_monsters: Array[MonsterState] = group_targets.get("monsters", [])
		var group_definitions: Array[MonsterDefinition] = group_targets.get("definitions", [])
		var group := _rules.magic.resolve_character_group_spell(caster, group_characters, group_monsters, group_definitions, spell, power_level, cast_level, rng, false, false)
		if group == null or not group.cast:
			return _rollback_combat_scroll(state, rng, state_checkpoint, rng_checkpoint, &"scroll_spell_failed", "The group scroll could not be resolved.")
		result = _commit_character_multi_spell(state, content, caster, spell, power_level, cast_level, group, rng, INVALID_COORDINATE, 0, "classic-scroll", "", false)
	elif spell.target_type == 0:
		var selections: Array[SpellTargetSelection] = []
		for selected_id: String in target_ids:
			var selection := _spell_target_selection(state, content, selected_id)
			if selection == null:
				return _rollback_combat_scroll(state, rng, state_checkpoint, rng_checkpoint, &"scroll_target_unavailable", "A repeated-scroll target became unavailable.")
			selections.append(selection)
		var repeated := _rules.magic.resolve_character_repeated_spell(caster, selections, spell, power_level, cast_level, rng, false)
		if repeated == null or not repeated.cast:
			return _rollback_combat_scroll(state, rng, state_checkpoint, rng_checkpoint, &"scroll_spell_failed", "The repeated scroll could not be resolved.")
		result = _commit_character_multi_spell(state, content, caster, spell, power_level, cast_level, repeated, rng, INVALID_COORDINATE, 0, "classic-scroll", "", false)
	else:
		var effective_target_id := caster_id if spell.target_type == 5 else target_id
		var selection := _spell_target_selection(state, content, effective_target_id)
		var targeted := _rules.magic.resolve_character_targeted_spell(caster, selection, spell, power_level, cast_level, rng, false)
		if targeted == null or not targeted.cast:
			return _rollback_combat_scroll(state, rng, state_checkpoint, rng_checkpoint, &"scroll_spell_failed", "The targeted scroll could not be resolved.")
		result = _commit_character_multi_spell(state, content, caster, spell, power_level, cast_level, targeted, rng, INVALID_COORDINATE, 0, "classic-scroll", "", false)
	if not result.ok:
		return _rollback_combat_scroll(state, rng, state_checkpoint, rng_checkpoint, result.error_code, result.error_message)
	var committed_caster := state.party.character_by_id(caster_id)
	if committed_caster == null or not committed_caster.clear_scroll(scroll_slot):
		return _rollback_combat_scroll(state, rng, state_checkpoint, rng_checkpoint, &"scroll_commit_failed", "The resolved scroll could not be removed from its case.")
	var events: Array[DomainEvent] = [DomainEvent.new(&"scroll_used", {"characterId": caster_id, "slot": scroll_slot, "spellId": spell.id, "power": power_level, "source": "classic-combat"})]
	events.append_array(result.events)
	result.events = events
	return result


func _combat_spell_group_targets(state: GameState, content: RealmzContent, caster: CharacterState, spell: SpellDefinition, selected_ids: Dictionary = {}, area_target: bool = false) -> Dictionary:
	var character_targets: Array[CharacterState] = []
	var monster_targets: Array[MonsterState] = []
	var monster_definitions: Array[MonsterDefinition] = []
	for character: CharacterState in state.party.characters():
		if character.current_health <= 0 or not state.combat.battlefield.has_actor(character.id):
			continue
		if area_target:
			if not selected_ids.has(character.id):
				continue
			if character.conditions.is_active(ConditionRules.REFLECTING_SPELLS):
				return {"ok": false, "error": "This area intersects a spell-reflecting character; Classic reflection targeting remains unresolved."}
		elif not _group_target_matches(spell.target_type, character.traitor, caster.traitor):
			continue
		character_targets.append(character)
	for monster: MonsterState in state.combat.monsters():
		if monster.current_health <= 0 or not state.combat.battlefield.has_actor(monster.id):
			continue
		if area_target:
			if not selected_ids.has(monster.id):
				continue
			if monster.conditions.is_active(ConditionRules.REFLECTING_SPELLS):
				return {"ok": false, "error": "This area intersects a spell-reflecting monster; Classic reflection targeting remains unresolved."}
			if monster.magic_resistance > 100:
				continue
		elif not _group_target_matches(spell.target_type, monster.traitor, caster.traitor):
			continue
		var definition := content.monster_by_id(monster.definition_id)
		if definition == null:
			return {"ok": false, "error": "A scroll target has no immutable monster definition."}
		monster_targets.append(monster)
		monster_definitions.append(definition)
	return {"ok": true, "characters": character_targets, "monsters": monster_targets, "definitions": monster_definitions}


func _rollback_combat_scroll(state: GameState, rng: RealmzRng, state_checkpoint: Dictionary, rng_checkpoint: Dictionary, error_code: StringName, error_message: String) -> CombatFlowResult:
	if not state.restore_from_data(state_checkpoint) or not rng.rollback(rng_checkpoint):
		return CombatFlowResult.failed(&"combat_scroll_rollback_failed", "Combat scroll resolution failed and its transaction could not be restored.")
	return CombatFlowResult.failed(error_code, error_message)


func _cast_character_group_spell(state: GameState, content: RealmzContent, caster: CharacterState, spell: SpellDefinition, power_level: int, cast_level: int, rng: RealmzRng) -> CombatFlowResult:
	var combat := state.combat
	var character_targets: Array[CharacterState] = []
	var monster_targets: Array[MonsterState] = []
	var monster_definitions: Array[MonsterDefinition] = []
	for character: CharacterState in state.party.characters():
		if character.current_health > 0 and combat.battlefield.has_actor(character.id) and _group_target_matches(spell.target_type, character.traitor, caster.traitor):

	var movement := definition.movement_max
	var tangled := monster.conditions.value(ConditionRules.TANGLED)
	if tangled > 0:
		movement -= tangled
	if monster.conditions.is_active(ConditionRules.SLOW):
		movement = int(float(movement) / 2.0)
	if monster.conditions.is_active(ConditionRules.SPEEDY):
		movement *= 2
	return maxi(0, movement)


static func _monster_attack_limit(definition: MonsterDefinition) -> int:
	return mini(maxi(0, definition.attack_count), definition.attacks().size())


func _process_charmed_character_turn(state: GameState, content: RealmzContent, actor: CharacterState, rng: RealmzRng, events: Array[DomainEvent]) -> bool:
	var adjacent_ids := _rules.battlefield.adjacent_actor_ids(state.combat.battlefield, actor.id)
	var character_targets: Array[CharacterState] = []
	for candidate: CharacterState in state.party.characters():
		if candidate.id != actor.id and candidate.current_health > 0 and candidate.traitor != actor.traitor and adjacent_ids.has(candidate.id):
			character_targets.append(candidate)
	var monster_targets: Array[MonsterState] = []
	for candidate: MonsterState in state.combat.monsters():
		if candidate.current_health > 0 and candidate.traitor != actor.traitor and adjacent_ids.has(candidate.id):
			monster_targets.append(candidate)
	var target_count := character_targets.size() + monster_targets.size()
	if target_count == 0:
		events.append(DomainEvent.new(&"combat_monster_action_unavailable", {"actorId": actor.id, "action": "advance", "reason": "tactical-movement-not-implemented"}))
		return false
	var target_index := rng.draw_between(0, target_count - 1, &"combat.charmed-target")
	var equipment := _rules.inventory.combat_equipment(actor, content.item_definitions())
	if not equipment.valid:
		events.append(DomainEvent.new(&"combat_attack_blocked", {"actorId": actor.id, "reason": String(equipment.error_code), "message": equipment.error_message}))
		return false
	var active_turn := state.combat.begin_active_turn()
	if active_turn == null:
		return false
	if target_index < character_targets.size():
		var character_target := character_targets[target_index]
		var target_equipment := _rules.inventory.combat_equipment(character_target, content.item_definitions())
		if not target_equipment.valid:
			events.append(DomainEvent.new(&"combat_attack_blocked", {"actorId": actor.id, "targetId": character_target.id, "reason": String(target_equipment.error_code), "message": target_equipment.error_message}))
			return false
		active_turn.physical_action_committed = true
		var character_resolution := _rules.combat.resolve_character_attack_character(actor, equipment, character_target, target_equipment, rng, false, true, state.combat.can_queue_fumbled_item())
		if character_resolution.total_damage() > 0:
			state.combat.mark_attacked(character_target.id)
		if character_resolution.fumbled and not _commit_character_fumble(state, actor, equipment, events):
			events.append(DomainEvent.new(&"combat_fumble_failed", {"actorId": actor.id, "reason": "invalid-fumble-state"}))
			return false
		var character_event := _character_attack_event(actor.id, character_target.id, &"character", character_resolution, equipment.melee_weapon != null)
		_append_character_attack_audio(events, actor, equipment, character_resolution, &"character")
		character_event.payload["automatic"] = true
		events.append(character_event)
		_mark_character_bleeding(state, character_target, character_resolution.killed)
		_remove_defeated_position(state.combat, character_target.id, character_resolution.killed)
		return false
	var monster_target := monster_targets[target_index - character_targets.size()]
	var target_definition := content.monster_by_id(monster_target.definition_id)
	active_turn.physical_action_committed = true
	var resolution := _rules.combat.resolve_character_attack(actor, equipment, monster_target, target_definition, rng, state.clock.day(), false, true, state.combat.can_queue_fumbled_item())
	if resolution.total_damage() > 0:
		state.combat.mark_attacked(monster_target.id)
	if resolution.fumbled and not _commit_character_fumble(state, actor, equipment, events):
		events.append(DomainEvent.new(&"combat_fumble_failed", {"actorId": actor.id, "reason": "invalid-fumble-state"}))
		return false
	var event := _character_attack_event(actor.id, monster_target.id, &"monster", resolution, equipment.melee_weapon != null)
	_append_character_attack_audio(events, actor, equipment, resolution, &"monster")
	event.payload["automatic"] = true
	events.append(event)
	var death_macro_requested := resolution.killed and _request_monster_death_macro(monster_target, target_definition, events)
	_remove_defeated_position(state.combat, monster_target.id, resolution.killed and not death_macro_requested)
	return death_macro_requested


func _hostile_adjacent_ids(state: GameState, actor_id: String, anchor_override: Vector2i = Vector2i(-1, -1)) -> Array[String]:
	var result: Array[String] = []
	if state == null or state.combat == null or state.combat.battlefield == null:
		return result
	var actor_traitor := false
	var character := state.party.character_by_id(actor_id)
	if character != null:
		actor_traitor = character.traitor
	else:
		var monster := state.combat.monster_by_id(actor_id)
		if monster == null:
			return result
		actor_traitor = monster.traitor
	var adjacent_ids := _rules.battlefield.adjacent_actor_ids(state.combat.battlefield, actor_id, anchor_override)
	# Castle scans numeric combat slots: party members first, then monsters in
	# authored runtime order. Stable IDs must not accidentally redefine reactions.
	for candidate_character: CharacterState in state.party.characters():
		if adjacent_ids.has(candidate_character.id) and candidate_character.current_health > 0 and candidate_character.traitor != actor_traitor:
			result.append(candidate_character.id)
	for candidate_monster: MonsterState in state.combat.monsters():
		if adjacent_ids.has(candidate_monster.id) and candidate_monster.current_health > 0 and candidate_monster.traitor != actor_traitor:
			result.append(candidate_monster.id)
	return result


func _hostile_contact_target_id(state: GameState, actor_id: String, destination_or_target: Variant) -> String:
	if state == null or state.combat == null or state.combat.battlefield == null:
		return ""
	var candidate_id := ""
	if destination_or_target is String:
		candidate_id = destination_or_target
	elif destination_or_target is Vector2i:
		candidate_id = state.combat.battlefield.actor_at(destination_or_target, actor_id)
	if candidate_id.is_empty():
		return ""
	var actor := state.party.character_by_id(actor_id)
	if actor == null or actor.current_health <= 0:
		return ""
	var monster := state.combat.monster_by_id(candidate_id)
	if monster != null:
		return candidate_id if monster.current_health > 0 and monster.traitor != actor.traitor else ""
	var character := state.party.character_by_id(candidate_id)
	return candidate_id if character != null and character.current_health > 0 and character.traitor != actor.traitor else ""


static func _remove_defeated_position(combat: CombatState, actor_id: String, defeated: bool) -> void:
	if not defeated or combat == null or combat.battlefield == null:
		return
	if combat.monster_by_id(actor_id) != null:
		combat.battlefield.remove_monster(actor_id)
	else:
		combat.battlefield.remove_character(actor_id)


static func _remove_all_defeated_positions(state: GameState) -> void:
	if state == null or state.combat == null or state.combat.battlefield == null:
		return
	for monster: MonsterState in state.combat.monsters():
		_remove_defeated_position(state.combat, monster.id, monster.current_health <= 0)
	for character: CharacterState in state.party.characters():
		_remove_defeated_position(state.combat, character.id, character.current_health <= 0)


static func _battle_terrain_set(content: RealmzContent, battlefield: BattlefieldState) -> BattleTerrainSetDefinition:
	var map := content.world.map_by_id(battlefield.map_id)
	return null if map == null else content.world.battle_terrain_set_by_id(map.battle_terrain_set_id)


static func _movement_failure_message(result: BattlefieldStepResult) -> String:
	match result.reason:
		&"invalid_direction":
			return "Tactical movement accepts one adjacent eight-direction step."
		&"outside_battlefield":
			return "The destination is outside the Classic battlefield."
		&"occupied":
			return "The destination footprint is occupied by '%s'." % result.occupant_id
		&"solid_terrain":
			return "The destination terrain blocks this combatant."
		&"insufficient_movement":
			return "The step costs %d movement points." % result.movement_cost
		_:
			return "The tactical step is unavailable: %s." % String(result.reason)


static func _character_attack_event(actor_id: String, target_id: String, target_kind: StringName, resolution: AttackResolution, armed: bool) -> DomainEvent:

		var defender_armor := defender_equipment.effective_armor if defender_equipment.valid else character_target.armor
		var monster_attack_context := MonsterAttackContext.new(attack_weapon, state.clock.day(), false, defender_luck, state.party.conditions.is_active(ConditionRules.PARTY_DRAGON_HIDE), defender_armor)
		var monster_resolution := _rules.combat.resolve_monster_attack(monster, definition, attack_index, character_target, race, caste, rng, charm_bonus, monster_attack_context, true)
		if monster_resolution.total_damage() > 0:
			combat.mark_attacked(character_target.id)
		if monster_resolution.fumbled:
			_commit_monster_fumble(monster, events)
		var age_update_requested := false
		if monster_resolution.special_handled:
			_append_monster_special_events(events, monster.id, character_target.id, &"character", monster_resolution)
			if monster_resolution.aging != null and monster_resolution.aging.changed_group():
				events.append(DomainEvent.new(&"character_age_changed", monster_resolution.aging.event_payload(character_target, race)))
				age_update_requested = true
		if age_update_requested:
			combat.pending_monster_attack = PendingMonsterAttack.new(monster.id, character_target.id, active_turn.action, monster_resolution.damage, monster_resolution.chance, monster_resolution.roll, monster_resolution.weapon_condition_index, monster_resolution.weapon_condition_before, monster_resolution.weapon_condition_after, monster_resolution.physical_feedback_sound_id)
			return MONSTER_ATTACK_WAITING
		_append_monster_physical_feedback(events, monster_resolution.physical_feedback_sound_id)
		_append_monster_attack_audio(events, monster, definition, attack_index, attack_weapon, monster_resolution, rng)
		var character_attack_event := DomainEvent.new(&"combat_attack_resolved", {"actorId": monster.id, "targetId": character_target.id, "action": String(active_turn.action), "attackIndex": attack_index, "hit": monster_resolution.hit, "damage": monster_resolution.total_damage(), "defeated": monster_resolution.killed, "chance": monster_resolution.chance, "roll": monster_resolution.roll})
		_append_physical_result_effect(character_attack_event, monster_resolution.hit, attack_weapon != null)
		events.append(character_attack_event)
		_mark_character_bleeding(state, character_target, monster_resolution.killed)
		_remove_defeated_position(combat, character_target.id, monster_resolution.killed)
		if monster_resolution.killed:
			active_turn.target_id = ""
			monster.target_id = ""
		return MONSTER_ATTACK_COMPLETED
	var monster_target := combat.monster_by_id(active_turn.target_id)
	if monster_target == null:
		active_turn.target_id = ""
		return MONSTER_ATTACK_COMPLETED
	var target_definition := content.monster_by_id(monster_target.definition_id)
	var weapon := content.item_by_id(monster.weapon_id) if not monster.weapon_id.is_empty() else null
	var attack_context := MonsterAttackContext.new(weapon, state.clock.day())
	var resolution := _rules.combat.resolve_monster_attack_monster(monster, definition, attack_index, monster_target, target_definition, rng, attack_context, true)
	if resolution.total_damage() > 0:
		combat.mark_attacked(monster_target.id)
	if resolution.fumbled:
		_commit_monster_fumble(monster, events)
	if resolution.special_handled:
		_append_monster_special_events(events, monster.id, monster_target.id, &"monster", resolution)
	_append_monster_attack_audio(events, monster, definition, attack_index, weapon, resolution, rng)
	var monster_attack_event := DomainEvent.new(&"combat_attack_resolved", {"actorId": monster.id, "targetId": monster_target.id, "action": String(active_turn.action), "attackIndex": attack_index, "hit": resolution.hit, "damage": resolution.total_damage(), "defeated": resolution.killed, "chance": resolution.chance, "roll": resolution.roll})
	_append_physical_result_effect(monster_attack_event, resolution.hit, weapon != null)
	events.append(monster_attack_event)
	if resolution.killed:
		active_turn.target_id = ""
		monster.target_id = ""
		var death_macro_requested := _request_monster_death_macro(monster_target, target_definition, events)
		_remove_defeated_position(combat, monster_target.id, not death_macro_requested)
		if death_macro_requested:
			if active_turn.attack_index >= _monster_attack_limit(definition):
				_advance_turn(state, rng, events)
			return MONSTER_ATTACK_DEATH_MACRO
	return MONSTER_ATTACK_COMPLETED


func _select_adjacent_monster_target(state: GameState, monster: MonsterState, rng: RealmzRng) -> String:
	var target_ids: Array[String] = []
	var adjacent_ids := _rules.battlefield.adjacent_actor_ids(state.combat.battlefield, monster.id)
	for character: CharacterState in state.party.characters():
		if character.current_health > 0 and character.traitor != monster.traitor and adjacent_ids.has(character.id):
			target_ids.append(character.id)
	for candidate: MonsterState in state.combat.monsters():
		if candidate.id != monster.id and candidate.current_health > 0 and candidate.traitor != monster.traitor and adjacent_ids.has(candidate.id):
			target_ids.append(candidate.id)
	if target_ids.is_empty():
		return ""
	return target_ids[rng.draw_between(0, target_ids.size() - 1, &"combat.monster-target")]


func _monster_projectile_target_ids(state: GameState, monster: MonsterState, terrain_set: BattleTerrainSetDefinition, maximum_range: int) -> Array[String]:
	var candidates: Array[String] = []
	for character: CharacterState in state.party.characters():
		if _monster_target_is_available(state, monster, character.id) and _rules.battlefield.projectile_target_is_valid(state.combat.battlefield, terrain_set, monster.id, character.id, maximum_range, true):
			candidates.append(character.id)
	# Hostile monsters normally target party slots. Castle's monster-on-monster
	# projectile formula reads the stale global player missile statistic, so that
	# ally/traitor branch remains explicitly disabled pending an oracle decision.
	return candidates


func _prepare_monster_melee_weapon(monster: MonsterState, definition: MonsterDefinition, content: RealmzContent) -> void:
	if monster == null or definition == null or content == null or monster.weapon_id.is_empty():
		return
	var active_item := content.item_by_id(monster.weapon_id)
	var active_spell := content.spell_by_classic_id(absi(active_item.special_2)) if active_item != null and active_item.special_2 != 0 else null
	if active_spell == null or active_spell.damage_type != 9:
		return
	# attack2 writes this replacement through Castle's global monsterup instead
	# of its mon argument. Apply the intended slot-0 replacement to the actual
	# attacker so reactions cannot mutate an unrelated monster.
	monster.weapon_id = definition.item_id_at(0)


func _select_visible_monster_target(state: GameState, monster: MonsterState, terrain_set: BattleTerrainSetDefinition, rng: RealmzRng) -> String:
	var slot_count := 10 + state.combat.monsters().size()
	if not _has_available_monster_target(state, monster):
		return ""
	for _attempt: int in 4096:
		var slot := rng.draw_between(0, slot_count - 1, &"combat.monster-target-slot")
		var candidate_id := _monster_target_id_for_slot(state, monster, slot)
		if candidate_id.is_empty():
			continue
		if _rules.battlefield.has_line_of_sight(state.combat.battlefield, terrain_set, monster.id, candidate_id):
			return candidate_id
		break
	# Castle switches from random selection to ascending combat slots after its
	# first unseen valid target. Bound the scan to real typed slots instead of
	# reading uninitialized native monster entries through its 110 sentinel.
	return _scan_visible_monster_target(state, monster, terrain_set)


func _scan_visible_monster_target(state: GameState, monster: MonsterState, terrain_set: BattleTerrainSetDefinition) -> String:
	var slot_count := 10 + state.combat.monsters().size()
	for slot: int in slot_count:
		var candidate_id := _monster_target_id_for_slot(state, monster, slot)
		if not candidate_id.is_empty() and _rules.battlefield.has_line_of_sight(state.combat.battlefield, terrain_set, monster.id, candidate_id):
			return candidate_id
	return ""


func _monster_target_id_for_slot(state: GameState, monster: MonsterState, slot: int) -> String:
	if slot >= 0 and slot < 9:
		var characters := state.party.characters()
		if slot >= characters.size():
			return ""
		var character: CharacterState = characters[slot]
		return character.id if _monster_target_is_available(state, monster, character.id) else ""
	if slot < 10:
		return ""
	var monsters := state.combat.monsters()
	var monster_index := slot - 10
	if monster_index < 0 or monster_index >= monsters.size():
		return ""
	var candidate: MonsterState = monsters[monster_index]
	return candidate.id if _monster_target_is_available(state, monster, candidate.id) else ""


func _has_available_monster_target(state: GameState, monster: MonsterState) -> bool:
	for character: CharacterState in state.party.characters():
		if _monster_target_is_available(state, monster, character.id):
			return true
	for candidate: MonsterState in state.combat.monsters():
		if _monster_target_is_available(state, monster, candidate.id):
			return true
	return false


func _monster_target_is_available(state: GameState, monster: MonsterState, target_id: String) -> bool:
	if target_id.is_empty():
		return false
	var character := state.party.character_by_id(target_id)
	if character != null:
		return character.current_health > 0 and character.traitor != monster.traitor and state.combat.battlefield.has_actor(character.id)
	var candidate := state.combat.monster_by_id(target_id)
	return candidate != null and candidate.id != monster.id and candidate.current_health > 0 and candidate.traitor != monster.traitor and state.combat.battlefield.has_actor(candidate.id)


static func _monster_movement_allowance(monster: MonsterState, definition: MonsterDefinition) -> int:

		if movement_result == REACTION_DEATH_MACRO:
