func _init(combat: CombatState, characters: Array[CharacterState] = [], content: RealmzContent = null, inventory_rules: InventoryRules = null, battlefield_rules: BattlefieldRules = null, combat_flow: CombatFlow = null, game_state: GameState = null) -> void:
	battle_id = combat.battle_id
	round_number = combat.round_number
	active_actor_id = combat.active_actor_id()
	outcome = combat.outcome
	turn_order = combat.turn_order()
	if combat.battlefield != null:
		var upper_tileset_id := ""
		if content != null:
			var source_map := content.world.map_by_id(combat.battlefield.map_id)
			if source_map != null and source_map.level_type == &"land" and source_map.landlook >= 0:
				upper_tileset_id = "landlook-%d" % source_map.landlook
		battlefield = BattlefieldView.new(combat.battlefield, upper_tileset_id)
	var adjacent_ids: Array[String] = []
	if combat.battlefield != null and battlefield_rules != null and not active_actor_id.is_empty():
		adjacent_ids = battlefield_rules.adjacent_actor_ids(combat.battlefield, active_actor_id)
	for monster: MonsterState in combat.monsters():
		var definition := content.monster_by_id(monster.definition_id) if content != null else null
		var view := MonsterView.new(monster, definition, content)
		monsters.append(view)
		if monster.current_health > 0 and monster.traitor and adjacent_ids.has(monster.id):
			targets.append(view)
	for character: CharacterState in characters:
		if character.id == active_actor_id:
			attack_units_remaining = character.attacks_remaining
			movement_remaining = character.maximum_movement if combat.active_turn == null else character.movement
		if character.current_health > 0 and character.traitor and adjacent_ids.has(character.id):
			character_targets.append(CharacterView.new(character, content))
	_populate_active_relationships(combat, characters)
	if combat.completed:
		return
	var active_character: CharacterState = null
	for character: CharacterState in characters:
		if character.id == active_actor_id:
			active_character = character
			break
	if active_character != null and content != null and inventory_rules != null:
		if combat_flow != null:
			var retreat_probe: Variant = combat_flow.probe_character_retreat(combat, characters, active_character.id)
			retreat_available = retreat_probe.allowed
			retreat_unavailable_reason = retreat_probe.reason_text
			nearest_enemy_range = retreat_probe.nearest_enemy_range
			auto_turn = ActionAvailabilityView.new(&"auto", true)
			var delay_probe := combat_flow.probe_delay(game_state, active_character.id)
			delay = ActionAvailabilityView.new(&"delay", delay_probe.allowed, delay_probe.reason_text)
			var bandage_probe := combat_flow.probe_bandage(game_state, active_character.id)
			bandage = ActionAvailabilityView.new(&"bandage", bandage_probe.allowed, bandage_probe.reason_text)
			var turn_probe := combat_flow.probe_turn_undead(game_state, content, active_character.id)
			turn_undead = ActionAvailabilityView.new(&"turn_undead", turn_probe.allowed, turn_probe.reason_text)
			var undo_probe := combat_flow.probe_undo(game_state, active_character.id)
			undo = ActionAvailabilityView.new(&"undo", undo_probe.allowed, undo_probe.reason_text)
			for candidate_id: String in combat_flow.bandage_candidate_ids(game_state):
				var candidate := game_state.party.character_by_id(candidate_id)
				if candidate != null:
					bandage_candidates.append(CharacterView.new(candidate, content))
			for target_id: String in combat_flow.turn_undead_target_ids(game_state, content):
				var target := combat.monster_by_id(target_id)
				if target != null:
					turn_undead_targets.append(MonsterView.new(target, content.monster_by_id(target.definition_id), content))
		var equipment := inventory_rules.combat_equipment(active_character, content.item_definitions())
		if equipment.valid:
			weapon_mode = combat.character_weapon_mode(active_character.id)
			melee_weapon_id = equipment.melee_weapon.id if equipment.melee_weapon != null else ""
			missile_weapon_id = equipment.missile_weapon.id if equipment.missile_weapon != null else ""
			weapon_switch_available = weapon_mode == &"missile" or equipment.missile_weapon != null
			weapon_switch_target_mode = &"melee" if weapon_mode == &"missile" else &"missile"
			weapon_switch_unavailable_reason = "" if weapon_switch_available else "The active character has no equipped Classic type-15 missile weapon."
			if weapon_mode != &"melee":
				targets.clear()
				character_targets.clear()
				var profile := combat_flow.character_projectile_profile(active_character, content, equipment) if combat_flow != null else null
				if profile == null or not profile.available:
					ranged_attack_unavailable_reason = profile.error_message if profile != null else "Projectile rules are unavailable."
				else:
					for monster: MonsterState in combat.monsters():
						if monster.current_health > 0 and monster.traitor != active_character.traitor and combat_flow.projectile_target_is_valid(combat, content, active_character.id, monster.id, profile.maximum_range, profile.spell.range_min + profile.spell.range_max > 0):
							targets.append(MonsterView.new(monster, content.monster_by_id(monster.definition_id), content))
					if targets.is_empty():
						ranged_attack_unavailable_reason = "No hostile monster is within the projectile's Classic range and line of sight."
					else:
						legal_actions.append(&"attack")
			if weapon_switch_available:
				legal_actions.append(&"switch_weapon")
		else:
			equipment_error_reason = equipment.error_message
			weapon_switch_unavailable_reason = equipment.error_message
		if combat.battlefield != null and battlefield_rules != null:
			var map := content.world.map_by_id(combat.battlefield.map_id)
			var terrain_set := content.world.battle_terrain_set_by_id(map.battle_terrain_set_id) if map != null else null
			if terrain_set != null:
				var contact_attack_available := false
				var movement_allowance := active_character.maximum_movement if combat.active_turn == null else active_character.movement
				for direction: Vector2i in BattlefieldRules.DIRECTIONS:
					var destination := combat.battlefield.actor_position(active_character.id) + direction
					var edge_retreat: Variant = combat_flow.probe_edge_retreat(combat, active_character.id, destination) if combat_flow != null else null
					var probe := battlefield_rules.probe_step(combat.battlefield, terrain_set, active_character.id, direction, movement_allowance)
					var contact_target_id := ""
					var contact_target_name := ""
					if weapon_mode == &"melee" and probe.reason == &"occupied" and _is_hostile_target(combat, characters, active_character, probe.occupant_id):
						contact_target_id = probe.occupant_id
						contact_target_name = _target_name(combat, characters, contact_target_id)
						contact_attack_available = true
					movement_options.append(CombatMoveOptionView.new(direction, probe, edge_retreat != null and edge_retreat.allowed, edge_retreat != null and edge_retreat.forced, contact_target_id, contact_target_name))
				if weapon_mode == &"melee" and not contact_attack_available:
					melee_attack_unavailable_reason = "No hostile battlefield footprint is adjacent."
				if weapon_mode == &"melee":
					targets.clear()
					character_targets.clear()
	legal_actions.append(&"finish")
	legal_actions.append(&"defend")
	if retreat_available:
		legal_actions.append(&"retreat")
	if auto_turn.enabled:
		legal_actions.append(&"auto")
	if delay.enabled:
		legal_actions.append(&"delay")
	if bandage.enabled:
		legal_actions.append(&"bandage")
	if turn_undead.enabled:
		legal_actions.append(&"turn_undead")

	for index: int in 15:
		var amount := character.ability_value(index)
		if amount != 0:
			var detail := "The original label is not recoverable from the pinned source tree; the Classic slot and value are preserved." if ABILITY_NAMES[index].begins_with("Classic ability") else ""
			abilities.append(CharacterMetricView.new(StringName("ability-%d" % index), index, ABILITY_NAMES[index], amount, detail))
	for item: ItemInstance in character.inventory():
		var definition := null if content == null else content.item_by_id(item.definition_id)
		var presentation_definition: ItemDefinition = definition
		if definition != null and not item.equipped and not definition.cursed_item_id.is_empty():
			presentation_definition = content.item_by_id(definition.cursed_item_id)
		items.append(ItemView.new(item, definition, presentation_definition, content))
	if content != null:
		for spell_id: String in character.known_spells():
			var definition := content.spell_by_id(spell_id)
			if definition != null:
				spells.append(SpellView.new(definition))
		for index: int in character.scroll_case().size():
			var scroll := character.scroll_at(index)
			scrolls.append(SpellScrollView.new(index, scroll, content.spell_by_id(scroll.spell_id) if scroll != null and not scroll.is_empty() else null))
	for index: int in character.fast_spells().size():
		var binding := character.fast_spell_at(index)
		fast_spells.append(FastSpellBindingView.new(index, binding, content.spell_by_id(binding.spell_id) if content != null and binding != null and not binding.is_empty() else null))


func apply_equipment(equipment: CharacterCombatEquipment) -> void:
	if equipment == null or not equipment.valid:
		return
	damage_bonus = equipment.effective_damage_bonus
	luck = equipment.effective_luck
	armor = equipment.effective_armor
	_refresh_display_bonuses(equipment.equipped_damage_bonus)


func _refresh_display_bonuses(equipped_damage: int) -> void:
	attack_bonus = to_hit + 5 * equipped_damage
	attack_bonus += 15 if _condition(ConditionRules.STRONG) != 0 else 0
	attack_bonus -= 15 if _condition(ConditionRules.SLOW) != 0 else 0
	attack_bonus -= 10 if _condition(ConditionRules.CONFUSED) != 0 else 0
	attack_bonus -= 15 if _condition(ConditionRules.BLIND) != 0 else 0
	attack_bonus += 5 if _condition(ConditionRules.MAGIC_AURA) != 0 else 0
	attack_bonus -= 5 if _condition(ConditionRules.CURSED) != 0 else 0
	attack_bonus -= absi(_condition(ConditionRules.TANGLED))
	attack_bonus -= absi(_condition(ConditionRules.HINDERED_ATTACKS))
	defense_bonus = armor
	defense_bonus += 10 if _condition(ConditionRules.INVISIBLE) != 0 else 0
	defense_bonus -= 15 if _condition(ConditionRules.SLOW) != 0 else 0
	defense_bonus -= 10 if _condition(ConditionRules.CONFUSED) != 0 else 0
	defense_bonus -= 15 if _condition(ConditionRules.BLIND) != 0 else 0
	defense_bonus += 5 if _condition(ConditionRules.MAGIC_AURA) != 0 else 0
	defense_bonus -= 5 if _condition(ConditionRules.CURSED) != 0 else 0
	defense_bonus -= absi(_condition(ConditionRules.TANGLED))
	defense_bonus -= absi(_condition(ConditionRules.HINDERED_DEFENSE))
	defense_bonus += absi(_condition(ConditionRules.DEFENSE_BONUS))
	defense_bonus += 2 * absi(_condition(ConditionRules.SHIELD_FROM_HITS))


func _condition(index: int) -> int:
	return condition_values[index] if index >= 0 and index < condition_values.size() else 0


func _populate_race_details(race: RaceDefinition) -> void:
	race_traits = [
		CharacterMetricView.new(&"base-movement", 0, "Base Movement", race.base_movement),
		CharacterMetricView.new(&"magic-resistance", 1, "Magic Resistance", race.magic_resistance),
		CharacterMetricView.new(&"two-hand", 2, "Two-Hand Bonus", race.two_hand_bonus),
		CharacterMetricView.new(&"missile", 3, "Missile Bonus", race.missile_bonus),
		CharacterMetricView.new(&"base-attacks", 4, "Base Attacks", race.base_attacks),
		CharacterMetricView.new(&"maximum-attacks", 5, "Maximum Attacks", race.maximum_attacks),
		CharacterMetricView.new(&"maximum-age", 6, "Maximum Age", race.max_age, "Does not die of age" if race.does_not_die else ""),
		CharacterMetricView.new(&"regeneration", 7, "Regenerates", 1 if race.can_regenerate else 0, "Yes" if race.can_regenerate else "No"),
	]
	for band_index: int in 5:
		var age_range := race.age_range(band_index)
		var active := age_years >= age_range.x and age_years <= age_range.y
		age_bands.append(CharacterAgeBandView.new(band_index + 1, _age_group_name(band_index + 1), age_range, active, race.age_change(band_index), AGE_CHANGE_NAMES))


func _populate_caste_details(caste: CasteDefinition) -> void:
	caste_traits = [
		CharacterMetricView.new(&"minimum-age-group", 0, "Minimum Age Group", caste.minimum_age_group, _age_group_name(caste.minimum_age_group)),
		CharacterMetricView.new(&"movement-bonus", 1, "Movement Bonus", caste.movement_bonus),
		CharacterMetricView.new(&"magic-resistance-multiplier", 2, "Magic Resistance Multiplier", caste.magic_resistance_multiplier),
		CharacterMetricView.new(&"two-hand", 3, "Two-Hand Bonus", caste.two_hand_bonus),
		CharacterMetricView.new(&"maximum-stamina-bonus", 4, "Maximum Stamina Bonus", caste.maximum_stamina_bonus),
		CharacterMetricView.new(&"bonus-attacks", 5, "Bonus Attacks", caste.bonus_attacks),
		CharacterMetricView.new(&"maximum-attacks", 6, "Maximum Attacks", caste.maximum_attacks),
		CharacterMetricView.new(&"missile-use", 7, "Can Use Missile Weapons", 1 if caste.can_use_missile else 0, "Yes" if caste.can_use_missile else "No"),
		CharacterMetricView.new(&"missile-bonus", 8, "Receives Missile Bonus", 1 if caste.gets_missile_bonus else 0, "Yes" if caste.gets_missile_bonus else "No"),
	]


static func _attacks_per_round(total: int) -> String:
	if total >= 2 and total <= 19:
		return "%d/%d" % [floori(float(total) / 2.0) if total % 2 == 0 else total, 1 if total % 2 == 0 else 2]
	if total > 12:
		return ">/10"
	return "1/1"


static func _label_at(labels: Array[String], index: int, fallback: String) -> String:
	return fallback if index < 0 or index >= labels.size() else labels[index]


static func _age_group_name(group: int) -> String:
	return CharacterAgingResult.age_group_name(group)

class_name WorldDefinition
extends RefCounted

var _maps_by_id: Dictionary = {}
var _transitions_by_source: Dictionary = {}
var _battle_terrain_sets: Dictionary = {}
var _player_maps_by_id: Dictionary = {}
var _player_maps_by_classic_id: Dictionary = {}


func _init(world_maps: Array[MapDefinition], transitions: Array[MapTransition] = [], battle_terrain_sets: Array[BattleTerrainSetDefinition] = [], player_map_definitions: Array[PlayerMapDefinition] = []) -> void:
	for map_definition: MapDefinition in world_maps:
		_maps_by_id[map_definition.id] = map_definition
	for transition: MapTransition in transitions:
		_transitions_by_source[_transition_key(transition.source_map_id, transition.source_edge)] = transition
	for terrain_set: BattleTerrainSetDefinition in battle_terrain_sets:
		_battle_terrain_sets[terrain_set.id] = terrain_set
	for player_map: PlayerMapDefinition in player_map_definitions:
		_player_maps_by_id[player_map.id] = player_map
		_player_maps_by_classic_id[player_map.classic_id] = player_map


func map_by_id(map_id: String) -> MapDefinition:
	return _maps_by_id.get(map_id) as MapDefinition


func map_ids() -> Array[String]:
	var ids: Array[String] = []
	for map_id: Variant in _maps_by_id.keys():
		ids.append(String(map_id))
	ids.sort()
	return ids


func map_by_type_and_index(level_type: StringName, level_index: int) -> MapDefinition:
	for value: Variant in _maps_by_id.values():
		var map := value as MapDefinition
		if map.level_type == level_type and map.level_index == level_index:
			return map
	return null


func battle_terrain_set_by_id(definition_id: String) -> BattleTerrainSetDefinition:
	return _battle_terrain_sets.get(definition_id) as BattleTerrainSetDefinition


func player_map_by_id(definition_id: String) -> PlayerMapDefinition:
	return _player_maps_by_id.get(definition_id) as PlayerMapDefinition


func player_map_by_classic_id(classic_id: int) -> PlayerMapDefinition:
	return _player_maps_by_classic_id.get(classic_id) as PlayerMapDefinition


func player_maps() -> Array[PlayerMapDefinition]:
	var result: Array[PlayerMapDefinition] = []
	for value: Variant in _player_maps_by_classic_id.values():
		result.append(value as PlayerMapDefinition)
	result.sort_custom(func(left: PlayerMapDefinition, right: PlayerMapDefinition) -> bool: return left.classic_id < right.classic_id)
	return result


func transition_from(map_id: String, edge: StringName) -> MapTransition:
	return _transitions_by_source.get(_transition_key(map_id, edge)) as MapTransition


func transition_target_coordinate(transition: MapTransition, source_coordinate: Vector2i) -> Vector2i:
	var target_map := map_by_id(transition.target_map_id)
	if target_map == null:
		return Vector2i(-1, -1)
	match transition.target_edge:
		&"north":
			return Vector2i(clampi(source_coordinate.x, 0, target_map.topology.width - 1), 0)
		&"east":
			return Vector2i(target_map.topology.width - 1, clampi(source_coordinate.y, 0, target_map.topology.height - 1))
		&"south":
			return Vector2i(clampi(source_coordinate.x, 0, target_map.topology.width - 1), target_map.topology.height - 1)
		&"west":
			return Vector2i(0, clampi(source_coordinate.y, 0, target_map.topology.height - 1))
		&"northwest":
			return Vector2i.ZERO
		&"northeast":
			return Vector2i(target_map.topology.width - 1, 0)
		&"southeast":
			return Vector2i(target_map.topology.width - 1, target_map.topology.height - 1)
		&"southwest":
			return Vector2i(0, target_map.topology.height - 1)
		_:
			return Vector2i(-1, -1)


func probe_movement(map_id: String, origin: Vector2i, direction: Vector2i, world_state: WorldState) -> WorldMovementResult:
	var source_map := map_by_id(map_id)
	if source_map == null:
		return WorldMovementResult.blocked(&"outside_map")
	if source_map.level_type == &"land":
		if not MapTopology.is_cardinal_direction(direction) and not MapTopology.is_diagonal_direction(direction):
			return WorldMovementResult.blocked(&"invalid_direction", source_map)
	elif not MapTopology.is_cardinal_direction(direction):
		return WorldMovementResult.blocked(&"invalid_direction", source_map)
	var target_map := source_map
	var target_coordinate := origin + direction
	var transition: MapTransition = null
	if not source_map.topology.contains(target_coordinate):
		var crossing := Vector2i(
			-1 if target_coordinate.x < 0 else (1 if target_coordinate.x >= source_map.topology.width else 0),
			-1 if target_coordinate.y < 0 else (1 if target_coordinate.y >= source_map.topology.height else 0)
		)
		transition = transition_from(source_map.id, MapTopology.direction_name(crossing))
		if transition == null:
			return WorldMovementResult.blocked(&"map_boundary", source_map)
		target_map = map_by_id(transition.target_map_id)
		if target_map == null:
			return WorldMovementResult.blocked(&"outside_map", source_map)
		target_coordinate = transition_target_coordinate(transition, target_coordinate)
	var topology_result := target_map.topology.probe_movement(target_coordinate, direction, world_state, source_map.level_type)
	if not topology_result.allowed:
		return WorldMovementResult.blocked(topology_result.reason, source_map, target_map, target_coordinate, topology_result)
	return WorldMovementResult.permitted(source_map, target_map, target_coordinate, transition, topology_result)


static func _transition_key(map_id: String, edge: StringName) -> String:
	return "%s:%s" % [map_id, String(edge)]

class_name MapTopology
extends RefCounted

var width: int
var height: int
var _cells: Array[MapCell]
var _cells_by_coordinate: Dictionary = {}


func _init(map_width: int, map_height: int, map_cells: Array[MapCell]) -> void:
	width = map_width
	height = map_height
	_cells = map_cells.duplicate()
	for cell: MapCell in _cells:
		_cells_by_coordinate[cell.coordinate] = cell


func contains(coordinate: Vector2i) -> bool:
	return coordinate.x >= 0 and coordinate.y >= 0 and coordinate.x < width and coordinate.y < height


func cell_at(coordinate: Vector2i) -> MapCell:
	return _cells_by_coordinate.get(coordinate) as MapCell


func cells() -> Array[MapCell]:
	return _cells.duplicate()


func probe_entry(coordinate: Vector2i, move_direction: Vector2i, world_state: WorldState) -> TopologyMoveResult:
	var cell_probe := probe_land_entry(coordinate, world_state)
	if not cell_probe.allowed:
		return cell_probe
	var cell := cell_probe.target_cell
	var entry_direction_name := direction_name(move_direction)
	if not is_cardinal_direction(move_direction):
		return TopologyMoveResult.blocked(&"invalid_direction")
	var edge := cell.edge(entry_direction_name)
	if edge == null or not edge.passable:
		return TopologyMoveResult.blocked(&"edge_blocked")
	return TopologyMoveResult.permitted(cell, edge.door_id, edge.secret_id)


func probe_land_entry(coordinate: Vector2i, world_state: WorldState) -> TopologyMoveResult:
	var cell := cell_at(coordinate)
	if cell == null:
		return TopologyMoveResult.blocked(&"outside_map")
	if not cell.passable:
		return TopologyMoveResult.blocked(&"terrain_blocked", cell)
	var cell_secret := cell.feature_by_kind(&"secret")
	if cell_secret != null and cell_secret.orientation.is_empty() and not world_state.secret_is_discovered(cell_secret.id, cell_secret.initial_state == &"revealed"):
		return TopologyMoveResult.blocked(&"secret_hidden", cell)
	return TopologyMoveResult.permitted(cell)


func probe_movement(coordinate: Vector2i, move_direction: Vector2i, world_state: WorldState, level_type: StringName) -> TopologyMoveResult:
	if level_type == &"land":
		if not is_cardinal_direction(move_direction) and not is_diagonal_direction(move_direction):
			return TopologyMoveResult.blocked(&"invalid_direction")
		return probe_land_entry(coordinate, world_state)
	if not is_cardinal_direction(move_direction):
		return TopologyMoveResult.blocked(&"invalid_direction")
	return probe_entry(coordinate, move_direction, world_state)


func has_line_of_sight(from: Vector2i, to: Vector2i, world_state: WorldState) -> bool:
	if not contains(from) or not contains(to):
		return false
	var x := from.x
	var y := from.y
	var dx := absi(to.x - from.x)
	var dy := -absi(to.y - from.y)
	var step_x := 1 if from.x < to.x else -1
	var step_y := 1 if from.y < to.y else -1
	var error := dx + dy
	while x != to.x or y != to.y:
		var twice_error := 2 * error
		if twice_error >= dy:
			error += dy
			x += step_x
		if twice_error <= dx:
			error += dx
			y += step_y
		var cell := cell_at(Vector2i(x, y))
		if cell == null:
			return false
		if Vector2i(x, y) != to and _cell_blocks_los(cell, world_state):
			return false
	return true


func visible_cells(origin: Vector2i, radius: int, world_state: WorldState, use_los: bool) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	for cell: MapCell in _cells:
		if not use_los or origin.distance_squared_to(cell.coordinate) <= radius * radius and has_line_of_sight(origin, cell.coordinate, world_state):
			result.append(cell.coordinate)
	return result


func find_path(origin: Vector2i, destination: Vector2i, world_state: WorldState, level_type: StringName) -> Array[Vector2i]:
	if not contains(origin) or not contains(destination):
		return []
	if origin == destination:
		return []
	var frontier: Array[Vector2i] = [origin]
	var frontier_index := 0
	var previous: Dictionary = {origin: origin}
	var directions := land_directions() if level_type == &"land" else cardinal_directions()
	while frontier_index < frontier.size():
		var current := frontier[frontier_index]
		frontier_index += 1
		for move_direction: Vector2i in directions:
			var neighbor := current + move_direction
			if not contains(neighbor) or previous.has(neighbor):
				continue
			if not probe_movement(neighbor, move_direction, world_state, level_type).allowed:
				continue
			previous[neighbor] = current
			if neighbor == destination:
				return _reconstruct_path(origin, destination, previous)
			frontier.append(neighbor)
	return []


static func direction_name(direction: Vector2i) -> StringName:
	match direction:
		Vector2i.UP:
			return &"north"
		Vector2i.RIGHT:
			return &"east"
		Vector2i.DOWN:
			return &"south"
		Vector2i.LEFT:
			return &"west"
		Vector2i(-1, -1):
			return &"northwest"
		Vector2i(1, -1):
			return &"northeast"
		Vector2i(-1, 1):
			return &"southwest"
		Vector2i(1, 1):
			return &"southeast"
		_:
			return &""


static func is_cardinal_direction(direction: Vector2i) -> bool:
	return direction in [Vector2i.UP, Vector2i.RIGHT, Vector2i.DOWN, Vector2i.LEFT]


static func is_diagonal_direction(direction: Vector2i) -> bool:
	return absi(direction.x) == 1 and absi(direction.y) == 1


static func cardinal_directions() -> Array[Vector2i]:
	return [Vector2i.UP, Vector2i.RIGHT, Vector2i.DOWN, Vector2i.LEFT]


static func land_directions() -> Array[Vector2i]:
	return [Vector2i.UP, Vector2i(1, -1), Vector2i.RIGHT, Vector2i(1, 1), Vector2i.DOWN, Vector2i(-1, 1), Vector2i.LEFT, Vector2i(-1, -1)]

