	if _turn_order.is_empty():
		return false
	active_turn = null
	undo_state = null
	turn_index += 1
	if turn_index >= _turn_order.size():
		turn_index = 0
		round_number += 1
		_attacked_actor_ids.clear()
		return true
	return false


