func _ints(count: int) -> Array[int]:
	var result: Array[int] = []
	result.resize(count)
	result.fill(0)
	return result

	macro_definition.can_summon = 1
	macro_definition.death_macro = 321
	var macro_monster := MonsterState.new("monster.auto-turn-macro.instance", macro_definition.id, macro_definition.name, 20, 20, 1)
	var macro_state := _state(macro_actor, macro_monster, "battle.auto-turn-macro")
	var macro_result := rules.combat_flow.run_auto_turn(macro_state, _content([macro_definition]), macro_actor.id, ScriptedRng.new([8192]))
	assert_true(macro_result.ok, "Auto stops successfully at a mandatory Turn Undead death-macro boundary")
	assert_equal(macro_state.combat.pending_spell_death_macro_id(), macro_monster.id, "Auto retains the exact mandatory death-macro subject")
	assert_true(macro_result.events.any(func(event: DomainEvent) -> bool: return event.kind == &"monster_death_macro_requested" and event.payload.get("combatantId") == macro_monster.id), "Auto publishes the mandatory interaction boundary without selecting another action")
	var macro_restored := GameState.from_data(JSON.parse_string(JSON.stringify(macro_state.to_data())))
	assert_not_null(macro_restored, "the mandatory Auto stop is a restorable combat boundary")
	if macro_restored != null:
		assert_equal([macro_restored.combat.pending_spell_death_macro_id(), macro_restored.combat.active_actor_id()], [macro_monster.id, macro_actor.id], "restore retains the Auto-issued death macro and exact issuing actor")

	var chain_first := _character("character.auto-chain-first")
	var chain_second := _character("character.auto-chain-second")
	var chain_manual := _character("character.auto-chain-manual")
	var chain_monster := MonsterState.new("monster.auto-chain.instance", auto_definition.id, auto_definition.name, 1000, 1000, 1)
	var chain_state := _state(chain_first, chain_monster, "battle.auto-chain")
	assert_true(chain_state.party.add_character(chain_second), "persistent Auto fixture adds its second enabled character")
	assert_true(chain_state.party.add_character(chain_manual), "persistent Auto fixture adds the manual stop character")
	chain_state.combat.battlefield.place_character(chain_second.id, Vector2i(46, 46))
	chain_state.combat.battlefield.place_character(chain_manual.id, Vector2i(44, 45))
	chain_state.combat.set_turn_order([chain_first.id, chain_second.id, chain_manual.id, chain_monster.id])
	chain_state.set_combat_auto(chain_first.id, true)
	chain_state.set_combat_auto(chain_second.id, true)
	var chain_result := rules.combat_flow.run_persistent_auto_characters(chain_state, _content([auto_definition]), RealmzRng.new(23))
	assert_true(chain_result.ok, "persistent Auto resolves adjacent enabled characters through the same rules-owned routine")
	assert_equal(chain_state.combat.active_actor_id(), chain_manual.id, "persistent Auto stops at the first living manual party actor")
	assert_equal(chain_result.events.filter(func(event: DomainEvent) -> bool: return event.kind == &"combat_auto_started").map(func(event: DomainEvent) -> String: return event.payload.get("actorId")), [chain_first.id, chain_second.id], "persistent Auto preserves turn-order activation identity")

	var limit_actor := _character("character.auto-limit")
	limit_actor.maximum_movement = 0
	limit_actor.movement = 0
	var limit_monster := MonsterState.new("monster.auto-limit.instance", auto_definition.id, auto_definition.name, 32_767, 32_767, 1)
	limit_monster.conditions.set_value(ConditionRules.HELPLESS, 1)
	var limit_state := _state(limit_actor, limit_monster, "battle.auto-limit")
	limit_state.combat.battlefield.place_monster(limit_monster.id, Vector2i(60, 60), 0)
	limit_state.set_combat_auto(limit_actor.id, true)
	var limit_rng := RealmzRng.new(29)
	assert_not_null(GameState.from_data(limit_state.to_data()), "the operation-limit fixture is a valid restorable transaction checkpoint")
	var limit_state_before := JSON.stringify(limit_state.to_data())
	var limit_rng_before := limit_rng.snapshot()
	var limit_result := rules.combat_flow.run_persistent_auto_characters(limit_state, _content([auto_definition]), limit_rng)
	assert_false(limit_result.ok, "persistent Auto fails explicitly at its bounded activation limit")
	assert_equal(limit_result.error_code, &"combat_auto_operation_limit", "persistent Auto reports its specific bounded-operation failure")
	assert_equal(JSON.stringify(limit_state.to_data()), limit_state_before, "persistent Auto rolls the complete battle state back after operation-limit exhaustion")
	assert_equal([limit_rng.snapshot().generator_state, limit_rng.snapshot().draw_count, limit_rng.trace().size()], [limit_rng_before.generator_state, limit_rng_before.draw_count, 0], "persistent Auto restores RNG state, draw count, and trace after operation-limit exhaustion")


func _test_bounded_classic_undo_and_restore() -> void:
	var rules := RealmzRules.new()
	var actor := _character("character.undo")
	actor.normal_attacks = 2
	actor.attack_bonus = 1
	var definition := _monster_definition("monster.undo", [])
	var monster := MonsterState.new("monster.undo.instance", definition.id, definition.name, 100, 100, 1)
	var state := _state(actor, monster, "battle.undo")
	state.combat.battlefield.move_actor(monster.id, Vector2i(50, 45))
