func _run_battle_macro(source_kind: String, caller: Dictionary, preceding_events: Array[DomainEvent], request_id: String) -> ScenarioRuntimeOperationResult:
	var combat := _game_state.combat
	if combat == null or combat.completed or combat.macro_id >= 0:
		return ScenarioRuntimeOperationResult.waiting(_combat_request(request_id), {"kind": source_kind, "battleId": combat.battle_id, "battleCaller": caller.duplicate(true)}, preceding_events)
	var program_id := "xap:%d" % absi(combat.macro_id)
	var vm := ScenarioVm.new()
	vm.configure(_content.scenario)
	var started := vm.start_program(program_id, {"callingContext": "battle-macro", "battleId": combat.battle_id})
	if started.state == ScenarioVmResult.State.FAILED:
		return ScenarioRuntimeOperationResult.failed(started.error_code, started.error_message)
	var result := vm.run(self)
	var events: Array[DomainEvent] = []
	events.assign(preceding_events)
	events.append(DomainEvent.new(&"battle_macro_started", {"battleId": combat.battle_id, "programId": program_id, "round": combat.round_number}))
	events.append_array(result.events)
	if result.state == ScenarioVmResult.State.FAILED:
		return ScenarioRuntimeOperationResult.failed(result.error_code, result.error_message)
	if result.state == ScenarioVmResult.State.SUSPENDED:
		return ScenarioRuntimeOperationResult.failed(&"nested_host_handoff", "A battle macro cannot suspend a second battle into the application host.")
	if result.state == ScenarioVmResult.State.WAITING:
		return ScenarioRuntimeOperationResult.waiting(result.interaction, {
			"kind": "%s-macro" % source_kind,
			"sourceKind": source_kind,
			"battleId": combat.battle_id,
			"programId": program_id,
			"battleCaller": caller.duplicate(true),
			"macroVm": vm.snapshot().to_data(),
		}, events)
	return _continue_after_battle_macro(source_kind, caller, request_id, program_id, events)


func _resume_battle_macro(continuation: Dictionary, response: InteractionResponse, request_id: String) -> ScenarioRuntimeOperationResult:
	if _game_state.combat == null or _game_state.combat.battle_id != continuation.get("battleId"):
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "The pending battle macro is unavailable.")
	var snapshot := ScenarioVmSnapshot.from_data(continuation.get("macroVm"))
	if snapshot == null:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_macro_continuation", "The pending battle macro state is invalid.")
	var vm := ScenarioVm.new()
	vm.configure(_content.scenario)
	if not vm.restore(snapshot):
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_macro_continuation", "The pending battle macro cannot be restored.")
	var result := vm.resume(response, self)
	if result.state == ScenarioVmResult.State.FAILED:
		return ScenarioRuntimeOperationResult.failed(result.error_code, result.error_message)
	if result.state == ScenarioVmResult.State.SUSPENDED:
		return ScenarioRuntimeOperationResult.failed(&"nested_host_handoff", "A resumed battle macro cannot suspend a second battle into the application host.")
	if result.state == ScenarioVmResult.State.WAITING:
		var next_continuation := continuation.duplicate(true)
		next_continuation["macroVm"] = vm.snapshot().to_data()
		return ScenarioRuntimeOperationResult.waiting(result.interaction, next_continuation, result.events)
	return _continue_after_battle_macro(String(continuation.get("sourceKind", "classic-combat")), _battle_caller(continuation), request_id, String(continuation.get("programId", "")), result.events)


func _continue_after_battle_macro(source_kind: String, caller: Dictionary, request_id: String, program_id: String, events: Array[DomainEvent]) -> ScenarioRuntimeOperationResult:
	var committed: Array[DomainEvent] = []
	committed.assign(events)
	committed.append(DomainEvent.new(&"battle_macro_completed", {"battleId": _game_state.combat.battle_id, "programId": program_id, "round": _game_state.combat.round_number}))
	if _game_state.combat.completed:
		return _finish_battle_with_allies(source_kind, caller, request_id, committed)
	return ScenarioRuntimeOperationResult.waiting(_combat_request(request_id), {"kind": source_kind, "battleId": _game_state.combat.battle_id, "battleCaller": caller.duplicate(true)}, committed)

class_name ScenarioVm
extends RefCounted

const CLASSIC_CALL_LIMIT: int = 20
const ACTION_CALL_LIMIT: int = 32
const EXECUTION_STEP_LIMIT: int = 65536
const TRACE_LIMIT: int = 4096

var _definition: ScenarioDefinition
var _frames: Array[ScenarioFrame] = []
var _pending_request: InteractionRequest
var _pending_continuation: Dictionary = {}
var _trace: Array[Dictionary] = []
var _request_counter: int = 0
var _step_count: int = 0
var _execution_step_limit: int = EXECUTION_STEP_LIMIT
var _halted: bool = true
var _last_outcome: Variant


func configure(definition: ScenarioDefinition, execution_step_limit: int = EXECUTION_STEP_LIMIT) -> void:
	assert(execution_step_limit > 0 and execution_step_limit <= EXECUTION_STEP_LIMIT, "Scenario step limit must remain within the engine budget")
	_definition = definition
	_execution_step_limit = execution_step_limit
	reset()


func reset() -> void:
	_frames.clear()
	_pending_request = null
	_pending_continuation.clear()
	_trace.clear()
	_request_counter = 0
	_step_count = 0
	_halted = true
	_last_outcome = null


func start_program(program_id: String, context: Dictionary = {}) -> ScenarioVmResult:
	if _definition == null:
		return ScenarioVmResult.failed(&"scenario_not_configured", "Scenario VM has no validated definition.")
	if _pending_request != null or not _frames.is_empty():
		return ScenarioVmResult.failed(&"scenario_already_running", "A scenario program is already active.")
	if _definition.program_by_id(program_id) == null:
		return ScenarioVmResult.failed(&"unknown_scenario_program", "Scenario program '%s' is unavailable." % program_id)
	var frame := ScenarioFrame.new(ScenarioFrame.PROGRAM, program_id)
	frame.set_context(context)
	_frames.append(frame)
	_halted = false
	_step_count = 0
	_last_outcome = null
	_append_trace({"event": "start", "programId": program_id})
	return ScenarioVmResult.completed()


func run(runtime_api: RealmzRuntimeApi) -> ScenarioVmResult:
	if _halted:
		return ScenarioVmResult.completed([], _last_outcome)
	if _pending_request != null:
		return ScenarioVmResult.failed(&"interaction_pending", "The Scenario VM is waiting for interaction '%s'." % _pending_request.request_id)
	var events: Array[DomainEvent] = []
	while not _frames.is_empty():
		_step_count += 1
		if _step_count > _execution_step_limit:
			return _fail(&"scenario_step_limit", "Scenario execution exceeded %s steps." % _execution_step_limit, events)
		var frame: ScenarioFrame = _frames.back()
		var result: ScenarioVmResult = _execute_program_frame(frame, runtime_api) if frame.kind == ScenarioFrame.PROGRAM else _execute_action_frame(frame, runtime_api)
		events.append_array(result.events)
		if result.state == ScenarioVmResult.State.WAITING:
			return ScenarioVmResult.waiting(result.interaction, events)
		if result.state == ScenarioVmResult.State.SUSPENDED:
			return ScenarioVmResult.suspended(result.handoff, events)
		if result.state == ScenarioVmResult.State.FAILED:
			return _fail(result.error_code, result.error_message, events)
	_halted = true
	return ScenarioVmResult.completed(events, _last_outcome)


func resume(response: InteractionResponse, runtime_api: RealmzRuntimeApi) -> ScenarioVmResult:
	if _pending_request == null:
		return ScenarioVmResult.failed(&"no_interaction_pending", "The Scenario VM has no interaction to resume.")
	if response == null or response.request_id != _pending_request.request_id:
		return ScenarioVmResult.failed(&"interaction_mismatch", "The interaction response does not match the issuing VM request.")
	var events: Array[DomainEvent] = []
	var continuation := _pending_continuation.duplicate(true)
	var request_id := _pending_request.request_id
	_pending_request = null
	_pending_continuation.clear()
	_append_trace({"event": "resume", "requestId": request_id, "kind": continuation.get("kind", "")})
	match continuation.get("kind"):
		"safe-operation":
			var operation := runtime_api.resume_safe(continuation.get("runtime", {}), response, _next_request_id())
			if operation.state == ScenarioRuntimeOperationResult.State.FAILED:
				return _fail(operation.error_code, operation.error_message, events)
			events.append_array(operation.events)
			if operation.state == ScenarioRuntimeOperationResult.State.WAITING:
				_pending_request = operation.interaction
				_pending_continuation = {"kind": "safe-operation", "frameIndex": continuation.get("frameIndex", -1), "resultTarget": continuation.get("resultTarget", ""), "runtime": operation.continuation.duplicate(true)}
				_append_trace({"event": "yield", "requestId": operation.interaction.request_id, "kind": String(operation.interaction.kind)})
				return ScenarioVmResult.waiting(operation.interaction, events)
			if operation.state == ScenarioRuntimeOperationResult.State.SUSPENDED:
				return _suspend_operation("safe-operation", operation, continuation.get("frameIndex", -1), continuation.get("resultTarget", ""))
			var frame_index: int = int(continuation.get("frameIndex", -1))
			if frame_index < 0 or frame_index >= _frames.size() or _frames[frame_index].kind != ScenarioFrame.ACTION:
				return _fail(&"invalid_vm_continuation", "Scenario Action continuation frame is unavailable.", events)
			var result_target: String = str(continuation.get("resultTarget", ""))
			if not result_target.is_empty():
				_frames[frame_index].set_local(result_target, operation.value)
		"classic-operation":
			var operation := runtime_api.resume_classic(continuation.get("runtime", {}), response, _next_request_id())
			if operation.state == ScenarioRuntimeOperationResult.State.FAILED:
				return _fail(operation.error_code, operation.error_message, events)
			events.append_array(operation.events)
			if operation.state == ScenarioRuntimeOperationResult.State.WAITING:
				_pending_request = operation.interaction
				_pending_continuation = {"kind": "classic-operation", "runtime": operation.continuation.duplicate(true)}
				_append_trace({"event": "yield", "requestId": operation.interaction.request_id, "kind": String(operation.interaction.kind)})
				return ScenarioVmResult.waiting(operation.interaction, events)
			if operation.state == ScenarioRuntimeOperationResult.State.SUSPENDED:
				return _suspend_operation("classic-operation", operation)
			var directive_result := _apply_classic_directive(operation.directive)
			if directive_result.state == ScenarioVmResult.State.FAILED:
				return _fail(directive_result.error_code, directive_result.error_message, events)
		_:
			return _fail(&"unknown_interaction_continuation", "Scenario VM continuation kind is unavailable.", events)
	var resumed := run(runtime_api)
	events.append_array(resumed.events)
	if resumed.state == ScenarioVmResult.State.WAITING:
		return ScenarioVmResult.waiting(resumed.interaction, events)
	if resumed.state == ScenarioVmResult.State.SUSPENDED:
		return ScenarioVmResult.suspended(resumed.handoff, events)
	if resumed.state == ScenarioVmResult.State.FAILED:
		return ScenarioVmResult.failed(resumed.error_code, resumed.error_message, events)
	return ScenarioVmResult.completed(events, resumed.outcome)


func resume_handoff(handoff: Dictionary, operation: ScenarioRuntimeOperationResult, runtime_api: RealmzRuntimeApi) -> ScenarioVmResult:
	if _halted or _frames.is_empty() or _pending_request != null:
		return ScenarioVmResult.failed(&"invalid_vm_handoff", "The suspended Scenario VM is unavailable.")
	if operation == null or operation.state != ScenarioRuntimeOperationResult.State.COMPLETED:
		return ScenarioVmResult.failed(&"invalid_runtime_handoff", "The Realmz runtime did not complete the suspended operation.")
	var events: Array[DomainEvent] = []
	events.append_array(operation.events)
	match String(handoff.get("kind", "")):
		"safe-operation":
			var frame_index := int(handoff.get("frameIndex", -1))
			if frame_index < 0 or frame_index >= _frames.size() or _frames[frame_index].kind != ScenarioFrame.ACTION:
				return ScenarioVmResult.failed(&"invalid_vm_handoff", "The suspended Scenario Action frame is unavailable.", events)
			var result_target := String(handoff.get("resultTarget", ""))
			if not result_target.is_empty():
				_frames[frame_index].set_local(result_target, operation.value)
		"classic-operation":
			var context: Dictionary = _frames.back().context_data()
			var directive_result := _apply_classic_directive(operation.directive, context)
			if directive_result.state == ScenarioVmResult.State.FAILED:
				return ScenarioVmResult.failed(directive_result.error_code, directive_result.error_message, events)
		_:
			return ScenarioVmResult.failed(&"invalid_vm_handoff", "The suspended operation kind is unavailable.", events)
	_append_trace({"event": "host-handoff-resume", "kind": handoff.get("kind", "")})
	var resumed := run(runtime_api)

	var restored := GameState.from_data(JSON.parse_string(JSON.stringify(state.to_data())))
	assert_not_null(restored, "Turn Undead's used state and changed allegiance survive save restoration")
