		restored.combat.turn_index = 0
		restored.party.character_by_id(actor.id).attacks_remaining = 2
		assert_false(rules.combat_flow.probe_turn_undead(restored, content, actor.id).allowed, "a restored character cannot Turn Undead a second time in the same battle")
	var unknown_turner: Dictionary = state.to_data()
	unknown_turner["combat"]["turnOrder"].append("character.unknown-turner")
	unknown_turner["combat"]["turnUndeadActorIds"] = ["character.unknown-turner"]
	assert_equal(GameState.from_data(unknown_turner), null, "the central aggregate rejects Turn Undead history outside the party")

	state.priest_turning_allowed = false
	assert_false(rules.combat_flow.probe_turn_undead(state, content, actor.id).allowed, "campaign priest-turning permission remains a rules-owned gate")
