    while ($true) {
        $candidate = if ([string]::IsNullOrEmpty($dir)) { "AGENTS.md" } else { "$dir/AGENTS.md" }
        if ($FileByPath.ContainsKey($candidate)) { return "dox:$candidate" }
        if ([string]::IsNullOrEmpty($dir)) { break }
