            $base = [Drawing.Bitmap]::new(512, 512, [Drawing.Imaging.PixelFormat]::Format32bppArgb)
            $graphics = [Drawing.Graphics]::FromImage($base)
            try {
                $graphics.InterpolationMode = [Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                $graphics.PixelOffsetMode = [Drawing.Drawing2D.PixelOffsetMode]::HighQuality
                $graphics.DrawImage($source, [Drawing.Rectangle]::new(0, 0, 512, 512))
            }
            finally { $graphics.Dispose() }
            Save-Png $base $basePath
            $base.Dispose()
        }
        finally { $source.Dispose() }
        $sourceHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $sourcePath).Hash.ToLowerInvariant()
        $selectedAsset = [ordered]@{
            asset_id = $SpriteCookAssetId
            label = $SpriteCookLabel
            source_sha256 = $sourceHash
            source_sha256_prefix = $sourceHash.Substring(0, 12)
            mode = "texture"
        }
    }

    $baseSurface = [Drawing.Bitmap]::new([string]$basePath)
    try {
        $seamlessTile = New-SeamlessTile $baseSurface
        try {
            Save-Png $seamlessTile (Join-Path $stagingRoot "classic-charcoal-slate-tile.png")
            foreach ($definition in @(
                @{ Name = "classic-raised-frame.png"; Top = [Drawing.Color]::FromArgb(190, 128, 138, 139); Bottom = [Drawing.Color]::FromArgb(220, 8, 11, 13) },
                @{ Name = "classic-inset-frame.png"; Top = [Drawing.Color]::FromArgb(225, 6, 8, 10); Bottom = [Drawing.Color]::FromArgb(180, 112, 121, 122) }
            )) {
                $frame = [Drawing.Bitmap]::new($seamlessTile.Width + 16, $seamlessTile.Height + 16, [Drawing.Imaging.PixelFormat]::Format32bppArgb)
                $frameGraphics = [Drawing.Graphics]::FromImage($frame)
                try {
                    $frameGraphics.DrawImageUnscaled($seamlessTile, 8, 8)
                    $topPen = [Drawing.Pen]::new($definition.Top, 3)
                    $bottomPen = [Drawing.Pen]::new($definition.Bottom, 3)
                    try {
                        $maximum = $frame.Width - 2
                        $frameGraphics.DrawLine($topPen, 1, 1, $maximum, 1)
                        $frameGraphics.DrawLine($topPen, 1, 1, 1, $maximum)
                        $frameGraphics.DrawLine($bottomPen, 2, $maximum, $maximum, $maximum)
                        $frameGraphics.DrawLine($bottomPen, $maximum, 2, $maximum, $maximum)
                        $innerPen = [Drawing.Pen]::new([Drawing.Color]::FromArgb(170, 31, 38, 40), 1)
                        try { $frameGraphics.DrawRectangle($innerPen, 5, 5, $frame.Width - 11, $frame.Height - 11) }
                        finally { $innerPen.Dispose() }
                    }
                    finally {
                        $topPen.Dispose()
                        $bottomPen.Dispose()
                    }
                }
                finally { $frameGraphics.Dispose() }
                Save-Png $frame (Join-Path $stagingRoot $definition.Name)
                $frame.Dispose()
            }

function Invoke-StreamingProcess {
    param(
        [Parameter(Mandatory = $true)][string]$FilePath,
        [string[]]$ArgumentList = @(),
        [Parameter(Mandatory = $true)][string]$Label,
        [ValidateRange(0, 86400)][int]$TimeoutSeconds = 0,
        [ValidateRange(1, 300)][int]$HeartbeatSeconds = 10
    )

    $quotedArguments = @($ArgumentList | ForEach-Object {
        if ($_ -match '[\s"]') { '"' + $_.Replace('"', '\"') + '"' } else { $_ }
    })
    $stdoutPath = Join-Path ([System.IO.Path]::GetTempPath()) ("realmz-process-{0}.out" -f [guid]::NewGuid().ToString("N"))
    $stderrPath = Join-Path ([System.IO.Path]::GetTempPath()) ("realmz-process-{0}.err" -f [guid]::NewGuid().ToString("N"))
    $captured = [System.Collections.Generic.List[string]]::new()
    $stdoutCount = 0
    $stderrCount = 0
    $process = $null
    $startedAt = [DateTime]::UtcNow
    $nextHeartbeat = $startedAt.AddSeconds($HeartbeatSeconds)
    $timedOut = $false
    $terminationVerified = $true

    function Write-NewProcessOutput {
        param([string]$Path, [ref]$Count, [System.Collections.Generic.List[string]]$Capture)
        if (-not (Test-Path -LiteralPath $Path)) { return }
        $lines = @(Get-Content -LiteralPath $Path -ErrorAction SilentlyContinue)
        for ($index = $Count.Value; $index -lt $lines.Count; $index++) {
            $line = [string]$lines[$index]
            $Capture.Add($line)
            Write-Host $line
        }
        $Count.Value = $lines.Count
    }

    try {
        Write-Host "Starting $Label$(if ($TimeoutSeconds -gt 0) { " with a ${TimeoutSeconds}-second process budget" })..."
        $process = Start-Process -FilePath $FilePath -ArgumentList $quotedArguments -PassThru -NoNewWindow -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath
        while (-not $process.HasExited) {
            Write-NewProcessOutput -Path $stdoutPath -Count ([ref]$stdoutCount) -Capture $captured
            Write-NewProcessOutput -Path $stderrPath -Count ([ref]$stderrCount) -Capture $captured
            $now = [DateTime]::UtcNow
            if ($now -ge $nextHeartbeat) {
                Write-Host ("{0} still running ({1:n0}s elapsed)..." -f $Label, ($now - $startedAt).TotalSeconds)
                $nextHeartbeat = $now.AddSeconds($HeartbeatSeconds)
            }
            if ($TimeoutSeconds -gt 0 -and ($now - $startedAt).TotalSeconds -ge $TimeoutSeconds) {
                $timedOut = $true
                if ($env:OS -eq "Windows_NT") {
                    & taskkill.exe /PID $process.Id /T /F 2>$null | Out-Null
                    $terminationVerified = $LASTEXITCODE -eq 0
                } else {
                    try { $process.Kill($true) } catch { $process.Kill() }
                }
                try { $terminationVerified = $process.WaitForExit(5000) -and $terminationVerified } catch { $terminationVerified = $false }
                $process.Refresh()
                if (-not $process.HasExited) { $terminationVerified = $false }
                break
            }
            Start-Sleep -Milliseconds 250
            $process.Refresh()
        }
        Write-NewProcessOutput -Path $stdoutPath -Count ([ref]$stdoutCount) -Capture $captured
        Write-NewProcessOutput -Path $stderrPath -Count ([ref]$stderrCount) -Capture $captured
        $elapsedMilliseconds = [int]([DateTime]::UtcNow - $startedAt).TotalMilliseconds
        Write-Host "$Label completed in $elapsedMilliseconds ms."
        if ($timedOut) {
            $lastOutput = "<no process output>"
            for ($index = $captured.Count - 1; $index -ge 0; $index--) {
                if (-not [string]::IsNullOrWhiteSpace($captured[$index])) {
                    $lastOutput = $captured[$index]
                    break
                }
            }
            if (-not $terminationVerified) {
                throw "$Label exceeded the ${TimeoutSeconds}-second budget and process-tree termination could not be verified. Last output: $lastOutput"
            }
            throw "$Label exceeded the ${TimeoutSeconds}-second budget; its process tree was terminated. Last output: $lastOutput"
        }
        return [pscustomobject]@{
            ExitCode = $process.ExitCode
            Output = $captured.ToArray()
            ElapsedMilliseconds = $elapsedMilliseconds
        }
    } finally {
        if ($process -and -not $process.HasExited) {
            try { $process.Kill($true) } catch { try { $process.Kill() } catch { } }
        }
        Remove-Item -LiteralPath $stdoutPath, $stderrPath -Force -ErrorAction SilentlyContinue
    }
}

    foreach ($sidecar in Get-ChildItem -LiteralPath $sidecarRoot -Recurse -File -Filter "*.import") {
        $relativePath = [IO.Path]::GetRelativePath($sidecarRoot, $sidecar.FullName)
        $sourceAssetRelativePath = $relativePath.Substring(0, $relativePath.Length - ".import".Length)
        if (Test-Path -LiteralPath (Join-Path $destinationRoot $sourceAssetRelativePath) -PathType Leaf) {
            $destinationSidecar = Join-Path $destinationRoot $relativePath
            New-Item -ItemType Directory -Path (Split-Path -Parent $destinationSidecar) -Force | Out-Null
            Copy-Item -LiteralPath $sidecar.FullName -Destination $destinationSidecar
        }
    }
    Copy-Item -LiteralPath $stagedManifest -Destination $manifestPath -Force
    Write-Host "Imported $($records.Count) exact-commit Classic application media assets."
}
finally {
    if (Test-Path -LiteralPath $stagingRoot) {
        Remove-Item -LiteralPath $stagingRoot -Recurse -Force
    }
}

