	for index: int in value.length():
		var code := value.unicode_at(index)
		var lower := code >= 97 and code <= 122
		var digit := code >= 48 and code <= 57
		if not lower and not (digit and index > 0) and not (code == 95 and index > 0):
			return false
	return true


