	if depth > 64:
		return false
	if value == null or value is bool or value is int or value is float or value is String:
		return true
	if value is Array:
		if value.size() > 4096:
			return false
		for child: Variant in value:
			if not _json_safe(child, depth + 1):
				return false
		return true
	if value is Dictionary:
		if value.size() > 4096:
			return false
		for key: Variant in value.keys():
			if not key is String or not _json_safe(value[key], depth + 1):
				return false
		return true
	return false


func _sha256(bytes: PackedByteArray) -> String:
	var context := HashingContext.new()
	context.start(HashingContext.HASH_SHA256)
	context.update(bytes)
	return context.finish().hex_encode()


func _reject(message: String) -> bool:
	_last_error = message
	return false


func _validation_failure() -> PackageLoadResult:
	if _last_error == "Package operation cancelled.":
		return PackageLoadResult.failed(&"package_cancelled", _last_error)
	return PackageLoadResult.failed("package_validation_failed", _last_error if not _last_error.is_empty() else "Package validation failed.")


func _report_progress(callback: Callable, phase: StringName, completed: int, total: int) -> void:
	if callback.is_valid():
		callback.call(phase, completed, total)


func _cancel_requested(callback: Callable) -> bool:
	return callback.is_valid() and bool(callback.call())

	return DirAccess.remove_absolute(ProjectSettings.globalize_path(path)) == OK


func _safe_component(value: String) -> bool:
	if value.is_empty() or value.length() > 128:
		return false
	for index: int in value.length():
		var code := value.unicode_at(index)
		var valid := (code >= 48 and code <= 57) or (code >= 65 and code <= 90) or (code >= 97 and code <= 122) or code == 45 or code == 95
		if not valid:
			return false
	return true


func _fail(message: String) -> bool:
	last_error = message
	return false

class_name SaveRepository
extends RefCounted

const SaveSlotPreviewScript := preload("res://src/infrastructure/saves/save_slot_preview.gd")

var _root_path: String
var last_error: String = ""


func _init(root_path: String = "user://saves") -> void:
	_root_path = root_path.trim_suffix("/")


func save(campaign_id: String, slot_id: String, envelope: SaveEnvelope) -> bool:
	last_error = ""
	if envelope == null or envelope.campaign_id != campaign_id:
		return _fail("Save envelope does not match the requested campaign.")
	if not _safe_component(campaign_id) or not _safe_component(slot_id):
		return _fail("Campaign and slot IDs must be portable path components.")
	var campaign_path := "%s/%s" % [_root_path, campaign_id]
	var create_error := DirAccess.make_dir_recursive_absolute(ProjectSettings.globalize_path(campaign_path))
	if create_error != OK:
		return _fail("Could not create the campaign save directory (error %d)." % create_error)
	var slot_path := "%s/%s.r2save" % [campaign_path, slot_id]
	var temp_path := slot_path + ".tmp"
	var backup_path := slot_path + ".bak"
	var file := FileAccess.open(temp_path, FileAccess.WRITE)
	if file == null:
		return _fail("Could not open the temporary save file.")
	file.store_string(JSON.stringify(envelope.to_data()))
	file.flush()
	file.close()
	var verified := _read_envelope(temp_path)
	if verified == null or verified.campaign_id != envelope.campaign_id or verified.package_hash != envelope.package_hash:
		_delete_file(temp_path)
		return _fail("Temporary save verification failed.")
	if FileAccess.file_exists(backup_path) and not _delete_file(backup_path):
		_delete_file(temp_path)
		return _fail("Could not rotate the previous save backup.")
	var absolute_slot := ProjectSettings.globalize_path(slot_path)
	var absolute_backup := ProjectSettings.globalize_path(backup_path)
	var absolute_temp := ProjectSettings.globalize_path(temp_path)
	if FileAccess.file_exists(slot_path):
		var backup_error := DirAccess.rename_absolute(absolute_slot, absolute_backup)
		if backup_error != OK:
			_delete_file(temp_path)
			return _fail("Could not move the current save to its backup (error %d)." % backup_error)
	var replace_error := DirAccess.rename_absolute(absolute_temp, absolute_slot)
	if replace_error != OK:
		if FileAccess.file_exists(backup_path):
			DirAccess.rename_absolute(absolute_backup, absolute_slot)
		_delete_file(temp_path)
		return _fail("Could not atomically install the verified save (error %d)." % replace_error)
	return true


func load(campaign_id: String, slot_id: String, expected_package_hash: String) -> SaveEnvelope:
	return _load_path(campaign_id, slot_id, expected_package_hash, false)


func load_backup(campaign_id: String, slot_id: String, expected_package_hash: String) -> SaveEnvelope:
	return _load_path(campaign_id, slot_id, expected_package_hash, true)


func list_previews(campaign_id: String, expected_package_hash: String) -> Array:
	last_error = ""
	var previews: Array = []
	if not _safe_component(campaign_id):
		_fail("Campaign ID must be a portable path component.")
		return previews
	var campaign_path := "%s/%s" % [_root_path, campaign_id]
	if not DirAccess.dir_exists_absolute(ProjectSettings.globalize_path(campaign_path)):
		return previews
	for file_name: String in DirAccess.get_files_at(campaign_path):
		var source: StringName = SaveSlotPreviewScript.PRIMARY
		var slot_id := ""
		if file_name.ends_with(".r2save.bak"):
			source = SaveSlotPreviewScript.BACKUP
			slot_id = file_name.trim_suffix(".r2save.bak")
		elif file_name.ends_with(".r2save"):
			slot_id = file_name.trim_suffix(".r2save")
		else:
			continue
		if not _safe_component(slot_id):
			continue
		previews.append(_preview_for_path(campaign_path.path_join(file_name), slot_id, source, campaign_id, expected_package_hash))
	previews.sort_custom(func(left: RefCounted, right: RefCounted) -> bool:
		if left.slot_id != right.slot_id:
			return left.slot_id.naturalnocasecmp_to(right.slot_id) < 0
		return left.source == SaveSlotPreviewScript.PRIMARY and right.source == SaveSlotPreviewScript.BACKUP
	)
	return previews


func _load_path(campaign_id: String, slot_id: String, expected_package_hash: String, backup: bool) -> SaveEnvelope:
	last_error = ""
	if not _safe_component(campaign_id) or not _safe_component(slot_id):
		_fail("Campaign and slot IDs must be portable path components.")
		return null
	var suffix := ".r2save.bak" if backup else ".r2save"
	var envelope := _read_envelope("%s/%s/%s%s" % [_root_path, campaign_id, slot_id, suffix])
	if envelope == null:
		_fail("Save backup is missing, corrupt, or uses an unsupported schema." if backup else "Save file is missing, corrupt, or uses an unsupported schema.")
		return null
	if envelope.campaign_id != campaign_id or envelope.package_hash != expected_package_hash:
		_fail("Save package identity does not match the installed campaign.")
		return null
	return envelope


func _preview_for_path(path: String, slot_id: String, source: StringName, expected_campaign_id: String, expected_package_hash: String) -> RefCounted:
	var envelope := _read_envelope(path)
	if envelope == null:
		var corrupt := SaveSlotPreviewScript.new(slot_id, source, SaveSlotPreviewScript.CORRUPT)
		corrupt.modified_unix = int(FileAccess.get_modified_time(path))
		corrupt.error_message = "This save is corrupt or uses an unsupported schema."
		return corrupt
	var status: StringName = SaveSlotPreviewScript.VALID
	var error_message := ""
	if envelope.campaign_id != expected_campaign_id:
		status = SaveSlotPreviewScript.CAMPAIGN_MISMATCH
		error_message = "This save belongs to campaign '%s'." % envelope.campaign_id
	elif envelope.package_hash != expected_package_hash:
		status = SaveSlotPreviewScript.PACKAGE_MISMATCH
		error_message = "This save was created for a different immutable package revision."
	var preview := SaveSlotPreviewScript.new(slot_id, source, status)
	preview.campaign_id = envelope.campaign_id
	preview.package_hash = envelope.package_hash
	preview.rules_version = envelope.rules_version
	preview.view_revision = envelope.view_revision
	preview.modified_unix = int(FileAccess.get_modified_time(path))
	preview.realmz_day = envelope.game_state.clock.day()
	preview.realmz_hour = envelope.game_state.clock.hour()
	preview.realmz_minute = envelope.game_state.clock.minute()
	preview.map_id = envelope.game_state.party.map_id
	preview.coordinate = envelope.game_state.party.coordinate
	for character: CharacterState in envelope.game_state.party.characters():
		preview.character_names.append(character.name)
	preview.error_message = error_message
	preview.can_load = status == SaveSlotPreviewScript.VALID
	return preview


func _read_envelope(path: String) -> SaveEnvelope:
	if not FileAccess.file_exists(path):
		return null
	var file := FileAccess.open(path, FileAccess.READ)
	if file == null:
		return null
	var parser := JSON.new()
	var parse_error := parser.parse(file.get_as_text())
	file.close()
	if parse_error != OK:
		return null
	return SaveEnvelope.from_data(parser.data)


func _delete_file(path: String) -> bool:
	if not FileAccess.file_exists(path):
		return true

class_name ApplicationMediaCatalog
extends RefCounted

const MANIFEST_PATH := "res://src/presentation/assets/classic-application-media.json"
const CASTLE_SOURCE_COMMIT := "491816ad60037394f92c428e99c004494d3c28b3"

var source_commit: String = ""
var last_error: String = ""
var _assets: Array[PackageMediaAsset] = []
var _assets_by_id: Dictionary = {}
var _assets_by_resource: Dictionary = {}
var _ambiguous_resource_keys: Dictionary = {}


func _init(manifest_path: String = MANIFEST_PATH) -> void:
	_load_manifest(manifest_path)


func is_valid() -> bool:
	return last_error.is_empty() and not _assets.is_empty()


func assets() -> Array[PackageMediaAsset]:
	return _assets.duplicate()


func asset_by_id(asset_id: String) -> PackageMediaAsset:
	return _assets_by_id.get(asset_id) as PackageMediaAsset


func asset_by_resource(resource_type: String, resource_id: int) -> PackageMediaAsset:
	if resource_type.is_empty():
		return null
	return _assets_by_resource.get(_resource_key(resource_type, resource_id)) as PackageMediaAsset


func resource_status(resource_type: String, resource_id: int) -> StringName:
	if resource_type.is_empty():
		return &"missing"
	var key := _resource_key(resource_type, resource_id)
	if _ambiguous_resource_keys.has(key):
		return &"ambiguous"
	return &"resolved" if _assets_by_resource.has(key) else &"missing"


func owns_asset(asset: PackageMediaAsset) -> bool:
	return asset != null and _assets.has(asset)


func read_bytes(asset: PackageMediaAsset) -> PackedByteArray:
	if not owns_asset(asset):
		return PackedByteArray()
	var bytes := FileAccess.get_file_as_bytes(asset.path)
	if bytes.size() != asset.byte_count or _sha256(bytes) != asset.sha256:
		return PackedByteArray()
	return bytes


func audio_stream(asset: PackageMediaAsset) -> AudioStream:
	if not owns_asset(asset) or not asset.is_sound():
		return null
	return load(asset.path) as AudioStream


func _load_manifest(manifest_path: String) -> void:
	var parsed: Variant = JSON.parse_string(FileAccess.get_file_as_string(manifest_path))
	if not parsed is Dictionary:
		last_error = "Classic application media manifest is unavailable or malformed."
		return
	var manifest := parsed as Dictionary
	if int(manifest.get("schema_version", 0)) != 1 or String(manifest.get("lookup", "")) != "scenario-first-application-fallback":
		last_error = "Classic application media manifest contract is unsupported."
		return
	source_commit = String(manifest.get("source_commit", ""))
	if source_commit != CASTLE_SOURCE_COMMIT:
		last_error = "Classic application media source revision is unsupported."
		return
	for value: Variant in manifest.get("assets", []):
		if not value is Dictionary:
			last_error = "Classic application media contains a malformed asset."
			return
		var record := value as Dictionary
		var asset := PackageMediaAsset.new(
			String(record.get("id", "")),
			String(record.get("label", "")),
			String(record.get("kind", "")),
			String(record.get("mime_type", "")),
			String(record.get("resource_type", "")),
			int(record.get("resource_id", 0)),
			int(record.get("bytes", 0)),
			String(record.get("sha256", "")),
			String(record.get("path", "")),
			int(record.get("width", 0)),
			int(record.get("height", 0)),
			int(record.get("duration_ms", 0)),
			int(record.get("sample_rate", 0)),
			int(record.get("channels", 0)),
			int(record.get("tile_width", 0)),
			int(record.get("tile_height", 0)),
			int(record.get("columns", 0)),
			int(record.get("rows", 0)),
			int(record.get("landlook", -1)),
			int(record.get("base_tile", -1))
		)
		if asset.id.is_empty() or asset.resource_type.is_empty() or asset.path.is_empty() or asset.byte_count <= 0 or asset.sha256.length() != 64:
			last_error = "Classic application media contains an incomplete asset."
			return
		if _assets_by_id.has(asset.id):
			last_error = "Classic application media contains duplicate asset IDs."
			return
		_assets.append(asset)
		_assets_by_id[asset.id] = asset
		var key := _resource_key(asset.resource_type, asset.resource_id)
		if _ambiguous_resource_keys.has(key):
			continue
		if _assets_by_resource.has(key):
			_assets_by_resource.erase(key)
			_ambiguous_resource_keys[key] = true
			last_error = "Classic application media contains duplicate resource keys."
			continue
		_assets_by_resource[key] = asset


static func _sha256(bytes: PackedByteArray) -> String:
	var hashing := HashingContext.new()
	if hashing.start(HashingContext.HASH_SHA256) != OK or hashing.update(bytes) != OK:
		return ""
	return hashing.finish().hex_encode()


static func _resource_key(resource_type: String, resource_id: int) -> String:
	return JSON.stringify([resource_type, resource_id])

