class_name ClassicPartyRoster
extends PanelContainer

signal character_selected(character_id: String)
signal combat_auto_changed(character_id: String, enabled: bool)

const MUTED := Color("9da8aa")

@onready var _party_list: VBoxContainer = %PartyList
@onready var _heading: Label = %Heading

var _media: ClassicMediaCatalog
var _selected_character_id: String = ""


func set_media_catalog(media: ClassicMediaCatalog) -> void:
	_media = media


func present(view: GameView, selected_character_id: String = "") -> void:
	_selected_character_id = selected_character_id
	_clear()
	if view == null or not view.session_started:
		_heading.text = "Party"
		_add_empty("No active party")
		return
	_heading.text = "Party • %d / 6" % view.party_members.size()
	var combat_active := view.combat_view != null and view.combat_view.outcome == &"active"
	var auto_character_ids: Array[String] = []
	if combat_active:
		auto_character_ids.assign(view.combat_view.auto_character_ids)
	for character: CharacterView in view.party_members:
		_add_character(character, combat_active, auto_character_ids)
	for index: int in maxi(0, 6 - view.party_members.size()):
		_add_empty("Empty position %d" % (view.party_members.size() + index + 1))


func _add_character(character: CharacterView, combat_active: bool, auto_character_ids: Array[String]) -> void:
	var row_container := HBoxContainer.new()
	row_container.custom_minimum_size.y = 58.0
	row_container.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	row_container.add_theme_constant_override("separation", 3)
	var row := Button.new()
	row.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	row.alignment = HORIZONTAL_ALIGNMENT_LEFT
	row.text_overrun_behavior = TextServer.OVERRUN_TRIM_ELLIPSIS
	row.add_theme_constant_override("icon_max_width", 42)
	row.toggle_mode = true
	row.button_pressed = character.id == _selected_character_id
	var condition_text := _condition_summary(character.condition_values)
	var action_fact := "SP %d/%d" % [character.spell_points, character.maximum_spell_points] if character.maximum_spell_points > 0 else "Attacks %d" % character.normal_attacks
	row.text = "%s\n%s / %s  •  Stamina %d/%d\n%s  •  AR %d%s" % [
		character.name,
		character.race_name,
		character.caste_name,
		character.current_health,
		character.maximum_health,
		action_fact,
		character.armor,
		"  •  %s" % condition_text if not condition_text.is_empty() else "",
	]
	row.tooltip_text = "Level %d • Movement %d/%d" % [character.level, character.movement, character.maximum_movement]
	var portrait := _portrait_texture(character.portrait_id)
	if portrait != null:
		row.icon = portrait
	row.pressed.connect(func() -> void:
		_selected_character_id = character.id
		character_selected.emit(character.id)
	)
	row_container.add_child(row)
	if combat_active:
		var auto_toggle := CheckButton.new()
		auto_toggle.name = "CombatAuto"
		auto_toggle.text = "Auto"
		auto_toggle.custom_minimum_size.x = 52.0
		var auto_available := character.current_health > 0 and not character.traitor
		auto_toggle.disabled = not auto_available
		auto_toggle.tooltip_text = "Persistent Auto for this character's next combat activation." if auto_available else "Persistent Auto requires a living loyal party character."
		auto_toggle.button_pressed = auto_character_ids.has(character.id)
		auto_toggle.toggled.connect(func(enabled: bool) -> void: combat_auto_changed.emit(character.id, enabled))
		row_container.add_child(auto_toggle)
	_party_list.add_child(row_container)


func _add_empty(text: String) -> void:
	var label := Label.new()
	label.custom_minimum_size.y = 42.0
	label.text = text
	label.vertical_alignment = VERTICAL_ALIGNMENT_CENTER
	label.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER
	label.add_theme_color_override("font_color", MUTED)
	_party_list.add_child(label)


func _portrait_texture(asset_id: String) -> Texture2D:
	if _media == null or asset_id.is_empty():
		return null
	var asset := _media.asset_by_id(asset_id)
	if asset == null or not asset.is_picture():
		return null
	var bytes := _media.read_bytes(asset)
	var image := Image.new()
	var error := ERR_UNAVAILABLE
	match asset.path.get_extension().to_lower():
		"png": error = image.load_png_from_buffer(bytes)
		"jpg", "jpeg": error = image.load_jpg_from_buffer(bytes)
		"webp": error = image.load_webp_from_buffer(bytes)
	return ImageTexture.create_from_image(image) if error == OK else null


func _condition_summary(values: Array[int]) -> String:
	var active: Array[String] = []
	for index: int in values.size():
		if values[index] != 0:
			active.append("Condition %d" % (index + 1))
		if active.size() == 2:
			break
	return ", ".join(active)


func _clear() -> void:
	for child: Node in _party_list.get_children():
		_party_list.remove_child(child)
		child.queue_free()

	_add_metric_views(_content, character.race_traits)
	_add_heading(_content, character.caste_name)
	_add_label(_content, character.caste_description if not character.caste_description.is_empty() else "No class description is present in this package.", MUTED)
	_add_metric_views(_content, character.caste_traits)
	_add_heading(_content, "Aging", "Viewing this table never mutates the character")
	for band: CharacterAgeBandView in character.age_bands:
		var changes: Array[String] = []
		for change: CharacterMetricView in band.changes:
			if change.value != 0:
				changes.append("%s %+d" % [change.name, change.value])
		_add_card(_content, "%s%s" % ["Current • " if band.active else "", band.name], "Ages %d–%d" % [band.minimum_age, band.maximum_age], "No changes" if changes.is_empty() else " • ".join(changes))


func _build_record(character: CharacterView) -> void:
	_add_heading(_content, "Lifetime combat record and prestige")
	if not character.record_available:
		_add_label(_content, character.record_unavailable_reason, BAD)
		_add_label(_content, "Castle derives prestige from hits, misses, damage, kills, deaths, knockouts, spells, turns, destroyed foes, and penalties. Showing zero would be misleading.", MUTED)


func _select_character(character_id: String) -> void:
	if character_id == _selected_character_id:
		return
	_selected_character_id = character_id
	_sync_appearance_draft()
	character_selected.emit(character_id)
	_rebuild()


func _select_tab(tab_id: StringName) -> void:
	if tab_id == _active_tab:
		return
	_active_tab = tab_id
	tab_changed.emit(tab_id)
	_rebuild()


func _selected_character() -> CharacterView:
	for character: CharacterView in _characters:
		if character.id == _selected_character_id:
			return character
	return null


func _tab_exists(tab_id: StringName) -> bool:
	for tab: Dictionary in TABS:
		if StringName(tab["id"]) == tab_id:
			return true
	return false


func _appearance(asset_id: String, fallback_text: String, role: String) -> PanelContainer:
	var frame := PanelContainer.new()
	frame.custom_minimum_size = Vector2(68, 68)
	var texture := _textures.get(asset_id) as Texture2D
	if texture != null:
		var image := TextureRect.new()
		image.texture = texture
		image.expand_mode = TextureRect.EXPAND_IGNORE_SIZE
		image.stretch_mode = TextureRect.STRETCH_KEEP_ASPECT_CENTERED
		image.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
		image.tooltip_text = role
		frame.add_child(image)
	else:
		var fallback := _label(fallback_text if not fallback_text.is_empty() else "?", MUTED, 18)
		fallback.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER
		fallback.vertical_alignment = VERTICAL_ALIGNMENT_CENTER
		fallback.tooltip_text = "%s media unavailable." % role
		frame.add_child(fallback)
	return frame


func _add_metrics(parent: Container, metrics: Array[CharacterMetricView]) -> void:
	_add_metric_views(parent, metrics)


func _add_metric_views(parent: Container, metrics: Array[CharacterMetricView]) -> void:
	var grid := GridContainer.new()
	grid.columns = 2
	grid.add_theme_constant_override("h_separation", 14)
	grid.add_theme_constant_override("v_separation", 3)
	grid.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	for metric: CharacterMetricView in metrics:
		var name_label := _label(metric.name, MUTED, 14)
		name_label.size_flags_horizontal = Control.SIZE_EXPAND_FILL
		if not metric.detail.is_empty():
			name_label.tooltip_text = metric.detail
		grid.add_child(name_label)
		var value_text := metric.detail if metric.value in [0, 1] and metric.detail in ["Yes", "No"] else "%+d" % metric.value if metric.value > 0 else str(metric.value)
		if not metric.detail.is_empty() and metric.name in ["Attacks / Round", "Movement"]:
			value_text = metric.detail
		elif metric.detail == "Permanent":
			value_text = "Permanent"
		var value_label := _label(value_text, GOOD if metric.value > 0 else BAD if metric.value < 0 else Color("e0e2e5"), 14)
		value_label.horizontal_alignment = HORIZONTAL_ALIGNMENT_RIGHT
		if not metric.detail.is_empty():
			value_label.tooltip_text = metric.detail
		grid.add_child(value_label)
	parent.add_child(grid)


func _metric(metric_name: String, value: int, detail: String = "") -> CharacterMetricView:
	return CharacterMetricView.new(StringName(metric_name.to_lower().replace(" ", "-")), 0, metric_name, value, detail)


func _add_heading(parent: Container, title: String, detail: String = "") -> void:
	var row := HBoxContainer.new()
	var heading := _label(title, GOLD, 18)
	heading.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	row.add_child(heading)
	if not detail.is_empty():
		var note := _label(detail, MUTED, 13)
		note.name = "HeadingDetail"
		note.size_flags_horizontal = Control.SIZE_EXPAND_FILL
		note.size_flags_stretch_ratio = 0.75
		note.horizontal_alignment = HORIZONTAL_ALIGNMENT_RIGHT
		note.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
		row.add_child(note)
	parent.add_child(row)


func _add_card(parent: Container, title: String, subtitle: String, detail: String) -> void:
	var panel := PanelContainer.new()
	panel.theme_type_variation = &"ClassicInset"
	panel.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	var box := VBoxContainer.new()
	box.add_theme_constant_override("separation", 2)
	panel.add_child(box)
	_add_label(box, title, GOLD, 16)
	_add_label(box, subtitle, Color("e0e2e5"), 14)
	if not detail.is_empty():
		_add_label(box, detail, MUTED, 13)
	parent.add_child(panel)


func _label(text: String, color: Color = Color.WHITE, font_size: int = 15) -> Label:
	var label := Label.new()
	label.text = text
	label.add_theme_color_override("font_color", color)
	label.add_theme_font_size_override("font_size", int(round(float(font_size) * _text_scale)))
	return label


func _add_label(parent: Container, text: String, color: Color = Color.WHITE, font_size: int = 15) -> Label:
	var label := _label(text, color, font_size)
	label.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
	parent.add_child(label)
	return label


func _clear(parent: Node) -> void:
	for child: Node in parent.get_children():
		parent.remove_child(child)
		child.queue_free()

	_add_heading(_content, "Conditions")
	if character.conditions.is_empty():
		_add_label(_content, "No active conditions.", MUTED)
	else:
		_add_metric_views(_content, character.conditions)
	_add_heading(_content, "Saving throws", "Castle displays all eight DRVs")
	_add_metric_views(_content, character.saving_throws)


func _build_equipment(character: CharacterView) -> void:
	_add_heading(_content, "Equipment and carried items", "%d of 30 slots" % character.items.size())
	if character.items.is_empty():
		_add_label(_content, "This character carries no items.", MUTED)
		return
	for item: ItemView in character.items:
		var state: Array[String] = ["Equipped" if item.equipped else "Carried", "Identified" if item.identified else "Unidentified"]
		if item.charges != 0:
			state.append("%d charges" % item.charges)
		_add_card(_content, item.name, " • ".join(state), "%d weight • value %d\n%s" % [item.weight, item.value, item.description])


func _build_abilities(character: CharacterView) -> void:
	_add_heading(_content, "Special modifiers", "Bonuses against Castle monster types")
	if character.special_modifiers.is_empty():
		_add_label(_content, "No active special modifiers.", MUTED)
	else:
		_add_metric_views(_content, character.special_modifiers)
	_add_heading(_content, "Special abilities")
	if character.abilities.is_empty():
		_add_label(_content, "No active special abilities.", MUTED)
	else:
		_add_metric_views(_content, character.abilities)


func _build_spells(character: CharacterView) -> void:
	_add_heading(_content, "Known spells", "%d spell points available" % character.spell_points)
	if character.spells.is_empty():
		_add_label(_content, "This character knows no spells.", MUTED)
	else:
		for spell: SpellView in character.spells:
			_add_card(_content, spell.name, "Class %d • Cost %d • Range %d–%d" % [spell.spell_class, spell.cost, spell.range_min, spell.range_max], spell.description)
	_add_heading(_content, "Scroll case", "%d fixed Classic slots" % character.scrolls.size())
	for scroll: SpellScrollView in character.scrolls:
		var empty := scroll.spell_id.is_empty()
		_add_label(_content, "Slot %d • %s" % [scroll.slot_index + 1, "Empty" if empty else "%s • Power %d" % [scroll.spell_name, scroll.power]], MUTED if empty else Color("e0e2e5"))


func _build_appearance(character: CharacterView) -> void:
	_add_heading(_content, "Portrait and combat icon", "Each Classic identity changes independently")
	_add_label(_content, "Choose a package-backed image, preview it here, then apply that one role. Discard leaves the campaign session unchanged; vault publication remains a separate explicit action.", MUTED, 13)
	var columns := HBoxContainer.new()
	columns.add_theme_constant_override("separation", 14)
	columns.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	columns.add_child(_appearance_picker(character, CharacterAppearanceDefinition.PORTRAIT, _portrait_options, _draft_portrait_id, "Portrait"))
	columns.add_child(_appearance_picker(character, CharacterAppearanceDefinition.COMBAT_ICON, _combat_icon_options, _draft_combat_icon_id, "Combat icon"))
	_content.add_child(columns)
	if not _appearance_availability.enabled:
		_add_label(_content, _appearance_availability.reason, BAD, 13)
	var actions := HFlowContainer.new()
	actions.add_theme_constant_override("h_separation", 6)
	actions.add_theme_constant_override("v_separation", 6)
	var apply_portrait := Button.new()
	apply_portrait.text = "Apply Portrait"
	apply_portrait.disabled = not _appearance_availability.enabled or _draft_portrait_id == character.portrait_id
	apply_portrait.tooltip_text = _appearance_availability.reason if not _appearance_availability.enabled else "Choose a different portrait first." if _draft_portrait_id == character.portrait_id else "Commit this portrait to the campaign session."
	if not apply_portrait.disabled:
		apply_portrait.pressed.connect(_apply_appearance.bind(CharacterAppearanceDefinition.PORTRAIT, _draft_portrait_id))
	actions.add_child(apply_portrait)
	var apply_icon := Button.new()
	apply_icon.text = "Apply Combat Icon"
	apply_icon.disabled = not _appearance_availability.enabled or _draft_combat_icon_id == character.combat_icon_id
	apply_icon.tooltip_text = _appearance_availability.reason if not _appearance_availability.enabled else "Choose a different combat icon first." if _draft_combat_icon_id == character.combat_icon_id else "Commit this tactical icon to the campaign session."
	if not apply_icon.disabled:
		apply_icon.pressed.connect(_apply_appearance.bind(CharacterAppearanceDefinition.COMBAT_ICON, _draft_combat_icon_id))
	actions.add_child(apply_icon)
	var discard := Button.new()
	discard.text = "Discard Appearance Changes"
	discard.disabled = _draft_portrait_id == character.portrait_id and _draft_combat_icon_id == character.combat_icon_id
	discard.tooltip_text = "The preview already matches the session." if discard.disabled else "Restore both previews without changing the session."
	if not discard.disabled:
		discard.pressed.connect(_discard_appearance_draft)
	actions.add_child(discard)
	_content.add_child(actions)


func _appearance_picker(character: CharacterView, kind: StringName, options: Array[CharacterAppearanceOptionView], selected_id: String, title: String) -> VBoxContainer:
	var column := VBoxContainer.new()
	column.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	column.add_theme_constant_override("separation", 6)
	_add_label(column, title, GOLD, 16)
	column.add_child(_appearance(selected_id, character.name.left(1) if kind == CharacterAppearanceDefinition.PORTRAIT else "⚔", "%s preview" % title))
	var picker := OptionButton.new()
	picker.name = "%sPicker" % title.replace(" ", "")
	picker.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	picker.fit_to_longest_item = false
	picker.clip_text = true
	picker.text_overrun_behavior = TextServer.OVERRUN_TRIM_ELLIPSIS
	var ordered := _recommended_first(options, character.race_id)
	var selected_index := -1
	for option: CharacterAppearanceOptionView in ordered:
		var recommended := option.is_recommended_for(character.race_id)
		var item_label := "%s%s • %d" % ["Recommended • " if recommended else "", option.label, option.classic_resource_id]
		var texture := _textures.get(option.id) as Texture2D
		if texture != null:
			picker.add_icon_item(texture, item_label)
		else:
			picker.add_item(item_label)
		var index := picker.item_count - 1
		picker.set_item_metadata(index, option.id)
		if option.id == selected_id:
			selected_index = index
	picker.select(selected_index)
	picker.disabled = not _appearance_availability.enabled or options.is_empty()
	picker.tooltip_text = _appearance_availability.reason if not _appearance_availability.enabled else "Browse all %d package-backed %s choices; Castle recommendations appear first." % [options.size(), title.to_lower()]
	if not picker.disabled:
		picker.item_selected.connect(_select_appearance_option.bind(picker, kind))
	column.add_child(picker)
	return column


func _recommended_first(options: Array[CharacterAppearanceOptionView], race_id: String) -> Array[CharacterAppearanceOptionView]:
	var result: Array[CharacterAppearanceOptionView] = []
	for option: CharacterAppearanceOptionView in options:
		if option.is_recommended_for(race_id):
			result.append(option)
	for option: CharacterAppearanceOptionView in options:
		if not option.is_recommended_for(race_id):
			result.append(option)
	return result


