class_name DungeonMap3DPresenter
extends SubViewportContainer

@export var cell_span: float = 2.5
@export var wall_height: float = 2.2
@export var wall_thickness: float = 0.14

var _enabled: bool = false
var _projection: DungeonGeometryProjection
var _viewport: SubViewport
var _geometry_root: Node3D
var _camera: Camera3D
var _floor_material: StandardMaterial3D
var _wall_material: StandardMaterial3D
var _door_material: StandardMaterial3D
var _secret_material: StandardMaterial3D
var _feature_material: StandardMaterial3D
var _party_material: StandardMaterial3D


func _ready() -> void:
	position = Vector2(205.0, 58.0)
	size = Vector2(530.0, 452.0)
	z_index = 6
	mouse_filter = Control.MOUSE_FILTER_IGNORE
	stretch = true
	visible = false
	_floor_material = _material(Color(0.27, 0.25, 0.20))
	_wall_material = _material(Color(0.53, 0.55, 0.58))
	_door_material = _material(Color(0.64, 0.42, 0.20))
	_secret_material = _material(Color(0.45, 0.25, 0.54))
	_feature_material = _material(Color(0.62, 0.62, 0.57))
	_party_material = _material(Color(0.92, 0.70, 0.20))
	_viewport = SubViewport.new()
	_viewport.name = "DungeonViewport"
	_viewport.size = Vector2i(530, 452)
	_viewport.own_world_3d = true
	_viewport.render_target_update_mode = SubViewport.UPDATE_WHEN_VISIBLE
	add_child(_viewport)
	_geometry_root = Node3D.new()
	_geometry_root.name = "TopologyGeometry"
	_viewport.add_child(_geometry_root)
	_camera = Camera3D.new()
	_camera.name = "DungeonCamera"
	_camera.fov = 58.0
	_viewport.add_child(_camera)
	var light := DirectionalLight3D.new()
	light.name = "DungeonLight"
	light.rotation_degrees = Vector3(-55.0, -35.0, 0.0)
	light.light_energy = 1.4
	_viewport.add_child(light)
	var environment_node := WorldEnvironment.new()
	var environment := Environment.new()
	environment.background_mode = Environment.BG_COLOR
	environment.background_color = Color(0.025, 0.027, 0.032)
	environment.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR
	environment.ambient_light_color = Color(0.46, 0.48, 0.54)
	environment.ambient_light_energy = 0.55
	environment_node.environment = environment
	_viewport.add_child(environment_node)


func set_enabled(enabled: bool) -> void:
	_enabled = enabled
	_update_visibility()


func present(game_view: GameView) -> void:
	_projection = null
	if game_view != null and game_view.session_started:
		_projection = DungeonGeometryProjection.from_map_view(game_view.map_view)
	_rebuild_geometry()
	_update_visibility()


func is_active() -> bool:
	return _enabled and _projection != null


func projection() -> DungeonGeometryProjection:
	return _projection


func _update_visibility() -> void:
	visible = is_active()


func _rebuild_geometry() -> void:
	if _geometry_root == null:
		return
	for child: Node in _geometry_root.get_children():
		_geometry_root.remove_child(child)
		child.queue_free()
	if _projection == null:
		return
	for cell: DungeonGeometryProjection.CellProjection in _projection.cells():
		if cell.passable:
			_add_box("Floor_%d_%d" % [cell.coordinate.x, cell.coordinate.y], Vector3(cell_span * 0.94, 0.10, cell_span * 0.94), _cell_center(cell.coordinate) + Vector3(0.0, -0.08, 0.0), _floor_material)
		if cell.features.has(&"column"):
			_add_column(cell.coordinate)
		if cell.features.has(&"stairs"):
			_add_stairs(cell.coordinate)
	var built_edges: Dictionary = {}
	for edge: DungeonGeometryProjection.EdgeProjection in _projection.edges():
		if edge.kind == &"open" or built_edges.has(edge.canonical_key):
			continue
		built_edges[edge.canonical_key] = true
		if edge.kind in [&"door", &"archway"]:
			_add_door_frame(edge)
		else:
			_add_wall(edge, _secret_material if edge.kind == &"secret" else _wall_material)
	_add_party_marker()
	var target := _cell_center(_projection.party_coordinate) + Vector3(0.0, 0.65, 0.0)
	_camera.position = target + Vector3(5.6, 7.5, 7.8)
	_camera.look_at(target, Vector3.UP)


func _add_wall(edge: DungeonGeometryProjection.EdgeProjection, surface_material: Material) -> void:
	var horizontal := edge.direction in [&"north", &"south"]
	var box_dimensions := Vector3(cell_span, wall_height, wall_thickness) if horizontal else Vector3(wall_thickness, wall_height, cell_span)
	_add_box("Edge_%s" % edge.canonical_key, box_dimensions, _edge_center(edge.coordinate, edge.direction) + Vector3(0.0, wall_height * 0.5, 0.0), surface_material)


func _add_door_frame(edge: DungeonGeometryProjection.EdgeProjection) -> void:
	var horizontal := edge.direction in [&"north", &"south"]
	var center := _edge_center(edge.coordinate, edge.direction)
	var post_offset := cell_span * 0.37
	var post_size := Vector3(wall_thickness * 1.35, wall_height * 0.82, wall_thickness * 1.35)
	var left_offset := Vector3(post_offset, 0.0, 0.0) if horizontal else Vector3(0.0, 0.0, post_offset)
	_add_box("DoorPostA_%s" % edge.canonical_key, post_size, center - left_offset + Vector3(0.0, post_size.y * 0.5, 0.0), _door_material)
	_add_box("DoorPostB_%s" % edge.canonical_key, post_size, center + left_offset + Vector3(0.0, post_size.y * 0.5, 0.0), _door_material)
	var lintel_size := Vector3(cell_span, wall_thickness * 1.5, wall_thickness * 1.5) if horizontal else Vector3(wall_thickness * 1.5, wall_thickness * 1.5, cell_span)
	_add_box("DoorLintel_%s" % edge.canonical_key, lintel_size, center + Vector3(0.0, wall_height * 0.84, 0.0), _door_material)
	if edge.kind == &"door" and not edge.passable:
		var panel_size := Vector3(cell_span * 0.62, wall_height * 0.70, wall_thickness * 0.65) if horizontal else Vector3(wall_thickness * 0.65, wall_height * 0.70, cell_span * 0.62)
		_add_box("DoorPanel_%s" % edge.canonical_key, panel_size, center + Vector3(0.0, panel_size.y * 0.5, 0.0), _door_material)


func _add_column(coordinate: Vector2i) -> void:
	var mesh := CylinderMesh.new()
	mesh.top_radius = 0.26
	mesh.bottom_radius = 0.31
	mesh.height = wall_height * 0.88
	var instance := MeshInstance3D.new()
	instance.name = "Column_%d_%d" % [coordinate.x, coordinate.y]
	instance.mesh = mesh
	instance.material_override = _feature_material
	instance.position = _cell_center(coordinate) + Vector3(0.0, mesh.height * 0.5, 0.0)
	_geometry_root.add_child(instance)


func _add_stairs(coordinate: Vector2i) -> void:
	for index: int in range(3):
		var height := 0.12 * float(index + 1)
		_add_box("Stair_%d_%d_%d" % [coordinate.x, coordinate.y, index], Vector3(cell_span * 0.62, height, cell_span * 0.20), _cell_center(coordinate) + Vector3(0.0, height * 0.5, (float(index) - 1.0) * cell_span * 0.20), _feature_material)


func _add_party_marker() -> void:
	var mesh := CylinderMesh.new()
	mesh.top_radius = 0.24

class_name CombatPlaybackFrame
extends RefCounted

var kind: StringName
var duration_seconds: float
var progress: float = 0.0
var actor_id: String = ""
var target_id: String = ""
var from_coordinate := Vector2i(-1, -1)
var to_coordinate := Vector2i(-1, -1)
var combatant_positions: Dictionary = {}
var hidden_combatant_ids: Array[String] = []
var result_kind: StringName = &""
var display_text: String = ""
var display_amount: int = 0
var effect_resource_type: String = "cicn"
var effect_resource_id: int = 0
var battle_tile_id: int = 0
var sound_event: DomainEvent


func _init(frame_kind: StringName, frame_duration_seconds: float) -> void:
	kind = frame_kind
	duration_seconds = maxf(frame_duration_seconds, 0.0)


func position_for(combatant_id: String) -> Vector2i:
	var value: Variant = combatant_positions.get(combatant_id)
	if value is Vector2i:
		return value
	return Vector2i(-1, -1)


func hides(combatant_id: String) -> bool:
	return hidden_combatant_ids.has(combatant_id)

func _append_bleeding_result(event: DomainEvent, positions: Dictionary, hidden: Array[String], defeated: bool) -> void:
	var target_id := String(event.payload.get("characterId", ""))
	var frame := _new_frame(&"result", RESULT_SECONDS, positions, hidden)
	frame.target_id = target_id
	frame.result_kind = &"bleeding"
	frame.display_text = "Bled to death" if defeated else "Bleeding"
	_frames.append(frame)
	if defeated and not target_id.is_empty() and not hidden.has(target_id):
		hidden.append(target_id)


func _append_simple_result(event: DomainEvent, positions: Dictionary, hidden: Array[String], result_kind: StringName, text: String) -> void:
	var frame := _new_frame(&"result", RESULT_SECONDS, positions, hidden)
	frame.actor_id = String(event.payload.get("actorId", ""))
	frame.target_id = String(event.payload.get("targetId", frame.actor_id))
	frame.result_kind = result_kind
	frame.display_text = text
	_frames.append(frame)


func _append_result(event: DomainEvent, positions: Dictionary, hidden: Array[String]) -> void:
	var result := _new_frame(&"result", RESULT_SECONDS, positions, hidden)
	result.actor_id = String(event.payload.get("actorId", ""))
	result.target_id = String(event.payload.get("targetId", ""))
	result.result_kind = _result_kind(event.payload)
	result.display_amount = int(event.payload.get("healing", event.payload.get("damage", 0)))
	result.display_text = _result_text(result.result_kind, result.display_amount)
	result.effect_resource_id = int(event.payload.get("classicResultEffectResourceId", 0))
	_frames.append(result)
	if bool(event.payload.get("defeated", false)) and not result.target_id.is_empty():
		var defeat := _new_frame(&"defeat", DEFEAT_SECONDS, positions, hidden)
		defeat.target_id = result.target_id
		defeat.result_kind = &"defeat"
		defeat.display_text = "Defeated"
		_frames.append(defeat)
		if not hidden.has(result.target_id):
			hidden.append(result.target_id)


func _append_next_actor_cue() -> void:
	if final_view == null or final_view.combat_view == null or final_view.combat_view.outcome != &"active":
		return
	var prior_actor := previous_view.combat_view.active_actor_id if previous_view != null and previous_view.combat_view != null else ""
	var next_actor := final_view.combat_view.active_actor_id
	var prior_round := previous_view.combat_view.round_number if previous_view != null and previous_view.combat_view != null else -1
	if next_actor == prior_actor and final_view.combat_view.round_number == prior_round:
		return
	var positions := _positions_for(final_view)
	var cue := _new_frame(&"actor_cue", CUE_SECONDS, positions, [])
	cue.actor_id = next_actor
	cue.target_id = next_actor
	cue.display_text = "Round %d" % final_view.combat_view.round_number if final_view.combat_view.round_number != prior_round else ""
	_frames.append(cue)


func _new_frame(kind: StringName, duration: float, positions: Dictionary, hidden: Array[String]) -> CombatPlaybackFrame:
	var frame := CombatPlaybackFrame.new(kind, duration)
	frame.combatant_positions = positions.duplicate(true)
	frame.hidden_combatant_ids = hidden.duplicate()
	return frame


func _positions_for(view: GameView) -> Dictionary:
	var result: Dictionary = {}
	if view == null or view.combat_view == null or view.combat_view.battlefield == null:
		return result
	for character: CharacterView in view.party_members:
		var coordinate := view.combat_view.battlefield.character_position(character.id)
		if coordinate.x >= 0:
			result[character.id] = coordinate
	for monster: MonsterView in view.combat_view.monsters:
		var coordinate := view.combat_view.battlefield.monster_position(monster.id)
		if coordinate.x >= 0:
			result[monster.id] = coordinate
	return result


func _position_for(combatant_id: String, positions: Dictionary) -> Vector2i:
	var value: Variant = positions.get(combatant_id)
	if value is Vector2i:
		return value
	var coordinate := _view_position(previous_view, combatant_id)
	if coordinate.x >= 0:
		return coordinate
	return _view_position(final_view, combatant_id)


func _view_position(view: GameView, combatant_id: String) -> Vector2i:
	if view == null or view.combat_view == null:
		return Vector2i(-1, -1)
	return ClassicBattlefieldPresenter.actor_position(view.combat_view, view.party_members, combatant_id)


static func _payload_coordinate(value: Variant) -> Vector2i:
	if value is Vector2i:
		return value
	if value is Array and value.size() == 2:
		return Vector2i(int(value[0]), int(value[1]))
	return Vector2i(-1, -1)


static func _result_kind(payload: Dictionary) -> StringName:
	if bool(payload.get("fumble", false)):
		return &"fumble"
	if bool(payload.get("blocked", false)):
		return &"blocked"
	if bool(payload.get("immune", false)):
		return &"immune"
	if bool(payload.get("resisted", false)):
		return &"resisted"
	if bool(payload.get("saved", false)):
		return &"saved"
	if not bool(payload.get("hit", true)):
		return &"miss"
	if int(payload.get("healing", 0)) > 0:
		return &"healing"
	if int(payload.get("damage", 0)) > 0:
		return &"damage"
	return &"no_effect"


static func _result_text(result_kind: StringName, amount: int) -> String:
	match result_kind:
		&"miss":
			return "Miss"
		&"blocked":
			return "Blocked"
		&"immune":
			return "Immune"
		&"resisted":
			return "Resist"
		&"saved":
			return "Saved"
		&"fumble":
			return "Fumble"
		&"healing":
			return "+%d" % amount
		&"damage":
			return str(amount)
	return "No effect"

class_name ClassicUiAssetCatalog
extends RefCounted

const MANIFEST_PATH := "res://src/presentation/assets/classic-ui-assets.json"

static var _definitions: Dictionary = {}


static func definition(asset_id: StringName) -> Dictionary:
	_ensure_loaded()
	return _definitions.get(String(asset_id), {})


static func texture(asset_id: StringName) -> Texture2D:
	var record := ClassicUiAssetCatalog.definition(asset_id)
	if record.is_empty():
		return null
	return load(String(record.get("path", ""))) as Texture2D


static func native_size(asset_id: StringName) -> Vector2i:
	var record := ClassicUiAssetCatalog.definition(asset_id)
	return Vector2i(int(record.get("native_width", 0)), int(record.get("native_height", 0)))


static func all_definitions() -> Array[Dictionary]:
	_ensure_loaded()
	var result: Array[Dictionary] = []
	for value: Variant in _definitions.values():
		result.append(value as Dictionary)
	return result


static func _ensure_loaded() -> void:
	if not _definitions.is_empty():
		return
	var parsed: Variant = JSON.parse_string(FileAccess.get_file_as_string(MANIFEST_PATH))
	if not parsed is Dictionary:
		push_error("Classic UI asset manifest is unavailable or malformed.")
		return
	for value: Variant in (parsed as Dictionary).get("assets", []):
		if value is Dictionary:
			var record := value as Dictionary
			_definitions[String(record.get("id", ""))] = record

func service_rows(cost_percent: int) -> Array[Dictionary]:
	var rows: Array[Dictionary] = []
	for index: int in SERVICE_IDS.size():
		rows.append({
			"id": String(SERVICE_IDS[index]),
			"label": LABELS[index],
			"description": DESCRIPTIONS[index],
			"cost": service_cost(SERVICE_IDS[index], cost_percent),
		})
	return rows

func service_cost(service_id: StringName, cost_percent: int) -> int:
	var index := SERVICE_IDS.find(service_id)
	if index < 0:
		return 0
	return RealmzArithmetic.new().signed_16(int(float(BASE_COSTS[index] * cost_percent) / 100.0))

func _apply_healing(character: CharacterState, amount: int, result: TempleServiceResult) -> void:
	if character.conditions.is_active(CONDITION_STONE) or character.current_health < -9:
		return
	var wrapped_health := RealmzArithmetic.new().signed_16(character.current_health + amount)
	character.current_health = mini(character.maximum_health, maxi(-10, wrapped_health))
	result.applied = character.current_health != result.health_before

func signed_16(value: int) -> int:
	var wrapped := value & 0xffff
	return wrapped - 0x10000 if wrapped >= 0x8000 else wrapped

func signed_32(value: int) -> int:
	var wrapped := value & 0xffffffff
	return wrapped - 0x1_0000_0000 if wrapped >= 0x8000_0000 else wrapped

func can_restore_item(character: CharacterState, item: ItemInstance, definition: ItemDefinition) -> bool:
	if character == null or item == null or definition == null or item.definition_id != definition.id:
		return false
	var items := character.inventory()
	if items.size() >= MAX_ITEMS or character.carried_load + definition.instance_weight(item.charges) > character.maximum_load:
		return false
	for carried: ItemInstance in items:
		if carried.id == item.id:
			return false
	return true

func restore_item(character: CharacterState, item: ItemInstance, definition: ItemDefinition) -> bool:
	if not can_restore_item(character, item, definition):
		return false
	var items := character.inventory()
	item.equipped = false
	items.append(item)
	character.set_inventory(items)
	character.carried_load += definition.instance_weight(item.charges)
	return true

static func _passive_effects_supported(item: ItemDefinition) -> bool:
	if item.strength_bonus != 0 or item.movement_bonus != 0 or item.magic_resistance_bonus != 0 or item.spell_point_bonus != 0:
		return false
	if item.special_3 != 0 or item.special_4 != 0 or item.special_1 == 122:
		return false
	return item.special_1 < 20 or item.special_1 >= 100

static func _first_category(low: int, high: int) -> int:
	for index: int in 58:
		if _mask_has(low, high, index):
			return index
	return -1

static func _definitions_by_id(definitions: Array[ItemDefinition]) -> Dictionary:
	var result: Dictionary = {}
	for definition: ItemDefinition in definitions:
		result[definition.id] = definition
	return result

func remove_item(character: CharacterState, instance_id: String, definition: ItemDefinition) -> ItemInstance:
	if character == null or definition == null:
		return null
	var items := character.inventory()
	for index: int in items.size():
		var instance := items[index]
		if instance.id != instance_id or instance.definition_id != definition.id:
			continue
		items.remove_at(index)
		character.set_inventory(items)
		character.carried_load = maxi(0, character.carried_load - definition.instance_weight(instance.charges))
		return instance
	return null

func _init(character_rules: CharacterRules = null, realmz_arithmetic: RealmzArithmetic = null) -> void:
	_characters = character_rules if character_rules != null else CharacterRules.new()
	_arithmetic = realmz_arithmetic if realmz_arithmetic != null else RealmzArithmetic.new()

func resolve_character_targeted_spell(caster: CharacterState, selection: SpellTargetSelection, spell: SpellDefinition, power_level: int, cast_level: int, rng: RealmzRng, spend_spell_points: bool = true) -> GroupSpellResolution:
	if caster == null or not _selection_is_valid(selection) or spell == null or rng == null or power_level < 1:
		return null
	var spell_cost := absi(spell.cost * power_level)
	if spend_spell_points and caster.spell_points < spell_cost:
		return GroupSpellResolution.new(false, spell_cost, 0, 0)
	if spend_spell_points:
		caster.spell_points -= spell_cost
	else:
		spell_cost = 0
	var effective := _reflect_to_character_caster(caster, selection, rng, &"magic.reflect")
	var duration := _scaled_roll(spell.duration_min, spell.duration_max, spell.power_duration_min, spell.power_duration_max, power_level, rng, &"magic.duration")
	var damage := _scaled_roll(spell.damage_min, spell.damage_max, spell.power_damage_min, spell.power_damage_max, power_level, rng, &"magic.damage")
	var result := GroupSpellResolution.new(true, spell_cost, duration, damage)
	if not effective.reflected and effective.kind == &"monster" and effective.monster.magic_resistance > 100:
		return result
	var resolution := _resolve_character_selection(caster, effective, spell, power_level, cast_level, damage, duration, spell_cost, rng)
	result.append_target(effective.id, effective.kind, resolution, effective.original_target_id, effective.reflected)
	return result

func resolve_character_group_spell(caster: CharacterState, character_targets: Array[CharacterState], monster_targets: Array[MonsterState], monster_definitions: Array[MonsterDefinition], spell: SpellDefinition, power_level: int, cast_level: int, rng: RealmzRng, allow_empty: bool = false, spend_spell_points: bool = true) -> GroupSpellResolution:
	if caster == null or spell == null or rng == null or power_level < 1 or monster_targets.size() != monster_definitions.size() or not allow_empty and character_targets.is_empty() and monster_targets.is_empty():
		return null
	for target: CharacterState in character_targets:
		if target == null:
			return null
	for index: int in monster_targets.size():
		if monster_targets[index] == null or monster_definitions[index] == null:
			return null
	var spell_cost := absi(spell.cost * power_level)
	if spend_spell_points and caster.spell_points < spell_cost:
		return GroupSpellResolution.new(false, spell_cost, 0, 0)
	if spend_spell_points:
		caster.spell_points -= spell_cost
	else:
		spell_cost = 0
	var duration := _scaled_roll(spell.duration_min, spell.duration_max, spell.power_duration_min, spell.power_duration_max, power_level, rng, &"magic.duration")
	var damage := _scaled_roll(spell.damage_min, spell.damage_max, spell.power_damage_min, spell.power_damage_max, power_level, rng, &"magic.damage")
	var result := GroupSpellResolution.new(true, spell_cost, duration, damage)
	for target: CharacterState in character_targets:
		result.append_target(target.id, &"character", _resolve_character_spell_character_target(caster, target, spell, power_level, cast_level, damage, duration, rng))
	for index: int in monster_targets.size():
		var target := monster_targets[index]
		var definition := monster_definitions[index]
		result.append_target(target.id, &"monster", _resolve_character_spell_monster_target(caster.level, target, definition, spell, power_level, cast_level, damage, duration, 0, rng))
	return result

func resolve_character_repeated_spell(caster: CharacterState, selections: Array[SpellTargetSelection], spell: SpellDefinition, power_level: int, cast_level: int, rng: RealmzRng, spend_spell_points: bool = true) -> RepeatedSpellResolution:
	if caster == null or spell == null or rng == null or power_level < 1 or selections.is_empty() or selections.size() > power_level:
		return null
	for selection: SpellTargetSelection in selections:
		if selection == null or (selection.character == null and (selection.monster == null or selection.monster_definition == null)):
			return null
	var spell_cost := absi(spell.cost * power_level)
	if spend_spell_points and caster.spell_points < spell_cost:
		return RepeatedSpellResolution.new(false, spell_cost, selections.size())
	if spend_spell_points:
		caster.spell_points -= spell_cost
	else:
		spell_cost = 0
	var result := RepeatedSpellResolution.new(true, spell_cost, selections.size())
	for index: int in selections.size():
		var selection := _reflect_to_character_caster(caster, selections[index], rng, StringName("magic.repeated.reflect.%d" % index))
		var duration := _scaled_roll(spell.duration_min, spell.duration_max, spell.power_duration_min, spell.power_duration_max, power_level, rng, StringName("magic.repeated.duration.%d" % index))
		var damage := _scaled_roll(spell.damage_min, spell.damage_max, spell.power_damage_min, spell.power_damage_max, power_level, rng, StringName("magic.repeated.damage.%d" % index))
		if not selection.reflected and selection.kind == &"monster" and selection.monster.magic_resistance > 100:
			result.exclude_target(selection.original_target_id)
			continue
		var resolution := _resolve_character_selection(caster, selection, spell, power_level, cast_level, damage, duration, 0, rng)
		result.append_target(selection.id, selection.kind, resolution, selection.original_target_id, selection.reflected)
	return result

func equip(character: CharacterState, instance_id: String, definition: ItemDefinition) -> bool:
	if not can_equip(character, definition):
		return false
	for instance: ItemInstance in character.inventory():
		if instance.id == instance_id and instance.definition_id == definition.id:
			instance.equipped = true
			return true
	return false

func calculated_load(character: CharacterState, definitions: Array[ItemDefinition]) -> int:
	if character == null:
		return -1
	var definitions_by_id := _definitions_by_id(definitions)
	var total := character.money.gold + character.money.gems + character.money.jewelry * 15
	for instance: ItemInstance in character.inventory():
		var definition: ItemDefinition = definitions_by_id.get(instance.definition_id)
		if definition == null:
			return -1
		total += definition.instance_weight(instance.charges)
	return maxi(0, total)

func use_charge(character: CharacterState, instance_id: String, definition: ItemDefinition) -> bool:
	var items := character.inventory()
	for index: int in items.size():
		var instance := items[index]
		if instance.id != instance_id or instance.definition_id != definition.id or instance.charges == 0:
			continue
		if instance.charges > 0:
			instance.charges -= 1
			character.carried_load = maxi(0, character.carried_load - definition.weight_per_charge)
		if instance.charges == 0 and definition.drop_on_empty:
			items.remove_at(index)
			character.carried_load = maxi(0, character.carried_load - definition.weight)
			character.set_inventory(items)
		return true
	return false

func _init(hit_bonus: int = 0, damage: int = 0) -> void:
	to_hit_bonus = hit_bonus
	damage_bonus = damage

func add_item(character: CharacterState, item: ItemDefinition, instance_id: String, identified: bool = false) -> ItemInstance:
	if character == null or item == null or character.inventory().size() >= MAX_ITEMS:
		return null
	var instance := ItemInstance.new(instance_id, item.id, item.initial_charges, false, identified)
	var items := character.inventory()
	if character.carried_load + item.instance_weight(instance.charges) > character.maximum_load:
		return null
	items.append(instance)
	character.set_inventory(items)
	character.carried_load += item.instance_weight(instance.charges)
	return instance

static func _invalid_weapon_reason(weapon: ItemDefinition) -> StringName:
	if weapon == null:
		return &""
	if weapon.vs_small < 0 or weapon.vs_large < 0 or weapon.heat < 0 or weapon.cold < 0 or weapon.electric < 0 or weapon.vs_undead < 0 or weapon.vs_demon_devil < 0 or weapon.vs_evil < 0:
		return &"unsupported_negative_weapon_range"
	if weapon.special_1 == -10:
		if weapon.special_3 < 20 or weapon.special_3 >= 60:
			return &"invalid_weapon_condition"
		if weapon.special_2 == 1 and (weapon.special_4 < 0 or weapon.special_4 >= 8):
			return &"invalid_weapon_condition_save"
	return &""

func _roll_weapon_condition_monster(weapon: ItemDefinition, defender: MonsterState, defender_definition: MonsterDefinition, rng: RealmzRng) -> Dictionary:
	if weapon == null or weapon.special_1 != -10:
		return {}
	var result := {"index": weapon.special_3 - 20, "amount": weapon.special_5, "applies": false}
	match weapon.special_2:
		1:
			var roll := rng.draw(100, &"combat.attack.weapon-condition-save")
			var chance := _monster_save_chance(defender, defender_definition, weapon.special_4)
			result["saveIndex"] = weapon.special_4
			result["saveChance"] = chance
			result["saveRoll"] = roll
			result["applies"] = not _monster_saved(defender, defender_definition, weapon.special_4, roll, chance)
		2:
			var roll := rng.draw(100, &"combat.attack.weapon-condition-chance")
			result["chance"] = weapon.special_4
			result["roll"] = roll
			result["applies"] = roll <= weapon.special_4
		_:
			result["applies"] = true
	return result

static func _apply_weapon_condition_monster(defender: MonsterState, condition_roll: Dictionary, resolution: AttackResolution) -> void:
	if condition_roll.is_empty() or not condition_roll.get("applies", false):
		return
	var index := int(condition_roll["index"])
	resolution.weapon_condition_index = index
	resolution.weapon_condition_before = defender.conditions.value(index)
	resolution.weapon_condition_after = resolution.weapon_condition_before
	if resolution.weapon_condition_before > -1:
		resolution.weapon_condition_after += int(condition_roll["amount"])
		defender.conditions.set_value(index, resolution.weapon_condition_after)

static func _record_weapon_condition_character(defender: CharacterState, condition_roll: Dictionary, resolution: AttackResolution) -> void:
	if condition_roll.is_empty() or not condition_roll.get("applies", false):
		return
	var index := int(condition_roll["index"])
	resolution.weapon_condition_index = index
	resolution.weapon_condition_before = defender.conditions.value(index)
	resolution.weapon_condition_after = resolution.weapon_condition_before
	if resolution.weapon_condition_before > -1:
		resolution.weapon_condition_after += int(condition_roll["amount"])

static func _roll_weapon_physical(weapon: ItemDefinition, defender_definition: MonsterDefinition, rng: RealmzRng) -> int:
	var damage := 0
	if defender_definition != null:
		if weapon.vs_undead != 0 and defender_definition.type_flag(1):
			damage += rng.draw(maxi(1, weapon.vs_undead), &"combat.attack.weapon-versus-undead")
		if weapon.vs_demon_devil != 0 and defender_definition.type_flag(2):
			damage += rng.draw(maxi(1, weapon.vs_demon_devil), &"combat.attack.weapon-versus-demon-devil")
		if weapon.vs_evil != 0 and defender_definition.type_flag(4):
			damage += rng.draw(maxi(1, weapon.vs_evil), &"combat.attack.weapon-versus-evil")
	# Castle's player melee path always uses the small-target weapon die, including Rand(0).
	damage += rng.draw(maxi(1, weapon.vs_small), &"combat.attack.weapon-physical")
	return damage

func _roll_weapon_elements_monster(weapon: ItemDefinition, defender: MonsterState, defender_definition: MonsterDefinition, rng: RealmzRng, effects: Array[Dictionary]) -> int:
	var total := 0
	var ranges: Array[int] = [weapon.heat, weapon.cold, weapon.electric]
	var names: Array[StringName] = [&"fire", &"cold", &"electrical"]
	var save_indexes: Array[int] = [1, 2, 3]
	var conditions: Array[int] = [ConditionRules.FIRE_PROTECTION, ConditionRules.COLD_PROTECTION, ConditionRules.ELECTRICAL_PROTECTION]
	for index: int in 3:
		if ranges[index] == 0 or defender_definition.spell_immune(save_indexes[index]):
			continue
		var rolled := rng.draw(ranges[index], StringName("combat.attack.weapon-%s" % names[index]))
		var effective := rolled
		var protected := defender.conditions.is_active(conditions[index])
		if protected:
			effective = int(float(effective) / 2.0)
		var save_roll := rng.draw(100, StringName("combat.attack.weapon-%s-save" % names[index]))
		var save_chance := _monster_save_chance(defender, defender_definition, save_indexes[index])
		var saved := _monster_saved(defender, defender_definition, save_indexes[index], save_roll, save_chance)
		if saved:
			effective = int(float(effective) / 2.0)
		effects.append({"element": String(names[index]), "rolled": rolled, "saveIndex": save_indexes[index], "saveChance": save_chance, "saveRoll": save_roll, "saved": saved, "protected": protected, "amount": effective})
		total += effective
	return total

static func _roll_weapon_elements_character(weapon: ItemDefinition, defender: CharacterState, rng: RealmzRng, effects: Array[Dictionary]) -> int:
	var total := 0
	var ranges: Array[int] = [weapon.heat, weapon.cold, weapon.electric]
	var names: Array[StringName] = [&"fire", &"cold", &"electrical"]
	var save_indexes: Array[int] = [1, 2, 3]
	var conditions: Array[int] = [ConditionRules.FIRE_PROTECTION, ConditionRules.COLD_PROTECTION, ConditionRules.ELECTRICAL_PROTECTION]
	for index: int in 3:
		if ranges[index] == 0:
			continue
		var rolled := rng.draw(ranges[index], StringName("combat.attack.weapon-%s" % names[index]))
		var save_roll := rng.draw(100, StringName("combat.attack.weapon-%s-save" % names[index]))
		var save_chance := defender.save_value(save_indexes[index])
		var saved := save_roll <= save_chance
		var effective := int(float(rolled) / 2.0) if saved else rolled
		var protected := defender.conditions.is_active(conditions[index])
		if protected:
			effective = int(float(effective) / 2.0)
		effects.append({"element": String(names[index]), "rolled": rolled, "saveIndex": save_indexes[index], "saveChance": save_chance, "saveRoll": save_roll, "saved": saved, "protected": protected, "amount": effective})
		total += effective
	return total

func resolve_monster_attack_monster(attacker: MonsterState, attacker_definition: MonsterDefinition, attack_index: int, defender: MonsterState, defender_definition: MonsterDefinition, rng: RealmzRng, context: MonsterAttackContext = null, allow_fumbles: bool = false) -> AttackResolution:
	if attacker == null or attacker_definition == null or defender == null or defender_definition == null or rng == null:
		return null
	var attack_context := context if context != null else MonsterAttackContext.new()
	var invalid_weapon := _invalid_weapon_reason(attack_context.attacker_weapon)
	if not invalid_weapon.is_empty():
		return _blocked_monster_attack(invalid_weapon)
	var condition_roll := _roll_weapon_condition_monster(attack_context.attacker_weapon, defender, defender_definition, rng)
	if condition_roll.get("blocked", false):
		return _blocked_monster_attack(StringName(condition_roll.get("reason", "invalid_weapon_condition")))
	var chance := _monster_attack_base_chance(attacker, attacker_definition, attack_context)
	chance += _attacker_condition_modifier(attacker.conditions)
	if attacker.conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL):
		chance += 10
	chance -= defender.armor
	chance += _defender_condition_modifier(defender.conditions, false)
	if attacker_definition.type_flag(4) and defender.conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL):
		chance -= 10
	chance = maxi(10, chance)
	var roll := rng.draw(100, &"combat.monster-attack.hit")
	var hit := roll <= chance or _monster_weapon_auto_hits(attack_context.attacker_weapon)
	var helpless := defender.conditions.is_active(ConditionRules.HELPLESS)
	if helpless:
		hit = true
	var fumble_roll := _monster_fumble_roll(attacker, rng, allow_fumbles)
	if _monster_fumbled(attack_context.attacker_weapon, fumble_roll):
		return _fumbled_attack(chance, roll, fumble_roll)
	if not hit:
		return _with_monster_fumble_roll(AttackResolution.new(false, false, chance, roll, 0), fumble_roll)
	var weapon_requirement := _monster_required_weapon_reason(attack_context.attacker_weapon, defender_definition)
	if not weapon_requirement.is_empty():
		return _with_monster_fumble_roll(_blocked_monster_attack(weapon_requirement, chance, roll), fumble_roll)
	var attacks := attacker_definition.attacks()
	var attack := _monster_attack_row(attacks, attack_index)
	var damage := attacker_definition.damage_bonus + attacker.conditions.value(ConditionRules.ATTACK_BONUS)
	if attacker.conditions.is_active(ConditionRules.STRONG):
		damage += 3
	var effects: Array[Dictionary] = []
	var elemental_damage := 0
	if helpless:
		damage = defender.current_health
	elif attack_context.attacker_weapon != null:
		damage += attack_context.attacker_weapon.damage_bonus
		damage += rng.draw(maxi(1, attack_context.attacker_weapon.vs_small), &"combat.monster-attack.weapon-physical")
		elemental_damage = _roll_weapon_elements_monster(attack_context.attacker_weapon, defender, defender_definition, rng, effects)
		elemental_damage += _roll_monster_weapon_type_damage(attack_context.attacker_weapon, defender_definition, rng, effects)
	else:
		damage += rng.draw_between(attack.damage_min, attack.damage_max, &"combat.monster-attack.damage")
	damage = maxi(0, damage)
	var resolution := AttackResolution.new(true, defender.current_health - damage - elemental_damage <= 0, chance, roll, damage + elemental_damage)
	_with_monster_fumble_roll(resolution, fumble_roll)
	resolution.physical_damage = damage
	resolution.weapon_effects = effects
	if attack.special != 0:
		resolution.special_code = attack.special
		var potency_low := int(float(attacker.hit_dice) / 2.0)
		resolution.special_potency = maxi(1, rng.draw_between(potency_low, attacker.hit_dice, &"combat.monster-attack.special-potency"))
		if _is_status_special(attack.special):
			resolution.special_handled = true
			resolution.special_save_index = _status_save_index(attack.special)
			resolution.special_condition_index = _status_condition_index(attack.special)
			resolution.special_condition_before = defender.conditions.value(resolution.special_condition_index)
			resolution.special_condition_after = resolution.special_condition_before
		elif _is_resource_special(attack.special):
			resolution.special_handled = true
			resolution.special_save_index = _resource_save_index(attack.special)
			resolution.special_resource = &"spell_points" if attack.special == 8 else &"experience"
		elif attack.special == 17:
			resolution.special_handled = true
		elif attack.special == 10:
			resolution.special_handled = true
			resolution.special_save_index = 0
			resolution.special_allegiance_before = defender.traitor
			resolution.special_allegiance_after = defender.traitor
		elif _is_elemental_special(attack.special):
			resolution.special_handled = true
			resolution.special_save_index = attack.special - 10
			resolution.special_condition_index = _elemental_condition_index(attack.special)
			resolution.special_element = _elemental_name(attack.special)
		elif attack.special in [18, 19]:
			resolution.special_handled = true
			resolution.special_save_index = 7
			resolution.special_condition_index = ConditionRules.BLIND if attack.special == 18 else ConditionRules.TURNED_TO_STONE
		if defender.magic_resistance > 100:
			resolution.special_blocked = true
			resolution.special_block_reason = &"magic_resistance"
			resolution.hit = false
			resolution.damage = 0
			resolution.killed = false
			return resolution
	if _is_status_special(attack.special):
		_apply_monster_status_special(resolution, defender, defender_definition, rng)
	elif attack.special == 8:
		_apply_monster_spell_drain(resolution, attacker, defender, defender_definition, rng)
	elif attack.special == 9:
		resolution.special_blocked = true
		resolution.special_block_reason = &"party_target_only"
	elif attack.special == 10:
		_apply_monster_charm_special(resolution, attacker, defender, defender_definition, rng)
	elif _is_elemental_special(attack.special):
		_apply_monster_elemental_special(resolution, attack, defender, defender_definition, rng)
	elif attack.special == 17:
		resolution.special_handled = true
	elif attack.special in [18, 19]:
		_apply_monster_permanent_affliction(resolution, defender, defender_definition, rng)
	_apply_weapon_condition_monster(defender, condition_roll, resolution)
	if not resolution.physical_damage_skipped:
		defender.current_health -= damage + elemental_damage + resolution.special_damage_amount
		resolution.killed = defender.current_health <= 0
	return resolution

static func _monster_attack_row(attacks: Array[MonsterAttackDefinition], attack_index: int) -> MonsterAttackDefinition:
	if attacks.is_empty():
		return MonsterAttackDefinition.new(1, 1)
	var selected := attacks[clampi(attack_index, 0, attacks.size() - 1)]
	if selected.damage_min == 0:
		return attacks[0]
	return selected

static func _monster_required_weapon_reason(weapon: ItemDefinition, defender: MonsterDefinition) -> StringName:
	if defender.required_weapon == 0:
		return &""
	if weapon == null:
		if defender.required_weapon == -1:
			return &"classic_blunt_weapon_required"
		if defender.required_weapon == -2:
			return &"classic_sharp_weapon_required"
		return &"classic_specific_weapon_required"
	if defender.required_weapon == -1:
		return &"" if weapon.blunt == -1 else &"classic_blunt_weapon_required"
	if defender.required_weapon == -2:
		return &"" if weapon.blunt == -2 else &"classic_sharp_weapon_required"
	var required_item_id := defender.required_weapon & 0xff
	return &"" if weapon.classic_id == required_item_id else &"classic_specific_weapon_required"

static func _required_weapon_reason(equipment: CharacterCombatEquipment, defender: MonsterDefinition, hit: bool) -> StringName:
	if not hit or defender.required_weapon == 0:
		return &""
	if not equipment.is_armed():
		if defender.required_weapon == -1:
			return &"classic_blunt_weapon_required"
		if defender.required_weapon == -2:
			return &"classic_sharp_weapon_required"
		return &"classic_specific_weapon_required"
	if defender.required_weapon == -1:
		return &"" if equipment.melee_weapon.blunt == -1 else &"classic_blunt_weapon_required"
	if defender.required_weapon == -2:
		return &"" if equipment.melee_weapon.blunt == -2 else &"classic_sharp_weapon_required"
	# FD-COMBAT-003: Castle's minus-1024 comparison cannot match the shipped
	# 1..999 item IDs. Divinity defines this byte as the ordinary Item Number.
	var required_item_id := defender.required_weapon & 0xff
	return &"" if equipment.melee_weapon.classic_id == required_item_id else &"classic_specific_weapon_required"

func resolve_monster_attack(attacker: MonsterState, attacker_definition: MonsterDefinition, attack_index: int, defender: CharacterState, race: RaceDefinition, caste: CasteDefinition, rng: RealmzRng, charm_save_bonus: int = 0, context: MonsterAttackContext = null, allow_fumbles: bool = false) -> AttackResolution:
	if attacker == null or attacker_definition == null or defender == null or rng == null:
		return null
	var attack_context := context if context != null else MonsterAttackContext.new(null, 0, false, defender.luck)
	var invalid_weapon := _invalid_weapon_reason(attack_context.attacker_weapon)
	if not invalid_weapon.is_empty():
		return _blocked_monster_attack(invalid_weapon)
	var condition_roll := _roll_weapon_condition_character(attack_context.attacker_weapon, defender, rng)
	if condition_roll.get("blocked", false):
		return _blocked_monster_attack(StringName(condition_roll.get("reason", "invalid_weapon_condition")))
	var chance := _monster_attack_base_chance(attacker, attacker_definition, attack_context)
	chance += _attacker_condition_modifier(attacker.conditions)
	if attacker.conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL):
		chance += 10
	chance -= rng.draw_classic(attack_context.defender_luck, &"combat.monster-attack.defender-luck")
	chance -= attack_context.defender_armor if attack_context.defender_armor >= 0 else defender.armor
	chance += _defender_condition_modifier(defender.conditions, false)
	if attacker_definition.type_flag(4) and defender.conditions.is_active(ConditionRules.PROTECTION_FROM_EVIL):
		chance -= 10
	chance = maxi(10, chance)
	var roll := rng.draw(100, &"combat.monster-attack.hit")
	var hit := roll <= chance or _monster_weapon_auto_hits(attack_context.attacker_weapon)
	var helpless := defender.conditions.is_active(ConditionRules.HELPLESS)
	if helpless:
		hit = true
	var fumble_roll := _monster_fumble_roll(attacker, rng, allow_fumbles)
	if _monster_fumbled(attack_context.attacker_weapon, fumble_roll):
		return _fumbled_attack(chance, roll, fumble_roll)
	if not hit:
		return _with_monster_fumble_roll(AttackResolution.new(false, false, chance, roll, 0), fumble_roll)
	var attacks := attacker_definition.attacks()
	var attack := _monster_attack_row(attacks, attack_index)
	var damage := attacker_definition.damage_bonus + attacker.conditions.value(ConditionRules.ATTACK_BONUS)
	if attacker.conditions.is_active(ConditionRules.STRONG):
		damage += 3
	var effects: Array[Dictionary] = []
	var elemental_damage := 0
	if helpless:
		damage = defender.current_health + rng.draw(10, &"combat.monster-attack.helpless-damage")
	elif attack_context.attacker_weapon != null:
		damage += attack_context.attacker_weapon.damage_bonus
		damage += rng.draw(maxi(1, attack_context.attacker_weapon.vs_small), &"combat.monster-attack.weapon-physical")
		elemental_damage = _roll_weapon_elements_character(attack_context.attacker_weapon, defender, rng, effects)
	else:
		damage += rng.draw_between(attack.damage_min, attack.damage_max, &"combat.monster-attack.damage")
	damage = maxi(0, damage)
	var resolution_physical_damage_reduction := 0
	if attack_context.party_dragon_hide and damage > 1:
		var damage_before_dragon_hide := damage
		damage = maxi(1, damage - 5)
		resolution_physical_damage_reduction = damage_before_dragon_hide - damage
	var resolution := AttackResolution.new(true, defender.current_health - damage - elemental_damage <= 0, chance, roll, damage + elemental_damage)
	_with_monster_fumble_roll(resolution, fumble_roll)
	resolution.physical_damage = damage
	resolution.physical_damage_reduction = resolution_physical_damage_reduction
	resolution.physical_feedback_sound_id = 694 if resolution_physical_damage_reduction > 0 else 0
	resolution.weapon_effects = effects
	if attack.special != 0:
		resolution.special_code = attack.special
		var potency_low := int(float(attacker.hit_dice) / 2.0)
		resolution.special_potency = maxi(1, rng.draw_between(potency_low, attacker.hit_dice, &"combat.monster-attack.special-potency"))
	if _is_status_special(attack.special):
		_apply_party_status_special(resolution, defender, rng)
	elif _is_resource_special(attack.special):
		_apply_party_resource_special(resolution, attacker, defender, rng)
	elif attack.special == 10:
		_apply_party_charm_special(resolution, attacker, defender, rng, charm_save_bonus)
	elif _is_elemental_special(attack.special):
		_apply_party_elemental_special(resolution, attack, defender, rng)
	elif attack.special == 17:
		resolution.special_handled = true
		resolution.special_save_index = 7
		resolution.special_save_chance = defender.save_value(7)
		resolution.special_save_roll = rng.draw(100, &"combat.monster-attack.special-save")
		resolution.special_saved = resolution.special_save_roll <= resolution.special_save_chance
		if not resolution.special_saved:
			resolution.special_applied = true
			var age_factor := _signed_16(attack.damage_max * attacker.hit_dice)
			resolution.special_age_days = int(float(race.max_age) * 0.01 * float(age_factor)) if race != null else 0
			if race != null and caste != null:
				resolution.aging = _characters.advance_age_days(defender, race, caste, resolution.special_age_days)
	elif attack.special in [18, 19]:
		_apply_party_permanent_affliction(resolution, defender, rng)
	resolution.damage_deferred = resolution.aging != null and resolution.aging.changed_group()
	if resolution.damage_deferred:
		_record_weapon_condition_character(defender, condition_roll, resolution)
	else:
		_apply_weapon_condition_character(defender, condition_roll, resolution)
	if not resolution.damage_deferred and not resolution.physical_damage_skipped:
		defender.current_health -= damage + elemental_damage + resolution.special_damage_amount
		resolution.killed = defender.current_health <= 0
	return resolution

func continue_after_age_update(state: GameState, content: RealmzContent, rng: RealmzRng) -> CombatFlowResult:
	if state == null or content == null or rng == null or state.combat == null or state.combat.pending_monster_attack == null:
		return CombatFlowResult.failed(&"invalid_age_update_continuation", "Monster age-update continuation requires an active battle.")
	var events: Array[DomainEvent] = []
	var combat := state.combat
	var pending := combat.pending_monster_attack
	var target := state.party.character_by_id(pending.target_id)
	if target == null:
		return CombatFlowResult.failed(&"invalid_age_update_continuation", "The pending monster attack target is unavailable.")
	if pending.weapon_condition_index >= 0:
		if target.conditions.value(pending.weapon_condition_index) != pending.weapon_condition_before:
			return CombatFlowResult.failed(&"invalid_age_update_continuation", "The pending monster weapon condition no longer matches its saved boundary.")
		target.conditions.set_value(pending.weapon_condition_index, pending.weapon_condition_after)
	_append_monster_physical_feedback(events, pending.physical_feedback_sound_id)
	target.current_health -= pending.damage
	if pending.damage > 0:
		combat.mark_attacked(target.id)
	var defeated := target.current_health <= 0
	_mark_character_bleeding(state, target, defeated)
	_remove_defeated_position(combat, target.id, defeated)
	var pending_attack_index := maxi(0, combat.active_turn.attack_index - 1) if combat.active_turn != null and combat.pending_reaction == null else 0
	var pending_attacker := combat.monster_by_id(pending.actor_id)
	var pending_definition := content.monster_by_id(pending_attacker.definition_id) if pending_attacker != null else null
	var pending_weapon := content.item_by_id(pending_attacker.weapon_id) if pending_attacker != null and not pending_attacker.weapon_id.is_empty() else null
	var pending_resolution := AttackResolution.new(true, defeated, pending.chance, pending.roll, pending.damage)
	_append_monster_attack_audio(events, pending_attacker, pending_definition, pending_attack_index, pending_weapon, pending_resolution, rng)
	var attack_event := DomainEvent.new(&"combat_attack_resolved", {"actorId": pending.actor_id, "targetId": pending.target_id, "action": String(pending.action), "attackIndex": pending_attack_index, "hit": true, "damage": pending.damage, "defeated": defeated, "chance": pending.chance, "roll": pending.roll})
	_append_physical_result_effect(attack_event, true, pending_weapon != null)
	if combat.pending_reaction != null:
		_append_reaction_identity(attack_event, pending.action, pending.action == &"withdrawal")
	events.append(attack_event)
	combat.pending_monster_attack = null
	if combat.pending_reaction != null:
		var reaction_kind := combat.pending_reaction.kind
		var mover_id := combat.pending_reaction.mover_id
		if defeated:
			combat.pending_reaction.mover_killed = true
		var reaction_result := _continue_pending_reaction(state, content, rng, events)
		if reaction_result == REACTION_WAITING or reaction_result == REACTION_DEATH_MACRO:
			return CombatFlowResult.succeeded(events)
		if reaction_result == REACTION_MOVER_DEFEATED:
			if combat.active_actor_id() == mover_id:
				_advance_turn(state, rng, events)
			if _finish_if_resolved(state, content, events):
				return CombatFlowResult.succeeded(events, true)
			_process_monster_turns(state, content, rng, events)
			return CombatFlowResult.succeeded(events, state.combat.completed)
		if reaction_kind == CombatReactionState.CHARACTER_MOVE:
			return CombatFlowResult.succeeded(events)
		_process_monster_turns(state, content, rng, events)
		return CombatFlowResult.succeeded(events, state.combat.completed)
	if _finish_if_resolved(state, content, events):
		return CombatFlowResult.succeeded(events, true)
	var monster := combat.monster_by_id(pending.actor_id)
	var definition := content.monster_by_id(monster.definition_id) if monster != null else null
	if combat.active_turn == null or combat.active_turn.actor_id != pending.actor_id or pending.action != &"advance" or definition == null or combat.active_turn.attack_index >= _monster_attack_limit(definition):
		_advance_turn(state, rng, events)
	elif defeated:
		combat.active_turn.target_id = ""
	_process_monster_turns(state, content, rng, events)
	return CombatFlowResult.succeeded(events, state.combat.completed)

func ally_selection_payload(state: GameState, content: RealmzContent) -> Dictionary:
	if state == null or content == null or state.combat == null or not state.combat.completed or state.allies_suspended:
		return {}
	var candidates: Array[Dictionary] = []
	for monster: MonsterState in state.combat.monsters():
		if candidates.size() >= 32 or monster.current_health <= 0 or monster.traitor:
			continue
		var definition := content.monster_by_id(monster.definition_id)
		if definition == null or definition.can_summon == 0:
			continue
		candidates.append({
			"id": monster.id,
			"name": monster.name,
			"currentHealth": monster.current_health,
			"maximumHealth": monster.maximum_health,
			"classicMonsterId": definition.classic_id,
			"required": definition.can_summon < 0,
			"canSummon": definition.can_summon,
		})
	# Castle bodycount.c returns before creating Dialog 173 when count is zero.
	# An empty choice is not an interaction boundary and must not stall battle return.
	if candidates.is_empty():
		return {}
	# bodycount.c promotes mandatory allies and then orders optional survivors by stamina.
	for _pass: int in range(maxi(0, candidates.size() - 1)):
		for index: int in range(maxi(0, candidates.size() - 1)):
			var current: Dictionary = candidates[index]
			var following: Dictionary = candidates[index + 1]
			if int(current["currentHealth"]) < int(following["currentHealth"]) or int(following["canSummon"]) < 0:
				candidates[index] = following
				candidates[index + 1] = current
	var required_ids: Array[String] = []
	for candidate: Dictionary in candidates:
		if candidate["required"]:
			required_ids.append(candidate["id"])
	var maximum := mini(18, 4 + required_ids.size())
	var selected_ids: Array[String] = required_ids.duplicate()
	for index: int in range(mini(10, candidates.size())):
		var candidate_id: String = candidates[index]["id"]
		if selected_ids.size() < maximum and not selected_ids.has(candidate_id):
			selected_ids.append(candidate_id)
	return {
		"prompt": "Choose the allies who will continue with the party.",
		"candidates": candidates,
		"requiredIds": required_ids,
		"maximum": maximum,
		"selectedIds": selected_ids,
	}

func apply_ally_selection(state: GameState, content: RealmzContent, selected_value: Variant) -> CombatFlowResult:
	var payload := ally_selection_payload(state, content)
	if payload.is_empty() or not selected_value is Array:
		return CombatFlowResult.failed(&"invalid_ally_selection", "The post-battle ally selection is unavailable.")
	var selected_ids: Array[String] = []
	for value: Variant in selected_value:
		if not value is String or value.is_empty() or selected_ids.has(value):
			return CombatFlowResult.failed(&"invalid_ally_selection", "Selected allies must be unique stable IDs.")
		selected_ids.append(value)
	if selected_ids.size() > int(payload["maximum"]):
		return CombatFlowResult.failed(&"invalid_ally_selection", "The ally selection exceeds the Classic body-count limit.")
	var candidate_ids: Array[String] = []
	for candidate: Dictionary in payload["candidates"]:
		candidate_ids.append(candidate["id"])
	for required_id: String in payload["requiredIds"]:
		if not selected_ids.has(required_id):
			return CombatFlowResult.failed(&"required_ally_missing", "A scenario-mandatory ally cannot be left behind.")
	for selected_id: String in selected_ids:
		if not candidate_ids.has(selected_id):
			return CombatFlowResult.failed(&"invalid_ally_selection", "The ally selection contains an unavailable combatant.")
	var retained: Array[MonsterState] = []
	for selected_id: String in selected_ids:
		var monster := state.combat.monster_by_id(selected_id)
		if monster == null:
			return CombatFlowResult.failed(&"invalid_ally_selection", "The selected combatant is unavailable.")
		monster.traitor = false
		retained.append(monster)
	state.party.set_allies(retained)
	return CombatFlowResult.succeeded([DomainEvent.new(&"allies_selected", {"battleId": state.combat.battle_id, "allyIds": selected_ids, "maximum": payload["maximum"]})], true)

func fumble_recovery_payload(state: GameState, content: RealmzContent) -> Dictionary:
	if state == null or content == null or state.combat == null or not state.combat.completed:
		return {}
	var queued := state.combat.fumbled_items()
	if queued.is_empty():
		return {}
	var item: ItemInstance = queued[0]
	var definition := content.item_by_id(item.definition_id)
	if definition == null:
		return {}
	var candidates: Array[Dictionary] = []
	for character: CharacterState in state.party.characters():
		var enabled := _rules.inventory.can_restore_item(character, item, definition)
		var reason := ""
		if character.inventory().size() >= InventoryRules.MAX_ITEMS:
			reason = "Inventory is full."
		elif character.carried_load + definition.instance_weight(item.charges) > character.maximum_load:
			reason = "The item would exceed maximum load."
		elif not enabled:
			reason = "This character cannot receive the item."
		candidates.append({
			"id": character.id,
			"name": character.name,
			"currentHealth": character.current_health,
			"maximumHealth": character.maximum_health,
			"enabled": enabled,
			"reason": reason,
		})
	return {
		"mode": "fumbled-item-recovery",
		"prompt": "Recover the fumbled weapon or leave it behind.",
		"battleId": state.combat.battle_id,
		"item": {
			"instanceId": item.id,
			"definitionId": item.definition_id,
			"name": definition.name,
			"charges": item.charges,
			"identified": true,
		},
		"characters": candidates,
		"remaining": queued.size(),
	}

func apply_fumble_recovery(state: GameState, content: RealmzContent, response_payload: Variant) -> CombatFlowResult:
	var request_payload := fumble_recovery_payload(state, content)
	if request_payload.is_empty() or not response_payload is Dictionary:
		return CombatFlowResult.failed(&"invalid_fumble_recovery", "Fumbled-weapon recovery is unavailable.")
	if not response_payload.get("action") is String or not response_payload.get("instanceId") is String or response_payload["instanceId"] != request_payload["item"]["instanceId"]:
		return CombatFlowResult.failed(&"invalid_fumble_recovery", "Fumbled-weapon recovery must identify the pending item and action.")
	var action: String = response_payload["action"]
	var instance_id: String = response_payload["instanceId"]
	if action == "discard":
		var discarded := state.combat.remove_fumbled_item(instance_id)
		if discarded == null:
			return CombatFlowResult.failed(&"invalid_fumble_recovery", "The pending fumbled weapon is unavailable.")
		return CombatFlowResult.succeeded([DomainEvent.new(&"fumbled_item_left_behind", {"battleId": state.combat.battle_id, "instanceId": discarded.id, "itemId": discarded.definition_id})])
	if action != "assign" or not response_payload.get("characterId") is String:
		return CombatFlowResult.failed(&"invalid_fumble_recovery", "Fumbled-weapon recovery requires an available character or discard action.")
	var character_id: String = response_payload["characterId"]
	var candidate: Dictionary = {}
	for entry: Dictionary in request_payload["characters"]:
		if entry["id"] == character_id:
			candidate = entry
			break
	if candidate.is_empty() or not candidate["enabled"]:
		return CombatFlowResult.failed(&"invalid_fumble_recovery", "The selected character cannot receive the fumbled weapon.")
	var character := state.party.character_by_id(character_id)
	var queued: ItemInstance = state.combat.fumbled_items()[0]
	var definition := content.item_by_id(queued.definition_id)
	if character == null or definition == null or not _rules.inventory.can_restore_item(character, queued, definition):
		return CombatFlowResult.failed(&"invalid_fumble_recovery", "The selected character can no longer receive the fumbled weapon.")
	var recovered := state.combat.remove_fumbled_item(instance_id)
	if recovered == null or not _rules.inventory.restore_item(character, recovered, definition):
		if recovered != null:
			state.combat.requeue_fumbled_item_first(recovered)
		return CombatFlowResult.failed(&"invalid_fumble_recovery", "The fumbled weapon could not be restored atomically.")
	return CombatFlowResult.succeeded([DomainEvent.new(&"fumbled_item_recovered", {"battleId": state.combat.battle_id, "instanceId": recovered.id, "itemId": recovered.definition_id, "characterId": character.id})])

func _fire_character_projectile(state: GameState, content: RealmzContent, actor: CharacterState, equipment: CharacterCombatEquipment, target_id: String, rng: RealmzRng) -> CombatFlowResult:
	var combat := state.combat
	var profile := character_projectile_profile(actor, content, equipment)
	if not profile.available:
		return CombatFlowResult.failed(profile.error_code, profile.error_message)
	var target := combat.monster_by_id(target_id)
	if target == null or target.current_health <= 0 or target.traitor == actor.traitor:
		return CombatFlowResult.failed(&"invalid_projectile_target", "This source-backed projectile slice can target only a living hostile monster.")
	if not projectile_target_is_valid(combat, content, actor.id, target.id, profile.maximum_range, profile.spell.range_min + profile.spell.range_max > 0):
		return CombatFlowResult.failed(&"projectile_target_unavailable", "The target is outside the Classic projectile range or line of sight.")
	var definition := content.monster_by_id(target.definition_id)
	var caste := content.caste_by_id(actor.caste_id)
	if definition == null or caste == null:
		return CombatFlowResult.failed(&"projectile_target_unavailable", "Projectile resolution requires the target monster and caster caste definitions.")
	_prepare_character_turn(combat, actor)
	if not _rules.inventory.use_charge(actor, profile.item_instance_id, profile.item):
		return CombatFlowResult.failed(&"projectile_charge_unavailable", "The selected projectile charge could not be consumed atomically.")
	combat.invalidate_undo()
	var resolution := _rules.magic.resolve_character_projectile(actor, caste, profile.item, target, profile.spell, profile.power_level, rng)
	if resolution == null:
		return CombatFlowResult.failed(&"unsupported_projectile_spell", "The selected projectile cannot be resolved by the source-backed missile rules.")
	if resolution.total_damage > 0:
		combat.mark_attacked(target.id)
	combat.active_turn.physical_action_committed = true
	actor.attacks_remaining = _rules.arithmetic.signed_16(actor.attacks_remaining - 2)
	actor.movement = maxi(0, actor.movement - 12)
	var events: Array[DomainEvent] = [DomainEvent.new(&"combat_projectile_resolved", {
		"actorId": actor.id,
		"targetId": target.id,
		"targetKind": "monster",
		"itemId": profile.item.id,
		"spellId": profile.spell.id,
		"powerLevel": profile.power_level,
		"range": _rules.battlefield.classic_range(combat.battlefield, actor.id, target.id),
		"hitCount": resolution.hit_count,
		"missCount": resolution.miss_count,
		"damage": resolution.total_damage,
		"defeated": resolution.target_defeated,
		"source": "classic",
	})]
	var death_macro_requested := resolution.target_defeated and _request_monster_death_macro(target, definition, events)
	_remove_defeated_position(combat, target.id, resolution.target_defeated and not death_macro_requested)
	if not _character_can_continue(actor):
		_advance_turn(state, rng, events)
	if death_macro_requested:
		return CombatFlowResult.succeeded(events)
	if _finish_if_resolved(state, content, events):
		return CombatFlowResult.succeeded(events, true)
	_process_monster_turns(state, content, rng, events)
	return CombatFlowResult.succeeded(events, state.combat.completed)

static func _projectile_spell_unavailable_reason(spell: SpellDefinition) -> String:
	if spell.target_type != 1:
		return "Classic projectile spell '%s' does not use a single-target picker." % spell.id
	if absi(spell.spell_class) != 9:
		return "Classic projectile spell '%s' is not missile class 9." % spell.id
	if absi(spell.damage_type) != 9:
		return "Elemental projectile spell '%s' requires its source-backed save and special-effect path." % spell.id
	if spell.special != 0:
		return "Projectile spell '%s' uses unresolved Classic special %d." % [spell.id, spell.special]
	return ""

func _consume_character_attack(character: CharacterState) -> void:
	character.attacks_remaining = _rules.arithmetic.signed_16(character.attacks_remaining - 2)
	character.movement = maxi(0, character.movement - 3)

static func _magic_weapon_requirement_reason(attacker: CharacterState, equipment: CharacterCombatEquipment, defender: MonsterDefinition, hit: bool) -> StringName:
	if defender.magic_to_hit <= 0:
		return &""
	if equipment.is_armed():
		if hit and defender.magic_to_hit > equipment.melee_weapon.damage_bonus:
			return &"classic_magic_weapon_required"
		return &""
	if defender.magic_to_hit > attacker.level / 8:
		return &"classic_magic_weapon_required"
	return &""

func _process_monster_turns(state: GameState, content: RealmzContent, rng: RealmzRng, events: Array[DomainEvent]) -> void:
	var combat := state.combat
	var guard := combat.turn_order().size()
	while guard > 0 and not combat.completed:
		var actor_id := combat.active_actor_id()
		var monster := combat.monster_by_id(actor_id)
		if monster == null:
			var charmed_actor := state.party.character_by_id(actor_id)
			if charmed_actor != null and (combat.battlefield == null or not combat.battlefield.has_actor(charmed_actor.id)):
				_advance_turn(state, rng, events)
				guard -= 1
				continue
			if charmed_actor == null or not charmed_actor.traitor:
				if charmed_actor != null and charmed_actor.current_health > 0:
					_prepare_character_turn(combat, charmed_actor)
					if state.combat_auto_enabled(charmed_actor.id) and not _processing_auto:
						var auto_result := run_persistent_auto_characters(state, content, rng)
						if not auto_result.ok:
							events.append(DomainEvent.new(&"combat_auto_failed", {"actorId": charmed_actor.id, "code": String(auto_result.error_code), "message": auto_result.error_message, "rolledBack": true}))
							return
						events.append_array(auto_result.events)
						return
				break
			if charmed_actor.current_health > 0 and _process_charmed_character_turn(state, content, charmed_actor, rng, events):
				_advance_turn(state, rng, events)
				return
			_advance_turn(state, rng, events)
			if _finish_if_resolved(state, content, events):
				break
			guard -= 1
			continue
		if monster.current_health <= 0:
			_advance_turn(state, rng, events)
			guard -= 1
			continue
		if combat.active_turn == null:
			combat.set_guarding(monster.id, true)
		if monster.conditions.is_active(ConditionRules.HELPLESS):
			events.append(DomainEvent.new(&"combat_monster_action", {"actorId": monster.id, "action": "incapacitated"}))
			_advance_turn(state, rng, events)
			guard -= 1
			continue
		var definition := content.monster_by_id(monster.definition_id)
		if definition == null:
			events.append(DomainEvent.new(&"combat_monster_action", {"actorId": monster.id, "action": "unavailable_definition"}))
			_advance_turn(state, rng, events)
			guard -= 1
			continue
		var active_turn := combat.begin_active_turn()
		if active_turn.movement_remaining < 0:
			active_turn.movement_remaining = _monster_movement_allowance(monster, definition)
		if active_turn.target_id.is_empty() and active_turn.attack_index == 0:
			active_turn.target_id = monster.target_id
		if active_turn.action.is_empty():
			active_turn.action = _rules.monsters.choose_action(monster, definition, rng, not _hostile_adjacent_ids(state, monster.id).is_empty())
		var attack_result := MONSTER_ATTACK_COMPLETED
		if active_turn.action == &"advance":
			if monster.conditions.is_active(ConditionRules.SPEEDY):
				events.append(DomainEvent.new(&"combat_monster_action_unavailable", {"actorId": monster.id, "action": "advance", "reason": "monster-speedy-cadence-unresolved"}))
			elif monster.conditions.value(ConditionRules.TANGLED) < 0:
				events.append(DomainEvent.new(&"combat_monster_action_unavailable", {"actorId": monster.id, "action": "advance", "reason": "permanent-tangle-movement-unresolved"}))
			else:
				attack_result = _process_monster_advance(state, content, monster, definition, active_turn, rng, events)
				if attack_result != MONSTER_ATTACK_COMPLETED:
					return
				if _monster_can_retry_cast(state, monster, definition, active_turn):
					attack_result = _process_monster_cast(state, content, monster, definition, active_turn, rng, events)
		elif active_turn.action == &"missile":
			attack_result = _process_monster_projectile(state, content, monster, definition, active_turn, rng, events)
			if attack_result == MONSTER_ATTACK_FALLBACK:
				active_turn.action = _rules.monsters.choose_action_after_missile(monster, definition, rng)
				if active_turn.action == &"cast":
					attack_result = _process_monster_cast(state, content, monster, definition, active_turn, rng, events)
					if attack_result == MONSTER_ATTACK_FALLBACK:
						active_turn.action = &"advance"
						attack_result = _process_monster_advance(state, content, monster, definition, active_turn, rng, events)
						if attack_result == MONSTER_ATTACK_COMPLETED and _monster_can_retry_cast(state, monster, definition, active_turn):
							attack_result = _process_monster_cast(state, content, monster, definition, active_turn, rng, events)
				else:
					attack_result = _process_monster_advance(state, content, monster, definition, active_turn, rng, events)
					if attack_result == MONSTER_ATTACK_COMPLETED and _monster_can_retry_cast(state, monster, definition, active_turn):
						attack_result = _process_monster_cast(state, content, monster, definition, active_turn, rng, events)
			if attack_result != MONSTER_ATTACK_COMPLETED:
				return
		elif active_turn.action == &"cast":
			attack_result = _process_monster_cast(state, content, monster, definition, active_turn, rng, events)
			if attack_result == MONSTER_ATTACK_FALLBACK:
				active_turn.action = &"advance"
				attack_result = _process_monster_advance(state, content, monster, definition, active_turn, rng, events)
				if attack_result == MONSTER_ATTACK_COMPLETED and _monster_can_retry_cast(state, monster, definition, active_turn):
					attack_result = _process_monster_cast(state, content, monster, definition, active_turn, rng, events)
			if attack_result != MONSTER_ATTACK_COMPLETED:
				return
		elif active_turn.action == &"retreat":
			attack_result = _process_monster_retreat(state, content, monster, definition, active_turn, rng, events)
			if attack_result != MONSTER_ATTACK_COMPLETED:
				return
		else:
			events.append(DomainEvent.new(&"combat_monster_action", {"actorId": monster.id, "action": String(active_turn.action)}))
		_advance_turn(state, rng, events)
		if _finish_if_resolved(state, content, events):
			break
		guard -= 1

static func _monster_spell_unavailable_reason(spell: SpellDefinition) -> String:
	if spell.queue_icon != 0:
		return "monster-queued-spell-field-unresolved"
	if spell.target_type in [9, 10, 12]:
		return "monster-group-spell-power-resource-anomaly"
	if spell.target_type == 0 and spell.size != 0:
		return "monster-repeated-open-space-spell-unresolved"
	if spell.target_type not in [0, 1]:
		return "monster-spell-target-shape-unresolved"
	var healing_spell := _is_source_backed_combat_healing_spell(spell)
	if spell.special != 0 and not healing_spell:
		return "monster-spell-special-unresolved"
	if not healing_spell and (absi(spell.damage_type) < 1 or absi(spell.damage_type) > 6 or absi(spell.spell_class) == 9):
		return "monster-spell-damage-class-unresolved"
	if not healing_spell and spell.damage_min == 0 and spell.damage_max == 0 and spell.power_damage_min == 0 and spell.power_damage_max == 0:
		return "monster-spell-zero-damage-effect-unresolved"
	if spell.cost <= 0:
		return "monster-spell-nonpositive-cost-anomaly"
	if spell.cannot == 4 and not healing_spell:
		return "monster-spell-friendly-target-unresolved"
	return ""

static func _is_source_backed_combat_healing_spell(spell: SpellDefinition) -> bool:
	if spell == null or absi(spell.special) != 57 or not spell.in_combat or spell.queue_icon != 0 or spell.target_type != 1 or spell.cannot != 4 or spell.cost <= 0:
		return false
	if absi(spell.spell_class) != 8 or absi(spell.damage_type) != 8:
		return false
	if spell.duration_min != 0 or spell.duration_max != 0 or spell.power_duration_min != 0 or spell.power_duration_max != 0:
		return false
	if spell.damage_min < 0 or spell.damage_max < 0 or spell.power_damage_min < 0 or spell.power_damage_max < 0:
		return false
	return spell.damage_min > 0 or spell.damage_max > 0 or spell.power_damage_min > 0 or spell.power_damage_max > 0

func _process_monster_advance(state: GameState, content: RealmzContent, monster: MonsterState, definition: MonsterDefinition, active_turn: CombatTurnState, rng: RealmzRng, events: Array[DomainEvent]) -> int:
	var combat := state.combat
	var terrain_set := _battle_terrain_set(content, combat.battlefield)
	if terrain_set == null:
		events.append(DomainEvent.new(&"combat_monster_action_unavailable", {"actorId": monster.id, "action": "advance", "reason": "missing-battle-terrain"}))
		active_turn.movement_remaining = 0
		return MONSTER_ATTACK_COMPLETED
	var contact_origin := combat.battlefield.actor_position(monster.id)
	combat.pending_reaction = CombatReactionState.new(CombatReactionState.MONSTER_CONTACT, monster.id, contact_origin, contact_origin, 0)
	combat.pending_reaction.set_phase(CombatReactionState.GUARD_AFTER, _guarding_hostiles(state, monster.id))
	var contact_result := _continue_pending_reaction(state, content, rng, events)
	if contact_result == REACTION_WAITING:
		return MONSTER_ATTACK_WAITING
	if contact_result == REACTION_DEATH_MACRO:
		return MONSTER_ATTACK_DEATH_MACRO
	if contact_result == REACTION_MOVER_DEFEATED:
		return MONSTER_ATTACK_COMPLETED
	var operation_guard := 512
	while operation_guard > 0 and active_turn.attack_index < _monster_attack_limit(definition):
		var adjacent_ids := _hostile_adjacent_ids(state, monster.id)
		if not adjacent_ids.is_empty():
			if (active_turn.attack_index == 0 and not active_turn.physical_action_committed) or not adjacent_ids.has(active_turn.target_id):
				active_turn.target_id = _select_adjacent_monster_target(state, monster, rng)
				monster.target_id = active_turn.target_id
			while active_turn.attack_index < _monster_attack_limit(definition):
				var attack_result := _resolve_monster_attack_row(state, content, monster, definition, active_turn.attack_index, active_turn, rng, events)
				if attack_result != MONSTER_ATTACK_COMPLETED:
					return attack_result
			return MONSTER_ATTACK_COMPLETED
		if active_turn.movement_remaining <= 0:
			return MONSTER_ATTACK_COMPLETED
		if _monster_target_is_available(state, monster, active_turn.target_id) and not _rules.battlefield.has_line_of_sight(combat.battlefield, terrain_set, monster.id, active_turn.target_id):
			active_turn.target_id = _scan_visible_monster_target(state, monster, terrain_set)
			monster.target_id = active_turn.target_id
		elif not _monster_target_is_available(state, monster, active_turn.target_id):
			active_turn.target_id = _select_visible_monster_target(state, monster, terrain_set, rng)
			monster.target_id = active_turn.target_id
		if active_turn.target_id.is_empty():
			active_turn.movement_remaining = 0
			events.append(DomainEvent.new(&"combat_monster_action_unavailable", {"actorId": monster.id, "action": "advance", "reason": "no-visible-target"}))
			return MONSTER_ATTACK_COMPLETED
		var target_coordinate := combat.battlefield.actor_position(active_turn.target_id)
		var origin := combat.battlefield.actor_position(monster.id)
		var probe := _rules.battlefield.probe_monster_step_toward(combat.battlefield, terrain_set, monster.id, target_coordinate, active_turn.movement_remaining, rng)
		if not probe.allowed:
			active_turn.target_id = ""
			monster.target_id = ""
			active_turn.movement_remaining = 0
			events.append(DomainEvent.new(&"combat_monster_action_unavailable", {"actorId": monster.id, "action": "advance", "reason": String(probe.reason)}))
			return MONSTER_ATTACK_COMPLETED
		combat.pending_reaction = CombatReactionState.new(CombatReactionState.MONSTER_MOVE, monster.id, origin, probe.destination, probe.movement_cost)
		combat.pending_reaction.set_phase(CombatReactionState.WITHDRAWAL, [])
		var movement_result := _continue_pending_reaction(state, content, rng, events)
		if movement_result == REACTION_WAITING:
			return MONSTER_ATTACK_WAITING
		if movement_result == REACTION_DEATH_MACRO:
			return MONSTER_ATTACK_DEATH_MACRO
		if movement_result == REACTION_MOVER_DEFEATED:
			return MONSTER_ATTACK_COMPLETED
		operation_guard -= 1
	if operation_guard == 0:
		active_turn.movement_remaining = 0
		events.append(DomainEvent.new(&"combat_monster_action_unavailable", {"actorId": monster.id, "action": "advance", "reason": "monster-movement-budget-exhausted"}))
	return MONSTER_ATTACK_COMPLETED

func _process_monster_retreat(state: GameState, content: RealmzContent, monster: MonsterState, definition: MonsterDefinition, active_turn: CombatTurnState, rng: RealmzRng, events: Array[DomainEvent]) -> int:
	var combat := state.combat
	var terrain_set := _battle_terrain_set(content, combat.battlefield)
	if terrain_set == null:
		events.append(DomainEvent.new(&"combat_monster_action_unavailable", {"actorId": monster.id, "action": "retreat", "reason": "missing-battle-terrain"}))
		active_turn.movement_remaining = 0
		return MONSTER_ATTACK_COMPLETED
	if not _monster_target_is_available(state, monster, active_turn.target_id):
		# movemonster.c reads pos[-1] when a routed monster has no retained target.
		# Keep that unsafe source path explicit instead of inventing a threat target.
		active_turn.movement_remaining = 0
		events.append(DomainEvent.new(&"combat_monster_action_unavailable", {"actorId": monster.id, "action": "retreat", "reason": "retreat-target-unresolved"}))
		return MONSTER_ATTACK_COMPLETED
	var operation_guard := 512
	while operation_guard > 0 and active_turn.movement_remaining > 0 and monster.current_health > 0:
		var origin := combat.battlefield.actor_position(monster.id)
		var target_coordinate := combat.battlefield.actor_position(active_turn.target_id)
		var probe := _rules.battlefield.probe_monster_step_away(combat.battlefield, terrain_set, monster.id, target_coordinate, active_turn.movement_remaining, rng)
		if not probe.allowed:
			active_turn.movement_remaining = 0
			events.append(DomainEvent.new(&"combat_monster_action_unavailable", {"actorId": monster.id, "action": "retreat", "reason": String(probe.reason)}))
			return MONSTER_ATTACK_COMPLETED
		combat.pending_reaction = CombatReactionState.new(CombatReactionState.MONSTER_RETREAT, monster.id, origin, probe.destination, probe.movement_cost)
		combat.pending_reaction.set_origin_hostiles(_hostile_adjacent_ids(state, monster.id))
		combat.pending_reaction.set_phase(CombatReactionState.WITHDRAWAL, _withdrawal_hostiles(state, combat.pending_reaction))
		var reaction_result := _continue_pending_reaction(state, content, rng, events)
		if reaction_result == REACTION_WAITING:
			return MONSTER_ATTACK_WAITING
		if reaction_result == REACTION_DEATH_MACRO:
			return MONSTER_ATTACK_DEATH_MACRO
		if reaction_result == REACTION_MOVER_DEFEATED:
			return MONSTER_ATTACK_COMPLETED
		operation_guard -= 1
	if operation_guard == 0:
		active_turn.movement_remaining = 0
		events.append(DomainEvent.new(&"combat_monster_action_unavailable", {"actorId": monster.id, "action": "retreat", "reason": "monster-movement-budget-exhausted"}))
	return MONSTER_ATTACK_COMPLETED

func _resolve_monster_attack_row(state: GameState, content: RealmzContent, monster: MonsterState, definition: MonsterDefinition, attack_index: int, active_turn: CombatTurnState, rng: RealmzRng, events: Array[DomainEvent]) -> int:
	var combat := state.combat
	_prepare_monster_melee_weapon(monster, definition, content)
	if not _monster_target_is_available(state, monster, active_turn.target_id) or not _rules.battlefield.are_adjacent(combat.battlefield, monster.id, active_turn.target_id):
		active_turn.target_id = _select_adjacent_monster_target(state, monster, rng)
		monster.target_id = active_turn.target_id
	if active_turn.target_id.is_empty():
		active_turn.attack_index = _monster_attack_limit(definition)
		return MONSTER_ATTACK_COMPLETED
	active_turn.attack_index += 1
	active_turn.physical_action_committed = true
	combat.set_guarding(monster.id, false)
	var character_target := state.party.character_by_id(active_turn.target_id)
	if character_target != null:
		var race := content.race_by_id(character_target.race_id)
		var caste := content.caste_by_id(character_target.caste_id)
		var charm_bonus := 50 if state.party.conditions.is_active(ConditionRules.PARTY_CHARM_RESISTANCE) else 0
		var defender_equipment := _rules.inventory.combat_equipment(character_target, content.item_definitions())
		var defender_luck := defender_equipment.effective_luck if defender_equipment.valid else character_target.luck
		var attack_weapon := content.item_by_id(monster.weapon_id) if not monster.weapon_id.is_empty() else null
		var defender_armor := defender_equipment.effective_armor if defender_equipment.valid else character_target.armor
		var monster_attack_context := MonsterAttackContext.new(attack_weapon, state.clock.day(), false, defender_luck, state.party.conditions.is_active(ConditionRules.PARTY_DRAGON_HIDE), defender_armor)
		var monster_resolution := _rules.combat.resolve_monster_attack(monster, definition, attack_index, character_target, race, caste, rng, charm_bonus, monster_attack_context, true)
		if monster_resolution.total_damage() > 0:
			combat.mark_attacked(character_target.id)
		if monster_resolution.fumbled:
			_commit_monster_fumble(monster, events)
		var age_update_requested := false
		if monster_resolution.special_handled:
			_append_monster_special_events(events, monster.id, character_target.id, &"character", monster_resolution)
			if monster_resolution.aging != null and monster_resolution.aging.changed_group():
				events.append(DomainEvent.new(&"character_age_changed", monster_resolution.aging.event_payload(character_target, race)))
				age_update_requested = true
		if age_update_requested:
			combat.pending_monster_attack = PendingMonsterAttack.new(monster.id, character_target.id, active_turn.action, monster_resolution.damage, monster_resolution.chance, monster_resolution.roll, monster_resolution.weapon_condition_index, monster_resolution.weapon_condition_before, monster_resolution.weapon_condition_after, monster_resolution.physical_feedback_sound_id)
			return MONSTER_ATTACK_WAITING
		_append_monster_physical_feedback(events, monster_resolution.physical_feedback_sound_id)
		_append_monster_attack_audio(events, monster, definition, attack_index, attack_weapon, monster_resolution, rng)
		var character_attack_event := DomainEvent.new(&"combat_attack_resolved", {"actorId": monster.id, "targetId": character_target.id, "action": String(active_turn.action), "attackIndex": attack_index, "hit": monster_resolution.hit, "damage": monster_resolution.total_damage(), "defeated": monster_resolution.killed, "chance": monster_resolution.chance, "roll": monster_resolution.roll})
		_append_physical_result_effect(character_attack_event, monster_resolution.hit, attack_weapon != null)
		events.append(character_attack_event)
		_mark_character_bleeding(state, character_target, monster_resolution.killed)
		_remove_defeated_position(combat, character_target.id, monster_resolution.killed)
		if monster_resolution.killed:
			active_turn.target_id = ""
			monster.target_id = ""
		return MONSTER_ATTACK_COMPLETED
	var monster_target := combat.monster_by_id(active_turn.target_id)
	if monster_target == null:
		active_turn.target_id = ""
		return MONSTER_ATTACK_COMPLETED
	var target_definition := content.monster_by_id(monster_target.definition_id)
	var weapon := content.item_by_id(monster.weapon_id) if not monster.weapon_id.is_empty() else null
	var attack_context := MonsterAttackContext.new(weapon, state.clock.day())
	var resolution := _rules.combat.resolve_monster_attack_monster(monster, definition, attack_index, monster_target, target_definition, rng, attack_context, true)
	if resolution.total_damage() > 0:
		combat.mark_attacked(monster_target.id)
	if resolution.fumbled:
		_commit_monster_fumble(monster, events)
	if resolution.special_handled:
		_append_monster_special_events(events, monster.id, monster_target.id, &"monster", resolution)
	_append_monster_attack_audio(events, monster, definition, attack_index, weapon, resolution, rng)
	var monster_attack_event := DomainEvent.new(&"combat_attack_resolved", {"actorId": monster.id, "targetId": monster_target.id, "action": String(active_turn.action), "attackIndex": attack_index, "hit": resolution.hit, "damage": resolution.total_damage(), "defeated": resolution.killed, "chance": resolution.chance, "roll": resolution.roll})
	_append_physical_result_effect(monster_attack_event, resolution.hit, weapon != null)
	events.append(monster_attack_event)
	if resolution.killed:
		active_turn.target_id = ""
		monster.target_id = ""
		var death_macro_requested := _request_monster_death_macro(monster_target, target_definition, events)
		_remove_defeated_position(combat, monster_target.id, not death_macro_requested)
		if death_macro_requested:
			if active_turn.attack_index >= _monster_attack_limit(definition):
				_advance_turn(state, rng, events)
			return MONSTER_ATTACK_DEATH_MACRO
	return MONSTER_ATTACK_COMPLETED

func _select_adjacent_monster_target(state: GameState, monster: MonsterState, rng: RealmzRng) -> String:
	var target_ids: Array[String] = []
	var adjacent_ids := _rules.battlefield.adjacent_actor_ids(state.combat.battlefield, monster.id)
	for character: CharacterState in state.party.characters():
		if character.current_health > 0 and character.traitor != monster.traitor and adjacent_ids.has(character.id):
			target_ids.append(character.id)
	for candidate: MonsterState in state.combat.monsters():
		if candidate.id != monster.id and candidate.current_health > 0 and candidate.traitor != monster.traitor and adjacent_ids.has(candidate.id):
			target_ids.append(candidate.id)
	if target_ids.is_empty():
		return ""
	return target_ids[rng.draw_between(0, target_ids.size() - 1, &"combat.monster-target")]

func _process_monster_cast(state: GameState, content: RealmzContent, monster: MonsterState, definition: MonsterDefinition, active_turn: CombatTurnState, rng: RealmzRng, events: Array[DomainEvent]) -> int:
	active_turn.monster_cast_attempt_count += 1
	if state.monster_spellcasting_blocked or state.combat.was_attacked(monster.id) or definition.magic_attack_count <= 0:
		return MONSTER_ATTACK_FALLBACK
	for condition: int in [ConditionRules.STUPID, ConditionRules.CONFUSED, ConditionRules.SILENCED, ConditionRules.HELPLESS]:
		if monster.conditions.is_active(condition):
			return MONSTER_ATTACK_FALLBACK
	var did_cast := active_turn.spell_cast_count > 0
	while active_turn.spell_cast_count < definition.magic_attack_count:
		var spell: SpellDefinition = null
		var sampled_slot := -1
		var sampled_id := ""
		for draw_index: int in 30:
			sampled_slot = rng.draw_between(0, 9, StringName("monster.spell.slot.%d.%d" % [active_turn.spell_cast_count, draw_index]))
			sampled_id = definition.spell_id_at(sampled_slot)
			if not sampled_id.is_empty():
				spell = content.spell_by_id(sampled_id)
