func classic_spell_item_probe(character: CharacterState, instance: ItemInstance, item: ItemDefinition, spell: SpellDefinition, race: RaceDefinition, caste: CasteDefinition, in_combat: bool) -> InventoryActionProbe:
	if instance == null or item == null or instance.definition_id != item.id:
		return InventoryActionProbe.block("The carried item is unavailable.")
	var use_probe := classic_use_probe(character, item, race, caste)
	if not use_probe.allowed:
		return use_probe
	if item.special_2 <= 1100:
		return InventoryActionProbe.block("This item has no Classic spell effect.")
	if spell == null or spell.classic_id != item.special_2:
		return InventoryActionProbe.block("The item's Classic spell is unavailable.")
	if instance.charges == 0:
		return InventoryActionProbe.block("This item has no charges remaining.")
	if instance.charges < 0 and item.initial_charges >= 0:
		return InventoryActionProbe.block("The item's charge state does not match its immutable definition.")
	var power := absi(item.special_1)
	if power < 1 or power > 8:
		return InventoryActionProbe.block("The item's Classic spell power is invalid.")
	if in_combat and not spell.in_combat:
		return InventoryActionProbe.block("This item cannot be used in combat.")
	if not in_combat and not spell.in_camp:
		return InventoryActionProbe.block("This item cannot be used outside combat.")
	return InventoryActionProbe.permit()

func classic_equip_probe(character: CharacterState, instance: ItemInstance, item: ItemDefinition, race: RaceDefinition, caste: CasteDefinition, party: Array[CharacterState], definitions: Array[ItemDefinition]) -> InventoryActionProbe:
	if character == null or instance == null or item == null or instance.definition_id != item.id:
		return InventoryActionProbe.block("The carried item is unavailable.")
	if instance.equipped:
		return InventoryActionProbe.block("This item is already equipped.")
	var use_probe := classic_use_probe(character, item, race, caste)
	if not use_probe.allowed:
		return use_probe
	var item_type := absi(item.item_type)
	if item_type > 19:
		return InventoryActionProbe.block("Classic treats this as a usable item, not wearable equipment.")
	if item_type == 1:
		return InventoryActionProbe.block("Classic item type 1 slot behavior is still unresolved.")
	if not _passive_effects_supported(item):
		return InventoryActionProbe.block("This item's passive equipment effects are not implemented yet.")
	if item.cost < 0:
		for member: CharacterState in party:
			if member == character:
				continue
			for carried: ItemInstance in member.inventory():
				if carried.definition_id == item.id:
					return InventoryActionProbe.block("Only one party member may equip this unique item.")
	var definitions_by_id := _definitions_by_id(definitions)
	var occupied_types: Dictionary = {}
	var used_hands := 0
	var equipped_ring_ids: Array[int] = []
	var has_quiver := false
	for carried: ItemInstance in character.inventory():
		if not carried.equipped:
			continue
		var equipped: ItemDefinition = definitions_by_id.get(carried.definition_id)
		if equipped == null:
			return InventoryActionProbe.block("An equipped item has no immutable definition.")
		var equipped_type := absi(equipped.item_type)
		occupied_types[equipped_type] = true
		if equipped_type == 2:
			used_hands += maxi(0, equipped.hands)
		elif equipped_type == 3:
			used_hands += 1
		elif equipped_type == 0:
			equipped_ring_ids.append(equipped.classic_id)
		elif equipped_type == 10:
			has_quiver = true
	if item_type == 0:
		if equipped_ring_ids.size() >= 2:
			return InventoryActionProbe.block("Both Classic ring slots are occupied.")
		if equipped_ring_ids.has(item.classic_id):
			return InventoryActionProbe.block("Classic does not allow the same ring in both slots.")
		return InventoryActionProbe.permit()
	if item_type > 1 and occupied_types.has(item_type):
		return InventoryActionProbe.block("The Classic equipment slot for this item is occupied.")
	if item_type == 2 and used_hands + maxi(0, item.hands) > 2:
		return InventoryActionProbe.block("The character does not have enough free hands.")
	if item_type == 3 and used_hands + maxi(1, item.hands) > 2:
		return InventoryActionProbe.block("The character does not have enough free hands for this shield.")
	if item_type == 15 and _mask_has(item.item_category_mask_low, item.item_category_mask_high, 12) and not has_quiver:
		return InventoryActionProbe.block("This missile weapon requires an equipped quiver.")
	return InventoryActionProbe.permit()

func classic_unequip_probe(character: CharacterState, instance: ItemInstance, item: ItemDefinition, definitions: Array[ItemDefinition]) -> InventoryActionProbe:
	if character == null or instance == null or item == null or instance.definition_id != item.id:
		return InventoryActionProbe.block("The carried item is unavailable.")
	if not instance.equipped:
		return InventoryActionProbe.block("This item is not equipped.")
	if not item.cursed_item_id.is_empty():
		return InventoryActionProbe.block("This cursed item cannot be removed.")
	if absi(item.item_type) == 10:
		var by_id := _definitions_by_id(definitions)
		for carried: ItemInstance in character.inventory():
			var definition: ItemDefinition = by_id.get(carried.definition_id)
			if carried.equipped and definition != null and absi(definition.item_type) == 15:
				return InventoryActionProbe.block("Unequip the missile weapon before removing its quiver.")
	return InventoryActionProbe.permit()

func classic_drop_probe(character: CharacterState, instance: ItemInstance) -> InventoryActionProbe:
	if character == null or instance == null:
		return InventoryActionProbe.block("The carried item is unavailable.")
	if instance.equipped:
		return InventoryActionProbe.block("Unequip this item before dropping it.")
	return InventoryActionProbe.permit()

func classic_trade_probe(source: CharacterState, destination: CharacterState, instance: ItemInstance, item: ItemDefinition) -> InventoryActionProbe:
	if source == null or destination == null or source == destination or instance == null or item == null:
		return InventoryActionProbe.block("Choose another party member.")
	if instance.equipped and not item.cursed_item_id.is_empty():
		return InventoryActionProbe.block("This cursed equipped item cannot be traded away.")
	if destination.inventory().size() >= MAX_ITEMS:
		return InventoryActionProbe.block("%s already carries 30 items." % destination.name)
	if destination.carried_load + item.instance_weight(instance.charges) > destination.maximum_load:
		return InventoryActionProbe.block("%s cannot carry this item's weight." % destination.name)
	for carried: ItemInstance in destination.inventory():
		if carried.id == instance.id:
			return InventoryActionProbe.block("The destination already has this item instance.")
	return InventoryActionProbe.permit()

func equip_classic(character: CharacterState, instance: ItemInstance, item: ItemDefinition, race: RaceDefinition, caste: CasteDefinition, party: Array[CharacterState], definitions: Array[ItemDefinition]) -> InventoryActionProbe:
	var probe := classic_equip_probe(character, instance, item, race, caste, party, definitions)
	if not probe.allowed:
		return probe
	instance.equipped = true
	if not item.cursed_item_id.is_empty():
		instance.identified = true
	return probe

func unequip_classic(character: CharacterState, instance: ItemInstance, item: ItemDefinition, definitions: Array[ItemDefinition]) -> InventoryActionProbe:
	var probe := classic_unequip_probe(character, instance, item, definitions)
	if probe.allowed:
		instance.equipped = false
	return probe

func _resolve_character_spell_monster_target(caster_level: int, target: MonsterState, target_definition: MonsterDefinition, spell: SpellDefinition, power_level: int, cast_level: int, damage: int, duration: int, spell_cost: int, rng: RealmzRng) -> SpellResolution:
	var rolled_damage := damage
	var resisted := _monster_resists(caster_level, target, target_definition, spell, power_level, cast_level, rng)
	if resisted:
		return SpellResolution.new(true, true, false, spell_cost, 0, duration)
	if absi(spell.special) == 57:
		return _heal_monster(target, damage, duration, spell_cost)
	var saved := false
	var damage_type := absi(spell.damage_type)
	if damage_type > 0 and damage_type <= 6:
		var save_roll := rng.draw(100, &"magic.damage-save")
		# savevs consumes its roll first, then forces failure when cannot > 1.
		saved = spell.cannot <= 1 and save_roll <= (target.save_value(damage_type - 1) if target.has_runtime_saves() else target_definition.save_value(damage_type - 1))
		if saved:
			damage /= 2
		if damage > 0 and target.conditions.is_active(ConditionRules.FIRE_PROTECTION + damage_type - 1):
			damage /= 2
	var save_modifier := (target.save_value(damage_type - 1) if target.has_runtime_saves() else target_definition.save_value(damage_type - 1)) if damage_type > 0 and damage_type <= 6 else 0
	if save_modifier < 0:
		damage = int(float(damage) * (1.0 + float(absi(save_modifier)) / 100.0))
	if rolled_damage != 0 and damage == 0:
		damage = 1
	target.current_health -= damage
	return SpellResolution.new(true, false, saved, spell_cost, damage, duration, target.current_health <= 0)

func _resolve_character_spell_character_target(caster: CharacterState, target: CharacterState, spell: SpellDefinition, power_level: int, cast_level: int, damage: int, duration: int, rng: RealmzRng) -> SpellResolution:
	var rolled_damage := damage
	var resisted := character_resists(caster.level, target, spell, power_level, cast_level, rng)
	if resisted:
		return SpellResolution.new(true, true, false, 0, 0, duration)
	if absi(spell.special) == 57:
		return _heal_character(target, damage, duration, 0)
	var saved := false
	var damage_type := absi(spell.damage_type)
	if damage_type > 0 and damage_type <= 6:
		var save_roll := rng.draw(100, &"magic.damage-save")
		saved = spell.cannot <= 1 and save_roll <= target.save_value(damage_type - 1)
		if saved:
			damage /= 2
		if damage > 0 and target.conditions.is_active(ConditionRules.FIRE_PROTECTION + damage_type - 1):
			damage /= 2
	if rolled_damage != 0 and damage == 0:
		damage = 1
	target.current_health -= damage
	return SpellResolution.new(true, false, saved, 0, damage, duration, target.current_health <= 0)

func resolve_character_projectile(caster: CharacterState, caste: CasteDefinition, projectile_item: ItemDefinition, target: MonsterState, spell: SpellDefinition, power_level: int, rng: RealmzRng) -> ProjectileResolution:
	if caster == null or projectile_item == null or target == null or spell == null or rng == null or power_level < 0 or absi(spell.spell_class) != 9 or absi(spell.damage_type) != 9 or spell.special != 0:
		return null
	var duration := _scaled_roll(spell.duration_min, spell.duration_max, spell.power_duration_min, spell.power_duration_max, power_level, rng, &"combat.projectile.duration")
	var damage := _scaled_roll(spell.damage_min, spell.damage_max, spell.power_damage_min, spell.power_damage_max, power_level, rng, &"combat.projectile.damage")
	damage += projectile_item.damage_bonus
	var effective_to_hit := spell.to_hit_bonus + 5 * projectile_item.damage_bonus
	if caste != null and caste.gets_missile_bonus:
		damage += rng.draw_between(1, maxi(1, caster.level / 2), &"combat.projectile.caste-bonus")
	var hit_count := 0
	var miss_count := 0
	var total_damage := 0
	var maximum_hits := maxi(1, spell.fixed_target_count)
	for hit_index: int in maximum_hits:
		if target.conditions.is_active(ConditionRules.SHIELD_FROM_PROJECTILES):
			miss_count += 1
			break
		var miss_chance := 10 + 5 * target.agility - caster.missile - effective_to_hit
		if rng.draw(100, StringName("combat.projectile.miss.%d" % hit_index)) <= miss_chance:
			miss_count += 1
			break
		target.current_health -= damage
		hit_count += 1
		total_damage += damage
		if target.current_health <= 0:
			break
	return ProjectileResolution.new(true, hit_count, miss_count, total_damage, damage, duration, target.current_health <= 0)

func classic_use_probe(character: CharacterState, item: ItemDefinition, race: RaceDefinition, caste: CasteDefinition) -> InventoryActionProbe:
	if character == null or item == null or race == null or caste == null:
		return InventoryActionProbe.block("The character or immutable item definition is unavailable.")
	if not item.specific_race_id.is_empty() and item.specific_race_id != character.race_id:
		return InventoryActionProbe.block("This item requires %s." % item.specific_race_id.replace("_", " ").capitalize())
	if not item.specific_caste_id.is_empty() and item.specific_caste_id != character.caste_id:
		return InventoryActionProbe.block("This item requires %s." % item.specific_caste_id.replace("_", " ").capitalize())
	var category := _first_category(item.item_category_mask_low, item.item_category_mask_high)
	if category < 0:
		return InventoryActionProbe.block("This item has no Classic usability category.")
	if not _mask_has(race.item_category_mask_low, race.item_category_mask_high, category):
		return InventoryActionProbe.block("This race cannot use this item category.")
	if not _mask_has(caste.item_category_mask_low, caste.item_category_mask_high, category):
		return InventoryActionProbe.block("This class cannot use this item category.")
	if (item.race_restrictions & race.descriptor_flags) != 0:
		return InventoryActionProbe.block("This item's race restrictions exclude the character.")
	if item.race_class_only != 0 and (item.race_class_only & race.descriptor_flags) != item.race_class_only:
		return InventoryActionProbe.block("This item requires race traits the character does not have.")
	var caste_class_index := caste.caste_class - 1
	if caste_class_index < 0 or caste_class_index > 15:
		return InventoryActionProbe.block("The character's Classic class group is invalid.")
	if (item.caste_restrictions & (1 << caste_class_index)) != 0:
		return InventoryActionProbe.block("This item's class restrictions exclude the character.")
	if item.caste_class_only != 0 and (item.caste_class_only & (1 << caste_class_index)) == 0:
		return InventoryActionProbe.block("This item requires another Classic class group.")
	return InventoryActionProbe.permit()

func character_resists(caster_level: int, target: CharacterState, spell: SpellDefinition, power_level: int, cast_level: int, rng: RealmzRng) -> bool:
	if spell.spell_class == 0:
		if rng.draw(100, &"magic.charm-save") <= target.save_value(0) + power_level * spell.save_adjust:
			return true
	if spell.damage_type < 0 and absi(spell.damage_type) != 9:
		var direct_chance := 35 + 5 * target.level - 5 * caster_level + power_level * spell.save_adjust
		if rng.draw(100, &"magic.direct-resist") <= direct_chance:
			return true
	if (spell.cannot == 1 or spell.cannot > 2) and absi(spell.spell_class) != 9:
		return false
	for level: int in range(cast_level, 5):
		if target.conditions.is_active(16 + level):
			return true
	if (spell.spell_class == 0 or spell.spell_class == 5) and target.conditions.is_active(ConditionRules.ANIMATED):
		return true
	if absi(spell.spell_class) == 9:
		if target.conditions.is_active(ConditionRules.SHIELD_FROM_PROJECTILES):
			return true
		return rng.draw(100, &"magic.missile-dodge") <= target.dodge - spell.to_hit_bonus
	return rng.draw(100, &"magic.resistance") <= target.magic_resistance + power_level * spell.resistance_adjust

func resolve_monster_targeted_spell(caster: MonsterState, caster_definition: MonsterDefinition, selection: SpellTargetSelection, spell: SpellDefinition, power_level: int, cast_level: int, rng: RealmzRng) -> GroupSpellResolution:
	if caster == null or caster_definition == null or not _selection_is_valid(selection) or spell == null or rng == null or power_level < 1:
		return null
	var spell_cost := spell.cost * power_level
	if spell_cost <= 0 or caster.spell_points < spell_cost:
		return GroupSpellResolution.new(false, maxi(0, spell_cost), 0, 0)
	caster.spell_points -= spell_cost
	var effective := _reflect_to_monster_caster(caster, caster_definition, selection, rng, &"magic.monster-spell.reflect")
	var duration := _scaled_roll(spell.duration_min, spell.duration_max, spell.power_duration_min, spell.power_duration_max, power_level, rng, &"magic.monster-spell.duration")
	var damage := _scaled_roll(spell.damage_min, spell.damage_max, spell.power_damage_min, spell.power_damage_max, power_level, rng, &"magic.monster-spell.damage")
	var result := GroupSpellResolution.new(true, spell_cost, duration, damage)
	if not effective.reflected and effective.kind == &"monster" and effective.monster.magic_resistance > 100:
		return result
	var resolution := _resolve_monster_selection(caster, effective, spell, power_level, cast_level, damage, duration, spell_cost, rng, &"magic.monster-spell.damage-save")
	result.append_target(effective.id, effective.kind, resolution, effective.original_target_id, effective.reflected)
	return result

func resolve_monster_repeated_spell(caster: MonsterState, caster_definition: MonsterDefinition, selections: Array[SpellTargetSelection], spell: SpellDefinition, power_level: int, cast_level: int, rng: RealmzRng) -> RepeatedSpellResolution:
	if caster == null or caster_definition == null or spell == null or rng == null or power_level < 1 or selections.is_empty() or selections.size() > power_level:
		return null
	for selection: SpellTargetSelection in selections:
		if not _selection_is_valid(selection):
			return null
	var spell_cost := spell.cost * power_level
	if spell_cost <= 0 or caster.spell_points < spell_cost:
		return RepeatedSpellResolution.new(false, maxi(0, spell_cost), selections.size())
	caster.spell_points -= spell_cost
	var result := RepeatedSpellResolution.new(true, spell_cost, selections.size())
	for index: int in selections.size():
		var selection := _reflect_to_monster_caster(caster, caster_definition, selections[index], rng, StringName("magic.monster-repeated.reflect.%d" % index))
		var duration := _scaled_roll(spell.duration_min, spell.duration_max, spell.power_duration_min, spell.power_duration_max, power_level, rng, StringName("magic.monster-repeated.duration.%d" % index))
		var damage := _scaled_roll(spell.damage_min, spell.damage_max, spell.power_damage_min, spell.power_damage_max, power_level, rng, StringName("magic.monster-repeated.damage.%d" % index))
		if not selection.reflected and selection.kind == &"monster" and selection.monster.magic_resistance > 100:
			result.exclude_target(selection.original_target_id)
			continue
		var save_tag := StringName("magic.monster-repeated.damage-save.%d" % index)
		var resolution := _resolve_monster_selection(caster, selection, spell, power_level, cast_level, damage, duration, 0, rng, save_tag)
		result.append_target(selection.id, selection.kind, resolution, selection.original_target_id, selection.reflected)
	return result

func consume_random_door(index: int) -> void:
	if index >= 0 and index < _random_door_percents.size() and _random_door_percents[index] > 0:
		_random_door_percents[index] = 0

static func from_data(data: Variant) -> RandomRegionState:
	if not data is Dictionary:
		return null
	for field: String in ["id", "chanceTenThousand", "battleMinimum", "battleMaximum", "randomDoorPercent"]:
		if not data.has(field):
			return null
	if not data["id"] is String or data["id"].is_empty():
		return null
	var chance := _signed_integer(data["chanceTenThousand"])
	var battle_min := _signed_integer(data["battleMinimum"])
	var battle_max := _signed_integer(data["battleMaximum"])
	if chance == -100_000 or battle_min == -100_000 or battle_max == -100_000 or not data["randomDoorPercent"] is Array or data["randomDoorPercent"].size() != 3:
		return null
	var door_percents: Array[int] = []
	for value: Variant in data["randomDoorPercent"]:
		var percent := _signed_integer(value)
		if percent == -100_000:
			return null
		door_percents.append(percent)
	return RandomRegionState.new(data["id"], chance, battle_min, battle_max, door_percents)

static func _signed_integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -100_000

func _init(scroll_spell_id: String = "", power_level: int = 0) -> void:
	spell_id = scroll_spell_id
	power = power_level

static func from_data(data: Variant) -> SpellScrollState:
	if not data is Dictionary or data.size() != 2 or not data.get("spellId") is String:
		return null
	var parsed_power := _integer(data.get("power"))
	var parsed_spell_id: String = data["spellId"]
	if parsed_power < 0 or parsed_power > 7:
		return null
	if parsed_power == 0 and not parsed_spell_id.is_empty() or parsed_power > 0 and parsed_spell_id.is_empty():
		return null
	return SpellScrollState.new(parsed_spell_id, parsed_power)

static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

static func _integer(value: Variant) -> int:
	if value is int:
