		return selection
	return SpellTargetSelection.for_monster(caster, caster_definition, selection.original_target_id, true)

func resolve_field_spell(caster: CharacterState, targets: Array[CharacterState], spell: SpellDefinition, power_level: int, rng: RealmzRng, castes: Array[CasteDefinition] = [], races: Array[RaceDefinition] = [], spend_spell_points: bool = true, allow_empty: bool = false) -> GroupSpellResolution:
	if caster == null or spell == null or rng == null or power_level < 1 or not allow_empty and targets.is_empty():
		return null
	if not castes.is_empty() and castes.size() != targets.size() or not races.is_empty() and races.size() != targets.size():
		return null
	for target: CharacterState in targets:
		if target == null:
			return null
	var spell_cost := absi(spell.cost * power_level)
	if spend_spell_points and caster.spell_points < spell_cost:
		return GroupSpellResolution.new(false, spell_cost, 0, 0)
	if spend_spell_points:
		caster.spell_points -= spell_cost
	else:
		spell_cost = 0
	var tag_prefix := "field-spell.%d" % spell.classic_id
	var duration := _scaled_roll(spell.duration_min, spell.duration_max, spell.power_duration_min, spell.power_duration_max, power_level, rng, StringName("%s.duration" % tag_prefix))
	var damage := _scaled_roll(spell.damage_min, spell.damage_max, spell.power_damage_min, spell.power_damage_max, power_level, rng, StringName("%s.damage" % tag_prefix))
	var result := GroupSpellResolution.new(true, spell_cost, duration, damage)
	for index: int in targets.size():
		var target := targets[index]
		var caste: CasteDefinition = null if castes.is_empty() else castes[index]
		var race: RaceDefinition = null if races.is_empty() else races[index]
		var resolution := _resolve_noncombat_character_effect(target, spell, power_level, 0, false, rng, caste, race, duration, damage, "%s.%s" % [tag_prefix, target.id])
		result.append_target(target.id, &"character", resolution)
	return result

func _resolve_noncombat_character_effect(target: CharacterState, spell: SpellDefinition, power_level: int, extra_save_adjust: int, force_affect: bool, rng: RealmzRng, caste: CasteDefinition, race: RaceDefinition, duration: int, damage: int, tag_prefix: String) -> SpellResolution:
	var special := absi(spell.special)
	var damage_type := absi(spell.damage_type)
	var saved := false
	if damage_type > 0 and damage_type < 8 and not force_affect and spell.cannot < 2:
		var save_target := target.save_value(damage_type) + power_level * (spell.save_adjust + extra_save_adjust) + spell.save_bonus
		saved = rng.draw(100, StringName("%s.save" % tag_prefix)) <= save_target
		if saved:
			if damage == 0:
				return SpellResolution.new(true, false, true, 0, 0, duration)
			damage /= 2
	if damage != 0 and damage_type > 0 and damage_type <= 6 and target.conditions.is_active(ConditionRules.FIRE_PROTECTION + damage_type - 1):
		damage /= 2
	if special > 0 and special < 41:
		if special == 28:
			damage = duration
		var condition_index := special - 1
		var current_condition := target.conditions.value(condition_index)
		if current_condition > -1 and current_condition + duration < 100:
			target.conditions.add(condition_index, duration)
	elif special > 99:
		target.conditions.set_value(special - 101, 0)
	match special:
		2:
			target.movement = 0
		3, 7:
			target.movement /= 2
		10:
			if target.conditions.value(ConditionRules.ANIMATED) < 0:
				target.conditions.set_value(ConditionRules.POISONED, 0)
		26:
			if target.current_health < -9:
				target.conditions.set_value(ConditionRules.ANIMATED, -1)
			target.current_health = int(float(target.maximum_health) / 4.0)
		27, 49:
			damage = 10 + target.current_health
			if special == 27:
				target.conditions.set_value(ConditionRules.TURNED_TO_STONE, -1)
		48:
			for item: ItemInstance in target.inventory():
				item.identified = true
		57:
			damage = -damage
		59:
			target.spell_points = mini(target.maximum_spell_points, target.spell_points + damage)
			damage = 0
		60:
			target.spell_points = maxi(0, target.spell_points - damage)
			damage = 0
		61:
			for index: int in target.conditions.size():
				if target.conditions.value(index) > 0:
					target.conditions.set_value(index, 0)
		62:
			target.conditions.set_value(ConditionRules.CURSED, 0)
		64:
			if not target.conditions.is_active(ConditionRules.TURNED_TO_STONE) and (target.current_health < -9 or target.conditions.is_active(ConditionRules.ANIMATED)):
				target.conditions.set_value(ConditionRules.ANIMATED, 0)
				target.current_health = -9
		66:
			_apply_attribute_increase(target, spell.size, caste, rng, tag_prefix)
	var aging: CharacterAgingResult = null
	if race != null and caste != null and special in [24, 91]:
		var age_percent_months := power_level * 30 if special == 24 else duration * 30
		var added_days := int(float(race.max_age) * 0.01 * float(age_percent_months))
		aging = _characters.advance_age_days(target, race, caste, added_days)
	elif race != null and caste != null and special == 92:
		var youth_months := duration * 30
		var removed_days := int(float(race.max_age) * 0.01 * float(youth_months))
		var next_age := maxi(3_650, target.age_days - removed_days)
		var stamina_loss := rng.draw(3, StringName("%s.youth-stamina" % tag_prefix))
		target.maximum_health = maxi(1, target.maximum_health - stamina_loss)
		target.current_health = maxi(1, target.current_health - stamina_loss)
		aging = _characters.advance_age_days(target, race, caste, next_age - target.age_days)
	if damage < 0:
		target.current_health = mini(target.maximum_health, target.current_health - damage)
	elif damage > 0 and target.current_health >= 0 and target.current_health > -10:
		target.current_health -= damage
	var result := SpellResolution.new(true, false, saved, 0, damage, duration, target.current_health <= -10)
	result.aging = aging
	return result

func _monster_resists(caster_level: int, target: MonsterState, definition: MonsterDefinition, spell: SpellDefinition, power_level: int, cast_level: int, rng: RealmzRng) -> bool:
	if spell.spell_class == 0:
		var charm_chance := 35 + 4 * target.hit_dice
		charm_chance += 5 if definition.type_flag(0) else 0
		charm_chance += 5 if definition.type_flag(5) else 0
		if rng.draw(100, &"magic.monster-charm") <= charm_chance + power_level * spell.save_adjust:
			return true
	if spell.damage_type < 0 and absi(spell.damage_type) != 9:
		var direct_chance := 35 + 5 * target.hit_dice - 5 * caster_level + power_level * spell.save_adjust
		if rng.draw(100, &"magic.monster-direct-resist") <= direct_chance:
			return true
	if spell.spell_class >= 0 and spell.spell_class < 6 and (definition.spell_immune(spell.spell_class) or target.magic_resistance > 100):
		return true
	if (spell.cannot == 1 or spell.cannot > 2) and absi(spell.spell_class) != 9:
		return false
	for level: int in range(cast_level, 5):
		if target.conditions.is_active(16 + level):
			return true
	if (spell.spell_class == 0 or spell.spell_class == 5) and target.conditions.is_active(ConditionRules.ANIMATED):
		return true
	return rng.draw(100, &"magic.monster-resistance") <= target.magic_resistance + power_level * spell.resistance_adjust

func _scaled_roll(base_min: int, base_max: int, power_min: int, power_max: int, power_level: int, rng: RealmzRng, tag: StringName) -> int:
	var total := rng.draw_between(base_min, base_max, tag) if base_max >= base_min else 0
	if power_min != 0:
		for index: int in power_level:
			if power_max >= power_min:
				total += rng.draw_between(power_min, power_max, StringName("%s.power.%d" % [tag, index]))
	return total

func _apply_attribute_increase(character: CharacterState, requested_attribute: int, caste: CasteDefinition, rng: RealmzRng, tag_prefix: String) -> void:
	var attribute := requested_attribute if requested_attribute != 0 else rng.draw(5, StringName("%s.attribute" % tag_prefix))
	match attribute:
		1:
			if character.brawn >= 25:
				return
			var maximum_bonus := caste.maximum_damage_bonus() if caste != null else 32_767
			var rules := CharacterRules.new()
			var before := rules.strength_bonuses(character.brawn, maximum_bonus)
			character.brawn += 1
			var after := rules.strength_bonuses(character.brawn, maximum_bonus)
			character.damage_bonus += after.damage_bonus - before.damage_bonus
			character.to_hit += after.to_hit_bonus - before.to_hit_bonus
			character.maximum_load = maxi(500, character.brawn * character.brawn * 20)
		2:
			if character.knowledge < 25:
				character.knowledge += 1
				if character.knowledge > 15 and caste != null:
					character.magic_resistance += caste.magic_resistance_multiplier
		3:
			if character.judgment < 25:
				character.judgment += 1
				if character.judgment > 15 and caste != null:
					character.magic_resistance += caste.magic_resistance_multiplier
		4:
			if character.agility < 25:
				character.agility += 1
				if character.agility > 14:
					character.armor += 2
		5:
			if character.vitality < 25:
				character.vitality += 1
				if character.vitality > 18:
					for index: int in 8:
						character.set_save_value(index, character.save_value(index) + 5)
		10:
			character.maximum_health += rng.draw(8, StringName("%s.stamina" % tag_prefix))
		11:
			if character.maximum_spell_points > 0:
				character.maximum_spell_points += rng.draw(20, StringName("%s.spell-points" % tag_prefix))

func resolve_scenario_spell(target: CharacterState, spell: SpellDefinition, power_level: int, extra_save_adjust: int, force_affect: bool, rng: RealmzRng, caste: CasteDefinition = null, race: RaceDefinition = null) -> SpellResolution:
	if target == null or spell == null or rng == null or power_level < 0:
		return null
	var tag_prefix := "scenario-spell.%d.%s" % [spell.classic_id, target.id]
	var duration := _scaled_roll(spell.duration_min, spell.duration_max, spell.power_duration_min, spell.power_duration_max, power_level, rng, StringName("%s.duration" % tag_prefix))
	var damage := _scaled_roll(spell.damage_min, spell.damage_max, spell.power_damage_min, spell.power_damage_max, power_level, rng, StringName("%s.damage" % tag_prefix))
	return _resolve_noncombat_character_effect(target, spell, power_level, extra_save_adjust, force_affect, rng, caste, race, duration, damage, tag_prefix)

func _prepare_monster_melee_weapon(monster: MonsterState, definition: MonsterDefinition, content: RealmzContent) -> void:
	if monster == null or definition == null or content == null or monster.weapon_id.is_empty():
		return
	var active_item := content.item_by_id(monster.weapon_id)
	var active_spell := content.spell_by_classic_id(absi(active_item.special_2)) if active_item != null and active_item.special_2 != 0 else null
	if active_spell == null or active_spell.damage_type != 9:
		return
	# attack2 writes this replacement through Castle's global monsterup instead
	# of its mon argument. Apply the intended slot-0 replacement to the actual
	# attacker so reactions cannot mutate an unrelated monster.
	monster.weapon_id = definition.item_id_at(0)

func _select_visible_monster_target(state: GameState, monster: MonsterState, terrain_set: BattleTerrainSetDefinition, rng: RealmzRng) -> String:
	var slot_count := 10 + state.combat.monsters().size()
	if not _has_available_monster_target(state, monster):
		return ""
	for _attempt: int in 4096:
		var slot := rng.draw_between(0, slot_count - 1, &"combat.monster-target-slot")
		var candidate_id := _monster_target_id_for_slot(state, monster, slot)
		if candidate_id.is_empty():
			continue
		if _rules.battlefield.has_line_of_sight(state.combat.battlefield, terrain_set, monster.id, candidate_id):
			return candidate_id
		break
	# Castle switches from random selection to ascending combat slots after its
	# first unseen valid target. Bound the scan to real typed slots instead of
	# reading uninitialized native monster entries through its 110 sentinel.
	return _scan_visible_monster_target(state, monster, terrain_set)

func _scan_visible_monster_target(state: GameState, monster: MonsterState, terrain_set: BattleTerrainSetDefinition) -> String:
	var slot_count := 10 + state.combat.monsters().size()
	for slot: int in slot_count:
		var candidate_id := _monster_target_id_for_slot(state, monster, slot)
		if not candidate_id.is_empty() and _rules.battlefield.has_line_of_sight(state.combat.battlefield, terrain_set, monster.id, candidate_id):
			return candidate_id
	return ""

func availability(action_id: StringName) -> ActionAvailabilityView:
	var value: Variant = action_availability.get(action_id)
	if value is ActionAvailabilityView:
		return value
	return ActionAvailabilityView.new(action_id, false, "This action is unavailable in the current gameplay slice.")

static func generate_character_draft(spec: CharacterCreationSpec) -> PlayerIntent:
	var intent := PlayerIntent.new(Kind.GENERATE_CHARACTER_DRAFT)
	if spec != null:
		intent.party_members = [spec]
	return intent

func _blocked_land_attempt_cost(movement: WorldMovementResult) -> int:
	if movement == null or movement.source_map == null or movement.source_map.level_type != &"land" or _state.party_in_boat:
		return 0
	if movement.reason not in [&"terrain_blocked", &"secret_hidden"] or movement.topology_result == null or movement.topology_result.target_cell == null:
		return 0
	return maxi(0, movement.topology_result.target_cell.movement_cost)

func _respond_session_interaction(response: InteractionResponse) -> SessionStep:
	if _session_continuation.get("kind") == "pooled-wealth-departure":
		return _respond_pooled_wealth_departure(response)
	if _session_continuation.get("kind") == "service-interaction":
		return _respond_runtime_service(response)
	if _session_continuation.get("kind") == "drop-item-confirmation":
		return _respond_drop_item(response)
	if _session_continuation.get("kind") == "item-use-target-selection":
		return _respond_item_use_target(response)
	if _session_continuation.get("kind") == "field-spell-target-selection":
		return _respond_field_spell_target(response)
	if _session_continuation.get("kind") == "scroll-target-selection":
		return _respond_scroll_target(response)
	if _session_continuation.get("kind") == "character-spell-confirmation":
		return _respond_character_spell_confirmation(response)
	if _session_continuation.get("kind") == "character-vault-publication":
		return _respond_character_vault_publication(response)
	if _session_continuation.get("kind") == "age-updates":
		return _respond_session_age_update(response)
	if _session_continuation.get("kind") == "combat-ally-selection":
		return _respond_session_ally_selection(response)
	if _session_continuation.get("kind") == "combat-fumble-recovery":
		return _respond_session_fumble_recovery(response)
	if _session_continuation.get("kind") == "combat-reward":
		return _respond_session_battle_reward(response)
	if _session_continuation.get("kind") == "combat-retreat-confirmation":
		return _respond_session_retreat(response)
	if response.kind != &"yes_no" or not response.payload.has("accepted") or not response.payload["accepted"] is bool:
		return SessionStep.failed(_view_revision, &"invalid_interaction_response", "The random encounter response must be a yes/no choice.")
	if _session_continuation.get("randomBattleStage", "") != "surprise-choice":
		return SessionStep.failed(_view_revision, &"invalid_session_continuation", "The random encounter choice has no matching continuation.")
	var map := _content.world.map_by_id(String(_session_continuation.get("mapId", "")))
	var region_id := String(_session_continuation.get("activeRandomRegionId", ""))
	var region: RandomEncounterRegion = null if map == null else map.random_region_by_id(region_id)
	if region == null:
		return SessionStep.failed(_view_revision, &"invalid_session_continuation", "The random encounter choice references unavailable content.")
	_session_interaction = null
	_session_continuation["activeRandomRegionId"] = ""
	_session_continuation["randomBattleStage"] = ""
	var events: Array[DomainEvent] = [DomainEvent.new(&"random_surprise_chosen", {"regionId": region.id, "accepted": response.payload["accepted"]})]
	if response.payload["accepted"]:
		return _start_random_battle(region, 1, events)
	_session_continuation["randomRegionIndex"] = int(_session_continuation["randomRegionIndex"]) - 1
	if region.only:
		if _session_continuation.get("kind") == "post-clock":
			return _complete_post_time(events)
		_session_continuation.clear()
		return _finish_completed(events)
	var next_step := _continue_random_regions(map, events)
	if next_step != null:
		return next_step
	if _session_continuation.get("kind") == "post-clock":
		return _complete_post_time(events)
	_session_continuation.clear()
	return _finish_completed(events)

func _finish_direct_battle_recovery(events: Array[DomainEvent]) -> SessionStep:
	var payload := _rules.combat_flow.fumble_recovery_payload(_state, _content)
	if not payload.is_empty():
		var request_id := "session.fumble-recovery.%d" % (_view_revision + 1)
		_session_continuation = {"kind": "combat-fumble-recovery", "battleId": _state.combat.battle_id}
		_session_interaction = InteractionRequest.new(request_id, InteractionRequest.TREASURE_DISTRIBUTION, payload)
		return _finish_waiting(_session_interaction, events)
	return _begin_direct_battle_reward(events)

func _finish_direct_battle_without_rewards(events: Array[DomainEvent]) -> SessionStep:
	if _state.combat == null or not _state.combat.completed:
		return _finish_failed(&"invalid_battle_continuation", "Suppressed battle rewards require a completed battle.", events)
	var battle_id := _state.combat.battle_id
	var return_continuation: Dictionary = _state.combat.return_continuation.duplicate(true)
	var battle_outcome := _state.combat.outcome
	events.append(DomainEvent.new(&"battle_returned", {"battleId": battle_id, "outcome": String(battle_outcome)}))
	_state.combat = null
	return _finish_after_direct_battle(events, return_continuation, battle_outcome)

func _begin_direct_battle_reward(events: Array[DomainEvent]) -> SessionStep:
	var return_continuation: Dictionary = _state.combat.return_continuation.duplicate(true)
	var battle_outcome := _state.combat.outcome
	var request_id := "session.battle-reward.%d" % (_view_revision + 1)
	var operation := _runtime_api.begin_completed_battle_reward(request_id)
	events.append_array(operation.events)
	if operation.state == ScenarioRuntimeOperationResult.State.FAILED:
		return _finish_failed(operation.error_code, operation.error_message, events)
	if operation.state == ScenarioRuntimeOperationResult.State.WAITING:
		_session_continuation = {"kind": "combat-reward", "battleId": _state.combat.battle_id, "runtimeContinuation": operation.continuation.duplicate(true)}
		_session_interaction = operation.interaction
		return _finish_waiting(_session_interaction, events)
	_session_interaction = null
	_session_continuation.clear()
	return _finish_after_direct_battle(events, return_continuation, battle_outcome)

func _finish_after_direct_battle(events: Array[DomainEvent], return_continuation: Dictionary, battle_outcome: StringName) -> SessionStep:
	if return_continuation.is_empty() or battle_outcome == &"defeat" or not _events_have(events, &"battle_returned"):
		return _finish_completed(events)
	_session_continuation = return_continuation.duplicate(true)
	return _continue_post_time(events)

func _continue_random_regions(map: MapDefinition, events: Array[DomainEvent]) -> SessionStep:
	if not _state.random_encounters_enabled:
		return null
	var region_ids: Array = _session_continuation["randomRegionIds"]
	while int(_session_continuation["randomRegionIndex"]) >= 0:
		var region_index: int = int(_session_continuation["randomRegionIndex"])
		var region_id: String = String(region_ids[region_index])
		var region := map.random_region_by_id(region_id)
		if region == null:
			_session_continuation.clear()
			return _finish_failed(&"invalid_session_continuation", "Random-region continuation references unavailable content.", events)
		var effective := _state.world.random_region(region)
		var roll := _rng.draw(10_000, StringName("random-region.%s" % region.id))
		var triggered := roll <= effective.chance_ten_thousand
		events.append(DomainEvent.new("random_encounter_checked", {"regionId": region.id, "roll": roll, "chanceTenThousand": effective.chance_ten_thousand, "triggered": triggered}))
		if triggered:
			events.append(DomainEvent.new(&"random_region_triggered", {"regionId": region.id}))
			var door_ids := region.random_doors()
			var door_percents := effective.random_door_percents()
			for door_index: int in door_ids.size():
				var door_roll := _rng.draw(100, StringName("random-region.%s.door.%d" % [region.id, door_index]))
				var door_fired := door_roll <= absi(door_percents[door_index])
				events.append(DomainEvent.new(&"random_door_checked", {"regionId": region.id, "doorIndex": door_index, "programId": "xap:%d" % door_ids[door_index], "roll": door_roll, "chancePercent": door_percents[door_index], "triggered": door_fired}))
				if not door_fired:
					continue
				effective.consume_random_door(door_index)
				_state.world.set_random_region(effective)
				var program_id := "xap:%d" % door_ids[door_index]
				_session_continuation["activeRandomProgramId"] = program_id
				events.append(DomainEvent.new(&"random_door_triggered", {"regionId": region.id, "programId": program_id, "oneShot": door_percents[door_index] > 0}))
				var started := _scenario_vm.start_program(program_id, {"callingContext": "action", "mapId": map.id, "x": _state.party.coordinate.x, "y": _state.party.coordinate.y, "randomRegionId": region.id})
				if started.state == ScenarioVmResult.State.FAILED:
					_session_continuation.clear()
					return _finish_failed(started.error_code, started.error_message, events)
				var result := _scenario_vm.run(_runtime_api)
				events.append_array(result.events)
				if result.state == ScenarioVmResult.State.SUSPENDED:
					return _begin_scenario_handoff(result, events)
				if result.state == ScenarioVmResult.State.WAITING:
					return _finish_waiting(result.interaction, events)
				if result.state == ScenarioVmResult.State.FAILED:
					_session_continuation.clear()
					return _finish_failed(result.error_code, result.error_message, events)
				if _events_have(result.events, &"destination_trigger_recheck_requested"):
					var requested_map := _content.world.map_by_id(_state.party.map_id)
					if requested_map == null:
						_session_continuation.clear()
						return _finish_failed(&"invalid_teleport", "Destination trigger recheck references an unavailable map.", events)
					_set_post_move_continuation(requested_map, _state.party.coordinate, 1)
					return _continue_post_move(events)
				return _complete_random_program(events)
			if effective.battle_minimum != 0 and not _state.party.conditions.is_active(7):
				var good_surprise_roll := _rng.draw(100, StringName("random-region.%s.good-surprise" % region.id))
				if good_surprise_roll < region.option:
					var message := _content.message_by_id(absi(region.text_id))
					var prompt := message.text if message != null else "Take the advantage and enter battle?"
					_session_continuation["activeRandomRegionId"] = region.id
					_session_continuation["randomBattleStage"] = "surprise-choice"
					var request_id := "random-surprise:%s:%d" % [region.id, _rng.snapshot().draw_count]
					_session_interaction = InteractionRequest.new(request_id, &"yes_no", {"prompt": prompt, "yesLabel": "Enter battle", "noLabel": "Avoid battle", "regionId": region.id})
					if region.sound_id > 0:
						events.append(DomainEvent.new(&"audio_requested", {"soundId": region.sound_id}))
					return _finish_waiting(_session_interaction, events)
				var bad_surprise_roll := _rng.draw(100, StringName("random-region.%s.bad-surprise" % region.id))
				var surprise := -1 if bad_surprise_roll < 10 else 0
				return _start_random_battle(region, surprise, events)
		_session_continuation["randomRegionIndex"] = region_index - 1
		if region.only:
			break
	return null

