static func from_data(data: Variant) -> ClassicRewardState:
	if not data is Dictionary:
		return null
	var required: Array[String] = ["origin", "sourceId", "experiencePool", "experienceShare", "initialWealth", "magicDetected", "identified", "completionPending", "phase", "items", "experienceAwards", "levelCharacterIds", "levelIndex", "spellCharacterIds", "spellIndex", "pendingLevelResult"]
	if data.size() != required.size():
		return null
	for field: String in required:
		if not data.has(field):
			return null
	if not data["origin"] is String or data["origin"].is_empty() or not data["sourceId"] is String or not data["magicDetected"] is bool or not data["identified"] is bool or not data["completionPending"] is bool or not data["phase"] is String or StringName(data["phase"]) not in [ITEM_PHASE, LEVEL_PHASE, SPELL_PHASE] or not data["items"] is Array or not data["experienceAwards"] is Dictionary or not data["levelCharacterIds"] is Array or not data["spellCharacterIds"] is Array or not data["pendingLevelResult"] is Dictionary:
		return null
	var loaded_experience_pool := _integer(data["experiencePool"])
	var loaded_experience_share := _integer(data["experienceShare"])
	var loaded_level_index := _integer(data["levelIndex"])
	var loaded_spell_index := _integer(data["spellIndex"])
	if loaded_experience_pool < 0 or loaded_experience_share < 0 or loaded_level_index < 0 or loaded_spell_index < 0:
		return null
	var wealth := WealthState.from_data(data["initialWealth"])
	if wealth == null:
		return null
	var result := ClassicRewardState.new(StringName(data["origin"]), data["sourceId"], loaded_experience_pool, wealth)
	result.experience_share = loaded_experience_share
	result.magic_detected = data["magicDetected"]
	result.identified = data["identified"]
	result.completion_pending = data["completionPending"]
	result.phase = StringName(data["phase"])
	var loaded_items: Array[ItemInstance] = []
	for entry: Variant in data["items"]:
		var item := ItemInstance.from_data(entry)
		if item == null:
			return null
		loaded_items.append(item)
	var awards: Dictionary = {}
	for character_id: Variant in data["experienceAwards"]:
		if not character_id is String or character_id.is_empty():
			return null
		var amount := _integer(data["experienceAwards"][character_id])
		if amount < 0:
			return null
		awards[character_id] = amount
	if not result.set_items(loaded_items) or not result.set_experience_awards(awards):
		return null
	var level_ids: Array[String] = []
	for value: Variant in data["levelCharacterIds"]:
		if not value is String:
			return null
		level_ids.append(value)
	var spell_ids: Array[String] = []
	for value: Variant in data["spellCharacterIds"]:
		if not value is String:
			return null
		spell_ids.append(value)
	result.level_index = loaded_level_index
	result.spell_index = loaded_spell_index
	if not result.set_level_character_ids(level_ids) or not result.set_spell_character_ids(spell_ids) or result.level_index < 0 or result.level_index > level_ids.size() or result.spell_index < 0 or result.spell_index > spell_ids.size():
		return null
	var level_result: Variant = _normalized_level_result(data["pendingLevelResult"])
	if level_result == null:
		return null
	result.pending_level_result = level_result
	return result

static func _valid_unique_ids(values: Array[String]) -> bool:
	var seen: Dictionary = {}
	for value: String in values:
		if value.is_empty() or seen.has(value):
			return false
		seen[value] = true
	return true

static func _normalized_level_result(data: Dictionary) -> Variant:
	if data.is_empty():
		return {}
	var fields: Array[String] = ["characterId", "characterName", "level", "stamina", "spellPoints", "toHit", "magicResistance"]
	if data.size() != fields.size():
		return null
	for field: String in fields:
		if not data.has(field):
			return null
	if not data["characterId"] is String or data["characterId"].is_empty() or not data["characterName"] is String:
		return null
	var result: Dictionary = {"characterId": data["characterId"], "characterName": data["characterName"]}
	for field: String in ["level", "stamina", "spellPoints", "toHit", "magicResistance"]:
		var value := _integer(data[field])
		if value == INVALID_INTEGER or field == "level" and value < 1:
			return null
		result[field] = value
	return result

static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return INVALID_INTEGER

func advance_classic_field_time(state: GameState, content: RealmzContent, timeclicks: int, minutes_per_timeclick: int, defer_midnight_recovery: bool = false) -> Array[DomainEvent]:
	var clicks := maxi(0, timeclicks)
	var scale := clampi(minutes_per_timeclick, 1, 5)
	var previous_minutes := state.clock.total_minutes()
	var events := advance_minutes(state, content, clicks * scale)
	var current_minutes := state.clock.total_minutes()
	var first_hour_boundary := floori(float(previous_minutes) / 60.0) + 1
	var last_hour_boundary := floori(float(current_minutes) / 60.0)
	for hour_boundary: int in range(first_hour_boundary, last_hour_boundary + 1):
		events.append_array(_conditions.tick_party(state.party))
		var previous_fatigue := state.party.fatigue
		change_fatigue(state.party, 1)
		events.append(DomainEvent.new(&"fatigue_changed", {"previous": previous_fatigue, "current": state.party.fatigue, "reason": "hour-boundary", "source": "classic"}))
		events.append_array(_restore_spell_points(state.party))
		if hour_boundary % 12 == 0 and not (defer_midnight_recovery and hour_boundary % 24 == 0):
			events.append_array(_restore_half_day_health(state.party, content))
	return events

func advance_minutes(state: GameState, content: RealmzContent, minutes: int, condition_ticks: int = 0) -> Array[DomainEvent]:
	var elapsed := maxi(0, minutes)
	var previous_day := state.clock.day()
	state.clock.advance_minutes(elapsed)
	var events: Array[DomainEvent] = [DomainEvent.new(&"time_advanced", {"minutes": elapsed, "day": state.clock.day(), "hour": state.clock.hour()})]
	for day_index: int in state.clock.day() - previous_day:
		for character: CharacterState in state.party.characters():
			var race := content.race_by_id(character.race_id) if content != null else null
			var caste := content.caste_by_id(character.caste_id) if content != null else null
			if race == null or caste == null:
				continue
			var aging := _characters.advance_age_days(character, race, caste, 1)
			if aging != null and aging.changed_group():
				events.append(DomainEvent.new(&"character_age_changed", aging.event_payload(character, race)))
	for tick: int in condition_ticks:
		events.append_array(_conditions.tick_party(state.party))
	return events

func change_fatigue(party: PartyState, amount: int) -> int:
	party.fatigue = clampi(party.fatigue + amount, 4, 135)
	return party.fatigue

func _consume_iron_ration(party: PartyState, content: RealmzContent) -> Dictionary:
	var definition := content.item_by_classic_id(877)
	if definition == null:
		return {}
	for character: CharacterState in party.characters():
		for instance: ItemInstance in character.inventory():
			if instance.definition_id != definition.id or instance.charges <= 0:
				continue
			var instance_id := instance.id
			if not _inventory.use_charge(character, instance_id, definition):
				return {}
			return {"characterId": character.id, "instanceId": instance_id, "itemId": definition.id, "chargesRemaining": maxi(0, instance.charges), "source": "classic-half-day"}
	return {}

func _restore_half_day_health(party: PartyState, content: RealmzContent) -> Array[DomainEvent]:
	var events: Array[DomainEvent] = []
	for character: CharacterState in party.characters():
		if character.current_health >= character.maximum_health or character.current_health <= -10:
			continue
		var ration := _consume_iron_ration(party, content)
		var amount := floori(float(character.level) / 3.0)
		if ration.is_empty():
			amount = floori(float(amount) / 2.0)
		amount = maxi(1, amount)
		amount += character.conditions.value(ConditionRules.POISONED)
		if not ration.is_empty():
			events.append(DomainEvent.new(&"rest_ration_consumed", ration))
		if character.conditions.is_active(ConditionRules.TURNED_TO_STONE):
			continue
		var previous_health := character.current_health
		character.current_health = clampi(character.current_health + amount, -10, character.maximum_health)
		var restored := character.current_health - previous_health
		if restored != 0:
			events.append(DomainEvent.new(&"health_recovered", {"characterId": character.id, "amount": restored, "source": "classic-half-day"}))
	for ally: MonsterState in party.allies():
		if ally.current_health >= ally.maximum_health:
			continue
		var previous_health := ally.current_health
		ally.current_health = mini(ally.maximum_health, ally.current_health + floori(float(ally.hit_dice) / 4.0) + 1)
		var restored := ally.current_health - previous_health
		if restored != 0:
			events.append(DomainEvent.new(&"ally_health_recovered", {"allyId": ally.id, "amount": restored, "source": "classic-half-day"}))
	return events

func _restore_spell_points(party: PartyState) -> Array[DomainEvent]:
	var events: Array[DomainEvent] = []
	for character: CharacterState in party.characters():
		if character.current_health <= 0 or character.conditions.is_active(ConditionRules.ANIMATED) or character.spell_points >= character.maximum_spell_points:
			continue
		var amount := mini(maxi(1, floori(float(character.level) / 2.0)), character.maximum_spell_points - character.spell_points)
		character.spell_points += amount
		events.append(DomainEvent.new(&"spell_points_recovered", {"characterId": character.id, "amount": amount, "source": "classic-hour"}))
	for ally: MonsterState in party.allies():
		if ally.spell_points >= ally.maximum_spell_points:
			continue
		var amount := mini(maxi(1, floori(float(ally.hit_dice) / 2.0)), ally.maximum_spell_points - ally.spell_points)
		ally.spell_points += amount
		events.append(DomainEvent.new(&"ally_spell_points_recovered", {"allyId": ally.id, "amount": amount, "source": "classic-hour"}))
	return events

func _init(event_kind: StringName, event_payload: Dictionary = {}) -> void:
	kind = event_kind
	payload = event_payload.duplicate(true)

func _depart_camp_and_move(direction: Vector2i, preceding_events: Array[DomainEvent] = []) -> SessionStep:
	var movement := _content.world.probe_movement(_state.party.map_id, _state.party.coordinate, direction, _state.world)
	if not movement.allowed and movement.reason == &"invalid_direction":
		return SessionStep.failed(_view_revision, &"invalid_direction", "Movement requires a cardinal direction, or a diagonal direction on a land map.")
	var map := _content.world.map_by_id(_state.party.map_id)
	if map == null:
		return SessionStep.failed(_view_revision, &"unknown_map", "The current map is unavailable for camp departure.")
	_state.party_camping = false
	var events: Array[DomainEvent] = []
	events.assign(preceding_events)
	events.append(DomainEvent.new(&"camp_mode_changed", {"camping": false, "source": "classic-movement"}))
	events.append(DomainEvent.new(&"camp_departed_for_movement", {"mapId": map.id, "x": _state.party.coordinate.x, "y": _state.party.coordinate.y, "direction": [direction.x, direction.y], "source": "classic"}))
	var timeclicks := 2 if map.level_type == &"dungeon" else 15
	var previous_day := _state.clock.day()
	events.append_array(_rules.clock.advance_classic_field_time(_state, _content, timeclicks, _classic_time_scale(map), true))
	_set_post_time_continuation(map, "move", direction, true, _state.clock.day() if _state.clock.day() != previous_day else 0, _state.party.coordinate + direction)
	return _finish_with_age_updates(events, "post-clock", _session_continuation)

func character_spell_unavailable_reason(state: GameState, content: RealmzContent, caster_id: String) -> String:
	if state == null or state.combat == null:
		return ""
	var caster := state.party.character_by_id(caster_id)
	if caster == null or caster.maximum_spell_attacks <= 0 or caster.known_spells().is_empty():
		return ""
	if not character_spell_options(state, content, caster_id).is_empty():
		return ""
	var spells := caster.known_spells()
	var first_spell := content.spell_by_id(spells[0])
	var targets := _character_actor_spell_candidates(state, content, caster, first_spell, 1) if first_spell != null else []
	if targets.is_empty():
		return "No live combatant is available for this spell."
	var probe := probe_character_spell_cast(state, content, caster_id, targets[0].id, spells[0], 1)
	return probe.reason_text

static func from_data(data: Variant) -> InteractionRequest:
	if not data is Dictionary:
		return null
	for field: String in ["request_id", "kind", "payload"]:
		if not data.has(field):
			return null
	if not data["request_id"] is String or data["request_id"].is_empty() or not data["kind"] is String or data["kind"].is_empty() or not data["payload"] is Dictionary:
		return null
	var request_kind := StringName(data["kind"])
	if not InteractionRequest.kind_is_supported(request_kind):
		return null
	return InteractionRequest.new(data["request_id"], request_kind, data["payload"])

static func from_data(value: Variant) -> CharacterDraft:
	if not value is Dictionary:
		return null
	for field: String in ["name", "gender", "raceId", "casteId", "portraitId", "combatIconId", "finalized"]:
		if not value.has(field):
			return null
	if not value["name"] is String or not value["raceId"] is String or not value["casteId"] is String or not value["portraitId"] is String or not value["combatIconId"] is String or not value["finalized"] is bool:
		return null
	if not value["gender"] is int or int(value["gender"]) not in [1, 2]:
		return null
	var result := CharacterDraft.new()
	result.name = value["name"]
	result.gender = value["gender"]
	var starting_level_value: Variant = value.get("startingLevel", 1)
	if not starting_level_value is int:
		return null
	result.starting_level = starting_level_value
	if not CharacterRules.STARTING_LEVELS.has(result.starting_level):
		return null
	result.race_id = value["raceId"]
	result.caste_id = value["casteId"]
	result.portrait_id = value["portraitId"]
	result.combat_icon_id = value["combatIconId"]
	result.finalized = value["finalized"]
	if value.has("generatedCharacter") and value["generatedCharacter"] != null:
		result.generated_character = CharacterState.from_data(value["generatedCharacter"])
		if result.generated_character == null:
			return null
	return result

func _service_action(intent: PlayerIntent) -> SessionStep:
	if intent.action != &"enter":
		return SessionStep.failed(_view_revision, &"unknown_service_action", "Only entering an available service is implemented through this intent.")
	if intent.target_id == "realmz.service.temple":
		if not _state.temple_available:
			return SessionStep.failed(_view_revision, &"service_unavailable", "The selected temple is not available at this location.")
		return _start_application_hook(ScenarioApplicationHooks.TEMPLE, "service", intent.target_id, [])
	elif intent.target_id == "realmz.service.bank":
		return _open_contextual_service(intent.target_id, [])
	elif intent.target_id == _state.active_shop_id:
		if intent.target_id.is_empty() or _content.shop_by_id(intent.target_id) == null:
			return SessionStep.failed(_view_revision, &"service_unavailable", "The selected shop is not available at this location.")
		return _start_application_hook(ScenarioApplicationHooks.SHOP, "service", intent.target_id, [])
	else:
		return SessionStep.failed(_view_revision, &"service_unavailable", "The selected service is not available at this location.")

func _open_contextual_service(service_id: String, preceding_events: Array[DomainEvent]) -> SessionStep:
	var request_id := "service:%s:%d" % [service_id, _view_revision]
	var operation: ScenarioRuntimeOperationResult
	if service_id == "realmz.service.temple":
		operation = _runtime_api.request_available_temple(request_id)
	elif service_id == "realmz.service.bank":
		operation = _runtime_api.request_available_bank(request_id)
	elif service_id == _state.active_shop_id:
		operation = _runtime_api.request_available_shop(request_id)
	else:
		return _finish_failed(&"service_unavailable", "The selected service is not available at this location.", preceding_events)
	operation.events = preceding_events + operation.events
	return _begin_runtime_service(service_id, operation)

func _finish_direct_battle(events: Array[DomainEvent]) -> SessionStep:
	if _state.combat == null or not _state.combat.completed:
		return _finish_failed(&"invalid_battle_continuation", "Post-battle completion requires a completed battle.", events)
	if _state.combat.outcome == &"defeat":
		return _start_application_hook(ScenarioApplicationHooks.PARTY_DEATH, "party-defeat", "", events)
	var payload := _rules.combat_flow.ally_selection_payload(_state, _content)
	if not payload.is_empty():
		var request_id := "session.ally-selection.%d" % (_view_revision + 1)
		_session_continuation = {"kind": "combat-ally-selection", "battleId": _state.combat.battle_id}
		_session_interaction = InteractionRequest.new(request_id, &"ally_selection", payload)
		return _finish_waiting(_session_interaction, events)
	return _finish_direct_battle_recovery(events)

func pool_probe(party: PartyState) -> EconomyActionProbe:
	if party == null:
		return EconomyActionProbe.new(false, "No party is available.")
	for character: CharacterState in party.characters():
		if character.money.gold > 0 or character.money.gems > 0 or character.money.jewelry > 0:
			return EconomyActionProbe.new(true)
	return EconomyActionProbe.new(false, "No adventurer carries wealth to pool.")

func take_from_pool_and_character(party: PartyState, character: CharacterState, amount: int, kind: WealthState.Kind) -> bool:
	if party == null or character == null:
		return false
	if amount < 0:
		party.pooled_wealth.add(kind, -amount)
		return true
	if amount > party.pooled_wealth.amount(kind) + character.money.amount(kind):
		return false
	var from_pool := mini(amount, party.pooled_wealth.amount(kind))
	party.pooled_wealth.add(kind, -from_pool)
	var from_character := amount - from_pool
	character.money.add(kind, -from_character)
	character.carried_load = maxi(0, character.carried_load - from_character * wealth_weight(kind))
	return true

func share_pooled_wealth(party: PartyState) -> bool:
	if not share_probe(party).allowed:
		return false
	var changed := false
	for kind: WealthState.Kind in [WealthState.Kind.JEWELRY, WealthState.Kind.GEMS, WealthState.Kind.GOLD]:
		var assigned := true
		while party.pooled_wealth.amount(kind) > 0 and assigned:
			assigned = false
			for character: CharacterState in party.characters():
				if party.pooled_wealth.amount(kind) < 1:
					break
				# FD-ECONOMY-003: Castle checks only current load here, so
				# jewelry can overload a recipient even though Swap rejects it.
				if character.carried_load + wealth_weight(kind) <= character.maximum_load:
					assigned = true
					changed = true
					character.money.add(kind, 1)
					character.carried_load += wealth_weight(kind)
					party.pooled_wealth.add(kind, -1)
	return changed

func share_probe(party: PartyState) -> EconomyActionProbe:
	if party == null:
		return EconomyActionProbe.new(false, "No party is available.")
	if party.pooled_wealth.gold < 1 and party.pooled_wealth.gems < 1 and party.pooled_wealth.jewelry < 1:
		return EconomyActionProbe.new(false, "The party wealth pool is empty.")
	for kind: WealthState.Kind in [WealthState.Kind.JEWELRY, WealthState.Kind.GEMS, WealthState.Kind.GOLD]:
		if party.pooled_wealth.amount(kind) < 1:
			continue
		for character: CharacterState in party.characters():
			if character.carried_load + wealth_weight(kind) <= character.maximum_load:
				return EconomyActionProbe.new(true)
	return EconomyActionProbe.new(false, "No adventurer can carry another pooled denomination.")

func transfer_probe(party: PartyState, character: CharacterState, kind: WealthState.Kind, amount: int, to_character: bool) -> EconomyActionProbe:
	if party == null or character == null:
		return EconomyActionProbe.new(false, "The selected adventurer is unavailable.")
	if amount != classic_transfer_increment(kind):
		return EconomyActionProbe.new(false, "The transfer does not use the Classic denomination increment.")
	if to_character:
		if party.pooled_wealth.amount(kind) < amount:
			return EconomyActionProbe.new(false, "The party pool does not contain that amount.")
		if character.carried_load + wealth_weight(kind) * amount > character.maximum_load:
			return EconomyActionProbe.new(false, "%s cannot carry that denomination." % character.name)
		return EconomyActionProbe.new(true)
	if character.money.amount(kind) < amount:
		return EconomyActionProbe.new(false, "%s does not carry that amount." % character.name)
	return EconomyActionProbe.new(true)

func bank_to_pool(party: PartyState) -> void:
	if party == null:
		return
	for kind: WealthState.Kind in [WealthState.Kind.GOLD, WealthState.Kind.GEMS, WealthState.Kind.JEWELRY]:
		party.pooled_wealth.add(kind, party.banked_wealth.amount(kind))
		party.banked_wealth.set_amount(kind, 0)

func pool_to_bank(party: PartyState) -> void:
	if party == null:
		return
	for kind: WealthState.Kind in [WealthState.Kind.GOLD, WealthState.Kind.GEMS, WealthState.Kind.JEWELRY]:
		party.banked_wealth.add(kind, party.pooled_wealth.amount(kind))
		party.pooled_wealth.set_amount(kind, 0)

func take(party: PartyState, amount: int, kind: WealthState.Kind) -> bool:
	if amount < 0:
		return false
	var total_available := party.pooled_wealth.amount(kind)
	for character: CharacterState in party.characters():
		total_available += character.money.amount(kind)
	if amount > total_available:
		return false
	var from_pool := mini(amount, party.pooled_wealth.amount(kind))
	party.pooled_wealth.add(kind, -from_pool)
	var remaining := amount - from_pool
	var characters := party.characters()
	var index := 0
	while remaining > 0:
		var character := characters[index]
		if character.money.amount(kind) > 0:
			character.money.add(kind, -1)
			character.carried_load = maxi(0, character.carried_load - (15 if kind == WealthState.Kind.JEWELRY else 1))
			remaining -= 1
		index = (index + 1) % characters.size()
	return true

func available(party: PartyState, kind: WealthState.Kind) -> int:
	if party == null:
		return 0
	var result := party.pooled_wealth.amount(kind)
	for character: CharacterState in party.characters():
		result += character.money.amount(kind)
	return result

func item_price(item: ItemDefinition, shop: ShopDefinition, selling: bool = false) -> int:
	if item == null or shop == null:
		return 0
	return shop_sell_price(item, null, shop.inflation_percent) if selling else shop_buy_price(item, shop.inflation_percent)

func shop_buy_price(item: ItemDefinition, inflation_percent: int) -> int:
	if item == null:
		return 0
	return mini(32_000, int(float(absi(item.cost) * maxi(0, inflation_percent)) / 100.0))

func shop_sell_price(item: ItemDefinition, instance: ItemInstance, inflation_percent: int) -> int:
	if item == null:
		return 0
	var current_charges := item.initial_charges if instance == null else instance.charges
	var condition := 1.0
	if item.initial_charges > 0:
		condition = float(current_charges) / float(item.initial_charges)
	# Castle divides current charges by authored charges. A literal 0/0 reaches
	# nonportable float-to-short conversion; uncharged items retain full condition.
	var half_cost := absi(item.cost) / 2
	var conditioned_cost := absi(int(float(half_cost) * condition))
	var price := mini(32_000, int(float(conditioned_cost * mini(maxi(0, inflation_percent), 100)) / 100.0))
	if instance != null and not instance.identified:
		price /= 50
	return maxi(0, price)

static func _monster_save_chance(monster: MonsterState, definition: MonsterDefinition, save_index: int) -> int:
	if save_index == 7:
		var total := 0
		for index: int in 6:
			total += monster.save_value(index) if monster.has_runtime_saves() else definition.save_value(index)
		return int(float(total) / 6.0)
	return (monster.save_value(save_index - 1) if monster.has_runtime_saves() else definition.save_value(save_index - 1)) if save_index > 0 else 0

static func _monster_saved(_monster: MonsterState, definition: MonsterDefinition, save_index: int, roll: int, chance: int) -> bool:
	if save_index < 6 and definition.spell_immune(save_index):
		return true
	if save_index > 0 and roll <= chance:
		return true
	return definition.type_flag(1) and save_index in [0, 4, 5]

func initiative_order(characters: Array[CharacterState], monsters: Array[MonsterState], surprise: int, rng: RealmzRng) -> Array[String]:
	var order: Array[String] = []
	for character: CharacterState in characters:
		if character.current_health > 0:
			order.append(character.id)
	for monster: MonsterState in monsters:
		if monster.current_health > 0:
			order.append(monster.id)
	if surprise > 0:
		return _party_first(order, characters)
	if surprise < 0:
		return _monsters_first(order, monsters)
	for index: int in range(order.size() - 1, 0, -1):
		var swap_index := rng.draw_between(0, index, &"combat.initiative.slot")
		var held := order[index]
		order[index] = order[swap_index]
		order[swap_index] = held
	for left: int in order.size():
		for right: int in range(left, order.size() - 1):
			if _agility(order[right + 1], characters, monsters) > _agility(order[right], characters, monsters):
				var held := order[right]
				order[right] = order[right + 1]
				order[right + 1] = held
	return order

func _agility(id: String, characters: Array[CharacterState], monsters: Array[MonsterState]) -> int:
	for character: CharacterState in characters:
		if character.id == id:
			return character.agility
	for monster: MonsterState in monsters:
		if monster.id == id:
			return monster.agility
	return 0

func _party_first(order: Array[String], characters: Array[CharacterState]) -> Array[String]:
	var party_ids: Dictionary = {}
	for character: CharacterState in characters:
		party_ids[character.id] = true
	var first: Array[String] = []
	var last: Array[String] = []
	for id: String in order:
		if party_ids.has(id):
			first.append(id)
		else:
			last.append(id)
	first.append_array(last)
	return first

func _monsters_first(order: Array[String], monsters: Array[MonsterState]) -> Array[String]:
	var monster_ids: Dictionary = {}
	for monster: MonsterState in monsters:
		monster_ids[monster.id] = true
	var first: Array[String] = []
	var last: Array[String] = []
	for id: String in order:
		if monster_ids.has(id):
			first.append(id)
		else:
			last.append(id)
	first.append_array(last)
	return first

func pool_party_wealth(party: PartyState) -> bool:
	if not pool_probe(party).allowed:
		return false
	for character: CharacterState in party.characters():
		party.pooled_wealth.gold += character.money.gold
		party.pooled_wealth.gems += character.money.gems
		party.pooled_wealth.jewelry += character.money.jewelry
		character.carried_load = maxi(0, character.carried_load - character.money.gold - character.money.gems - character.money.jewelry * 15)
		character.money = WealthState.new()
	return true

func _init(is_allowed: bool, unavailable_reason: String = "") -> void:
	allowed = is_allowed
	reason = "" if is_allowed else unavailable_reason

func _monster_target_id_for_slot(state: GameState, monster: MonsterState, slot: int) -> String:
	if slot >= 0 and slot < 9:
		var characters := state.party.characters()
		if slot >= characters.size():
			return ""
		var character: CharacterState = characters[slot]
		return character.id if _monster_target_is_available(state, monster, character.id) else ""
	if slot < 10:
		return ""
	var monsters := state.combat.monsters()
	var monster_index := slot - 10
	if monster_index < 0 or monster_index >= monsters.size():
		return ""
	var candidate: MonsterState = monsters[monster_index]
	return candidate.id if _monster_target_is_available(state, monster, candidate.id) else ""

func _has_available_monster_target(state: GameState, monster: MonsterState) -> bool:
	for character: CharacterState in state.party.characters():
		if _monster_target_is_available(state, monster, character.id):
			return true
	for candidate: MonsterState in state.combat.monsters():
		if _monster_target_is_available(state, monster, candidate.id):
			return true
	return false

func _monster_target_is_available(state: GameState, monster: MonsterState, target_id: String) -> bool:
	if target_id.is_empty():
		return false
	var character := state.party.character_by_id(target_id)
	if character != null:
		return character.current_health > 0 and character.traitor != monster.traitor and state.combat.battlefield.has_actor(character.id)
	var candidate := state.combat.monster_by_id(target_id)
	return candidate != null and candidate.id != monster.id and candidate.current_health > 0 and candidate.traitor != monster.traitor and state.combat.battlefield.has_actor(candidate.id)

static func _monster_movement_allowance(monster: MonsterState, definition: MonsterDefinition) -> int:
	var movement := definition.movement_max
	var tangled := monster.conditions.value(ConditionRules.TANGLED)
	if tangled > 0:
		movement -= tangled
	if monster.conditions.is_active(ConditionRules.SLOW):
		movement = int(float(movement) / 2.0)
	if monster.conditions.is_active(ConditionRules.SPEEDY):
		movement *= 2
	return maxi(0, movement)

func _process_charmed_character_turn(state: GameState, content: RealmzContent, actor: CharacterState, rng: RealmzRng, events: Array[DomainEvent]) -> bool:
	var adjacent_ids := _rules.battlefield.adjacent_actor_ids(state.combat.battlefield, actor.id)
	var character_targets: Array[CharacterState] = []
	for candidate: CharacterState in state.party.characters():
		if candidate.id != actor.id and candidate.current_health > 0 and candidate.traitor != actor.traitor and adjacent_ids.has(candidate.id):
			character_targets.append(candidate)
	var monster_targets: Array[MonsterState] = []
	for candidate: MonsterState in state.combat.monsters():
		if candidate.current_health > 0 and candidate.traitor != actor.traitor and adjacent_ids.has(candidate.id):
			monster_targets.append(candidate)
	var target_count := character_targets.size() + monster_targets.size()
	if target_count == 0:
		events.append(DomainEvent.new(&"combat_monster_action_unavailable", {"actorId": actor.id, "action": "advance", "reason": "tactical-movement-not-implemented"}))
		return false
	var target_index := rng.draw_between(0, target_count - 1, &"combat.charmed-target")
	var equipment := _rules.inventory.combat_equipment(actor, content.item_definitions())
	if not equipment.valid:
		events.append(DomainEvent.new(&"combat_attack_blocked", {"actorId": actor.id, "reason": String(equipment.error_code), "message": equipment.error_message}))
		return false
	var active_turn := state.combat.begin_active_turn()
	if active_turn == null:
		return false
	if target_index < character_targets.size():
		var character_target := character_targets[target_index]
		var target_equipment := _rules.inventory.combat_equipment(character_target, content.item_definitions())
		if not target_equipment.valid:
			events.append(DomainEvent.new(&"combat_attack_blocked", {"actorId": actor.id, "targetId": character_target.id, "reason": String(target_equipment.error_code), "message": target_equipment.error_message}))
			return false
		active_turn.physical_action_committed = true
		var character_resolution := _rules.combat.resolve_character_attack_character(actor, equipment, character_target, target_equipment, rng, false, true, state.combat.can_queue_fumbled_item())
		if character_resolution.total_damage() > 0:
			state.combat.mark_attacked(character_target.id)
		if character_resolution.fumbled and not _commit_character_fumble(state, actor, equipment, events):
			events.append(DomainEvent.new(&"combat_fumble_failed", {"actorId": actor.id, "reason": "invalid-fumble-state"}))
			return false
		var character_event := _character_attack_event(actor.id, character_target.id, &"character", character_resolution, equipment.melee_weapon != null)
		_append_character_attack_audio(events, actor, equipment, character_resolution, &"character")
		character_event.payload["automatic"] = true
		events.append(character_event)
		_mark_character_bleeding(state, character_target, character_resolution.killed)
		_remove_defeated_position(state.combat, character_target.id, character_resolution.killed)
		return false
	var monster_target := monster_targets[target_index - character_targets.size()]
	var target_definition := content.monster_by_id(monster_target.definition_id)
	active_turn.physical_action_committed = true
	var resolution := _rules.combat.resolve_character_attack(actor, equipment, monster_target, target_definition, rng, state.clock.day(), false, true, state.combat.can_queue_fumbled_item())
	if resolution.total_damage() > 0:
		state.combat.mark_attacked(monster_target.id)
	if resolution.fumbled and not _commit_character_fumble(state, actor, equipment, events):
		events.append(DomainEvent.new(&"combat_fumble_failed", {"actorId": actor.id, "reason": "invalid-fumble-state"}))
		return false
	var event := _character_attack_event(actor.id, monster_target.id, &"monster", resolution, equipment.melee_weapon != null)
	_append_character_attack_audio(events, actor, equipment, resolution, &"monster")
	event.payload["automatic"] = true
	events.append(event)
	var death_macro_requested := resolution.killed and _request_monster_death_macro(monster_target, target_definition, events)
	_remove_defeated_position(state.combat, monster_target.id, resolution.killed and not death_macro_requested)
	return death_macro_requested

func _hostile_adjacent_ids(state: GameState, actor_id: String, anchor_override: Vector2i = Vector2i(-1, -1)) -> Array[String]:
	var result: Array[String] = []
	if state == null or state.combat == null or state.combat.battlefield == null:
		return result
	var actor_traitor := false
	var character := state.party.character_by_id(actor_id)
	if character != null:
		actor_traitor = character.traitor
	else:
		var monster := state.combat.monster_by_id(actor_id)
		if monster == null:
			return result
		actor_traitor = monster.traitor
	var adjacent_ids := _rules.battlefield.adjacent_actor_ids(state.combat.battlefield, actor_id, anchor_override)
	# Castle scans numeric combat slots: party members first, then monsters in
	# authored runtime order. Stable IDs must not accidentally redefine reactions.
	for candidate_character: CharacterState in state.party.characters():
		if adjacent_ids.has(candidate_character.id) and candidate_character.current_health > 0 and candidate_character.traitor != actor_traitor:
			result.append(candidate_character.id)
	for candidate_monster: MonsterState in state.combat.monsters():
		if adjacent_ids.has(candidate_monster.id) and candidate_monster.current_health > 0 and candidate_monster.traitor != actor_traitor:
			result.append(candidate_monster.id)
	return result

func _hostile_contact_target_id(state: GameState, actor_id: String, destination_or_target: Variant) -> String:
	if state == null or state.combat == null or state.combat.battlefield == null:
		return ""
	var candidate_id := ""
	if destination_or_target is String:
		candidate_id = destination_or_target
	elif destination_or_target is Vector2i:
		candidate_id = state.combat.battlefield.actor_at(destination_or_target, actor_id)
	if candidate_id.is_empty():
		return ""
	var actor := state.party.character_by_id(actor_id)
	if actor == null or actor.current_health <= 0:
		return ""
	var monster := state.combat.monster_by_id(candidate_id)
	if monster != null:
		return candidate_id if monster.current_health > 0 and monster.traitor != actor.traitor else ""
	var character := state.party.character_by_id(candidate_id)
	return candidate_id if character != null and character.current_health > 0 and character.traitor != actor.traitor else ""

static func _remove_defeated_position(combat: CombatState, actor_id: String, defeated: bool) -> void:
	if not defeated or combat == null or combat.battlefield == null:
		return
	if combat.monster_by_id(actor_id) != null:
		combat.battlefield.remove_monster(actor_id)
	else:
		combat.battlefield.remove_character(actor_id)

static func _remove_all_defeated_positions(state: GameState) -> void:
	if state == null or state.combat == null or state.combat.battlefield == null:
		return
	for monster: MonsterState in state.combat.monsters():
		_remove_defeated_position(state.combat, monster.id, monster.current_health <= 0)
	for character: CharacterState in state.party.characters():
		_remove_defeated_position(state.combat, character.id, character.current_health <= 0)

static func _battle_terrain_set(content: RealmzContent, battlefield: BattlefieldState) -> BattleTerrainSetDefinition:
	var map := content.world.map_by_id(battlefield.map_id)
	return null if map == null else content.world.battle_terrain_set_by_id(map.battle_terrain_set_id)

func _commit_character_fumble(state: GameState, character: CharacterState, equipment: CharacterCombatEquipment, events: Array[DomainEvent]) -> bool:
	if state.combat == null or equipment == null or equipment.melee_weapon == null or equipment.melee_weapon_instance_id.is_empty() or not state.combat.can_queue_fumbled_item():
		return false
	var instance: ItemInstance = null
	for carried: ItemInstance in character.inventory():
		if carried.id == equipment.melee_weapon_instance_id and carried.definition_id == equipment.melee_weapon.id and carried.equipped:
			instance = carried
			break
	if instance == null or not state.combat.queue_fumbled_item(instance):
		return false
	var removed := _rules.inventory.remove_item(character, instance.id, equipment.melee_weapon)
	if removed == null:
		state.combat.remove_fumbled_item(instance.id)
		instance.equipped = true
		return false
	# FD-COMBAT-005 preserves the exact runtime item and its remaining charges.
	# Castle's short-only queue reconstructs the item from its definition at booty.
	removed.identified = true
	_append_fumble_feedback(events, character.id, removed, true)
	return true

static func _append_monster_physical_feedback(events: Array[DomainEvent], sound_id: int) -> void:
	if sound_id > 0:
		events.append(DomainEvent.new(&"sound_requested", {"soundId": sound_id, "waitForCompletion": true, "source": "classic-party-dragon-hide"}))

static func _append_character_attack_audio(events: Array[DomainEvent], attacker: CharacterState, equipment: CharacterCombatEquipment, resolution: AttackResolution, target_kind: StringName) -> void:
	if attacker == null or equipment == null or resolution == null:
		return
	if resolution.blocked:
		_append_attack_sound(events, _weapon_requirement_sound(resolution.block_reason))
		return
	if not resolution.hit:
		_append_attack_sound(events, 650)
		return
	var sound_id := 600 + (equipment.melee_weapon.sound_id if equipment.melee_weapon != null else 30 + attacker.gender * 8)
	if resolution.killed and target_kind == &"character":
		_append_attack_sound(events, 132)
	_append_attack_sound(events, sound_id)
	if resolution.killed and target_kind != &"character":
		_append_attack_sound(events, 132)

static func _append_monster_attack_audio(events: Array[DomainEvent], attacker: MonsterState, definition: MonsterDefinition, attack_index: int, weapon: ItemDefinition, resolution: AttackResolution, rng: RealmzRng) -> void:
	if attacker == null or definition == null or resolution == null or rng == null:
		return
	if resolution.blocked:
		_append_attack_sound(events, _weapon_requirement_sound(resolution.block_reason))
		return
	if not resolution.hit:
		_append_attack_sound(events, 650)
		return
	var sound_id := 0
	if weapon != null:
		if weapon.blunt == -2:
			sound_id = rng.draw_between(635, 637, &"combat.monster-attack.sound")
		else:
			sound_id = 632 if rng.draw(100, &"combat.monster-attack.sound") < 50 else 639
	else:
		var attacks := definition.attacks()
		var selected := MonsterAttackDefinition.new(1, 1)
		if not attacks.is_empty():
			selected = attacks[clampi(attack_index, 0, attacks.size() - 1)]
			if selected.damage_min == 0:
				selected = attacks[0]
		sound_id = 600 + selected.sound_or_type
		if sound_id == 631:
			sound_id = 632
	_append_attack_sound(events, sound_id)
	if resolution.killed:
		_append_attack_sound(events, 132)

func _request_monster_death_macro(monster: MonsterState, definition: MonsterDefinition, events: Array[DomainEvent]) -> bool:
	if monster == null or definition == null or definition.death_macro <= 0:
		return false
	_append_monster_death_macro_request(monster, definition, events, false)
	return true

func _remove_curse(character: CharacterState, item_definitions: Array[ItemDefinition], result: TempleServiceResult) -> void:
	_clear_condition(character, CONDITION_CURSED, result)
	var definitions: Dictionary = {}
	for definition: ItemDefinition in item_definitions:
		definitions[definition.id] = definition
	for instance: ItemInstance in character.inventory():
		var definition: ItemDefinition = definitions.get(instance.definition_id)
		if instance.equipped and definition != null and not definition.cursed_item_id.is_empty():
			instance.equipped = false
			result.unequipped_item_ids.append(instance.id)
	result.applied = result.applied or not result.unequipped_item_ids.is_empty()

func tick_character(character: CharacterState) -> Array[DomainEvent]:
	var events: Array[DomainEvent] = []
	if character.conditions.is_active(REGENERATING) and character.current_health > -10 and character.current_health < character.maximum_health and not character.conditions.is_active(ANIMATED):
		var healed := mini(absi(character.conditions.value(REGENERATING)), character.maximum_health - character.current_health)
		character.current_health += healed
		events.append(DomainEvent.new(&"condition_healed", {"characterId": character.id, "condition": REGENERATING, "amount": healed}))
	for index: int in [DISEASED, POISONED]:
		if character.conditions.is_active(index) and character.current_health > 0 and character.conditions.value(ANIMATED) > -1:
			var damage := absi(character.conditions.value(index))
			character.current_health -= damage
			events.append(DomainEvent.new(&"condition_damaged", {"characterId": character.id, "condition": index, "amount": damage}))
	if character.conditions.is_active(ENERGY_DRAIN) and character.current_health > 0:
		character.spell_points = maxi(0, character.spell_points - absi(character.conditions.value(ENERGY_DRAIN)))
	if character.conditions.is_active(ABSORBING_ENERGY) and character.maximum_spell_points > 0 and character.current_health > 0:
		character.spell_points = mini(character.maximum_spell_points, character.spell_points + absi(character.conditions.value(ABSORBING_ENERGY)))
	for index: int in character.conditions.decay_positive():
		events.append(DomainEvent.new(&"condition_expired", {"characterId": character.id, "condition": index}))
	return events

func tick_party(party: PartyState) -> Array[DomainEvent]:
	var events: Array[DomainEvent] = []
	for index: int in party.conditions.decay_positive():
		events.append(DomainEvent.new(&"party_condition_expired", {"condition": index}))
	# Castle reduces every positive party condition once, then reduces Torch Lit
	# once more. Values already expired by the shared pass are not decremented again.
	if party.conditions.value(PARTY_TORCH_LIT) > 0:
		party.conditions.add(PARTY_TORCH_LIT, -1)
		if party.conditions.value(PARTY_TORCH_LIT) == 0:
			events.append(DomainEvent.new(&"party_condition_expired", {"condition": PARTY_TORCH_LIT}))
	for character: CharacterState in party.characters():
		events.append_array(tick_character(character))
	for ally: MonsterState in party.allies():
		for index: int in ally.conditions.decay_positive():
			events.append(DomainEvent.new(&"ally_condition_expired", {"allyId": ally.id, "condition": index}))
	return events

func _build_player_map_view(definition: PlayerMapDefinition) -> PlayerMapView:
	var cells: Array[MapCellView] = []
	var source_map: MapDefinition = _content.world.map_by_id(definition.map_id) if not definition.map_id.is_empty() else null
	if definition.mode in [PlayerMapDefinition.LAND_CROP, PlayerMapDefinition.DUNGEON_CROP] and source_map != null:
		var tile_count := ceili(320.0 / float(definition.icon_size))
		for y: int in range(definition.start.y, definition.start.y + tile_count):
			for x: int in range(definition.start.x, definition.start.x + tile_count):
				var cell := source_map.topology.cell_at(Vector2i(x, y))
				if cell != null:
					cells.append(_build_cell_view(source_map, cell, true))
	var show_party := false
	if source_map != null and source_map.id == _state.party.map_id and definition.mode != PlayerMapDefinition.SCROLLING_TEXT:
		var visible_tiles := 320 / definition.icon_size
		var marker_bounds := Rect2i(definition.start - Vector2i.ONE, Vector2i(visible_tiles + 1, visible_tiles + 1))
		show_party = marker_bounds.has_point(_state.party.coordinate)
	return PlayerMapView.new(definition, cells, show_party, _state.party.coordinate, true)

func _build_cell_view(map: MapDefinition, cell: MapCell, is_visible: bool) -> MapCellView:
	var feature_kinds: Array[StringName] = []
	var feature_orientations: Dictionary = {}
	var edge_kinds: Dictionary = {}
	var edge_passability: Dictionary = {}
	for direction: StringName in [&"north", &"east", &"south", &"west"]:
		var edge := cell.edge(direction)
		edge_kinds[direction] = edge.kind
		edge_passability[direction] = edge.passable
	var hidden_secret := false
	for feature: MapFeature in cell.features():
		if feature.kind == &"secret" and not _state.world.secret_is_discovered(feature.id, feature.initial_state == &"revealed"):
			hidden_secret = true
			continue
		if not feature_kinds.has(feature.kind):
			feature_kinds.append(feature.kind)
			feature_orientations[feature.kind] = feature.orientation
	var can_enter := cell.passable and not hidden_secret
	return MapCellView.new(cell.coordinate, _state.world.terrain_for(map.id, cell), cell.render_tile, cell.tileset_id, can_enter, cell.blocks_los, is_visible, _state.world.was_visited(map.id, cell.coordinate), not hidden_secret and not cell.trigger_ids().is_empty(), not cell.random_rect_ids().is_empty(), feature_kinds, feature_orientations, edge_kinds, edge_passability, cell.overlay_asset_id)

func _recalculate_party_movement() -> void:
	for character: CharacterState in _state.party.characters():
		var race := _content.race_by_id(character.race_id)
		var caste := _content.caste_by_id(character.caste_id)
		_rules.characters.recalculate_movement(character, race, caste.movement_bonus)

func _money_action(intent: PlayerIntent) -> SessionStep:
	var movement_error := _money_movement_context_error()
	if not movement_error.is_empty():
		return SessionStep.failed(_view_revision, &"invalid_money_context", movement_error)
	var events: Array[DomainEvent] = []
	match intent.action:
		&"pool":
			var probe := _rules.economy.pool_probe(_state.party)
			if not probe.allowed:
				return SessionStep.failed(_view_revision, &"money_action_unavailable", probe.reason)
			_rules.economy.pool_party_wealth(_state.party)
			events.append(DomainEvent.new(&"wealth_pooled", {"source": "classic-money", "wealth": _state.party.pooled_wealth.to_data()}))
			events.append(DomainEvent.new(&"sound_requested", {"soundId": 128, "waitForCompletion": false, "source": "classic-money-pool"}))
		&"share":
			var probe := _rules.economy.share_probe(_state.party)
			if not probe.allowed:
				return SessionStep.failed(_view_revision, &"money_action_unavailable", probe.reason)
			_rules.economy.share_pooled_wealth(_state.party)
			events.append(DomainEvent.new(&"wealth_shared", {"source": "classic-money", "remaining": _state.party.pooled_wealth.to_data()}))
			events.append(DomainEvent.new(&"sound_requested", {"soundId": 128, "waitForCompletion": false, "source": "classic-money-share"}))
		&"to-pool", &"to-character":
			var character := _state.party.character_by_id(intent.actor_id)
			var kind := _money_kind(intent.target_id)
			if character == null:
				return SessionStep.failed(_view_revision, &"unknown_character", "The selected money-transfer character is unavailable.")
			if kind < 0:
				return SessionStep.failed(_view_revision, &"unknown_wealth_kind", "The selected denomination is unavailable.")
			var expected_amount := EconomyRules.classic_transfer_increment(kind as WealthState.Kind)
			if intent.amount != expected_amount:
				return SessionStep.failed(_view_revision, &"invalid_money_increment", "Classic Swap moves five gold or one gem or jewelry per action.")
			var to_character := intent.action == &"to-character"
			var probe := _rules.economy.transfer_probe(_state.party, character, kind as WealthState.Kind, intent.amount, to_character)
			if not probe.allowed:
				return SessionStep.failed(_view_revision, &"money_action_unavailable", probe.reason)
			var transferred := _rules.economy.transfer_pool_to_character(_state.party, character, kind as WealthState.Kind, intent.amount) if to_character else _rules.economy.transfer_character_to_pool(_state.party, character, kind as WealthState.Kind, intent.amount)
			if not transferred:
				return SessionStep.failed(_view_revision, &"money_action_unavailable", "The selected wealth transfer is no longer available.")
			events.append(DomainEvent.new(&"wealth_transferred", {"source": "classic-money", "characterId": character.id, "direction": String(intent.action), "kind": String(intent.target_id), "amount": intent.amount}))
			events.append(DomainEvent.new(&"sound_requested", {"soundId": 10051 if to_character else 663, "waitForCompletion": false, "source": "classic-money-swap"}))
		_:
			return SessionStep.failed(_view_revision, &"unknown_money_action", "Money action '%s' is unavailable." % intent.action)
	_recalculate_party_movement()
	return _finish_completed(events)

static func _events_keep_trigger(events: Array[DomainEvent], trigger_id: String) -> bool:
	for event: DomainEvent in events:
		if event.kind == &"action_point_kept" and String(event.payload.get("triggerId", "")) == trigger_id:
			return true
	return false

func _append_session_battle_after_message(battle_id: String, events: Array[DomainEvent]) -> void:
	var battle := _content.battle_by_id(battle_id)
	if battle == null or battle.message_after_id == 0:
		return
	var message := _content.message_by_id(absi(battle.message_after_id))
	if message != null:
		events.append(DomainEvent.new(&"message_shown", {"messageId": message.id, "text": message.text, "source": "classic-battle-definition"}))

func _continue_session_death_macro(events: Array[DomainEvent]) -> SessionStep:
	var combat := _state.combat
	var battle_id := str(_session_continuation.get("battleId", ""))
	var combatant_id := str(_session_continuation.get("combatantId", ""))
	var program_id := str(_session_continuation.get("programId", ""))
	if combat == null or combat.battle_id != battle_id:
		_session_continuation.clear()
		return _finish_failed(&"invalid_battle_continuation", "Monster death-macro completion lost its battle.", events)
	var monster := combat.monster_by_id(combatant_id)
	if monster != null and bool(_session_continuation.get("resetTraitorOnComplete", true)):
		monster.traitor = false
	events.append(DomainEvent.new(&"monster_death_macro_completed", {"battleId": battle_id, "combatantId": combatant_id, "programId": program_id, "revived": monster != null and monster.current_health > 0}))
	_session_continuation.clear()
	var continued := _rules.combat_flow.continue_after_monster_death_macro(_state, _content, _rng, combatant_id)
	if not continued.ok:
		return _finish_failed(continued.error_code, continued.error_message, events)
	events.append_array(continued.events)
	if not CharacterAgingResult.update_payloads(continued.events).is_empty():
		return _finish_with_age_updates(events, "combat-monster-turns")
	if not _event_payload(continued.events, &"monster_death_macro_requested").is_empty():
		return _start_session_death_macro(events)
	if continued.completed:
		return _finish_direct_battle(events)
	return _finish_completed(events)

func _start_session_death_macro(preceding_events: Array[DomainEvent]) -> SessionStep:
	var request := _event_payload(preceding_events, &"monster_death_macro_requested")
	var combat := _state.combat
	if request.is_empty() or combat == null:
		return _finish_failed(&"invalid_death_macro_request", "Monster death-macro execution requires an active combatant request.", preceding_events)
	var combatant_id := str(request.get("combatantId", ""))
	var program_id := str(request.get("programId", ""))
	var monster := combat.monster_by_id(combatant_id)
	if monster == null or _content.scenario.program_by_id(program_id) == null:
		return _finish_failed(&"invalid_death_macro_request", "Monster death-macro execution references unavailable content.", preceding_events)
	_session_continuation = {
		"kind": "combat-death-macro",
		"battleId": combat.battle_id,
		"combatantId": combatant_id,
		"programId": program_id,
		"resetTraitorOnComplete": bool(request.get("resetTraitorOnComplete", true)),
	}
	var started := _scenario_vm.start_program(program_id, {
		"callingContext": "monster-death-macro",
		"battleId": combat.battle_id,
		"combatantId": combatant_id,
		"classicMonsterId": int(request.get("classicMonsterId", 0)),
		"traitor": bool(request.get("traitor", monster.traitor)),
	})
	if started.state == ScenarioVmResult.State.FAILED:
		_session_continuation.clear()
		return _finish_failed(started.error_code, started.error_message, preceding_events)
	var result := _scenario_vm.run(_runtime_api)
	var events: Array[DomainEvent] = []
	events.assign(preceding_events)
	events.append(DomainEvent.new(&"monster_death_macro_started", {"battleId": combat.battle_id, "combatantId": combatant_id, "programId": program_id}))
	events.append_array(result.events)
	if result.state == ScenarioVmResult.State.SUSPENDED:
		_session_continuation.clear()
		return _finish_failed(&"unsupported_vm_handoff_owner", "A session-owned monster death macro cannot suspend a total-party defeat.", events)
	if result.state == ScenarioVmResult.State.FAILED:
		_session_continuation.clear()
		return _finish_failed(result.error_code, result.error_message, events)
	if result.state == ScenarioVmResult.State.WAITING:
		return _finish_waiting(result.interaction, events)
	return _continue_session_death_macro(events)

func _continue_post_time(events: Array[DomainEvent]) -> SessionStep:
	var active_timed_program_id := String(_session_continuation.get("activeTimedProgramId", ""))
	if not active_timed_program_id.is_empty() and not _rebase_post_time_location():
		_session_continuation.clear()
		return _finish_failed(&"invalid_timed_encounter_location", "The completed timed encounter left the party at an unavailable location.", events)
	var map := _content.world.map_by_id(String(_session_continuation.get("mapId", "")))
	if map == null or _state.party.map_id != map.id or _state.party.coordinate != Vector2i(int(_session_continuation.get("x", -1)), int(_session_continuation.get("y", -1))):
		_session_continuation.clear()
		return _finish_failed(&"invalid_session_continuation", "Post-clock exploration continuation is unavailable.", events)
	if not active_timed_program_id.is_empty():
		_session_continuation["activeTimedProgramId"] = ""
	var timed_step := _continue_timed_encounters(events)
	if timed_step != null:
		return timed_step
	map = _content.world.map_by_id(String(_session_continuation.get("mapId", "")))
	if map == null:
		_session_continuation.clear()
		return _finish_failed(&"invalid_timed_encounter_location", "Timed encounter continuation references an unavailable map.", events)
	var active_program_id := String(_session_continuation.get("activeRandomProgramId", ""))
	if not active_program_id.is_empty():
		_session_continuation["activeRandomProgramId"] = ""
		return _complete_post_time(events)
	if bool(_session_continuation.get("checkRandom", false)) and _session_continuation.get("resumeKind") != "post-move":
		var random_step := _continue_random_regions(map, events)
		if random_step != null:
			return random_step
	return _complete_post_time(events)

func _complete_post_time(events: Array[DomainEvent]) -> SessionStep:
	var resume_kind := String(_session_continuation.get("resumeKind", ""))
	var direction := Vector2i(int(_session_continuation.get("directionX", 0)), int(_session_continuation.get("directionY", 0)))
	_session_continuation.clear()
	if resume_kind == "move":
		return _commit_move(direction, events)
	if resume_kind == "post-move":
		var map := _content.world.map_by_id(_state.party.map_id)
		_set_post_move_continuation(map, _state.party.coordinate)
		return _continue_post_move(events)
	if resume_kind == "completed":
		return _finish_completed(events)
	return _finish_failed(&"invalid_session_continuation", "Post-clock exploration continuation has no valid completion path.", events)

func _continue_timed_encounters(events: Array[DomainEvent]) -> SessionStep:
	var timed_day := int(_session_continuation.get("timedDay", 0))
	if timed_day <= 0:
		return null
	var encounters := _content.timed_encounters()
	while int(_session_continuation.get("timedEncounterIndex", 0)) < encounters.size():
		var index := int(_session_continuation["timedEncounterIndex"])
		var encounter := encounters[index]
		_session_continuation["timedEncounterIndex"] = index + 1
		var effective := _state.timed_encounter_override(encounter.id)
		var effective_day := int(effective.get("day", encounter.day))
		if effective_day != timed_day:
			continue
		var increment := int(effective.get("increment", encounter.increment))
		effective["day"] = effective_day + increment
		_state.set_timed_encounter_override(encounter.id, effective)
		events.append(DomainEvent.new(&"timed_encounter_advanced", {"encounterId": encounter.id, "day": effective_day, "nextDay": effective["day"], "source": "classic-midnight"}))
		var chance := int(effective.get("percent", encounter.chance_percent))
		var roll := _rng.draw(100, StringName("timed-encounter.%d" % encounter.id))
		var map := _content.world.map_by_id(_state.party.map_id)
		if map == null:
			_session_continuation.clear()
			return _finish_failed(&"invalid_timed_encounter_location", "Timed encounter eligibility references an unavailable map.", events)
		var eligible := roll <= chance and _timed_encounter_requirements_met(encounter, map)
		events.append(DomainEvent.new(&"timed_encounter_checked", {"encounterId": encounter.id, "roll": roll, "chancePercent": chance, "eligible": eligible}))
		if not eligible:
			continue
		_apply_pending_midnight_recovery(events)
		var trigger := _content.trigger_by_map_record(map.id, encounter.trigger_record_index)
		if trigger == null:
			_session_continuation.clear()
			return _finish_failed(&"unknown_timed_encounter_trigger", "Timed Encounter %d references unavailable Action Point record %d on map '%s'." % [encounter.id, encounter.trigger_record_index, map.id], events)
		_session_continuation["activeTimedProgramId"] = trigger.program_id
		events.append(DomainEvent.new(&"timed_encounter_triggered", {"encounterId": encounter.id, "triggerId": trigger.id, "programId": trigger.program_id}))
		var started := _scenario_vm.start_program(trigger.program_id, {"callingContext": "action", "triggerId": trigger.id, "mapId": map.id, "x": _session_continuation["timedCheckX"], "y": _session_continuation["timedCheckY"], "timedEncounterId": encounter.id})
		if started.state == ScenarioVmResult.State.FAILED:
			_session_continuation.clear()
			return _finish_failed(started.error_code, started.error_message, events)
		var result := _scenario_vm.run(_runtime_api)
		events.append_array(result.events)
		if result.state == ScenarioVmResult.State.SUSPENDED:
			return _begin_scenario_handoff(result, events)
		if result.state == ScenarioVmResult.State.WAITING:
			if not _rebase_post_time_location():
				_session_continuation.clear()
				return _finish_failed(&"invalid_timed_encounter_location", "The timed encounter moved the party to an unavailable location.", events)
			return _finish_waiting(result.interaction, events)
		if result.state == ScenarioVmResult.State.FAILED:
			_session_continuation.clear()
			return _finish_failed(result.error_code, result.error_message, events)
		_session_continuation["activeTimedProgramId"] = ""
		if not _rebase_post_time_location():
			_session_continuation.clear()
			return _finish_failed(&"invalid_timed_encounter_location", "The completed timed encounter left the party at an unavailable location.", events)
	_apply_pending_midnight_recovery(events)
	_session_continuation["timedDay"] = 0
	return null

func _apply_pending_midnight_recovery(events: Array[DomainEvent]) -> void:
	if not bool(_session_continuation.get("midnightRecoveryPending", false)):
		return
	_session_continuation["midnightRecoveryPending"] = false
	events.append_array(_rules.clock.restore_half_day_health(_state.party, _content))

func _rebase_post_time_location() -> bool:
	var map := _content.world.map_by_id(_state.party.map_id)
	var cell: MapCell = null if map == null else map.topology.cell_at(_state.party.coordinate)
	if cell == null:
		return false
	_session_continuation["mapId"] = map.id
	_session_continuation["x"] = _state.party.coordinate.x
	_session_continuation["y"] = _state.party.coordinate.y
	_session_continuation["timedCheckX"] = _state.party.coordinate.x
	_session_continuation["timedCheckY"] = _state.party.coordinate.y
	_session_continuation["randomRegionIds"] = cell.random_rect_ids()
	_session_continuation["randomRegionIndex"] = cell.random_rect_ids().size() - 1
	return true

func _timed_encounter_requirements_met(encounter: TimedEncounterDefinition, map: MapDefinition) -> bool:
	if encounter.required_item_id > 0 and not _party_has_classic_item(encounter.required_item_id):
		return false
	if encounter.required_quest_id > -1 and not _state.quest_is_set(encounter.required_quest_id):
		return false
	if encounter.location_kind == TimedEncounterDefinition.LocationKind.ANY:
		return true
	if encounter.location_kind == TimedEncounterDefinition.LocationKind.LAND and map.level_type != &"land" or encounter.location_kind == TimedEncounterDefinition.LocationKind.DUNGEON and map.level_type != &"dungeon":
		return false
	if map.level_index != encounter.required_level:
		return false
	var coordinate := Vector2i(int(_session_continuation.get("timedCheckX", -1)), int(_session_continuation.get("timedCheckY", -1)))
	if encounter.required_random_rectangle > -1:
		var region := map.random_region_by_index(encounter.required_random_rectangle)
		if region == null or not region.bounds.has_point(coordinate):
			return false
	if encounter.required_x > -1 and coordinate.x != encounter.required_x:
		return false
	if encounter.required_y > -1 and coordinate.y != encounter.required_y:
		return false
	return true

static func _event_payload(events: Array[DomainEvent], kind: StringName) -> Dictionary:
	for index: int in range(events.size() - 1, -1, -1):
		if events[index].kind == kind:
			return events[index].payload
	return {}

func _party_has_classic_item(classic_item_id: int) -> bool:
	var definition := _content.item_by_classic_id(classic_item_id)
	if definition == null:
		return false
	for character: CharacterState in _state.party.characters():
		for item: ItemInstance in character.inventory():
			if item.definition_id == definition.id:
				return true
	return false

func _normalize_age_groups(state: GameState, content: RealmzContent, rules: RealmzRules) -> void:
	for character: CharacterState in state.party.characters():
		var race := content.race_by_id(character.race_id)
		var caste := content.caste_by_id(character.caste_id)
		if race != null and caste != null:
			rules.characters.ensure_age_group(character, race, caste)

func _continue_post_move(events: Array[DomainEvent]) -> SessionStep:
	if _events_have(events, &"destination_trigger_recheck_requested") and int(_session_continuation.get("actionPointDestinationDepth", 0)) == 0:
		var requested_map := _content.world.map_by_id(_state.party.map_id)
		if requested_map == null:
			_session_continuation.clear()
			return _finish_failed(&"invalid_teleport", "Destination trigger recheck references an unavailable map.", events)
		_set_post_move_continuation(requested_map, _state.party.coordinate, 1)
	var map := _content.world.map_by_id(String(_session_continuation.get("mapId", "")))
	var coordinate := Vector2i(int(_session_continuation.get("x", -1)), int(_session_continuation.get("y", -1)))
	var cell: MapCell = null if map == null else map.topology.cell_at(coordinate)
	if cell == null:
		_session_continuation.clear()
		return _finish_failed(&"invalid_session_continuation", "Post-movement topology continuation is unavailable.", events)
	var active_random_program_id := String(_session_continuation.get("activeRandomProgramId", ""))
	if not active_random_program_id.is_empty():
		_session_continuation.clear()
		return _finish_completed(events)
	var active_trigger_id := String(_session_continuation.get("activeTriggerId", ""))
	if not active_trigger_id.is_empty():
		var completed_trigger := _content.trigger_by_id(active_trigger_id)
		if completed_trigger == null:
			_session_continuation.clear()
			return _finish_failed(&"invalid_session_continuation", "Completed trigger continuation is unavailable.", events)
		_finalize_completed_trigger(completed_trigger, events)
		if _apply_trigger_destination(completed_trigger, events, int(_session_continuation.get("actionPointDestinationDepth", 0)) == 0):
			var destination_map := _content.world.map_by_id(_state.party.map_id)
			_set_post_move_continuation(destination_map, _state.party.coordinate, 1)
			return _continue_post_move(events)
		_session_continuation["activeTriggerId"] = ""
		_session_continuation["triggerIndex"] = _session_continuation["triggerIds"].size()
	var trigger_ids: Array = _session_continuation["triggerIds"]
	while int(_session_continuation["triggerIndex"]) < trigger_ids.size():
		var trigger_index: int = int(_session_continuation["triggerIndex"])
		var trigger_id: String = String(trigger_ids[trigger_index])
		var trigger := _content.trigger_by_id(trigger_id)
		if trigger == null or not trigger.active or _state.world.trigger_is_disabled(trigger_id):
			_session_continuation["triggerIndex"] = trigger_ids.size()
			break
		var trigger_chance := _state.world.trigger_chance(trigger.id, trigger.chance_percent)
		if trigger_chance < 1:
			_session_continuation["triggerIndex"] = trigger_ids.size()
			break
		if trigger_chance < 100:
			var chance_roll := _rng.draw(100, StringName("trigger.%s" % trigger.id))
			if chance_roll > trigger_chance:
				_session_continuation["triggerIndex"] = trigger_ids.size()
				break
		events.append(DomainEvent.new("trigger_fired", {"triggerId": trigger.id}))
		_session_continuation["activeTriggerId"] = trigger.id
		var started := _scenario_vm.start_program(trigger.program_id, {"callingContext": "action", "triggerId": trigger.id, "mapId": map.id, "x": coordinate.x, "y": coordinate.y})
		if started.state == ScenarioVmResult.State.FAILED:
			_session_continuation.clear()
			return _finish_failed(started.error_code, started.error_message, events)
		var result := _scenario_vm.run(_runtime_api)
		events.append_array(result.events)
		if result.state == ScenarioVmResult.State.SUSPENDED:
			return _begin_scenario_handoff(result, events)
		if result.state == ScenarioVmResult.State.WAITING:
			return _finish_waiting(result.interaction, events)
		if result.state == ScenarioVmResult.State.FAILED:
			_session_continuation.clear()
			return _finish_failed(result.error_code, result.error_message, events)
		_finalize_completed_trigger(trigger, events)
		if _events_have(result.events, &"destination_trigger_recheck_requested"):
			var requested_map := _content.world.map_by_id(_state.party.map_id)
			if requested_map == null:
				_session_continuation.clear()
				return _finish_failed(&"invalid_teleport", "Destination trigger recheck references an unavailable map.", events)
			_set_post_move_continuation(requested_map, _state.party.coordinate, 1)
			return _continue_post_move(events)
		if _apply_trigger_destination(trigger, events, int(_session_continuation.get("actionPointDestinationDepth", 0)) == 0):
			var destination_map := _content.world.map_by_id(_state.party.map_id)
			_set_post_move_continuation(destination_map, _state.party.coordinate, 1)
			return _continue_post_move(events)
		_session_continuation["activeTriggerId"] = ""
		_session_continuation["triggerIndex"] = trigger_ids.size()
	var random_step := _continue_random_regions(map, events)
	if random_step != null:
		return random_step
	_session_continuation.clear()
	return _finish_completed(events)

func _continue_exploration_continuation(events: Array[DomainEvent]) -> SessionStep:
	if _session_continuation.get("kind") == "application-hook":
		return _continue_application_hook(events)
	if _session_continuation.get("kind") == "post-clock":
		return _continue_post_time(events)
	if _session_continuation.get("kind") == "post-move":
		return _continue_post_move(events)
	return _finish_failed(&"invalid_session_continuation", "The completed scenario has no valid exploration continuation.", events)

func _start_application_hook(hook: StringName, resume_kind: String, service_id: String, preceding_events: Array[DomainEvent], suspended_context: Dictionary = {}) -> SessionStep:
	var program_id := _content.scenario.application_hook_program_id(hook)
	_session_continuation = {
		"kind": "application-hook",
		"hook": String(hook),
		"programId": program_id,
		"resumeKind": resume_kind,
		"serviceId": service_id,
		"partyRevived": false,
	}
	for key: Variant in suspended_context:
		_session_continuation[key] = suspended_context[key]
	if program_id.is_empty():
		return _continue_application_hook(preceding_events)
	var started := _scenario_vm.start_program(program_id, {
		"callingContext": "lifecycle",
		"applicationHook": String(hook),
		"serviceId": service_id,
	})
	if started.state == ScenarioVmResult.State.FAILED:
		_session_continuation.clear()
		return _finish_failed(started.error_code, started.error_message, preceding_events)
	var result := _scenario_vm.run(_runtime_api)
	var events: Array[DomainEvent] = []
	events.assign(preceding_events)
	events.append(DomainEvent.new(&"application_hook_started", {"hook": String(hook), "programId": program_id}))
	events.append_array(result.events)
	if _events_have(result.events, &"party_revived"):
		_session_continuation["partyRevived"] = true
	if result.state == ScenarioVmResult.State.SUSPENDED:
		return _finish_failed(&"nested_party_defeat_handoff", "An application hook cannot suspend another total-party defeat.", events)
	if result.state == ScenarioVmResult.State.FAILED:
		_session_continuation.clear()
		return _finish_failed(result.error_code, result.error_message, events)
	if result.state == ScenarioVmResult.State.WAITING:
		return _finish_waiting(result.interaction, events)
	return _continue_application_hook(events)

func _continue_application_hook(events: Array[DomainEvent]) -> SessionStep:
	var hook := StringName(_session_continuation.get("hook", ""))
	var program_id := String(_session_continuation.get("programId", ""))
	var resume_kind := String(_session_continuation.get("resumeKind", ""))
	var service_id := String(_session_continuation.get("serviceId", ""))
	var party_revived := bool(_session_continuation.get("partyRevived", false))
	var suspended_vm: Dictionary = _session_continuation.get("suspendedVm", {}).duplicate(true)
	var suspended_owner: Dictionary = _session_continuation.get("suspendedOwner", {}).duplicate(true)
	var vm_handoff: Dictionary = _session_continuation.get("vmHandoff", {}).duplicate(true)
	_session_continuation.clear()
	if not program_id.is_empty():
		events.append(DomainEvent.new(&"application_hook_completed", {"hook": String(hook), "programId": program_id}))
	match resume_kind:
		"begin-adventure":
			events.append(DomainEvent.new(&"adventure_begun", {"campaignId": _content.campaign_id}))
			return _finish_completed(events)
		"service":
			return _open_contextual_service(service_id, events)
		"end-adventure":
			return _start_application_hook(ScenarioApplicationHooks.PARTY_DEATH, "end-adventure-close", "", events)
		"end-adventure-close":
			if party_revived:
				events.append(DomainEvent.new(&"adventure_end_suppressed", {"reason": "classic-party-death-revival"}))
				return _finish_completed(events)
			return _commit_close(events, "end-adventure")
		"party-defeat":
			if not party_revived:
				return _commit_close(events, "party-defeat")
			if _state.combat == null or not _state.combat.completed or _state.combat.outcome != &"defeat":
				return _finish_failed(&"invalid_battle_continuation", "Party Death revival lost its completed defeat.", events)
			_state.combat.outcome = &"retreated"
			_state.last_battle_outcome = &"retreated"
			events.append(DomainEvent.new(&"party_defeat_revived", {"battleId": _state.combat.battle_id, "source": "classic-party-death-hook"}))
			return _finish_direct_battle_without_rewards(events)
		"scenario-party-defeat":
			if not party_revived:
				return _commit_close(events, "party-defeat")
			return _resume_scenario_party_defeat(suspended_vm, suspended_owner, vm_handoff, events)
	return _finish_failed(&"invalid_session_continuation", "Application hook '%s' has invalid resume kind '%s'." % [hook, resume_kind], events)

func _begin_scenario_handoff(result: ScenarioVmResult, events: Array[DomainEvent]) -> SessionStep:
	if result == null or result.state != ScenarioVmResult.State.SUSPENDED or not result.handoff.get("runtime") is Dictionary:
		_session_continuation.clear()
		return _finish_failed(&"invalid_vm_handoff", "The Scenario VM did not provide a typed application handoff.", events)
	if _session_continuation.get("kind") not in ["post-clock", "post-move"]:
		_session_continuation.clear()
		return _finish_failed(&"unsupported_vm_handoff_owner", "Total-party defeat cannot suspend this scenario caller.", events)
	var saved := _scenario_vm.snapshot()
	if not ScenarioVm.handoff_is_valid(result.handoff, saved) or not RealmzRuntimeApi.party_defeat_handoff_is_valid(_content, _state, result.handoff["runtime"]):
		_session_continuation.clear()
		return _finish_failed(&"invalid_party_defeat_handoff", "The Scenario VM total-party defeat handoff is invalid.", events)
	var suspended_context := {
		"suspendedVm": saved.to_data(),
		"suspendedOwner": _session_continuation.duplicate(true),
		"vmHandoff": result.handoff.duplicate(true),
	}
	_scenario_vm.reset()
	return _start_application_hook(ScenarioApplicationHooks.PARTY_DEATH, "scenario-party-defeat", "", events, suspended_context)

func _resume_scenario_party_defeat(suspended_vm_data: Dictionary, suspended_owner: Dictionary, vm_handoff: Dictionary, events: Array[DomainEvent]) -> SessionStep:
	var saved := ScenarioVmSnapshot.from_data(suspended_vm_data)
	if not ScenarioVm.handoff_is_valid(vm_handoff, saved) or not RealmzRuntimeApi.party_defeat_handoff_is_valid(_content, _state, vm_handoff.get("runtime")) or not _valid_suspended_scenario_owner(_content, _state, suspended_owner, saved):
		return _finish_failed(&"invalid_party_defeat_handoff", "The saved scenario defeat continuation is invalid.", events)
	var restored_vm := ScenarioVm.new()
	restored_vm.configure(_content.scenario)
	if not restored_vm.restore(saved):
		return _finish_failed(&"invalid_vm_state", "The suspended scenario cannot be restored after Party Death.", events)
	var operation := _runtime_api.complete_party_defeat_handoff(vm_handoff["runtime"])
	if operation.state == ScenarioRuntimeOperationResult.State.FAILED:
		return _finish_failed(operation.error_code, operation.error_message, events)
	_scenario_vm = restored_vm
	var resumed := _scenario_vm.resume_handoff(vm_handoff, operation, _runtime_api)
	events.append_array(resumed.events)
	_session_continuation = suspended_owner.duplicate(true)
	if resumed.state == ScenarioVmResult.State.SUSPENDED:
		return _begin_scenario_handoff(resumed, events)
	if resumed.state == ScenarioVmResult.State.WAITING:
		return _finish_waiting(resumed.interaction, events)
	if resumed.state == ScenarioVmResult.State.FAILED:
		_session_continuation.clear()
		return _finish_failed(resumed.error_code, resumed.error_message, events)
	if _session_continuation.is_empty():
		return _finish_completed(events)
	return _continue_exploration_continuation(events)

func _finalize_completed_trigger(trigger: TriggerDefinition, events: Array[DomainEvent]) -> void:
	if _events_keep_trigger(events, trigger.id) or _state.world.trigger_is_disabled(trigger.id):
		return
	_state.world.disable_trigger(trigger.id)
	events.append(DomainEvent.new(&"trigger_disabled", {"triggerId": trigger.id, "source": "classic-default-one-shot"}))

static func _events_have(events: Array[DomainEvent], kind: StringName) -> bool:
	for event: DomainEvent in events:
		if event.kind == kind:
			return true
	return false

static func _selected_placed_trigger_ids(content: RealmzContent, cell: MapCell) -> Array[String]:
	var selected_id := ""
	var selected_record_index := 2_147_483_647
	for trigger_id: String in cell.trigger_ids():
		var trigger := content.trigger_by_id(trigger_id)
		if trigger != null and trigger.classic_record_index < selected_record_index:
			selected_id = trigger.id
			selected_record_index = trigger.classic_record_index
	return [] if selected_id.is_empty() else [selected_id]

func _revive(character: CharacterState, result: TempleServiceResult) -> void:
	var stone_before := character.conditions.value(CONDITION_STONE)
	var animated_before := character.conditions.value(CONDITION_ANIMATED)
	if stone_before == 0 and (character.current_health < -9 or animated_before != 0):
		character.current_health = -9
		character.set_ability_value(2, RealmzArithmetic.new().signed_16(character.ability_value(2) - 2))
	character.conditions.set_value(CONDITION_ANIMATED, 0)
	character.conditions.set_value(CONDITION_STONE, 0)
	result.condition_index = CONDITION_ANIMATED if animated_before != 0 else CONDITION_STONE
	result.condition_before = animated_before if animated_before != 0 else stone_before
	result.condition_after = 0
	result.applied = character.current_health != result.health_before or character.ability_value(2) != result.ability_before or animated_before != 0 or stone_before != 0

func _build_map_view() -> MapView:
	var map := _content.world.map_by_id(_state.party.map_id)
	var visible: Dictionary = {}
	if map.uses_los:
		for coordinate: Vector2i in map.topology.visible_cells(_state.party.coordinate, 8, _state.world, true):
			visible[coordinate] = true
	var cells: Array[MapCellView] = []
	var first_x := maxi(0, _state.party.coordinate.x - MAP_VIEW_RADIUS)
	var first_y := maxi(0, _state.party.coordinate.y - MAP_VIEW_RADIUS)
	var last_x := mini(map.topology.width, _state.party.coordinate.x + MAP_VIEW_RADIUS + 1)
	var last_y := mini(map.topology.height, _state.party.coordinate.y + MAP_VIEW_RADIUS + 1)
	for y: int in range(first_y, last_y):
		for x: int in range(first_x, last_x):
			var cell := map.topology.cell_at(Vector2i(x, y))
			if cell == null:
				continue
			cells.append(_build_cell_view(map, cell, not map.uses_los or visible.has(cell.coordinate)))
	var movement_options: Dictionary = {}
	var directions := MapTopology.land_directions() if map.level_type == &"land" else MapTopology.cardinal_directions()
	for direction: Vector2i in directions:
		var direction_name := MapTopology.direction_name(direction)
		var probe := _probe_movement(direction)
		movement_options[direction_name] = {"allowed": probe.allowed, "reason": String(probe.reason)}
	return MapView.new(map.id, map.name, map.level_type, map.topology.width, map.topology.height, _state.party.coordinate, cells, _state.world.map_is_dark(map), _state.world.visited_coordinates(map.id), movement_options)

static func _valid_reward_continuation(content: RealmzContent, state: GameState, reward: ClassicRewardState, request: InteractionRequest) -> bool:
	if reward == null or request == null or reward.source_id.is_empty() or reward.origin not in [&"scenario", &"battle"]:
		return false
	if reward.origin == &"battle" and (state.combat == null or not state.combat.completed or not state.combat.rewards_started or state.combat.rewards_completed or state.combat.battle_id != reward.source_id):
		return false
	for item: ItemInstance in reward.items():
		if content.item_by_id(item.definition_id) == null:
			return false
	var character_ids: Dictionary = {}
	for character_id: Variant in reward.experience_awards():
		character_ids[String(character_id)] = true
	for character_id: String in reward.level_character_ids():
		character_ids[character_id] = true
	for character_id: String in reward.spell_character_ids():
		character_ids[character_id] = true
	if not reward.pending_level_result.is_empty():
		character_ids[String(reward.pending_level_result.get("characterId", ""))] = true
	for character_id: Variant in character_ids:
		if String(character_id).is_empty() or state.party.character_by_id(String(character_id)) == null:
			return false
	if reward.phase == ClassicRewardState.ITEM_PHASE:
		if request.kind != InteractionRequest.TREASURE_DISTRIBUTION:
			return false
		var expected_mode := "completion-confirmation" if reward.completion_pending else "ordinary"
		if request.payload.get("mode") != expected_mode:
			return false
		var pending := reward.first_item()
		var request_item: Variant = request.payload.get("item")
		return request_item == null if pending == null else request_item is Dictionary and request_item.get("instanceId") == pending.id
	if reward.phase == ClassicRewardState.LEVEL_PHASE:
		return not reward.pending_level_result.is_empty() and request.kind == InteractionRequest.LEVEL_UP and request.payload.get("mode") == "result" and request.payload.get("characterId") == reward.pending_level_result.get("characterId")
	if reward.phase == ClassicRewardState.SPELL_PHASE:
		var spell_ids := reward.spell_character_ids()
		return reward.spell_index < spell_ids.size() and request.kind == InteractionRequest.LEVEL_UP and request.payload.get("mode") == "spell-selection" and request.payload.get("characterId") == spell_ids[reward.spell_index]
	return false

static func _valid_ready_post_move_continuation(content: RealmzContent, state: GameState, continuation: Dictionary) -> bool:
	var fields: Array[String] = ["kind", "mapId", "x", "y", "triggerIds", "triggerIndex", "activeTriggerId", "randomRegionIds", "randomRegionIndex", "activeRandomProgramId", "activeRandomRegionId", "randomBattleStage", "actionPointDestinationDepth"]
	if continuation.size() != fields.size():
		return false
	for field: String in fields:
		if not continuation.has(field):
			return false
	if continuation["kind"] != "post-move" or not continuation["mapId"] is String or not continuation["x"] is int or not continuation["y"] is int or not continuation["triggerIds"] is Array or continuation["triggerIndex"] != 0 or not continuation["activeTriggerId"] is String or not continuation["activeTriggerId"].is_empty() or not continuation["randomRegionIds"] is Array or not continuation["randomRegionIndex"] is int or not continuation["activeRandomProgramId"] is String or not continuation["activeRandomProgramId"].is_empty() or not continuation["activeRandomRegionId"] is String or not continuation["activeRandomRegionId"].is_empty() or not continuation["randomBattleStage"] is String or not continuation["randomBattleStage"].is_empty() or not continuation["actionPointDestinationDepth"] is int or int(continuation["actionPointDestinationDepth"]) < 0 or int(continuation["actionPointDestinationDepth"]) > 1:
		return false
	var map := content.world.map_by_id(continuation["mapId"])
	var coordinate := Vector2i(continuation["x"], continuation["y"])
	var cell: MapCell = null if map == null else map.topology.cell_at(coordinate)
	return cell != null and state.party.map_id == map.id and state.party.coordinate == coordinate \
		and continuation["triggerIds"] == _selected_placed_trigger_ids(content, cell) \
		and continuation["randomRegionIds"] == cell.random_rect_ids() \
		and int(continuation["randomRegionIndex"]) == continuation["randomRegionIds"].size() - 1

static func _valid_age_update_payload(state: GameState, value: Variant) -> bool:
	if not value is Dictionary:
		return false
	var character_id: Variant = value.get("characterId")
	var changes: Variant = value.get("changes")
	return character_id is String and not character_id.is_empty() and state.party.character_by_id(character_id) != null \
		and value.get("presentation") == "classic-age-update" and value.get("soundId") is int \
		and value.get("ageGroup") is int and int(value.get("ageGroup")) >= 1 and int(value.get("ageGroup")) <= 5 \
		and value.get("transition") is int and int(value.get("transition")) in [-1, 1] \
		and changes is Array and changes.size() == 15 and changes.all(func(change: Variant) -> bool: return change is int)

func _begin_runtime_service(service_id: String, operation: ScenarioRuntimeOperationResult) -> SessionStep:
	if operation == null:
		return _finish_failed(&"service_failed", "The selected service returned no operation result.", [])
	if operation.state == ScenarioRuntimeOperationResult.State.FAILED:
		return _finish_failed(operation.error_code, operation.error_message, operation.events)
	if operation.state != ScenarioRuntimeOperationResult.State.WAITING or operation.interaction == null:
		return _finish_failed(&"service_failed", "The selected service did not produce its required interaction.", operation.events)
	_session_continuation = {"kind": "service-interaction", "serviceId": service_id, "runtimeContinuation": operation.continuation.duplicate(true)}
	_session_interaction = operation.interaction
	return _finish_waiting(_session_interaction, operation.events)

func _respond_runtime_service(response: InteractionResponse) -> SessionStep:
	var runtime_continuation: Variant = _session_continuation.get("runtimeContinuation")
	if not runtime_continuation is Dictionary:
		return SessionStep.failed(_view_revision, &"invalid_session_continuation", "The pending service has no runtime continuation.")
	var result := _runtime_api.resume_classic(runtime_continuation, response, response.request_id)
	if result.state == ScenarioRuntimeOperationResult.State.FAILED:
		return _finish_failed(result.error_code, result.error_message, result.events)
	if result.state == ScenarioRuntimeOperationResult.State.WAITING:
		_session_continuation["runtimeContinuation"] = result.continuation.duplicate(true)
		_session_interaction = result.interaction
		return _finish_waiting(_session_interaction, result.events)
	_session_interaction = null
	_session_continuation.clear()
	return _finish_completed(result.events)

func _respond_drop_item(response: InteractionResponse) -> SessionStep:
	if response.kind != InteractionRequest.YES_NO or response.payload.get("accepted") is not bool:
		return SessionStep.failed(_view_revision, &"invalid_interaction_response", "Dropping an item requires a yes/no response.")
	var character_id := String(_session_continuation.get("characterId", ""))
	var instance_id := String(_session_continuation.get("instanceId", ""))
	var character := _state.party.character_by_id(character_id)
	var instance := _item_instance(character, instance_id)
	var definition: ItemDefinition = null if instance == null else _content.item_by_id(instance.definition_id)
	if character == null or instance == null or definition == null:
		return SessionStep.failed(_view_revision, &"invalid_session_continuation", "The item awaiting drop confirmation is unavailable.")
	var probe := _rules.inventory.classic_drop_probe(character, instance)
	if not probe.allowed:
		return SessionStep.failed(_view_revision, &"item_cannot_drop", probe.reason)
	_session_interaction = null
	_session_continuation.clear()
	if not response.payload["accepted"]:
		return _finish_completed([DomainEvent.new(&"item_drop_declined", {"characterId": character.id, "instanceId": instance.id})])
	var removed := _rules.inventory.remove_item(character, instance.id, definition)
	if removed == null:
		return SessionStep.failed(_view_revision, &"item_drop_failed", "The item could not be removed from inventory.")
	return _finish_completed([DomainEvent.new(&"item_dropped", {"characterId": character.id, "instanceId": instance.id, "itemId": definition.id})])

func _respond_character_spell_confirmation(response: InteractionResponse) -> SessionStep:
	if response.kind != InteractionRequest.YES_NO or response.payload.get("accepted") is not bool:
		return SessionStep.failed(_view_revision, &"invalid_interaction_response", "Starting-spell confirmation requires a yes/no response.")
	var character_id := String(_session_continuation.get("characterId", ""))
	if _state.character_draft == null or _state.character_draft.generated_character == null or _state.character_draft.generated_character.id != character_id:
		return SessionStep.failed(_view_revision, &"invalid_session_continuation", "The character awaiting starting-spell confirmation is unavailable.")
	_session_interaction = null
	_session_continuation.clear()
	if not response.payload["accepted"]:
		return _finish_completed([DomainEvent.new(&"character_spell_confirmation_declined", {"characterId": character_id})])
	return _commit_character_draft([DomainEvent.new(&"character_spell_confirmation_accepted", {"characterId": character_id})])

func _respond_character_vault_publication(response: InteractionResponse) -> SessionStep:
	if response.kind != InteractionRequest.YES_NO or response.payload.get("accepted") is not bool:
