func _draw() -> void:
	if _view == null or _view.combat_view == null or _view.combat_view.battlefield == null:
		return
	var combat := _view.combat_view
	var battlefield := combat.battlefield
	var playback_focus_id := _playback_frame.actor_id if _playback_frame != null and not _playback_frame.actor_id.is_empty() else ""
	var focus_id := _camera_focus_id if not _camera_focus_id.is_empty() else playback_focus_id if not playback_focus_id.is_empty() else combat.active_actor_id
	var active_position := _effective_actor_position(combat, focus_id)
	if active_position.x < 0:
		active_position = battlefield.party_anchor
	var visible_cells := viewport_cells_for(size)
	var camera := camera_top_left(active_position, visible_cells)
	var draw_origin := battlefield_draw_origin(size, visible_cells)
	_draw_header(combat)
	for y: int in visible_cells.y:
		for x: int in visible_cells.x:
			var coordinate := camera + Vector2i(x, y)
			var rect := Rect2(draw_origin + Vector2(x, y) * NATIVE_CELL_SIZE, Vector2.ONE * NATIVE_CELL_SIZE)
			_draw_terrain_cell(battlefield.terrain_at(coordinate), rect)
	_draw_revealed_relationships(combat, camera, visible_cells, draw_origin)
	_draw_movement_options(combat, camera, visible_cells, draw_origin)
	_draw_targeting_preview(combat, camera, visible_cells, draw_origin)
	_draw_characters(combat, camera, visible_cells, draw_origin)
	_draw_monsters(combat, camera, visible_cells, draw_origin)
	_draw_playback_overlay(combat, camera, visible_cells, draw_origin)
	if not has_battle_artwork():
		draw_string(ThemeDB.fallback_font, Vector2(draw_origin.x + 8.0, draw_origin.y + 20.0), "Battle artwork unavailable", HORIZONTAL_ALIGNMENT_LEFT, -1.0, 13, Color(1.0, 0.78, 0.42))

func _draw_header(combat: CombatView) -> void:
	var current_actor_name := actor_name(combat, _view.party_members, combat.active_actor_id)
	var title := "Battle %s • Round %d • %s" % [combat.battle_id, combat.round_number, current_actor_name]
	var facts := "%d attack%s • %d movement • %s" % [combat.attack_units_remaining, "" if combat.attack_units_remaining == 1 else "s", combat.movement_remaining, String(combat.weapon_mode).capitalize()]
	draw_string(ThemeDB.fallback_font, Vector2(8.0, 17.0), title, HORIZONTAL_ALIGNMENT_LEFT, maxf(size.x - 250.0, 120.0), 16, Color(0.86, 0.75, 0.42))
	draw_string(ThemeDB.fallback_font, Vector2(size.x - 242.0, 17.0), facts, HORIZONTAL_ALIGNMENT_RIGHT, 234.0, 12, Color(0.73, 0.76, 0.80))

func _draw_terrain_cell(tile_id: int, rect: Rect2) -> void:
	var uses_landlook := tile_id <= 200 and not _upper_atlas_id.is_empty()
	var asset := _upper_atlas_asset if uses_landlook else _atlas_asset
	var texture := _upper_atlas_texture if uses_landlook else _atlas_texture
	var region := Rect2i() if asset == null else asset.region_for(tile_id)
	if texture != null and region.has_area():
		draw_texture_rect_region(texture, rect, Rect2(region))
		return
	var shade := 0.12 + float(posmod(tile_id, 7)) * 0.012
	draw_rect(rect, Color(shade, shade * 1.05, shade * 0.92), true)
	draw_rect(rect, Color(0.20, 0.22, 0.24), false, 1.0)

func set_movement_costs_visible(visible_costs: bool) -> void:
	if _movement_costs_visible == visible_costs:
		return
	_movement_costs_visible = visible_costs
	queue_redraw()

func _draw_spell_projectile(actor_rect: Rect2, target_rect: Rect2) -> void:
	if not actor_rect.has_area() or not target_rect.has_area():
		return
	var point := actor_rect.get_center().lerp(target_rect.get_center(), _playback_frame.progress)
	var region := Rect2i() if _atlas_asset == null else _atlas_asset.region_for(_playback_frame.battle_tile_id)
	if _playback_frame.battle_tile_id <= 0 or _atlas_texture == null or region.size.x <= 0 or region.size.y <= 0:
		last_playback_media_diagnostic = {"resourceType": "PICT", "resourceId": 302, "tileId": _playback_frame.battle_tile_id, "decodeResult": "unavailable", "role": "classic-combat-spell-projectile"}
		draw_circle(point, 6.0, Color(0.82, 0.72, 1.0, 0.96))
		return
	last_playback_media_diagnostic = {"resourceType": "PICT", "resourceId": 302, "tileId": _playback_frame.battle_tile_id, "assetId": _atlas_asset.id, "decodeResult": "decoded", "role": "classic-combat-spell-projectile"}
	var projectile_rect := Rect2(point - Vector2(16.0, 16.0), Vector2(32.0, 32.0))
	draw_texture_rect_region(_atlas_texture, projectile_rect, Rect2(region))

func _draw_centered_cue(text: String) -> void:
	if text.is_empty():
		return
	var cue_rect := Rect2(Vector2(size.x * 0.5 - 110.0, HEADER_HEIGHT + 8.0), Vector2(220.0, 34.0))
	draw_rect(cue_rect, Color(0.02, 0.025, 0.03, 0.86), true)
	draw_rect(cue_rect, Color(0.86, 0.72, 0.30, 0.95), false, 2.0)
	draw_string(ThemeDB.fallback_font, cue_rect.position + Vector2(4.0, 23.0), text, HORIZONTAL_ALIGNMENT_CENTER, cue_rect.size.x - 8.0, 16, Color(1.0, 0.90, 0.56))

func _submit_movement_option(option: CombatMoveOptionView) -> bool:
	if option == null or not option.enabled or _view == null or _view.combat_view == null:
		return false
	var payload := {
		"actorId": _view.combat_view.active_actor_id,
		"action": "retreat_edge" if option.retreats_from_battle else "move",
		"targetId": "",
		"destination": [option.destination.x, option.destination.y],
	}
	if option.retreats_from_battle:
		payload["forced"] = option.forced_retreat
	tactical_action_requested.emit(payload)
	return true

func _notification(what: int) -> void:
	if what == NOTIFICATION_MOUSE_EXIT and _hovered_coordinate != Vector2i(-1, -1):
		_hovered_coordinate = Vector2i(-1, -1)
		queue_redraw()

func begin_targeting(configuration: Dictionary) -> bool:
	if _playback_frame != null or _view == null or _view.combat_view == null:
		return false
	var mode := StringName(configuration.get("mode", &""))
	var response_payload: Variant = configuration.get("responsePayload", {})
	if mode not in [&"combatant", &"sequence", &"area"] or not response_payload is Dictionary:
		return false
	var state := CombatTargetingState.new(mode, response_payload)
	for value: Variant in configuration.get("candidateIds", []):
		var candidate_id := String(value)
		if not candidate_id.is_empty() and not state.candidate_ids.has(candidate_id):
			state.candidate_ids.append(candidate_id)
	for value: Variant in configuration.get("areaOffsets", []):
		var offset_coordinate := _array_coordinate(value)
		if offset_coordinate.x > -BattlefieldState.SIZE and offset_coordinate.y > -BattlefieldState.SIZE:
			state.area_offsets.append(offset_coordinate)
	for value: Variant in configuration.get("legalTargetCoordinates", []):
		var legal_coordinate := _array_coordinate(value)
		if legal_coordinate.x >= 0 and legal_coordinate.y >= 0:
			state.legal_coordinates.append(legal_coordinate)
	state.maximum_targets = maxi(1, int(configuration.get("maximumTargets", 1)))
	var default_coordinate := _array_coordinate(configuration.get("defaultTargetCoordinate", []))
	if mode == &"area" and default_coordinate.x >= 0:
		state.select_coordinate(default_coordinate)
	_targeting = state
	_reveal_friends = false
	targeting_changed.emit(_targeting.selection_data())
	queue_redraw()
	return true

func confirm_targeting() -> bool:
	if _targeting == null:
		return false
	var payload := _targeting.committed_payload()
	if payload.is_empty():
		targeting_changed.emit(_targeting.selection_data())
		return false
	_targeting = null
	queue_redraw()
	tactical_action_requested.emit(payload)
	return true

func _draw_projectile(actor_rect: Rect2, target_rect: Rect2) -> void:
	if not actor_rect.has_area() or not target_rect.has_area():
		return
	var point := actor_rect.get_center().lerp(target_rect.get_center(), _playback_frame.progress)
	draw_circle(point, 5.0, Color(1.0, 0.91, 0.55, 0.98))
	draw_circle(point, 7.0, Color(1.0, 1.0, 0.88, 0.72), false, 2.0)

func _coordinate_at_local_position(local_position: Vector2) -> Vector2i:
	var combat := _view.combat_view
	var battlefield := combat.battlefield
	var active_position := actor_position(combat, _view.party_members, combat.active_actor_id)
	if active_position.x < 0:
		active_position = battlefield.party_anchor
	var visible_cells := viewport_cells_for(size)
	var camera := camera_top_left(active_position, visible_cells)
	var draw_origin := battlefield_draw_origin(size, visible_cells)
	var relative := local_position - draw_origin
	if relative.x < 0.0 or relative.y < 0.0:
		return Vector2i(-1, -1)
	var cell := Vector2i(floori(relative.x / NATIVE_CELL_SIZE), floori(relative.y / NATIVE_CELL_SIZE))
	if cell.x < 0 or cell.y < 0 or cell.x >= visible_cells.x or cell.y >= visible_cells.y:
		return Vector2i(-1, -1)
	return camera + cell

func _movement_option_for_direction(direction: Vector2i) -> CombatMoveOptionView:
	if _view == null or _view.combat_view == null:
		return null
	for option: CombatMoveOptionView in _view.combat_view.movement_options:
		if option.direction == direction:
			return option
	return null

func _movement_option_for_destination(destination: Vector2i) -> CombatMoveOptionView:
	if _view == null or _view.combat_view == null:
		return null
	for option: CombatMoveOptionView in _view.combat_view.movement_options:
		if option.destination == destination:
			return option
	return null

func _movement_option_toward_local_position(local_position: Vector2) -> CombatMoveOptionView:
	if _view == null or _view.combat_view == null or _view.combat_view.battlefield == null:
		return null
	var origin := actor_position(_view.combat_view, _view.party_members, _view.combat_view.active_actor_id)
	var visible_cells := viewport_cells_for(size)
	var camera := camera_top_left(origin, visible_cells)
	var draw_origin := battlefield_draw_origin(size, visible_cells)
	return _movement_option_for_direction(click_direction_for_point(cell_rect(origin, camera, draw_origin), local_position))

func _draw_characters(combat: CombatView, camera: Vector2i, visible_cells: Vector2i, draw_origin: Vector2) -> void:
	var target_ids: Dictionary = {}
	for target: CharacterView in combat.character_targets:
		target_ids[target.id] = true
	for character: CharacterView in _view.party_members:
		if _playback_hides(character.id):
			continue
		var coordinate := _effective_actor_position(combat, character.id)
		if not coordinate_is_visible(coordinate, camera, visible_cells):
			continue
		var rect := _playback_actor_rect(character.id, coordinate, camera, draw_origin)
		var asset := _media.asset_by_id(character.combat_icon_id) if _media != null else null
		_draw_actor(rect, _texture_for(asset), character.name, _actor_is_highlighted(character.id, combat.active_actor_id), target_ids.has(character.id), character.traitor)

func _draw_revealed_relationships(combat: CombatView, camera: Vector2i, visible_cells: Vector2i, draw_origin: Vector2) -> void:
	if not _reveal_friends:
		return
	var origin := actor_position(combat, _view.party_members, combat.active_actor_id)
	if not coordinate_is_visible(origin, camera, visible_cells):
		return
	var start := cell_rect(origin, camera, draw_origin).get_center()
	for character: CharacterView in _view.party_members:
		var coordinate := combat.battlefield.character_position(character.id)
		if character.id == combat.active_actor_id or not coordinate_is_visible(coordinate, camera, visible_cells):
			continue
		var color := Color(0.20, 0.42, 1.0, 0.90) if character.condition_values[ConditionRules.HELPLESS] != 0 else Color(0.18, 0.90, 0.38, 0.86) if combat.friendly_actor_ids.has(character.id) else Color(0.95, 0.22, 0.18, 0.86)
		draw_line(start, cell_rect(coordinate, camera, draw_origin).get_center(), color, 2.0)
	for monster: MonsterView in combat.monsters:
		var coordinate := combat.battlefield.monster_position(monster.id)
		if not coordinate_is_visible(coordinate, camera, visible_cells):
			continue
		var color := Color(0.20, 0.42, 1.0, 0.90) if monster.helpless else Color(0.18, 0.90, 0.38, 0.86) if combat.friendly_actor_ids.has(monster.id) else Color(0.95, 0.22, 0.18, 0.86)
		draw_line(start, cell_rect(coordinate, camera, draw_origin).get_center(), color, 2.0)

func _draw_monsters(combat: CombatView, camera: Vector2i, visible_cells: Vector2i, draw_origin: Vector2) -> void:
	var target_ids: Dictionary = {}
	for target: MonsterView in combat.targets:
		target_ids[target.id] = true
	for monster: MonsterView in combat.monsters:
		if _playback_hides(monster.id):
			continue
		var footprint := combat.battlefield.monster_footprint(monster.id)
		var source_anchor := combat.battlefield.monster_position(monster.id)
		var effective_anchor := _effective_actor_position(combat, monster.id)
		if source_anchor.x >= 0 and effective_anchor.x >= 0 and source_anchor != effective_anchor:
			var offset := effective_anchor - source_anchor
			for index: int in footprint.size():
				footprint[index] += offset
		var visible_footprint: Array[Vector2i] = []
		for coordinate: Vector2i in footprint:
			if coordinate_is_visible(coordinate, camera, visible_cells):
				visible_footprint.append(coordinate)
		if visible_footprint.is_empty():
			continue
		var rect := footprint_rect(visible_footprint, camera, draw_origin)
		if _playback_frame != null and _playback_frame.actor_id == monster.id and _playback_frame.kind == &"move_start":
			rect.position = _interpolated_draw_position(_playback_frame, camera, draw_origin)
		var asset := _media.asset_by_resource(monster.icon_resource_type, monster.icon_id) if _media != null else null
		_draw_actor(rect, _texture_for(asset), monster.name, _actor_is_highlighted(monster.id, combat.active_actor_id), target_ids.has(monster.id), monster.traitor)

func _draw_targeting_preview(combat: CombatView, camera: Vector2i, visible_cells: Vector2i, draw_origin: Vector2) -> void:
	if _targeting == null:
		return
	if _targeting.mode == &"area":
		var center := _targeting.selected_coordinate if _targeting.selected_coordinate.x >= 0 else _targeting.hovered_coordinate
		if center.x < 0:
			return
		var legal := _targeting.legal_coordinates.has(center)
		var outline := Color(0.96, 0.82, 0.30, 0.96) if legal else Color(0.62, 0.64, 0.68, 0.86)
		for offset: Vector2i in _targeting.area_offsets:
			var coordinate := center + offset
			if coordinate_is_visible(coordinate, camera, visible_cells):
				draw_rect(cell_rect(coordinate, camera, draw_origin).grow(-2.0), outline, false, 2.0)
		return
	for candidate_id: String in _targeting.candidate_ids:
		var rect := _combatant_rect(combat, candidate_id, camera, visible_cells, draw_origin)
		if rect.has_area():
			draw_rect(rect.grow(2.0), Color(0.86, 0.80, 0.62, 0.78), false, 2.0)
	for index: int in _targeting.selected_ids.size():
		var selected_id := _targeting.selected_ids[index]
		var rect := _combatant_rect(combat, selected_id, camera, visible_cells, draw_origin)
		if not rect.has_area():
			continue
		draw_rect(rect.grow(4.0), Color(1.0, 0.86, 0.28, 0.98), false, 4.0)
		if _targeting.mode == &"sequence":
			draw_string(ThemeDB.fallback_font, rect.position + Vector2(4.0, 18.0), str(index + 1), HORIZONTAL_ALIGNMENT_LEFT, 24.0, 15, Color(1.0, 0.94, 0.72))

func _draw_playback_overlay(combat: CombatView, camera: Vector2i, visible_cells: Vector2i, draw_origin: Vector2) -> void:
	if _playback_frame == null:
		return
	var target_rect := _combatant_rect(combat, _playback_frame.target_id, camera, visible_cells, draw_origin)
	var actor_rect := _combatant_rect(combat, _playback_frame.actor_id, camera, visible_cells, draw_origin)
	if not target_rect.has_area() and _playback_frame.to_coordinate.x >= 0 and coordinate_is_visible(_playback_frame.to_coordinate, camera, visible_cells):
		target_rect = cell_rect(_playback_frame.to_coordinate, camera, draw_origin)
	match _playback_frame.kind:
		&"battle_cue":
			_draw_centered_cue(_playback_frame.display_text)
		&"actor_cue":
			if not target_rect.has_area():
				target_rect = actor_rect
			if target_rect.has_area():
				draw_rect(target_rect.grow(4.0), Color(1.0, 0.86, 0.28, 0.95), false, 4.0)
			if not _playback_frame.display_text.is_empty():
				_draw_centered_cue(_playback_frame.display_text)
		&"melee_attack":
			if actor_rect.has_area():
				draw_rect(actor_rect.grow(3.0), Color(1.0, 0.90, 0.58, 0.95), false, 3.0)
			if target_rect.has_area():
				draw_rect(target_rect.grow(2.0), Color(1.0, 0.96, 0.82, 0.95), false, 3.0)
		&"projectile":
			_draw_projectile(actor_rect, target_rect)
		&"spell_projectile":
			_draw_spell_projectile(actor_rect, target_rect)
		&"spell_cast", &"spell_effect":
			_draw_spell_effect(actor_rect, target_rect)
		&"result", &"defeat", &"retreat":
			_draw_result(target_rect if target_rect.has_area() else actor_rect)

func _handle_targeting_input(event: InputEvent) -> void:
	if event is InputEventMouseMotion:
		_targeting.hovered_coordinate = _coordinate_at_local_position((event as InputEventMouseMotion).position)
		queue_redraw()
		return
	if not event is InputEventMouseButton or not (event as InputEventMouseButton).pressed:
		return
	if (event as InputEventMouseButton).button_index == MOUSE_BUTTON_RIGHT:
		cancel_targeting()
		accept_event()
		return
	if (event as InputEventMouseButton).button_index != MOUSE_BUTTON_LEFT:
		return
	var coordinate := _coordinate_at_local_position((event as InputEventMouseButton).position)
	if coordinate.x < 0:
		return
	if _targeting.mode == &"area":
		_targeting.select_coordinate(coordinate)
	else:
		var combatant_id := combatant_at(_view.combat_view, _view.party_members, coordinate)
		_targeting.select_combatant(combatant_id)
	targeting_changed.emit(_targeting.selection_data())
	queue_redraw()
	accept_event()

func present_step(step: SessionStep) -> void:
	if step == null:
		return
	if step.state == SessionStep.State.FAILED:
		set_status("Action failed • %s" % step.error_message, true)
		_append_narrative("Action failed: %s" % step.error_message)
		return
	_picture_stage.visible = false
	for event: DomainEvent in step.events:
		_present_event(event)

func _interpolated_draw_position(frame: CombatPlaybackFrame, camera: Vector2i, draw_origin: Vector2) -> Vector2:
	var from_position := draw_origin + Vector2(frame.from_coordinate - camera) * NATIVE_CELL_SIZE
	var to_position := draw_origin + Vector2(frame.to_coordinate - camera) * NATIVE_CELL_SIZE
	return from_position.lerp(to_position, frame.progress)

func _combatant_rect(combat: CombatView, actor_id: String, camera: Vector2i, visible_cells: Vector2i, draw_origin: Vector2) -> Rect2:
	if actor_id.is_empty() or _playback_hides(actor_id):
		return Rect2()
	var coordinate := _effective_actor_position(combat, actor_id)
	if not coordinate_is_visible(coordinate, camera, visible_cells):
		return Rect2()
	for monster: MonsterView in combat.monsters:
		if monster.id != actor_id:
			continue
		var footprint := combat.battlefield.monster_footprint(actor_id)
		var source_anchor := combat.battlefield.monster_position(actor_id)
		var offset := coordinate - source_anchor
		for index: int in footprint.size():
			footprint[index] += offset
		return footprint_rect(footprint, camera, draw_origin)
	return _playback_actor_rect(actor_id, coordinate, camera, draw_origin)

func _draw_actor(rect: Rect2, texture: Texture2D, label: String, active: bool, target: bool, hostile: bool) -> void:
	if texture != null:
		draw_texture_rect(texture, rect, false)
	else:
		draw_rect(rect.grow(-3.0), Color(0.62, 0.20, 0.18) if hostile else Color(0.18, 0.42, 0.64), true)
		draw_string(ThemeDB.fallback_font, rect.position + Vector2(5.0, 20.0), label.left(2).to_upper(), HORIZONTAL_ALIGNMENT_LEFT, -1.0, 12, Color.WHITE)
	if target:
		draw_rect(rect.grow(-1.0), Color(0.95, 0.35, 0.26), false, 3.0)
	if active:
		draw_rect(rect.grow(2.0), Color(0.98, 0.82, 0.25), false, 3.0)

func _texture_for(asset: PackageMediaAsset) -> Texture2D:
	if asset == null:
		return null
	if _actor_textures.has(asset.id):
		return _actor_textures[asset.id] as Texture2D
	var texture := _load_image_texture(asset)
	_actor_textures[asset.id] = texture
	return texture

func _load_image_texture(asset: PackageMediaAsset) -> Texture2D:
	if asset == null or _media == null:
		return null
	var bytes := _media.read_bytes(asset)
	if bytes.is_empty():
		return null
	var image := Image.new()
	var error := ERR_FILE_UNRECOGNIZED
	match asset.mime_type:
		"image/png":
			error = image.load_png_from_buffer(bytes)
		"image/jpeg":
			error = image.load_jpg_from_buffer(bytes)
		"image/webp":
			error = image.load_webp_from_buffer(bytes)
	if error != OK:
		return null
	if asset.width > 0 and asset.height > 0 and (image.get_width() != asset.width or image.get_height() != asset.height):
		return null
	return ImageTexture.create_from_image(image)

static func actor_position(combat: CombatView, party_members: Array[CharacterView], actor_id: String) -> Vector2i:
	if combat == null or combat.battlefield == null or actor_id.is_empty():
		return Vector2i(-1, -1)
	for character: CharacterView in party_members:
		if character.id == actor_id:
			return combat.battlefield.character_position(actor_id)
	return combat.battlefield.monster_position(actor_id)

static func actor_name(combat: CombatView, party_members: Array[CharacterView], actor_id: String) -> String:
	for character: CharacterView in party_members:
		if character.id == actor_id:
			return character.name
	if combat != null:
		for monster: MonsterView in combat.monsters:
			if monster.id == actor_id:
				return monster.name
	return actor_id if not actor_id.is_empty() else "Waiting"

static func combatant_at(combat: CombatView, party_members: Array[CharacterView], coordinate: Vector2i) -> String:
	if combat == null or combat.battlefield == null:
		return ""
	for character: CharacterView in party_members:
		if combat.battlefield.character_position(character.id) == coordinate:
			return character.id
	for monster: MonsterView in combat.monsters:
		if combat.battlefield.monster_footprint(monster.id).has(coordinate):
			return monster.id
	return ""

static func click_direction(origin: Vector2i, destination: Vector2i) -> Vector2i:
	var offset := destination - origin
	return Vector2i(signi(offset.x), signi(offset.y))

static func click_direction_for_point(active_cell: Rect2, point: Vector2) -> Vector2i:
	var direction := Vector2i.ZERO
	if point.x < active_cell.position.x:
		direction.x = -1
	elif point.x > active_cell.end.x:
		direction.x = 1
	if point.y < active_cell.position.y:
		direction.y = -1
	elif point.y > active_cell.end.y:
		direction.y = 1
	return direction

static func _array_coordinate(value: Variant) -> Vector2i:
	if value is Vector2i:
		return value
	if value is Array and value.size() == 2:
		return Vector2i(int(value[0]), int(value[1]))
	return Vector2i(-100_000, -100_000)

static func viewport_cells_for(control_size: Vector2) -> Vector2i:
	return Vector2i(
		mini(MAX_VISIBLE_COLUMNS, maxi(1, floori(control_size.x / NATIVE_CELL_SIZE))),
		mini(MAX_VISIBLE_ROWS, maxi(1, floori((control_size.y - HEADER_HEIGHT) / NATIVE_CELL_SIZE)))
	)

static func camera_top_left(active_position: Vector2i, visible_cells: Vector2i) -> Vector2i:
	var maximum := Vector2i(BattlefieldState.SIZE, BattlefieldState.SIZE) - visible_cells
	return Vector2i(
		clampi(active_position.x - floori(float(visible_cells.x) / 2.0), 0, maximum.x),
		clampi(active_position.y - floori(float(visible_cells.y) / 2.0), 0, maximum.y)
	)

static func battlefield_draw_origin(control_size: Vector2, visible_cells: Vector2i) -> Vector2:
	var pixel_size := Vector2(visible_cells) * NATIVE_CELL_SIZE
	return Vector2(
		floorf((control_size.x - pixel_size.x) * 0.5),
		HEADER_HEIGHT + floorf(maxf(control_size.y - HEADER_HEIGHT - pixel_size.y, 0.0) * 0.5)
	)

func configure(definition: Dictionary, art_scale: int = 1) -> void:
	command_id = StringName(definition.get("id", &""))
	var asset_id := StringName(definition.get("asset_id", &""))
	texture_normal = ClassicUiAssetCatalog.texture(asset_id)
	_native_size = ClassicUiAssetCatalog.native_size(asset_id)
	if _native_size.x <= 0 or _native_size.y <= 0:
		_native_size = Vector2i(50, 50)
	tooltip_text = String(definition.get("tooltip", ""))
	var accelerator := String(definition.get("accelerator", ""))
	if not accelerator.is_empty():
		tooltip_text += " [%s]" % accelerator
	set_art_scale(art_scale)

func _draw() -> void:
	var rect := Rect2(Vector2(1.0, 1.0), size - Vector2(2.0, 2.0))
	if disabled:
		draw_rect(rect, DISABLED_OVERLAY, true)
	if button_pressed:
		draw_rect(rect.grow(-1.0), Color(0.95, 0.76, 0.24, 0.18), true)
	if has_focus():
		draw_rect(rect, FOCUS_COLOR, false, 2.0)
	elif is_hovered() and not disabled:
		draw_rect(rect, HOVER_COLOR, false, 1.0)

static func command(command_id: StringName) -> Dictionary:
	for definition: Dictionary in COMMANDS:
		if definition["id"] == command_id:
			return definition
	return {}

func _process(delta: float) -> void:
	if _held_direction == Vector2i.ZERO or not visible:
		return
	_mouse_repeat_remaining -= delta
	if _mouse_repeat_remaining <= 0.0:
		movement_requested.emit(_held_direction)
		_mouse_repeat_remaining = MOUSE_REPEAT_INTERVAL

func _init(package_catalog: PackageMediaCatalog, application_catalog: ApplicationMediaCatalog) -> void:
	package_media = package_catalog
	application_media = application_catalog

func _gui_input(event: InputEvent) -> void:
	if event is InputEventMouseButton and event.button_index == MOUSE_BUTTON_LEFT:
		if event.pressed:
			_held_direction = _movement_direction_at(event.position)
			if _held_direction != Vector2i.ZERO:
				movement_requested.emit(_held_direction)
				_mouse_repeat_remaining = MOUSE_REPEAT_DELAY
				accept_event()
		else:
			_held_direction = Vector2i.ZERO
			_mouse_repeat_remaining = 0.0
	elif event is InputEventMouseMotion and event.button_mask & MOUSE_BUTTON_MASK_LEFT:
		_held_direction = _movement_direction_at(event.position)

func present(game_view: GameView) -> void:
	_view = game_view
	visible = game_view != null and game_view.session_started and game_view.map_view != null
	if not visible:
		_held_direction = Vector2i.ZERO
	queue_redraw()

func set_media_catalog(media: ClassicMediaCatalog) -> void:
	_media = media
	_atlas_assets.clear()
	_atlas_textures.clear()
	_overlay_textures.clear()
	if _media == null:
		queue_redraw()
		return
	for asset: PackageMediaAsset in _media.assets():
		if not asset.is_tileset() and not asset.is_picture():
			continue
		var texture := _load_image_texture(asset)
		if texture == null:
			continue
		if asset.is_tileset():
			_atlas_assets[asset.id] = asset
			_atlas_textures[asset.id] = texture
		else:
			_overlay_textures[asset.id] = texture
	queue_redraw()

func _draw() -> void:
	if _view == null or _view.map_view == null:
		return
	var map_view := _view.map_view
	var font := ThemeDB.fallback_font
	var viewport_cells := viewport_cells_for(size, map_origin.y, cell_size)
	var draw_origin := map_draw_origin_for(size, map_origin, cell_size, viewport_cells)
	var camera := camera_top_left(map_view.party_coordinate, Vector2i(map_view.width, map_view.height), viewport_cells)
	var camera_end := camera + viewport_cells
	for cell: MapCellView in map_view.cells():
		if cell.coordinate.x < camera.x or cell.coordinate.y < camera.y or cell.coordinate.x >= camera_end.x or cell.coordinate.y >= camera_end.y:
			continue
		var rect := Rect2(draw_origin + Vector2(cell.coordinate - camera) * cell_size, Vector2.ONE * cell_size)
		_draw_cell(cell, rect, map_view.level_type, map_view.dark)
		if show_debug_facts:
			draw_rect(rect, Color(0.22, 0.25, 0.30), false, 1.0)
			_draw_edges(cell, rect)
			_draw_features(cell, rect)
			if cell.has_trigger:
				var center := rect.get_center()
				draw_colored_polygon(PackedVector2Array([center + Vector2(0, -6), center + Vector2(6, 0), center + Vector2(0, 6), center + Vector2(-6, 0)]), Color(0.95, 0.72, 0.26))
			if cell.in_random_region:
				draw_rect(rect.grow(-4.0), Color(0.48, 0.29, 0.58, 0.9), false, 2.0)
			var facts := "%s%s%s" % ["M" if cell.passable else "X", "L" if cell.blocks_los else "", "R" if cell.in_random_region else ""]
			draw_string(font, rect.position + Vector2(7, 17), facts, HORIZONTAL_ALIGNMENT_LEFT, -1, 12, Color(0.78, 0.82, 0.88))
	_party_rect = Rect2(draw_origin + Vector2(map_view.party_coordinate - camera) * cell_size, Vector2.ONE * cell_size)
	_draw_party_marker(_party_rect)
	draw_string(font, Vector2(8.0, 17.0), "%s • %s" % [map_view.map_name, String(map_view.level_type)], HORIZONTAL_ALIGNMENT_LEFT, -1, 16, Color(0.86, 0.75, 0.42))
	var input_hint := "Click map • numpad / arrows / WASD" if map_view.level_type == &"land" else "Click map • arrows / WASD"
	draw_string(font, Vector2(size.x - 258.0, 17.0), input_hint, HORIZONTAL_ALIGNMENT_RIGHT, 250.0, 12, Color(0.66, 0.69, 0.73))
	_draw_minimap(map_view, font)

func _draw_party_marker(party_rect: Rect2) -> void:
	if _party_marker_texture != null:
		draw_texture_rect(_party_marker_texture, party_rect, false)
		return
	draw_circle(party_rect.get_center(), 10.0, Color(0.92, 0.78, 0.34))
	draw_circle(party_rect.get_center(), 5.0, Color(0.17, 0.12, 0.06))

static func camera_top_left(party_coordinate: Vector2i, map_size: Vector2i, viewport_cells: Vector2i) -> Vector2i:
	var maximum := Vector2i(maxi(map_size.x - viewport_cells.x, 0), maxi(map_size.y - viewport_cells.y, 0))
	return Vector2i(
		clampi(party_coordinate.x - viewport_cells.x / 2, 0, maximum.x),
		clampi(party_coordinate.y - viewport_cells.y / 2, 0, maximum.y)
	)

static func viewport_cells_for(control_size: Vector2, header_height: float, native_cell_size: float) -> Vector2i:
	return Vector2i(
		mini(DETACHED_VIEW_DIAMETER, maxi(1, floori(control_size.x / native_cell_size))),
		mini(DETACHED_VIEW_DIAMETER, maxi(1, floori((control_size.y - header_height) / native_cell_size)))
	)

static func map_draw_origin_for(control_size: Vector2, minimum_origin: Vector2, native_cell_size: float, viewport_cells: Vector2i) -> Vector2:
	var map_pixel_size := Vector2(viewport_cells) * native_cell_size
	var available_height := maxf(control_size.y - minimum_origin.y, 0.0)
	return Vector2(
		maxf(minimum_origin.x, floorf((control_size.x - map_pixel_size.x) * 0.5)),
		minimum_origin.y + maxf(0.0, floorf((available_height - map_pixel_size.y) * 0.5))
	)

func assets() -> Array[PackageMediaAsset]:
	var result: Array[PackageMediaAsset] = []
	var occupied_resource_keys: Dictionary = {}
	if package_media != null:
		for asset: PackageMediaAsset in package_media.assets():
			result.append(asset)
			if not asset.resource_type.is_empty():
				occupied_resource_keys[_resource_key(asset.resource_type, asset.resource_id)] = true
	if application_media != null:
		for asset: PackageMediaAsset in application_media.assets():
			if not occupied_resource_keys.has(_resource_key(asset.resource_type, asset.resource_id)):
				result.append(asset)
	return result

func _draw_cell(cell: MapCellView, rect: Rect2, level_type: StringName, dark: bool) -> void:
	if not cell.visible:
		draw_rect(rect, _cell_color(cell, level_type, dark), true)
		return
	var atlas_asset: PackageMediaAsset = _atlas_assets.get(cell.tileset_id) as PackageMediaAsset
	var atlas_texture: Texture2D = _atlas_textures.get(cell.tileset_id) as Texture2D
	if level_type == &"dungeon" and atlas_asset != null and atlas_texture != null and atlas_asset.id == "dungeon-top-down-302":
		_draw_dungeon_atlas_cell(cell, rect, atlas_asset, atlas_texture)
		if dark:
			draw_rect(rect, Color(0.0, 0.0, 0.0, 0.45), true)
		return
	var region := Rect2i() if atlas_asset == null else atlas_asset.region_for(cell.render_tile)
	if atlas_texture == null or not region.has_area():
		draw_rect(rect, _cell_color(cell, level_type, false), true)
	else:
		draw_texture_rect_region(atlas_texture, rect, Rect2(region))
	var overlay_texture: Texture2D = _overlay_textures.get(cell.overlay_asset_id) as Texture2D
	if overlay_texture != null:
		draw_texture_rect(overlay_texture, rect, false)
	if dark:
		draw_rect(rect, Color(0.0, 0.0, 0.0, 0.45), true)

func _draw_atlas_region(rect: Rect2, atlas_asset: PackageMediaAsset, atlas_texture: Texture2D, tile_id: int) -> void:
	var region := atlas_asset.region_for(tile_id)
	if region.has_area():
		draw_texture_rect_region(atlas_texture, rect, Rect2(region))

func _load_image_texture(asset: PackageMediaAsset) -> Texture2D:
	var bytes := _media.read_bytes(asset)
	if bytes.is_empty():
		return null
	var image := Image.new()
	var load_error := ERR_FILE_UNRECOGNIZED
	match asset.mime_type:
		"image/png":
			load_error = image.load_png_from_buffer(bytes)
		"image/jpeg":
			load_error = image.load_jpg_from_buffer(bytes)
		"image/webp":
			load_error = image.load_webp_from_buffer(bytes)
	if load_error != OK:
		return null
	if asset.width > 0 and asset.height > 0 and (image.get_width() != asset.width or image.get_height() != asset.height):
		return null
	return ImageTexture.create_from_image(image)

func _cell_color(cell: MapCellView, level_type: StringName, dark: bool = false) -> Color:
	var color: Color
	if not cell.visible:
		color = Color(0.025, 0.03, 0.04)
	elif not cell.passable:
		color = Color(0.16, 0.17, 0.20)
	elif cell.terrain_id.ends_with(".2"):
		color = Color(0.34, 0.50, 0.31)
	elif level_type == &"dungeon":
		color = Color(0.28, 0.27, 0.24)
	else:
		color = Color(0.20, 0.38, 0.27)
	return color.darkened(0.45) if dark else color

func _draw_edges(cell: MapCellView, rect: Rect2) -> void:
	var edge_points := {
		&"north": [rect.position, rect.position + Vector2(rect.size.x, 0)],
		&"east": [rect.position + Vector2(rect.size.x, 0), rect.end],
		&"south": [rect.position + Vector2(0, rect.size.y), rect.end],
		&"west": [rect.position, rect.position + Vector2(0, rect.size.y)],
	}
	for direction: StringName in edge_points:
		var kind := cell.edge_kind(direction)
		if kind == &"open":
			continue
		var points: Array = edge_points[direction]
		var color := Color(0.84, 0.75, 0.52) if kind == &"door" else Color(0.64, 0.40, 0.72) if kind == &"secret" else Color(0.62, 0.65, 0.70)
		draw_line(points[0], points[1], color, 4.0 if cell.edge_is_passable(direction) else 7.0)

func _draw_features(cell: MapCellView, rect: Rect2) -> void:
	var center := rect.get_center()
	if cell.has_feature(&"door"):
		draw_line(center + Vector2(-13, 0), center + Vector2(13, 0), Color(0.84, 0.63, 0.30), 5.0)
	if cell.has_feature(&"secret"):
		draw_string(ThemeDB.fallback_font, center + Vector2(-5, 6), "S", HORIZONTAL_ALIGNMENT_LEFT, -1, 18, Color(0.71, 0.46, 0.82))
	if cell.has_feature(&"stairs"):
		for offset: int in [-8, 0, 8]:
			draw_line(center + Vector2(-12, offset), center + Vector2(12, offset), Color(0.72, 0.72, 0.68), 2.0)
	if cell.has_feature(&"column"):
		draw_circle(center, 10.0, Color(0.64, 0.64, 0.62))

func _draw_minimap(map_view: MapView, font: Font) -> void:
	var scale := minf(minimap_size / float(map_view.width), minimap_size / float(map_view.height))
	var map_pixel_size := Vector2(map_view.width, map_view.height) * scale
	var origin := Vector2(size.x - map_pixel_size.x - 8.0, size.y - map_pixel_size.y - 8.0)
	_minimap_rect = Rect2(origin - Vector2.ONE * 4.0, map_pixel_size + Vector2.ONE * 8.0)
	draw_rect(_minimap_rect, Color(0.035, 0.04, 0.05, 0.9), true)
	draw_string(font, origin - Vector2(0, 7), "Map", HORIZONTAL_ALIGNMENT_LEFT, -1, 11, Color(0.72, 0.76, 0.82))
	for coordinate: Vector2i in map_view.visited_coordinates():
		var rect := Rect2(origin + Vector2(coordinate) * scale, Vector2.ONE * maxf(scale, 1.0))
		draw_rect(rect, Color(0.28, 0.48, 0.32), true)
	var party_center := origin + (Vector2(map_view.party_coordinate) + Vector2.ONE * 0.5) * scale
	draw_circle(party_center, maxf(2.0, scale * 1.5), Color(0.94, 0.78, 0.28))

func _movement_direction_at(position: Vector2) -> Vector2i:
	if _party_rect.size == Vector2.ZERO or _minimap_rect.has_point(position):
		return Vector2i.ZERO
	if _view != null and _view.map_view != null and _view.map_view.level_type == &"land":
		return land_direction_at(position, _party_rect)
	var offset := position - _party_rect.get_center()
	if absf(offset.x) < cell_size * 0.35 and absf(offset.y) < cell_size * 0.35:
		return Vector2i.ZERO
	if absf(offset.x) > absf(offset.y):
		return Vector2i.RIGHT if offset.x > 0.0 else Vector2i.LEFT
	return Vector2i.DOWN if offset.y > 0.0 else Vector2i.UP

func _draw_dungeon_atlas_cell(cell: MapCellView, rect: Rect2, atlas_asset: PackageMediaAsset, atlas_texture: Texture2D) -> void:
	_draw_atlas_region(rect, atlas_asset, atlas_texture, 16)
	if cell.terrain_id == "classic.dungeon.wall":
		_draw_atlas_region(rect, atlas_asset, atlas_texture, 1)
	if cell.has_feature(&"door"):
		_draw_atlas_region(rect, atlas_asset, atlas_texture, 3 if cell.feature_orientation(&"door") == &"vertical" else 2)
	var feature_tiles: Dictionary = {
		&"stairs": 4,
		&"column": 5,
		&"note": 6,
		&"secret": 7,
	}
	for feature_kind: StringName in feature_tiles:
		if cell.has_feature(feature_kind):
			_draw_atlas_region(rect, atlas_asset, atlas_texture, int(feature_tiles[feature_kind]))

func asset_by_id(asset_id: String) -> PackageMediaAsset:
	var package_asset := package_media.asset_by_id(asset_id) if package_media != null else null
	if package_asset != null:
		return package_asset
	return application_media.asset_by_id(asset_id) if application_media != null else null

func assets_of_kind(kind: String) -> Array[PackageMediaAsset]:
	var result: Array[PackageMediaAsset] = []
	for asset: PackageMediaAsset in assets():
		if asset.kind == kind:
			result.append(asset)
	result.sort_custom(func(left: PackageMediaAsset, right: PackageMediaAsset) -> bool: return left.resource_id < right.resource_id)
	return result

func asset_by_resource(resource_type: String, resource_id: int) -> PackageMediaAsset:
	if package_media != null:
		var package_status := package_media.resource_status(resource_type, resource_id)
		if package_status == &"ambiguous":
			return null
		if package_status == &"resolved":
			return package_media.asset_by_resource(resource_type, resource_id)
	return application_media.asset_by_resource(resource_type, resource_id) if application_media != null else null

func tileset_by_id(tileset_id: String) -> PackageMediaAsset:
	var asset := asset_by_id(tileset_id)
	return asset if asset != null and asset.is_tileset() else null

func battle_tileset() -> PackageMediaAsset:
	var asset := asset_by_id("classic-battle-tiles-302")
	return asset if asset != null and asset.is_battle_tileset() else null

func read_bytes(asset: PackageMediaAsset) -> PackedByteArray:
	if package_media != null and package_media.owns_asset(asset):
		return package_media.read_bytes(asset)
	if application_media != null and application_media.owns_asset(asset):
		return application_media.read_bytes(asset)
	return PackedByteArray()

func read_bytes_batch(requested_assets: Array[PackageMediaAsset]) -> Dictionary:
	var result: Dictionary = {}
	var package_assets: Array[PackageMediaAsset] = []
	for asset: PackageMediaAsset in requested_assets:
		if package_media != null and package_media.owns_asset(asset):
			package_assets.append(asset)
		elif application_media != null and application_media.owns_asset(asset):
			var bytes := application_media.read_bytes(asset)
			if not bytes.is_empty():
				result[asset.id] = bytes
	if package_media != null:
		result.merge(package_media.read_bytes_batch(package_assets), true)
	return result

func audio_stream_by_resource(resource_type: String, resource_id: int) -> AudioStream:
	var asset := asset_by_resource(resource_type, resource_id)
	if asset == null:
		return null
	if application_media != null and application_media.owns_asset(asset):
		return application_media.audio_stream(asset)
	return _decode_stream(asset, package_media.read_bytes(asset)) if package_media != null else null

static func _decode_stream(asset: PackageMediaAsset, bytes: PackedByteArray) -> AudioStream:
	if bytes.is_empty():
		return null
	var mime := asset.mime_type.to_lower()
	var extension := asset.path.get_extension().to_lower()
	if mime == "audio/wav" or mime == "audio/x-wav" or extension == "wav":
		return AudioStreamWAV.load_from_buffer(bytes)
	if mime in ["audio/mpeg", "audio/mp3"] or extension == "mp3":
		return AudioStreamMP3.load_from_buffer(bytes)
	if mime in ["audio/ogg", "audio/vorbis"] or extension == "ogg":
		return AudioStreamOggVorbis.load_from_buffer(bytes)
	return null

func _effective_actor_position(combat: CombatView, actor_id: String) -> Vector2i:
	if _playback_frame != null:
		var playback_position := _playback_frame.position_for(actor_id)
		if playback_position.x >= 0:
			return playback_position
	return actor_position(combat, _view.party_members, actor_id)

func _playback_actor_rect(actor_id: String, coordinate: Vector2i, camera: Vector2i, draw_origin: Vector2) -> Rect2:
	var rect := cell_rect(coordinate, camera, draw_origin)
	if _playback_frame != null and _playback_frame.actor_id == actor_id and _playback_frame.kind == &"move_start":
		rect.position = _interpolated_draw_position(_playback_frame, camera, draw_origin)
	return rect

func build(request: InteractionRequest) -> void:
	var identity := Label.new()
	identity.text = "%s • %s" % [request.payload.get("characterName", "Character"), request.payload.get("raceName", "Unknown race")]
	identity.theme_type_variation = &"ClassicHeading"
	add_child(identity)

	var age_group := String(request.payload.get("ageGroupName", "Unknown"))
	var minimum_years := int(request.payload.get("ageMinimumYears", 0))
	var maximum_years := int(request.payload.get("ageMaximumYears", 0))
	add_hint("%s • ages %d–%d" % [age_group, minimum_years, maximum_years])

	var changes: Variant = request.payload.get("changes", [])
	var grid := GridContainer.new()
	grid.columns = 2
	grid.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	add_child(grid)
	if changes is Array:
		for index: int in mini(changes.size(), CHANGE_LABELS.size()):
			var amount := int(changes[index])
			if amount == 0:
				continue
			var label := Label.new()
			label.text = CHANGE_LABELS[index]
			label.size_flags_horizontal = Control.SIZE_EXPAND_FILL
			grid.add_child(label)
			var value := Label.new()
			value.text = "%+d" % amount
			value.horizontal_alignment = HORIZONTAL_ALIGNMENT_RIGHT
			value.add_theme_color_override("font_color", Color("7bdc8b") if amount > 0 else Color("e58a8a"))
			grid.add_child(value)
	if grid.get_child_count() == 0:
		add_hint("This transition changes no listed statistics.")
	add_response("Continue", {})

func _creator_back() -> void:
	if _creator_step <= 0:
		return
	if _creator_step == 3 and _view != null and _view.character_draft != null:
		_creator_step = 2
		intent_submitted.emit(PlayerIntent.cancel_character_draft())
		return
	_creator_step -= 1
	_setup_message.text = _creator_step_message()
	_render_creator_step()

func _cancel_creator() -> void:
	var had_generated_draft := _view != null and _view.character_draft != null
	_reset_creator(true)
	if had_generated_draft:
		intent_submitted.emit(PlayerIntent.cancel_character_draft())
	else:
		_render_creator_step()

func _reroll_character() -> void:
	if _creator_step != 3 or _view == null or _view.character_draft == null:
		return
	_awaiting_draft_generation = true
	intent_submitted.emit(PlayerIntent.generate_character_draft(_character_creation_spec()))

func _draft_spell_selection_changed(_index: int, _selected: bool) -> void:
	if _spell_list == null:
		return
