func _add_item_intent_action(parent: Container, asset_id: StringName, label: String, availability: ActionAvailabilityView, intent: PlayerIntent) -> BaseButton:
	var button: BaseButton
	if ClassicUiAssetCatalog.definition(asset_id).is_empty():
		var text_button := Button.new()
		text_button.text = label
		text_button.custom_minimum_size = Vector2(64.0, 56.0)
		button = text_button
	else:
		button = _bitmap_button(asset_id, label)
	button.disabled = availability == null or not availability.enabled
	button.tooltip_text = "Unavailable" if availability == null else availability.reason if not availability.enabled else label
	if not button.disabled:
		if button is ClassicBitmapButton:
			(button as ClassicBitmapButton).command_requested.connect(func(_command_id: StringName) -> void: intent_submitted.emit(intent))
		else:
			button.pressed.connect(func() -> void: intent_submitted.emit(intent))
	parent.add_child(button)
	return button

func _apply_availability(button: BaseButton, action_id: StringName) -> void:
	var availability := _view.availability(action_id) if _view != null else ActionAvailabilityView.new(action_id, false, "No active session.")
	button.disabled = not availability.enabled
	button.tooltip_text = availability.reason if not availability.enabled else ""

func _add_setting_toggle(label: String, enabled: bool, setting_id: StringName) -> void:
	var toggle := CheckButton.new()
	toggle.text = label
	toggle.button_pressed = enabled
	toggle.toggled.connect(func(value: bool) -> void: presentation_setting_changed.emit(setting_id, value))
	_body.add_child(toggle)

func _apply_classic_region() -> void:
	if not is_inside_tree():
		return
	set_anchors_preset(Control.PRESET_TOP_LEFT)
	if _playback_masked:
		theme_type_variation = &"ClassicOpenRight"
		position = _combat_rect.position
		size = _combat_rect.size
	elif uses_textbox_region(_request, _passive_text):
		theme_type_variation = &"ClassicOpenRight"
		var region := interaction_region(_request, _textbox_rect, _stage_rect, _combat_rect)
		position = region.position
		size = region.size
	elif uses_full_stage_region(_request):
		theme_type_variation = &"ClassicInset"
		position = _stage_rect.position
		size = _stage_rect.size
	else:
		theme_type_variation = &"ClassicInset"
		var desired := Vector2(minf(700.0, _stage_rect.size.x - 20.0), minf(520.0, _stage_rect.size.y - 20.0))
		desired.x = maxf(300.0, desired.x)
		desired.y = maxf(260.0, desired.y)
		position = _stage_rect.position + (_stage_rect.size - desired) * 0.5
		size = desired

static func definition(asset_id: StringName) -> Dictionary:
	_ensure_loaded()
	return _definitions.get(String(asset_id), {})

static func texture(asset_id: StringName) -> Texture2D:
	var record := ClassicUiAssetCatalog.definition(asset_id)
	if record.is_empty():
		return null
	return load(String(record.get("path", ""))) as Texture2D

static func native_size(asset_id: StringName) -> Vector2i:
	var record := ClassicUiAssetCatalog.definition(asset_id)
	return Vector2i(int(record.get("native_width", 0)), int(record.get("native_height", 0)))

static func _ensure_loaded() -> void:
	if not _definitions.is_empty():
		return
	var parsed: Variant = JSON.parse_string(FileAccess.get_file_as_string(MANIFEST_PATH))
	if not parsed is Dictionary:
		push_error("Classic UI asset manifest is unavailable or malformed.")
		return
	for value: Variant in (parsed as Dictionary).get("assets", []):
		if value is Dictionary:
			var record := value as Dictionary
			_definitions[String(record.get("id", ""))] = record

func _display_screen_label(screen_id: StringName) -> String:
	var definition := _screen_definition(screen_id)
	if not definition.is_empty():
		return String(definition["label"])
	return "Realmz"

func _assign_focus_keys(parent: Node, next_index: int = 0) -> int:
	for child: Node in parent.get_children():
		if child is Control and (child as Control).focus_mode != Control.FOCUS_NONE:
			if not child.has_meta("focus_key"):
				child.set_meta("focus_key", "%s:%d" % [_screen_id, next_index])
			next_index += 1
		next_index = _assign_focus_keys(child, next_index)
	return next_index

func _new_frame(kind: StringName, duration: float, positions: Dictionary, hidden: Array[String]) -> CombatPlaybackFrame:
	var frame := CombatPlaybackFrame.new(kind, duration)
	frame.combatant_positions = positions.duplicate(true)
	frame.hidden_combatant_ids = hidden.duplicate()
	return frame

func _append_next_actor_cue() -> void:
	if final_view == null or final_view.combat_view == null or final_view.combat_view.outcome != &"active":
		return
	var prior_actor := previous_view.combat_view.active_actor_id if previous_view != null and previous_view.combat_view != null else ""
	var next_actor := final_view.combat_view.active_actor_id
	var prior_round := previous_view.combat_view.round_number if previous_view != null and previous_view.combat_view != null else -1
	if next_actor == prior_actor and final_view.combat_view.round_number == prior_round:
		return
	var positions := _positions_for(final_view)
	var cue := _new_frame(&"actor_cue", CUE_SECONDS, positions, [])
	cue.actor_id = next_actor
	cue.target_id = next_actor
	cue.display_text = "Round %d" % final_view.combat_view.round_number if final_view.combat_view.round_number != prior_round else ""
	_frames.append(cue)

func begin(previous: GameView, events: Array[DomainEvent], final: GameView, reduced_motion: bool) -> bool:
	reset()
	previous_view = previous
	final_view = final
	base_view = _choose_base_view(previous, final)
	if base_view == null or not _has_playback_event(events):
		return false
	if reduced_motion:
		for event: DomainEvent in events:
			if event.kind == &"sound_requested":
				var sound_frame := CombatPlaybackFrame.new(&"sound", SOUND_FRAME_SECONDS)
				sound_frame.sound_event = event
				_frames.append(sound_frame)
		_frames.append(CombatPlaybackFrame.new(&"settle", 0.0))
	else:
		_build_frames(events)
		_append_next_actor_cue()
	if _frames.is_empty():
		return false
	_active = true
	_frame_index = 0
	return true

func current_frame() -> CombatPlaybackFrame:
	if not _active or _frame_index < 0 or _frame_index >= _frames.size():
		return null
	return _frames[_frame_index]

func advance(delta_seconds: float, sound_is_blocking: bool = false) -> void:
	if not _active:
		return
	var frame := current_frame()
	if frame == null:
		_finish()
		return
	if sound_is_blocking and not _frame_started:
		return
	if not _frame_started:
		_frame_started = true
		frame.progress = 0.0
		frame_changed.emit(frame)
		if frame.sound_event != null:
			sound_requested.emit(frame.sound_event)
	if sound_is_blocking:
		return
	_elapsed_seconds += maxf(delta_seconds, 0.0)
	frame.progress = 1.0 if frame.duration_seconds <= 0.0 else clampf(_elapsed_seconds / frame.duration_seconds, 0.0, 1.0)
	frame_changed.emit(frame)
	if _elapsed_seconds < frame.duration_seconds:
		return
	_frame_index += 1
	_elapsed_seconds = 0.0
	_frame_started = false
	if _frame_index >= _frames.size():
		_finish()

func skip() -> bool:
	if not _active:
		return false
	var first_unplayed := _frame_index + 1 if _frame_started else _frame_index
	for index: int in range(maxi(first_unplayed, 0), _frames.size()):
		var frame := _frames[index]
		if frame.sound_event != null:
			sound_requested.emit(frame.sound_event)
	_finish()
	return true

func _finish() -> void:
	_active = false
	playback_finished.emit()

func _choose_base_view(previous: GameView, final: GameView) -> GameView:
	if previous != null and previous.combat_view != null and previous.combat_view.battlefield != null:
		return previous
	if final != null and final.combat_view != null and final.combat_view.battlefield != null:
		return final
	return null

func _store_focus() -> void:
	var owner := get_viewport().gui_get_focus_owner()
	if owner != null and is_ancestor_of(owner) and owner.has_meta("focus_key"):
		_focus_keys[_screen_id] = String(owner.get_meta("focus_key"))

func _restore_focus(reset_scroll_to_top: bool = false, previous_scroll_horizontal: int = 0, previous_scroll_vertical: int = 0) -> void:
	var wanted := String(_focus_keys.get(_screen_id, ""))
	var restored := false
	if not wanted.is_empty():
		var focus_match := _find_focus_key(_body, wanted)
		if focus_match != null:
			focus_match.grab_focus()
			restored = true
	if not restored:
		_focus_first(_body)
	if _body_scroll != null:
		# Focus restoration runs before the rebuilt layout has settled and can
		# otherwise force the ScrollContainer to its final focusable control.
		_body_scroll.scroll_horizontal = 0 if reset_scroll_to_top else previous_scroll_horizontal
		_body_scroll.scroll_vertical = 0 if reset_scroll_to_top else previous_scroll_vertical

func _find_focus_key(parent: Node, key: String) -> Control:
	for child: Node in parent.get_children():
		if child is Control and child.has_meta("focus_key") and String(child.get_meta("focus_key")) == key:
			return child
		var nested := _find_focus_key(child, key)
		if nested != null:
			return nested
	return null

func _focus_first(parent: Node) -> void:
	for child: Node in parent.get_children():
		if child is Control:
			var control := child as Control
			if control.is_inside_tree() and control.visible and control.focus_mode != Control.FOCUS_NONE and not (control is BaseButton and (control as BaseButton).disabled):
				control.grab_focus()
				return
		_focus_first(child)
		var viewport := get_viewport()
		var focus_owner := viewport.gui_get_focus_owner() if viewport != null else null
		if focus_owner != null and parent.is_ancestor_of(focus_owner):
			return

func _campaign_precedes(left: PackageDiscoveryResult, right: PackageDiscoveryResult) -> bool:
	if left.ready != right.ready:
		return left.ready
	return _display_name(left).naturalnocasecmp_to(_display_name(right)) < 0

func _label(text: String, color: Color = Color.WHITE, size: int = 15) -> Label:
	var label := Label.new()
	label.text = text
	label.add_theme_color_override("font_color", color)
	label.add_theme_font_size_override("font_size", int(round(float(size) * _settings.text_scale)))
	return label

func _add_label(parent: Container, text: String, color: Color = Color.WHITE, size: int = 15) -> Label:
	var label := _label(text, color, size)
	label.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
	parent.add_child(label)
	return label

func _add_card_to(parent: Container, title: String, subtitle: String, detail: String) -> void:
	var panel := PanelContainer.new()
	panel.theme_type_variation = &"ClassicInset"
	panel.custom_minimum_size.x = 280.0
	panel.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	var box := VBoxContainer.new()
	box.add_theme_constant_override("separation", 3)
	panel.add_child(box)
	_add_label(box, title, Color("e7d078"), 17)
	_add_label(box, subtitle, Color("e0e2e5"))
	if not detail.is_empty():
		_add_label(box, detail, MUTED)
	parent.add_child(panel)

func _positions_for(view: GameView) -> Dictionary:
	var result: Dictionary = {}
	if view == null or view.combat_view == null or view.combat_view.battlefield == null:
		return result
	for character: CharacterView in view.party_members:
		var coordinate := view.combat_view.battlefield.character_position(character.id)
		if coordinate.x >= 0:
			result[character.id] = coordinate
	for monster: MonsterView in view.combat_view.monsters:
		var coordinate := view.combat_view.battlefield.monster_position(monster.id)
		if coordinate.x >= 0:
			result[monster.id] = coordinate
	return result

func _position_for(combatant_id: String, positions: Dictionary) -> Vector2i:
	var value: Variant = positions.get(combatant_id)
	if value is Vector2i:
		return value
	var coordinate := _view_position(previous_view, combatant_id)
	if coordinate.x >= 0:
		return coordinate
	return _view_position(final_view, combatant_id)

func _view_position(view: GameView, combatant_id: String) -> Vector2i:
	if view == null or view.combat_view == null:
		return Vector2i(-1, -1)
	return ClassicBattlefieldPresenter.actor_position(view.combat_view, view.party_members, combatant_id)

static func _payload_coordinate(value: Variant) -> Vector2i:
	if value is Vector2i:
		return value
	if value is Array and value.size() == 2:
		return Vector2i(int(value[0]), int(value[1]))
	return Vector2i(-1, -1)

static func _result_kind(payload: Dictionary) -> StringName:
	if bool(payload.get("fumble", false)):
		return &"fumble"
	if bool(payload.get("blocked", false)):
		return &"blocked"
	if bool(payload.get("immune", false)):
		return &"immune"
	if bool(payload.get("resisted", false)):
		return &"resisted"
	if bool(payload.get("saved", false)):
		return &"saved"
	if not bool(payload.get("hit", true)):
		return &"miss"
	if int(payload.get("healing", 0)) > 0:
		return &"healing"
	if int(payload.get("damage", 0)) > 0:
		return &"damage"
	return &"no_effect"

func _close_setup_character_inspection() -> void:
	_setup_inspection_character_id = ""
	if _setup_inspection_overlay != null:
		_setup_inspection_overlay.visible = false
	call_deferred("_focus_first", _setup_overlay)

func _init(target_mode: StringName, base_response_payload: Dictionary) -> void:
	mode = target_mode
	response_payload = base_response_payload.duplicate(true)

func _submit_swap(selector: OptionButton, rows: Array[Dictionary], direction: String, kind: String, amount: int) -> void:
	if selector.selected < 0 or selector.selected >= rows.size():
		return
	payload_submitted.emit({"action": "transfer", "direction": direction, "kind": kind, "amount": amount, "characterId": String(rows[selector.selected]["id"])})

func _refresh_inspected_label() -> void:
	if _inspected_label == null:
		return
	if _inspected_index < 0 or _inspected_index >= _combatants.size():
		_inspected_label.text = "Shown • No combatant selected"
		return
	var combatant := _combatants[_inspected_index]
	var details: Array[String] = ["HP %d/%d" % [int(combatant.get("currentHealth", 0)), int(combatant.get("maximumHealth", 0))]]
	if int(combatant.get("maximumSpellPoints", 0)) > 0:
		details.append("SP %d/%d" % [int(combatant.get("spellPoints", 0)), int(combatant.get("maximumSpellPoints", 0))])
	details.append("AR %d" % int(combatant.get("armor", 0)))
	details.append("MR %d" % int(combatant.get("magicResistance", 0)))
	if combatant.has("hitDice"):
		details.append("HD %d" % int(combatant.get("hitDice", 0)))
	if int(combatant.get("range", -1)) >= 0:
		details.append("Range %d%s" % [int(combatant.get("range", -1)), " • Blocked" if bool(combatant.get("blocked", false)) else ""])
	var secondary: Array[String] = []
	var weapon := String(combatant.get("weapon", ""))
	if not weapon.is_empty():
		var charges := int(combatant.get("weaponCharges", -1))
		secondary.append("%s%s" % [weapon, " (%d)" % charges if charges >= 0 else ""])
	secondary.append("Attacks %s" % String(combatant.get("attacks", "0")))
	secondary.append("Move %d" % int(combatant.get("maximumMovement", combatant.get("movement", 0))))
	var conditions := _string_array(combatant.get("conditions", []))
	if not conditions.is_empty():
		secondary.append("Conditions: %s" % ", ".join(conditions))
	var defenses: Array[String] = []
	var immunities := _string_array(combatant.get("immunities", []))
	var vulnerabilities := _string_array(combatant.get("vulnerabilities", []))
	if not immunities.is_empty():
		defenses.append("Immune: %s" % ", ".join(immunities))
	if not vulnerabilities.is_empty():
		defenses.append("Vulnerable: %s" % ", ".join(vulnerabilities))
	var defense_line := "\n%s" % " • ".join(defenses) if not defenses.is_empty() else ""
	_inspected_label.text = "Shown • %s\n%s\n%s%s" % [String(combatant.get("name", "Combatant")), " • ".join(details), " • ".join(secondary), defense_line]

func _perform_presentation_action(action: StringName) -> void:
	if action in [&"inspect_previous", &"inspect_next"] and not _combatants.is_empty():
		var delta := -1 if action == &"inspect_previous" else 1
		_inspected_index = posmod(_inspected_index + delta, _combatants.size())
		_refresh_inspected_label()
		presentation_action_requested.emit(&"focus_combatant", {"combatantId": String(_combatants[_inspected_index].get("id", "")), "playSound": true})
		return
	if action == &"center_active":
		inspect_combatant(_actor_id)
		presentation_action_requested.emit(&"focus_combatant", {"combatantId": _actor_id, "playSound": true})
		return
	if action == &"reveal_friends":
		presentation_action_requested.emit(&"toggle_reveal_friends", {})

func select_coordinate(coordinate: Vector2i) -> bool:
	if mode != &"area":
		return false
	selected_coordinate = coordinate
	if not legal_coordinates.has(coordinate):
		status_text = "That center is outside the rules-owned range, line of sight, or safe mask boundary."
		return false
	status_text = "Area center is legal. Confirm to commit the spell."
	return true

static func from_map_view(map_view: MapView) -> DungeonGeometryProjection:
	if map_view == null or map_view.level_type != &"dungeon":
		return null
	var projection := DungeonGeometryProjection.new()
	projection.map_id = map_view.map_id
	projection.map_name = map_view.map_name
	projection.party_coordinate = map_view.party_coordinate
	for cell: MapCellView in map_view.cells():
		if not cell.visible:
			continue
		var cell_projection := CellProjection.new(cell)
		projection._cells.append(cell_projection)
		projection._cells_by_coordinate[cell.coordinate] = cell_projection
		for direction: StringName in DIRECTIONS:
			var edge := EdgeProjection.new(cell.coordinate, direction, cell.edge_kind(direction), cell.edge_is_passable(direction))
			projection._edges.append(edge)
			projection._edges_by_direction[_directed_edge_key(cell.coordinate, direction)] = edge
	return projection

func can_confirm() -> bool:
	match mode:
		&"combatant", &"sequence":
			return not selected_ids.is_empty()
		&"area":
			return legal_coordinates.has(selected_coordinate)
	return false

func selection_data() -> Dictionary:
	return {
		"mode": String(mode),
		"selectedIds": selected_ids.duplicate(),
		"selectedCoordinate": [selected_coordinate.x, selected_coordinate.y],
		"maximumTargets": maximum_targets,
		"canConfirm": can_confirm(),
		"status": status_text,
	}

func inspect_combatant(combatant_id: String) -> void:
	for index: int in _combatants.size():
		if String(_combatants[index].get("id", "")) == combatant_id:
			_inspected_index = index
			_refresh_inspected_label()
			return

func _read_combatants(value: Variant) -> void:
	_combatants.clear()
	if value is Array:
		for combatant: Variant in value:
			if combatant is Dictionary and not String(combatant.get("id", "")).is_empty():
				_combatants.append((combatant as Dictionary).duplicate(true))

func _refresh_selected_character() -> void:
	for child: Node in _transfer_rows.get_children():
		_transfer_rows.remove_child(child)
		child.free()
	if _picker == null or _picker.item_count < 1:
		_summary.text = "No eligible character was supplied."
		return
	var character_id := String(_picker.get_selected_metadata())
	var character: Dictionary = {}
	for candidate: Dictionary in _characters:
		if candidate.get("id") == character_id:
			character = candidate
			break
	var wealth: Variant = character.get("wealth", {})
	var wealth_data := wealth as Dictionary if wealth is Dictionary else {}
	_summary.text = "%s • %d gold • %d gems • %d jewelry • load %d/%d" % [
		character.get("name", "Character"),
		int(wealth_data.get("gold", 0)),
		int(wealth_data.get("gems", 0)),
		int(wealth_data.get("jewelry", 0)),
		int(character.get("load", 0)),
		int(character.get("maximumLoad", 0)),
	]
	var transfers: Variant = character.get("transfers", [])
	if not transfers is Array:
		return
	for transfer: Variant in transfers:
		if not transfer is Dictionary:
			continue
		_add_transfer_row(character_id, String(character.get("name", "Character")), transfer)

func present(game_view: GameView) -> void:
	_projection = null
	if game_view != null and game_view.session_started:
		_projection = DungeonGeometryProjection.from_map_view(game_view.map_view)
	_rebuild_geometry()
	_update_visibility()

func build(request: InteractionRequest) -> void:
	var departure_mode: bool = request.kind == InteractionRequest.POOLED_WEALTH_DEPARTURE or String(request.payload.get("mode", "")) == "departure"
	var pooled := request.payload.get("pooledWealth", {}) as Dictionary
	var banked := request.payload.get("bankedWealth", {}) as Dictionary
	add_hint("Distribute pooled wealth before leaving" if departure_mode else "Bank-backed Swap")
	add_hint("Pool: %d gold • %d gems • %d jewelry" % [int(pooled.get("gold", 0)), int(pooled.get("gems", 0)), int(pooled.get("jewelry", 0))])
	if departure_mode:
		add_hint("Done leaves any unassigned wealth behind, then continues this movement attempt.")
	else:
		add_hint("Deposited until departure: %d gold • %d gems • %d jewelry" % [int(banked.get("gold", 0)), int(banked.get("gems", 0)), int(banked.get("jewelry", 0))])
		add_hint("Opening the bank moves deposited wealth into the pool. Done closes Swap; leaving the location returns the remaining pool to the bank.")
	var characters: Variant = request.payload.get("characters", [])
	if characters is Array:
		for character: Variant in characters:
			if character is Dictionary:
				_characters.append(character.duplicate(true))
	var pool: Variant = request.payload.get("pool", {})
	var share: Variant = request.payload.get("share", {})
	add_response("Pool party wealth", {"action": "pool"}, pool is Dictionary and bool(pool.get("enabled", false)), String(pool.get("reason", "Pooling is unavailable.")) if pool is Dictionary else "Pooling is unavailable.")
	add_response("Share pooled wealth", {"action": "share"}, share is Dictionary and bool(share.get("enabled", false)), String(share.get("reason", "Sharing is unavailable.")) if share is Dictionary else "Sharing is unavailable.")
	_picker = character_option(_characters)
	var selected_character_id := String(request.payload.get("selectedCharacterId", ""))
	for index: int in _picker.item_count:
		if String(_picker.get_item_metadata(index)) == selected_character_id:
			_picker.select(index)
			break
	_picker.item_selected.connect(func(_index: int) -> void: _refresh_selected_character())
	add_child(_picker)
	_summary = add_hint("")
	_transfer_rows = VBoxContainer.new()
	add_child(_transfer_rows)
	add_response("Done", {"action": "leave"})
	_refresh_selected_character()

func _rebuild_geometry() -> void:
	if _geometry_root == null:
		return
	for child: Node in _geometry_root.get_children():
		_geometry_root.remove_child(child)
		child.queue_free()
	if _projection == null:
		return
	for cell: DungeonGeometryProjection.CellProjection in _projection.cells():
		if cell.passable:
			_add_box("Floor_%d_%d" % [cell.coordinate.x, cell.coordinate.y], Vector3(cell_span * 0.94, 0.10, cell_span * 0.94), _cell_center(cell.coordinate) + Vector3(0.0, -0.08, 0.0), _floor_material)
		if cell.features.has(&"column"):
			_add_column(cell.coordinate)
		if cell.features.has(&"stairs"):
			_add_stairs(cell.coordinate)
	var built_edges: Dictionary = {}
	for edge: DungeonGeometryProjection.EdgeProjection in _projection.edges():
		if edge.kind == &"open" or built_edges.has(edge.canonical_key):
			continue
		built_edges[edge.canonical_key] = true
		if edge.kind in [&"door", &"archway"]:
			_add_door_frame(edge)
		else:
			_add_wall(edge, _secret_material if edge.kind == &"secret" else _wall_material)
	_add_party_marker()
	var target := _cell_center(_projection.party_coordinate) + Vector3(0.0, 0.65, 0.0)
	_camera.position = target + Vector3(5.6, 7.5, 7.8)
	_camera.look_at(target, Vector3.UP)

func _add_door_frame(edge: DungeonGeometryProjection.EdgeProjection) -> void:
	var horizontal := edge.direction in [&"north", &"south"]
	var center := _edge_center(edge.coordinate, edge.direction)
	var post_offset := cell_span * 0.37
	var post_size := Vector3(wall_thickness * 1.35, wall_height * 0.82, wall_thickness * 1.35)
	var left_offset := Vector3(post_offset, 0.0, 0.0) if horizontal else Vector3(0.0, 0.0, post_offset)
	_add_box("DoorPostA_%s" % edge.canonical_key, post_size, center - left_offset + Vector3(0.0, post_size.y * 0.5, 0.0), _door_material)
	_add_box("DoorPostB_%s" % edge.canonical_key, post_size, center + left_offset + Vector3(0.0, post_size.y * 0.5, 0.0), _door_material)
	var lintel_size := Vector3(cell_span, wall_thickness * 1.5, wall_thickness * 1.5) if horizontal else Vector3(wall_thickness * 1.5, wall_thickness * 1.5, cell_span)
	_add_box("DoorLintel_%s" % edge.canonical_key, lintel_size, center + Vector3(0.0, wall_height * 0.84, 0.0), _door_material)
	if edge.kind == &"door" and not edge.passable:
		var panel_size := Vector3(cell_span * 0.62, wall_height * 0.70, wall_thickness * 0.65) if horizontal else Vector3(wall_thickness * 0.65, wall_height * 0.70, cell_span * 0.62)
		_add_box("DoorPanel_%s" % edge.canonical_key, panel_size, center + Vector3(0.0, panel_size.y * 0.5, 0.0), _door_material)

func _add_stairs(coordinate: Vector2i) -> void:
	for index: int in range(3):
		var height := 0.12 * float(index + 1)
		_add_box("Stair_%d_%d_%d" % [coordinate.x, coordinate.y, index], Vector3(cell_span * 0.62, height, cell_span * 0.20), _cell_center(coordinate) + Vector3(0.0, height * 0.5, (float(index) - 1.0) * cell_span * 0.20), _feature_material)

func _add_box(node_name: String, box_size: Vector3, box_position: Vector3, surface_material: Material) -> void:
	var mesh := BoxMesh.new()
	mesh.size = box_size
	var instance := MeshInstance3D.new()
	instance.name = node_name.validate_node_name()
	instance.mesh = mesh
	instance.material_override = surface_material
	instance.position = box_position
	_geometry_root.add_child(instance)

func _add_wall(edge: DungeonGeometryProjection.EdgeProjection, surface_material: Material) -> void:
	var horizontal := edge.direction in [&"north", &"south"]
	var box_dimensions := Vector3(cell_span, wall_height, wall_thickness) if horizontal else Vector3(wall_thickness, wall_height, cell_span)
	_add_box("Edge_%s" % edge.canonical_key, box_dimensions, _edge_center(edge.coordinate, edge.direction) + Vector3(0.0, wall_height * 0.5, 0.0), surface_material)

func _spell_targeting_configuration(spell_casts: Array, selected: Dictionary, response_payload: Dictionary) -> Dictionary:
	var mode := String(selected.get("targetMode", "combatant"))
	var candidate_ids: Array[String] = []
	if mode == "sequence":
		for candidate: Variant in selected.get("targetCandidates", []):
			if candidate is Dictionary and not String(candidate.get("id", "")).is_empty():
				candidate_ids.append(String(candidate.get("id")))
	elif mode == "combatant":
		for candidate: Variant in spell_casts:
			if candidate is Dictionary and candidate.get("spellId") == selected.get("spellId") and int(candidate.get("power", 0)) == int(selected.get("power", 0)) and (not selected.has("scrollSlot") or candidate.get("scrollSlot") == selected.get("scrollSlot")) and candidate.get("targetMode", "combatant") == "combatant" and not String(candidate.get("targetId", "")).is_empty():
				candidate_ids.append(String(candidate.get("targetId")))
	return {
		"mode": mode,
		"responsePayload": response_payload,
		"candidateIds": candidate_ids,
		"maximumTargets": int(selected.get("maximumTargets", 1)),
		"areaOffsets": selected.get("areaOffsets", []),
		"defaultTargetCoordinate": selected.get("defaultTargetCoordinate", []),
		"legalTargetCoordinates": selected.get("legalTargetCoordinates", []),
	}

