func _refresh_selected_character() -> void:
	if _picker == null or _picker.item_count < 1:
		_summary.text = "No eligible character was supplied."
		for button: Button in _service_buttons.values():
			button.disabled = true
			button.tooltip_text = "No eligible character was supplied."
		return
	var character_id := String(_picker.get_selected_metadata())
	var character: Dictionary = {}
	for candidate: Dictionary in _characters:
		if candidate.get("id") == character_id:
			character = candidate
			break
	var condition_names: Array[String] = []
	var conditions: Variant = character.get("conditions", [])
	if conditions is Array:
		for condition: Variant in conditions:
			if condition is Dictionary:
				condition_names.append(String(condition.get("name", "Condition")))
	var condition_text := "None shown" if condition_names.is_empty() else ", ".join(condition_names)
	_summary.text = "%s • HP %d/%d • personal gold %d • load %d/%d\nConditions: %s" % [
		character.get("name", "Character"),
		int(character.get("currentHealth", 0)),
		int(character.get("maximumHealth", 0)),
		int(character.get("personalGold", 0)),
		int(character.get("load", 0)),
		int(character.get("maximumLoad", 0)),
		condition_text,
	]
	var available := int(character.get("availableGold", _pooled_gold + int(character.get("personalGold", 0))))
	for service: Dictionary in _services:
		var service_id := String(service.get("id", ""))
		var button: Button = _service_buttons.get(service_id)
		if button == null:
			continue
		var cost := int(service.get("cost", 0))
		button.disabled = cost > available
		button.tooltip_text = "Requires %d gold from the pool and selected character." % cost if button.disabled else String(service.get("description", ""))

func build(request: InteractionRequest) -> void:
	match request.kind:
		&"encounter_choice", &"scenario_choice":
			var options: Variant = request.payload.get("options", [])
			if options is Array:
				for index: int in options.size():
					var option: Variant = options[index]
					if option is Dictionary:
						add_response(String(option.get("label", "Option %d" % (index + 1))), {"index": index})
			if request.kind == &"encounter_choice" and bool(request.payload.get("canBackOut", false)):
				add_response("Back out", {"cancelled": true})
		&"yes_no":
			add_response(String(request.payload.get("yesLabel", "Yes")), {"accepted": true})
			add_response(String(request.payload.get("noLabel", "No")), {"accepted": false})
		&"acknowledge":
			if bool(request.payload.get("journalEligible", false)) and not bool(request.payload.get("journalRecorded", false)):
				add_response("Take note", {"takeNote": true})
			elif bool(request.payload.get("journalRecorded", false)):
				add_hint("Already recorded in the journal.")
			add_response("Continue", {})

func build(request: InteractionRequest) -> void:
	var mode := String(request.payload.get("mode", ""))
	if mode == "fumbled-item-recovery":
		_build_fumble_recovery(request.payload)
	elif mode == "ordinary":
		_build_ordinary(request.payload)
	elif mode == "completion-confirmation":
		_build_completion_confirmation(request.payload)
	else:
		add_hint("The treasure request is malformed.")

func _build_fumble_recovery(payload: Dictionary) -> void:
	if not payload.get("item") is Dictionary:
		add_hint("The recovery request is malformed.")
		return
	var item: Dictionary = payload["item"]
	var instance_id := String(item.get("instanceId", ""))
	var charge_count := int(item.get("charges", 0))
	var charge_text := " • %d charge%s" % [charge_count, "" if charge_count == 1 else "s"] if charge_count > 0 else ""
	var remaining_text := " • %d items remain" % int(payload.get("remaining", 1)) if int(payload.get("remaining", 1)) > 1 else ""
	add_hint("%s%s%s" % [String(item.get("name", "Fumbled weapon")), charge_text, remaining_text])
	_add_item_recipients(instance_id, payload.get("characters", []))
	add_response("Leave behind", {"action": "discard", "instanceId": instance_id})

func _build_ordinary(payload: Dictionary) -> void:
	var wealth: Variant = payload.get("wealth", {})
	if wealth is Dictionary:
		add_hint("Pool: %d gold • %d gems • %d jewelry" % [int(wealth.get("gold", 0)), int(wealth.get("gems", 0)), int(wealth.get("jewelry", 0))])
	var share := int(payload.get("experienceShare", 0))
	if share > 0:
		add_hint("Each eligible adventurer receives %d experience." % share)
	var item: Variant = payload.get("item")
	if item is Dictionary:
		var item_data: Dictionary = item
		var instance_id := String(item_data.get("instanceId", ""))
		var display_name := String(item_data.get("name", "Unknown item"))
		if bool(item_data.get("magical", false)) and not bool(item_data.get("identified", false)):
			display_name += " • magic detected"
		add_hint("%s • %d item%s remain" % [display_name, int(payload.get("remaining", 1)), "" if int(payload.get("remaining", 1)) == 1 else "s"])
		_add_item_recipients(instance_id, payload.get("characters", []))
		add_response("Leave this item", {"action": "discard", "instanceId": instance_id})
	elif int(payload.get("remaining", 0)) == 0:
		add_hint("No items remain to distribute.")
	var detect: Variant = payload.get("detect", {})
	if detect is Dictionary and bool(detect.get("visible", false)):
		_add_caster_actions("Detect magic", "detect", detect)
	var identify: Variant = payload.get("identify", {})
	if identify is Dictionary and bool(identify.get("visible", false)):
		_add_caster_actions("Identify treasure", "identify", identify)
	var characters: Variant = payload.get("characters", [])
	var has_carried_wealth := false
	if characters is Array:
		for value: Variant in characters:
			if value is Dictionary and value.get("wealth") is Dictionary:
				var carried: Dictionary = value["wealth"]
				has_carried_wealth = has_carried_wealth or int(carried.get("gold", 0)) > 0 or int(carried.get("gems", 0)) > 0 or int(carried.get("jewelry", 0)) > 0
	add_response("Pool party wealth", {"action": "pool"}, has_carried_wealth, "No adventurer carries wealth to pool.")
	var has_pool := wealth is Dictionary and (int(wealth.get("gold", 0)) > 0 or int(wealth.get("gems", 0)) > 0 or int(wealth.get("jewelry", 0)) > 0)
	add_response("Share pooled wealth", {"action": "share"}, has_pool and bool(payload.get("hasShareCapacity", false)), "The pool is empty or no adventurer can carry another unit.")
	_add_swap_controls(characters)
	add_response("Done", {"action": "done"})

func build(request: InteractionRequest) -> void:
	var characters: Variant = request.payload.get("characters", [])
	if characters is Array:
		for character: Variant in characters:
			if character is Dictionary:
				_characters.append(character.duplicate(true))
	var services: Variant = request.payload.get("services", [])
	if services is Array:
		for service: Variant in services:
			if service is Dictionary:
				_services.append(service.duplicate(true))
	var pooled: Variant = request.payload.get("pooledWealth", {})
	_pooled_gold = int(pooled.get("gold", 0)) if pooled is Dictionary else 0
	add_hint("Temple services • %d%% rate • pooled gold %d" % [int(request.payload.get("costPercent", 100)), _pooled_gold])
	_picker = character_option(_characters)
	var selected_character_id := String(request.payload.get("selectedCharacterId", ""))
	for index: int in _picker.item_count:
		if String(_picker.get_item_metadata(index)) == selected_character_id:
			_picker.select(index)
			break
	_picker.item_selected.connect(func(_index: int) -> void: _refresh_selected_character())
	add_child(_picker)
	_summary = add_hint("")
	for service: Dictionary in _services:
		var service_id := String(service.get("id", ""))
		var button := Button.new()
		button.text = "%s • %d gold" % [service.get("label", "Service"), int(service.get("cost", 0))]
		button.custom_minimum_size.y = 36.0
		button.size_flags_horizontal = Control.SIZE_EXPAND_FILL
		button.pressed.connect(_submit_service.bind(service_id))
		add_child(button)
		_service_buttons[service_id] = button
	add_hint("Wealth")
	_add_temple_action("Pool party wealth", "pool")
	_add_temple_action("Share pooled wealth", "share")
	_add_temple_action("Leave temple", "leave")
	_refresh_selected_character()

