func begin_completed_battle_reward(request_id: String) -> ScenarioRuntimeOperationResult:
	var combat := _game_state.combat
	if combat == null or not combat.completed:
		return ScenarioRuntimeOperationResult.failed(&"invalid_battle_continuation", "Battle rewards require a completed battle.")
	if combat.rewards_completed:
		return ScenarioRuntimeOperationResult.completed(String(combat.outcome))
	if combat.rewards_started:
		return ScenarioRuntimeOperationResult.failed(&"battle_reward_already_started", "The completed battle already has an active reward continuation.")
	var defeated_monsters: Array[Dictionary] = []
	var pending_item_count := 0
	if combat.outcome == &"victory":
		for monster: MonsterState in combat.monsters():
			var definition := _content.monster_by_id(monster.definition_id)
			if definition == null:
				return ScenarioRuntimeOperationResult.failed(&"unknown_monster", "Battle reward references unavailable monster content.")
			if not monster.traitor or monster.current_health >= 1:
				continue
			var loot := monster.loot_item_ids()
			if loot.is_empty():
				loot = definition.item_ids()
				if not loot.is_empty() and definition.random_weapon_table > 0:
					loot[0] = monster.weapon_id
			for item_id: String in loot:
				if item_id.is_empty():
					continue
				if _content.item_by_id(item_id) == null:
					return ScenarioRuntimeOperationResult.failed(&"unknown_item", "Battle reward references unavailable item '%s'." % item_id)
				pending_item_count += 1
				if pending_item_count > ClassicRewardState.MAX_PENDING_ITEMS:
					return ScenarioRuntimeOperationResult.failed(&"invalid_reward", "The battle reward exceeds the supported Classic reward bounds.")
			defeated_monsters.append({"monster": monster, "definition": definition, "loot": loot})
	# Validate the whole source-owned reward before consuming RNG or claiming its
	# one-shot battle continuation. A malformed package therefore remains retryable.
	combat.rewards_started = true
	var item_ids: Array[String] = []
	var wealth := WealthState.new()
	var experience := 0
	var events: Array[DomainEvent] = []
	if combat.outcome == &"victory":
		for row: Dictionary in defeated_monsters:
			var monster: MonsterState = row["monster"]
			var definition: MonsterDefinition = row["definition"]
			var money := definition.money_values()
			for kind: WealthState.Kind in [WealthState.Kind.GOLD, WealthState.Kind.GEMS, WealthState.Kind.JEWELRY]:
				var maximum := maxi(0, money[kind] if kind < money.size() else 0)
				if maximum > 0:
					wealth.add(kind, _rng.draw_between(0, maximum, StringName("battle.reward.%s.money.%d" % [monster.id, kind])))
			experience += _monster_reward_experience(monster, definition)
			for item_id: String in row["loot"]:
				if not item_id.is_empty():
					item_ids.append(item_id)
		events.append(DomainEvent.new(&"battle_reward_constructed", {"battleId": combat.battle_id, "experience": experience, "wealth": wealth.to_data(), "itemCount": item_ids.size()}))
	var operation := _begin_reward(&"battle", combat.battle_id, experience, wealth, item_ids, request_id)
	operation.events = events + operation.events
	return operation

func _apply_classic_condition(action: ClassicActionDefinition) -> ScenarioRuntimeOperationResult:
	if action.extra_code.size() < 3:
		return ScenarioRuntimeOperationResult.failed(&"missing_extra_code", "Classic opcode 43 requires a five-value Extra Code row.")
	var target_mode := action.extra_code[0]
	var condition_index := action.extra_code[1]
	var duration := action.extra_code[2]
	if target_mode < 0 or target_mode > 2 or condition_index < 0 or condition_index >= ConditionSet.CHARACTER_COUNT:
		return ScenarioRuntimeOperationResult.failed(&"invalid_condition", "Classic opcode 43 has an invalid target or condition index.")
	var targets: Array[CharacterState] = []
	if target_mode == 1:
		targets = _game_state.selected_characters()
	else:
		for character: CharacterState in _game_state.party.characters():
			if target_mode == 0 or character.current_health > 0:
				targets.append(character)
	for character: CharacterState in targets:
		character.conditions.set_value(condition_index, duration)
	var ids: Array[String] = []
	for character: CharacterState in targets:
		ids.append(character.id)
	return ScenarioRuntimeOperationResult.completed(ids, [DomainEvent.new(&"condition_applied", {"characterIds": ids, "condition": condition_index, "duration": duration, "soundId": action.extra_code[3] if action.extra_code.size() > 3 else 0})])

func _add_classic_ally(classic_monster_id: int) -> ScenarioRuntimeOperationResult:
	var definition := _content.monster_by_classic_id_for_set(classic_monster_id, _game_state.monster_set)
	if definition == null:
		return ScenarioRuntimeOperationResult.failed(&"unknown_monster", "Classic opcode 89 references unavailable monster %d." % classic_monster_id)
	var ally := _rules.monsters.build_monster(definition, _game_state.next_instance_id("party.ally"), 0, _game_state.difficulty, _game_state.clock.day(), _rng)
	if ally == null or not _game_state.party.add_ally(ally):
		return ScenarioRuntimeOperationResult.failed(&"ally_add_failed", "The ally could not join the party.")
	return ScenarioRuntimeOperationResult.completed(ally.id, [DomainEvent.new(&"ally_added", {"allyId": ally.id, "monsterId": definition.id})])

func _grant_treasure_definition(treasure: TreasureDefinition, request_id: String) -> ScenarioRuntimeOperationResult:
	var roll := _rules.economy.roll_treasure(treasure, _rng)
	return _begin_reward(&"scenario", treasure.id, roll.experience, roll.wealth, roll.item_ids, request_id)

static func from_data(data: Variant) -> ScenarioFrame:
	if not data is Dictionary:
		return null
	for field: String in ["kind", "definitionId", "cursor", "returnTarget", "countsAsClassicCall", "parameters", "locals", "context", "iterators"]:
		if not data.has(field):
			return null
	var saved_cursor := _integer(data["cursor"])
	if data["kind"] not in ["program", "action"] or not data["definitionId"] is String or data["definitionId"].is_empty() or saved_cursor < 0 or not data["returnTarget"] is String or not data["countsAsClassicCall"] is bool:
		return null
	if not data["parameters"] is Dictionary or not data["locals"] is Dictionary or not data["context"] is Dictionary or not data["iterators"] is Array:
		return null
	var frame := ScenarioFrame.new(StringName(data["kind"]), data["definitionId"], saved_cursor)
	frame.return_target = data["returnTarget"]
	frame.counts_as_classic_call = data["countsAsClassicCall"]
	frame._parameters = data["parameters"].duplicate(true)
	frame._locals = data["locals"].duplicate(true)
	frame._context = data["context"].duplicate(true)
	for iterator: Variant in data["iterators"]:
		if not iterator is Dictionary:
			return null
		frame._iterators.append(iterator.duplicate(true))
	return frame

static func from_data(data: Variant) -> ScenarioActionState:
	if not data is Dictionary or data.size() > MAX_ENTRIES:
		return null
	var state := ScenarioActionState.new()
	for key: Variant in data.keys():
		if not key is String or key.is_empty():
			return null
		var decoded := _decode(data[key], 0)
		if not decoded["ok"]:
			return null
		state._values[key] = decoded["value"]
	return state

func to_data() -> Dictionary:
	var result: Dictionary = {}
	var keys: Array = _values.keys()
	keys.sort()
	for key: Variant in keys:
		result[key] = _encode(_values[key])
	return result

func write(state_scope: String, owner_id: String, name: String, value: Variant) -> bool:
	var key := _key(state_scope, owner_id, name)
	if not _values.has(key) and _values.size() >= MAX_ENTRIES:
		return false
	if not _json_safe(value, 0):
		return false
	_values[key] = value
	return true

func _init(option_label_id: int, option_text: String) -> void:
	id = option_label_id
	text = option_text

static func _json_safe(value: Variant, depth: int) -> bool:
	if depth > 32:
		return false
	if value == null or value is bool or value is int or value is String:
		return true
	if value is float:
		return not is_nan(value) and not is_inf(value)
	if value is Array:
		if value.size() > 256:
			return false
		for child: Variant in value:
			if not _json_safe(child, depth + 1):
				return false
		return true
	if value is Dictionary:
		if value.size() > 256:
			return false
		for key: Variant in value.keys():
			if not key is String or not _json_safe(value[key], depth + 1):
				return false
		return true
	return false

static func _encode(value: Variant) -> Dictionary:
	if value == null:
		return {"type": "null"}
	if value is bool:
		return {"type": "bool", "value": value}
	if value is int:
		return {"type": "int", "value": value}
	if value is float:
		return {"type": "float", "value": value}
	if value is String:
		return {"type": "string", "value": value}
	if value is Array:
		var entries: Array[Dictionary] = []
		for child: Variant in value:
			entries.append(_encode(child))
		return {"type": "array", "value": entries}
	var fields: Dictionary = {}
	var keys: Array = value.keys()
	keys.sort()
	for key: Variant in keys:
		fields[key] = _encode(value[key])
	return {"type": "record", "value": fields}

static func _decode(value: Variant, depth: int) -> Dictionary:
	if depth > 32 or not value is Dictionary or not value.get("type") is String:
		return {"ok": false}
	match value["type"]:
		"null":
			return {"ok": value.size() == 1, "value": null}
		"bool":
			return {"ok": value.size() == 2 and value.get("value") is bool, "value": value.get("value")}
		"int":
			var integer: Variant = _integer(value.get("value"))
			return {"ok": value.size() == 2 and integer != null, "value": integer}
		"float":
			var number: Variant = value.get("value")
			return {"ok": value.size() == 2 and (number is int or number is float) and not is_nan(float(number)) and not is_inf(float(number)), "value": float(number) if number is int or number is float else 0.0}
		"string":
			return {"ok": value.size() == 2 and value.get("value") is String, "value": value.get("value")}
		"array":
			if value.size() != 2 or not value.get("value") is Array or value["value"].size() > 256:
				return {"ok": false}
			var entries: Array = []
			for child: Variant in value["value"]:
				var decoded := _decode(child, depth + 1)
				if not decoded["ok"]:
					return {"ok": false}
				entries.append(decoded["value"])
			return {"ok": true, "value": entries}
		"record":
			if value.size() != 2 or not value.get("value") is Dictionary or value["value"].size() > 256:
				return {"ok": false}
			var fields: Dictionary = {}
			for key: Variant in value["value"].keys():
				if not key is String:
					return {"ok": false}
				var decoded := _decode(value["value"][key], depth + 1)
				if not decoded["ok"]:
					return {"ok": false}
				fields[key] = decoded["value"]
			return {"ok": true, "value": fields}
	return {"ok": false}

static func _integer(value: Variant) -> Variant:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return null

static func _integer(value: Variant) -> int:
	if value is int:
		return value
	if value is float and is_equal_approx(value, round(value)):
		return int(value)
	return -1

static func from_data(data: Variant) -> ScenarioVmSnapshot:
	if not data is Dictionary or data.get("schemaVersion") != SCHEMA_VERSION:
		return null
	for field: String in ["frames", "pendingRequest", "pendingContinuation", "trace", "requestCounter", "stepCount", "halted", "lastOutcome"]:
		if not data.has(field):
			return null
	var saved_request_counter := _integer(data["requestCounter"])
	var saved_step_count := _integer(data["stepCount"])
	if not data["frames"] is Array or not data["pendingContinuation"] is Dictionary or not data["trace"] is Array or saved_request_counter < 0 or saved_step_count < 0 or not data["halted"] is bool:
		return null
	var snapshot := ScenarioVmSnapshot.new()
	for frame_data: Variant in data["frames"]:
		var frame := ScenarioFrame.from_data(frame_data)
		if frame == null:
			return null
		snapshot.frames.append(frame)
	if data["pendingRequest"] != null:
		snapshot.pending_request = InteractionRequest.from_data(data["pendingRequest"])
		if snapshot.pending_request == null:
			return null
	snapshot.pending_continuation = data["pendingContinuation"].duplicate(true)
	if (snapshot.pending_request == null and not snapshot.pending_continuation.is_empty()) or (snapshot.pending_request != null and snapshot.pending_continuation.is_empty()):
		return null
	for entry: Variant in data["trace"]:
		if not entry is Dictionary:
			return null
		snapshot.trace.append(entry.duplicate(true))
	snapshot.request_counter = saved_request_counter
	snapshot.step_count = saved_step_count
	snapshot.halted = data["halted"]
	snapshot.last_outcome = data["lastOutcome"]
	return snapshot

func update_current_iterator(iterator: Dictionary) -> void:
	assert(not _iterators.is_empty(), "An active iterator is required")
	_iterators[_iterators.size() - 1] = iterator.duplicate(true)

func argument_names() -> Array[String]:
	var names: Array[String] = []
	for argument_name: Variant in _arguments.keys():
		names.append(String(argument_name))
	names.sort()
	return names

func has_line_of_sight_to_coordinate(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, from_actor_id: String, destination: Vector2i) -> bool:
	if battlefield == null or terrain_set == null or not battlefield.has_actor(from_actor_id) or not BattlefieldState.contains(destination):
		return false
	var origin := battlefield.actor_position(from_actor_id)
	var part := Vector2(origin * 32)
	var step := Vector2(destination - origin) * 32.0 / 128.0
	# FD-COMBAT-008 retains Castle's 128 center-offset samples but removes the
	# animation-delay term from the divisor. Presentation speed cannot alter AI.
	for _sample: int in 128:
		var coordinate := Vector2i(floori((part.x + 16.0) / 32.0), floori((part.y + 16.0) / 32.0))
		if not BattlefieldState.contains(coordinate):
			return false
		# Castle's field contains actor IDs, so occupied cells do not expose their
		# underlying terrain to cansee(). Preserve that observable distinction.
		if battlefield.actor_at(coordinate).is_empty():
			var terrain := terrain_set.tile_by_id(battlefield.terrain_at(coordinate))
			if terrain == null or terrain.blocks_los:
				return false
		part += step
	return true

func probe_monster_step_toward(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, actor_id: String, target: Vector2i, movement_available: int, rng: RealmzRng) -> BattlefieldStepResult:
	if battlefield == null or terrain_set == null or rng == null or not battlefield.has_actor(actor_id):
		return BattlefieldStepResult.blocked(&"invalid_actor")
	var origin := battlefield.actor_position(actor_id)
	var direction := Vector2i(signi(target.x - origin.x), signi(target.y - origin.y))
	var maximum_cost := 0
	for attempt: int in 21:
		var probe := _probe_step_with_cost_floor(battlefield, terrain_set, actor_id, direction, movement_available, maximum_cost)
		maximum_cost = maxi(maximum_cost, probe.movement_cost)
		if probe.allowed:
			return probe
		direction = _shift_monster_direction(origin, target, direction, rng, actor_id, attempt)
	var blocked := BattlefieldStepResult.blocked(&"monster_path_blocked", origin)
	blocked.movement_cost = maximum_cost
	return blocked

func probe_monster_step_away(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, actor_id: String, target: Vector2i, movement_available: int, rng: RealmzRng) -> BattlefieldStepResult:
	if battlefield == null or not battlefield.has_actor(actor_id):
		return BattlefieldStepResult.blocked(&"invalid_actor")
	var origin := battlefield.actor_position(actor_id)
	return probe_monster_step_toward(battlefield, terrain_set, actor_id, origin * 2 - target, movement_available, rng)

func _probe_step_with_cost_floor(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, actor_id: String, direction: Vector2i, movement_available: int, cost_floor: int) -> BattlefieldStepResult:
	if battlefield == null or terrain_set == null or not battlefield.has_actor(actor_id):
		return BattlefieldStepResult.blocked(&"invalid_actor")
	if direction == Vector2i.ZERO or absi(direction.x) > 1 or absi(direction.y) > 1:
		return BattlefieldStepResult.blocked(&"invalid_direction")
	var destination := battlefield.actor_position(actor_id) + direction
	var footprint := battlefield.actor_footprint_at(actor_id, destination)
	if footprint.is_empty():
		return BattlefieldStepResult.blocked(&"invalid_actor", destination)
	var maximum_cost := maxi(0, cost_floor)
	for coordinate: Vector2i in footprint:
		if not BattlefieldState.contains(coordinate):
			return _blocked_with_cost(&"outside_battlefield", destination, maximum_cost)
		var occupant := battlefield.actor_at(coordinate, actor_id)
		if not occupant.is_empty():
			return _blocked_with_cost(&"occupied", destination, maximum_cost, occupant)
		var terrain := terrain_set.tile_by_id(battlefield.terrain_at(coordinate))
		if terrain == null:
			return _blocked_with_cost(&"missing_terrain", destination, maximum_cost)
		var size := battlefield.actor_size(actor_id)
		if size == 0 and terrain.solid != 0 or size > 0 and terrain.solid > 1:
			return _blocked_with_cost(&"solid_terrain", destination, maximum_cost)
		maximum_cost = maxi(maximum_cost, _movement_cost(terrain, direction))
	if maximum_cost > movement_available:
		var result := BattlefieldStepResult.blocked(&"insufficient_movement", destination)
		result.movement_cost = maximum_cost
		return result
	return BattlefieldStepResult.permitted(destination, maximum_cost)

static func _movement_cost(terrain: BattleTerrainTileDefinition, direction: Vector2i) -> int:
	var cost := maxi(0, floori(float(terrain.movement_time) / 2.0) - 1)
	if direction.x != 0:
		cost += 1
	if direction.y != 0:
		cost += 1
	return cost

static func _shift_monster_direction(origin: Vector2i, target: Vector2i, direction: Vector2i, rng: RealmzRng, actor_id: String, attempt: int) -> Vector2i:
	var result := direction
	var net_x := absi(target.x - origin.x)
	var net_y := absi(target.y - origin.y)
	var tag_prefix := "combat.monster-shift.%s.%d" % [actor_id, attempt]
	if net_x > net_y:
		if result.y != 0 and rng.draw(2, StringName(tag_prefix + ".drop-y")) == 1:
			result.y = 0
		else:
			result.y = -1
			var y_roll := rng.draw(3, StringName(tag_prefix + ".y"))
			if y_roll == 1:
				result.y = 1
			elif y_roll == 2:
				result.y = 0
			var x_roll := rng.draw(3, StringName(tag_prefix + ".x"))
			if x_roll == 1:
				result.x = -1
			elif x_roll == 2:
				result.x = 1
			if x_roll == 3 and result.y != 0:
				result.x = 0
			else:
				result.x = -1 if rng.draw(2, StringName(tag_prefix + ".x-sign")) == 1 else 1
	else:
		if result.x != 0:
			result.x = 0
		else:
			result.x = -1
			var x_roll := rng.draw(3, StringName(tag_prefix + ".x"))
			if x_roll == 1:
				result.x = 1
			elif x_roll == 2:
				result.x = 0
			result.y = -1
			var y_roll := rng.draw(3, StringName(tag_prefix + ".y"))
			if y_roll == 1:
				result.y = -1
			elif y_roll == 2:
				result.y = 1
			elif y_roll == 3:
				result.y = 0
	return result

static func _footprints_are_adjacent(first: Array[Vector2i], second: Array[Vector2i]) -> bool:
	if first.is_empty() or second.is_empty():
		return false
	for first_cell: Vector2i in first:
		for second_cell: Vector2i in second:
			var delta := second_cell - first_cell
			if delta != Vector2i.ZERO and absi(delta.x) <= 1 and absi(delta.y) <= 1:
				return true
	return false

func _level_spell_points(character: CharacterState, caste: CasteDefinition, rng: RealmzRng) -> int:
	if character.level <= 1 or character.spellcaster_type < 1:
		return 0
	var rows := caste.spellcaster_rows()
	var row_index := character.spellcaster_type - 1
	if row_index >= rows.size() or rows[row_index].y <= 0 or rows[row_index].y > character.level:
		return 0
	if character.spellcaster_type == 1:
		return character.level + rng.draw(maxi(1, character.knowledge + int(float(character.judgment) / 2.0)), &"character.level.spell-points")
	return character.level + rng.draw(maxi(1, character.judgment + int(float(character.knowledge) / 2.0)), &"character.level.spell-points")

func character_item_spell_unavailable_reason(state: GameState, content: RealmzContent, caster_id: String) -> String:
	if state == null or state.combat == null or state.combat.active_actor_id() != caster_id:
		return "Only the active character may use an item."
	var caster := state.party.character_by_id(caster_id)
	if caster == null or caster.inventory().is_empty():
		return "The active character carries no items."
	for instance: ItemInstance in caster.inventory():
		var item := content.item_by_id(instance.definition_id)
		var spell := content.spell_by_classic_id(item.special_2) if item != null else null
		if item != null and spell != null:
			var probe := probe_character_item_spell(state, content, caster_id, caster_id if spell.target_type == 5 else "", instance.id)
			if not probe.allowed:
				return probe.reason_text
	return "No carried item has a supported Classic combat use."

func projectile_target_is_valid(combat: CombatState, content: RealmzContent, actor_id: String, target_id: String, maximum_range: int, require_line_of_sight: bool = true) -> bool:
	if combat == null or content == null or combat.battlefield == null:
		return false
	var terrain_set := _battle_terrain_set(content, combat.battlefield)
	return terrain_set != null and _rules.battlefield.projectile_target_is_valid(combat.battlefield, terrain_set, actor_id, target_id, maximum_range, require_line_of_sight)

func probe_edge_retreat(combat: CombatState, actor_id: String, destination: Vector2i):
	if combat == null or combat.completed or combat.battlefield == null or combat.active_actor_id() != actor_id or not combat.battlefield.has_actor(actor_id):
		return CombatRetreatProbeType.blocked(&"invalid_combat_actor", "The active character is unavailable.")
	var origin := combat.battlefield.actor_position(actor_id)
	var direction := destination - origin
	if direction == Vector2i.ZERO or absi(direction.x) > 1 or absi(direction.y) > 1:
		return CombatRetreatProbeType.blocked(&"invalid_direction", "Battlefield-edge retreat requires one adjacent movement direction.")
	if destination.x >= 2 and destination.y >= 2 and destination.x <= 87 and destination.y <= 87:
		return CombatRetreatProbeType.blocked(&"not_battlefield_edge", "This movement does not enter Castle's retreat band.")
	var forced := origin.x < 1 or origin.y < 1 or origin.x > 88 or origin.y > 88
	return CombatRetreatProbeType.permitted(127, forced)

func retreat_character(state: GameState, content: RealmzContent, actor_id: String, mode: StringName, destination: Vector2i, rng: RealmzRng) -> CombatFlowResult:
	var combat := state.combat
	if combat == null or combat.completed or combat.battlefield == null or combat.active_actor_id() != actor_id:
		return CombatFlowResult.failed(&"invalid_combat_actor", "The active character cannot retreat.")
	var actor := state.party.character_by_id(actor_id)
	if actor == null:
		return CombatFlowResult.failed(&"invalid_combat_actor", "The active character cannot retreat.")
	var probe: Variant = probe_character_retreat(combat, state.party.characters(), actor_id) if mode == &"explicit" else probe_edge_retreat(combat, actor_id, destination) if mode == &"edge" else null
	if probe == null:
		return CombatFlowResult.failed(&"invalid_retreat_mode", "The retreat route is unavailable.")
	if not probe.allowed:
		return CombatFlowResult.failed(probe.reason, probe.reason_text)
	if not combat.mark_character_retreated(actor.id):
		return CombatFlowResult.failed(&"invalid_retreat_state", "The active character's Escape state could not be recorded.")
	combat.battlefield.remove_character(actor.id)
	combat.set_guarding(actor.id, false)
	combat.clear_active_turn()
	actor.attacks_remaining = 0
	actor.movement = 0
	actor.prestige_penalty = _rules.arithmetic.signed_32(actor.prestige_penalty + 200)
	var events: Array[DomainEvent] = [DomainEvent.new(&"combatant_retreated", {"actorId": actor.id, "mode": String(mode), "forced": probe.forced, "prestigePenalty": 200, "nearestEnemyRange": probe.nearest_enemy_range, "source": "classic"})]
	if not _has_loyal_battlefield_character(state):
		_complete_battle(state, content, &"retreated", events)
		return CombatFlowResult.succeeded(events, true)
	_advance_turn(state, rng, events)
	_process_monster_turns(state, content, rng, events)
	return CombatFlowResult.succeeded(events, state.combat.completed)

func move_character(state: GameState, content: RealmzContent, actor_id: String, destination: Vector2i, rng: RealmzRng, auto_switch_to_melee: bool = false) -> CombatFlowResult:
	var combat := state.combat
	if combat == null or combat.completed or rng == null:
		return CombatFlowResult.failed(&"no_active_battle", "No Realmz battle is accepting tactical movement.")
	if combat.pending_reaction != null or combat.pending_monster_attack != null:
		return CombatFlowResult.failed(&"combat_reaction_pending", "The previous Classic combat reaction must finish before another movement command.")
	if combat.active_actor_id() != actor_id:
		return CombatFlowResult.failed(&"wrong_combat_actor", "Combat movement actor '%s' does not own the current turn." % actor_id)
	var actor := state.party.character_by_id(actor_id)
	if actor == null or actor.current_health <= 0 or actor.traitor or combat.battlefield == null:
		return CombatFlowResult.failed(&"invalid_combat_actor", "The current combat actor or battlefield is unavailable.")
	var terrain_set := _battle_terrain_set(content, combat.battlefield)
	if terrain_set == null:
		return CombatFlowResult.failed(&"missing_battle_terrain", "The active battlefield has no validated Classic terrain catalog.")
	var origin := combat.battlefield.actor_position(actor_id)
	var direction := destination - origin
	var available_movement := actor.maximum_movement if combat.active_turn == null else actor.movement
	var probe := _rules.battlefield.probe_step(combat.battlefield, terrain_set, actor_id, direction, available_movement)
	var contact_target_id := _hostile_contact_target_id(state, actor.id, probe.occupant_id) if probe.reason == &"occupied" else ""
	var automatic_actor := _processing_auto or actor.traitor or actor.conditions.is_active(ConditionRules.ANIMATED)
	var should_auto_switch := false
	if not contact_target_id.is_empty() and combat.character_weapon_mode(actor.id) != &"melee":
		if not auto_switch_to_melee or automatic_actor or not _classic_projectile_uses_point_blank_auto_switch(actor, content):
			return CombatFlowResult.failed(&"melee_weapon_mode_required", "Switch to the melee weapon before attacking an occupied hostile footprint.")
		should_auto_switch = true
	if not probe.allowed and contact_target_id.is_empty():
		return CombatFlowResult.failed(probe.reason, _movement_failure_message(probe))
	if not contact_target_id.is_empty():
		var equipment := _rules.inventory.combat_equipment(actor, content.item_definitions())
		if not equipment.valid:
			return CombatFlowResult.failed(equipment.error_code, equipment.error_message)
	_prepare_character_turn(combat, actor)
	combat.pending_reaction = CombatReactionState.new(CombatReactionState.CHARACTER_MOVE, actor.id, origin, destination, 3 if not contact_target_id.is_empty() else probe.movement_cost)
	combat.pending_reaction.auto_switch_to_melee = should_auto_switch
	var origin_hostiles := _hostile_adjacent_ids(state, actor.id)
	combat.pending_reaction.set_origin_hostiles(origin_hostiles)
	combat.pending_reaction.set_phase(CombatReactionState.GUARD_BEFORE, _guarding_actor_ids(state, origin_hostiles))
	var events: Array[DomainEvent] = []
	var reaction_result := _continue_pending_reaction(state, content, rng, events)
	if reaction_result == REACTION_MOVER_DEFEATED:
		if combat.active_actor_id() == actor.id:
			_advance_turn(state, rng, events)
		if _finish_if_resolved(state, content, events):
			return CombatFlowResult.succeeded(events, true)
		_process_monster_turns(state, content, rng, events)
	return CombatFlowResult.succeeded(events, state.combat.completed)

func _classic_projectile_uses_point_blank_auto_switch(actor: CharacterState, content: RealmzContent) -> bool:
	var equipment := _rules.inventory.combat_equipment(actor, content.item_definitions())
	if not equipment.valid or equipment.missile_weapon == null:
		return false
	var projectile_item := equipment.missile_weapon
	if projectile_item.special_2 <= 1100:
		return false
	var spell := content.spell_by_classic_id(absi(projectile_item.special_2))
	return spell != null and spell.spell_class == 9 and spell.damage_type == 9

func _continue_pending_reaction(state: GameState, content: RealmzContent, rng: RealmzRng, events: Array[DomainEvent]) -> int:
	var combat := state.combat
	var operation_guard := 256
	while combat != null and combat.pending_reaction != null and operation_guard > 0:
		var reaction := combat.pending_reaction
		if reaction.mover_killed or not _combatant_is_alive(state, reaction.mover_id):
			reaction.mover_killed = true
			combat.pending_reaction = null
			return REACTION_MOVER_DEFEATED
		if reaction.has_next_attacker():
			var attacker_id := reaction.take_next_attacker()
			var attack_result := _resolve_reaction_attack(state, content, attacker_id, reaction, rng, events)
			if attack_result != REACTION_COMPLETED:
				if attack_result == REACTION_MOVER_DEFEATED:
					combat.pending_reaction = null
				return attack_result
			operation_guard -= 1
			continue
		match reaction.phase:
			CombatReactionState.GUARD_BEFORE:
				if reaction.kind == CombatReactionState.CHARACTER_MOVE:
					var contact_target_id := _hostile_contact_target_id(state, reaction.mover_id, reaction.destination)
					if not contact_target_id.is_empty():
						if reaction.auto_switch_to_melee and combat.character_weapon_mode(reaction.mover_id) != &"melee":
							if not combat.set_character_weapon_mode(reaction.mover_id, &"melee"):
								combat.pending_reaction = null
								events.append(DomainEvent.new(&"combat_contact_attack_failed", {"actorId": reaction.mover_id, "targetId": contact_target_id, "reason": "invalid_weapon_mode"}))
								return REACTION_COMPLETED
							events.append(DomainEvent.new(&"sound_requested", {"soundId": 141, "waitForCompletion": false, "source": "classic-auto-weapon-switch"}))
							events.append(DomainEvent.new(&"combat_weapon_mode_changed", {"actorId": reaction.mover_id, "mode": "melee", "source": "classic-auto-weapon-switch"}))
						combat.pending_reaction = null
						var contact_result := submit_action(state, content, reaction.mover_id, &"attack", contact_target_id, rng)
						if not contact_result.ok:
							events.append(DomainEvent.new(&"combat_contact_attack_failed", {"actorId": reaction.mover_id, "targetId": contact_target_id, "reason": String(contact_result.error_code)}))
							return REACTION_COMPLETED
						events.append_array(contact_result.events)
						return REACTION_COMPLETED
					reaction.auto_switch_to_melee = false
					reaction.set_phase(CombatReactionState.WITHDRAWAL, _withdrawal_hostiles(state, reaction))
				else:
					if not _commit_reaction_move(state, content, reaction, events):
						combat.pending_reaction = null
						return REACTION_MOVER_DEFEATED
			CombatReactionState.WITHDRAWAL:
				if not _commit_reaction_move(state, content, reaction, events):
					combat.pending_reaction = null
					return REACTION_MOVER_DEFEATED
			CombatReactionState.GUARD_AFTER:
				combat.pending_reaction = null
				return REACTION_COMPLETED
		operation_guard -= 1
	if operation_guard == 0:
		events.append(DomainEvent.new(&"combat_reaction_failed", {"reason": "reaction-budget-exhausted"}))
		if combat != null:
			combat.pending_reaction = null
	return REACTION_COMPLETED

func _commit_reaction_move(state: GameState, content: RealmzContent, reaction: CombatReactionState, events: Array[DomainEvent]) -> bool:
	var combat := state.combat
	if combat == null or combat.battlefield == null or not _combatant_is_alive(state, reaction.mover_id) or combat.battlefield.actor_position(reaction.mover_id) != reaction.origin:
		return false
	var movement_remaining := 0
	if reaction.kind == CombatReactionState.CHARACTER_MOVE:
		if state.party.character_by_id(reaction.mover_id) == null:
			return false
	else:
		if combat.active_turn == null or combat.active_turn.actor_id != reaction.mover_id:
			return false
	if not combat.battlefield.move_actor(reaction.mover_id, reaction.destination):
		return false
	if reaction.kind == CombatReactionState.CHARACTER_MOVE:
		var character := state.party.character_by_id(reaction.mover_id)
		character.movement = maxi(0, character.movement - reaction.movement_cost)
		movement_remaining = character.movement
	else:
		combat.active_turn.movement_remaining = maxi(0, combat.active_turn.movement_remaining - reaction.movement_cost)
		movement_remaining = combat.active_turn.movement_remaining
	events.append(DomainEvent.new(&"combatant_moved", {
		"actorId": reaction.mover_id,
		"from": [reaction.origin.x, reaction.origin.y],
		"to": [reaction.destination.x, reaction.destination.y],
		"cost": reaction.movement_cost,
		"movementRemaining": movement_remaining,
		"automatic": reaction.kind != CombatReactionState.CHARACTER_MOVE,
	}))
	var terrain_set := _battle_terrain_set(content, combat.battlefield)
	var terrain := terrain_set.tile_by_id(combat.battlefield.terrain_at(reaction.destination)) if terrain_set != null else null
	if terrain != null and terrain.sound != 0:
		events.append(DomainEvent.new(&"sound_requested", {"soundId": terrain.sound, "waitForCompletion": terrain.sound < 0, "source": "classic-battle-movement"}))
	if reaction.kind == CombatReactionState.MONSTER_RETREAT and _retreating_monster_reached_edge(state, content, reaction.mover_id, reaction.destination, events):
		reaction.set_phase(CombatReactionState.GUARD_AFTER, [])
		return true
	reaction.set_phase(CombatReactionState.GUARD_AFTER, _guarding_hostiles(state, reaction.mover_id))
	return true

func _resolve_reaction_attack(state: GameState, content: RealmzContent, attacker_id: String, reaction: CombatReactionState, rng: RealmzRng, events: Array[DomainEvent]) -> int:
	var combat := state.combat
	if not _combatant_is_alive(state, attacker_id) or _combatant_is_helpless(state, attacker_id):
		return REACTION_COMPLETED
	combat.set_guarding(attacker_id, false)
	var action: StringName = &"withdrawal" if reaction.phase == CombatReactionState.WITHDRAWAL else &"guard"
	var behind := reaction.phase == CombatReactionState.WITHDRAWAL
	var character_attacker := state.party.character_by_id(attacker_id)
	if character_attacker != null:
		return _resolve_character_reaction(state, content, character_attacker, reaction.mover_id, action, behind, rng, events)
	var monster_attacker := combat.monster_by_id(attacker_id)
	if monster_attacker == null:
		return REACTION_COMPLETED
	return _resolve_monster_reaction(state, content, monster_attacker, reaction.mover_id, action, behind, rng, events)

func _resolve_character_reaction(state: GameState, content: RealmzContent, attacker: CharacterState, target_id: String, action: StringName, behind: bool, rng: RealmzRng, events: Array[DomainEvent]) -> int:
	var combat := state.combat
	combat.invalidate_undo()
	var equipment := _rules.inventory.combat_equipment(attacker, content.item_definitions())
	if not equipment.valid:
		events.append(DomainEvent.new(&"combat_reaction_failed", {"actorId": attacker.id, "targetId": target_id, "reason": String(equipment.error_code)}))
		return REACTION_COMPLETED
	var monster_target := combat.monster_by_id(target_id)
	if monster_target != null:
		var definition := content.monster_by_id(monster_target.definition_id)
		var reaction_resolution := _rules.combat.resolve_character_attack(attacker, equipment, monster_target, definition, rng, state.clock.day(), behind, true, combat.can_queue_fumbled_item())
		if reaction_resolution.total_damage() > 0:
			combat.mark_attacked(monster_target.id)
		if reaction_resolution.fumbled and not _commit_character_fumble(state, attacker, equipment, events):
			events.append(DomainEvent.new(&"combat_fumble_failed", {"actorId": attacker.id, "reason": "invalid-fumble-state"}))
		_append_character_attack_audio(events, attacker, equipment, reaction_resolution, &"monster")
		var reaction_event := _character_attack_event(attacker.id, monster_target.id, &"monster", reaction_resolution, equipment.melee_weapon != null)
		_append_reaction_identity(reaction_event, action, behind)
		events.append(reaction_event)
		if reaction_resolution.killed:
			combat.pending_reaction.mover_killed = true
			var death_macro_requested := _request_monster_death_macro(monster_target, definition, events)
			_remove_defeated_position(combat, monster_target.id, not death_macro_requested)
			return REACTION_DEATH_MACRO if death_macro_requested else REACTION_MOVER_DEFEATED
		return REACTION_COMPLETED
	var character_target := state.party.character_by_id(target_id)
	if character_target == null:
		return REACTION_COMPLETED
	var target_equipment := _rules.inventory.combat_equipment(character_target, content.item_definitions())
	if not target_equipment.valid:
		events.append(DomainEvent.new(&"combat_reaction_failed", {"actorId": attacker.id, "targetId": target_id, "reason": String(target_equipment.error_code)}))
		return REACTION_COMPLETED
	var resolution := _rules.combat.resolve_character_attack_character(attacker, equipment, character_target, target_equipment, rng, behind, true, combat.can_queue_fumbled_item())
	if resolution.total_damage() > 0:
		combat.mark_attacked(character_target.id)
	if resolution.fumbled and not _commit_character_fumble(state, attacker, equipment, events):
		events.append(DomainEvent.new(&"combat_fumble_failed", {"actorId": attacker.id, "reason": "invalid-fumble-state"}))
	_append_character_attack_audio(events, attacker, equipment, resolution, &"character")
	var event := _character_attack_event(attacker.id, character_target.id, &"character", resolution, equipment.melee_weapon != null)
	_append_reaction_identity(event, action, behind)
	events.append(event)
	if resolution.killed:
		combat.pending_reaction.mover_killed = true
		_mark_character_bleeding(state, character_target, true)
		_remove_defeated_position(combat, character_target.id, true)
		return REACTION_MOVER_DEFEATED
	return REACTION_COMPLETED

func _resolve_monster_reaction(state: GameState, content: RealmzContent, attacker: MonsterState, target_id: String, action: StringName, behind: bool, rng: RealmzRng, events: Array[DomainEvent]) -> int:
	var combat := state.combat
	combat.invalidate_undo()
	var definition := content.monster_by_id(attacker.definition_id)
	if definition == null:
		return REACTION_COMPLETED
	_prepare_monster_melee_weapon(attacker, definition, content)
	var weapon := content.item_by_id(attacker.weapon_id) if not attacker.weapon_id.is_empty() else null
	var character_target := state.party.character_by_id(target_id)
	if character_target != null:
		var race := content.race_by_id(character_target.race_id)
		var caste := content.caste_by_id(character_target.caste_id)
		var charm_bonus := 50 if state.party.conditions.is_active(ConditionRules.PARTY_CHARM_RESISTANCE) else 0
		var defender_equipment := _rules.inventory.combat_equipment(character_target, content.item_definitions())
		var defender_luck := defender_equipment.effective_luck if defender_equipment.valid else character_target.luck
		var defender_armor := defender_equipment.effective_armor if defender_equipment.valid else character_target.armor
		var reaction_context := MonsterAttackContext.new(weapon, state.clock.day(), behind, defender_luck, state.party.conditions.is_active(ConditionRules.PARTY_DRAGON_HIDE), defender_armor)
		var reaction_resolution := _rules.combat.resolve_monster_attack(attacker, definition, 0, character_target, race, caste, rng, charm_bonus, reaction_context, true)
		if reaction_resolution.total_damage() > 0:
			combat.mark_attacked(character_target.id)
		if reaction_resolution.fumbled:
			_commit_monster_fumble(attacker, events)
		if reaction_resolution.special_handled:
			_append_monster_special_events(events, attacker.id, character_target.id, &"character", reaction_resolution)
			if reaction_resolution.aging != null and reaction_resolution.aging.changed_group():
				events.append(DomainEvent.new(&"character_age_changed", reaction_resolution.aging.event_payload(character_target, race)))
				combat.pending_monster_attack = PendingMonsterAttack.new(attacker.id, character_target.id, action, reaction_resolution.damage, reaction_resolution.chance, reaction_resolution.roll, reaction_resolution.weapon_condition_index, reaction_resolution.weapon_condition_before, reaction_resolution.weapon_condition_after, reaction_resolution.physical_feedback_sound_id)
				return REACTION_WAITING
		_append_monster_physical_feedback(events, reaction_resolution.physical_feedback_sound_id)
		_append_monster_attack_audio(events, attacker, definition, 0, weapon, reaction_resolution, rng)
		var reaction_event := DomainEvent.new(&"combat_attack_resolved", {"actorId": attacker.id, "targetId": character_target.id, "targetKind": "character", "action": String(action), "attackIndex": 0, "hit": reaction_resolution.hit, "damage": reaction_resolution.total_damage(), "defeated": reaction_resolution.killed, "chance": reaction_resolution.chance, "roll": reaction_resolution.roll})
		_append_physical_result_effect(reaction_event, reaction_resolution.hit, weapon != null)
		_append_reaction_identity(reaction_event, action, behind)
		events.append(reaction_event)
		if reaction_resolution.killed:
			combat.pending_reaction.mover_killed = true
			_mark_character_bleeding(state, character_target, true)
			_remove_defeated_position(combat, character_target.id, true)
			return REACTION_MOVER_DEFEATED
		return REACTION_COMPLETED
	var monster_target := combat.monster_by_id(target_id)
	if monster_target == null:
		return REACTION_COMPLETED
	var target_definition := content.monster_by_id(monster_target.definition_id)
	var context := MonsterAttackContext.new(weapon, state.clock.day(), behind)
	var resolution := _rules.combat.resolve_monster_attack_monster(attacker, definition, 0, monster_target, target_definition, rng, context, true)
	if resolution.total_damage() > 0:
		combat.mark_attacked(monster_target.id)
	if resolution.fumbled:
		_commit_monster_fumble(attacker, events)
	if resolution.special_handled:
		_append_monster_special_events(events, attacker.id, monster_target.id, &"monster", resolution)
	_append_monster_attack_audio(events, attacker, definition, 0, weapon, resolution, rng)
	var event := DomainEvent.new(&"combat_attack_resolved", {"actorId": attacker.id, "targetId": monster_target.id, "targetKind": "monster", "action": String(action), "attackIndex": 0, "hit": resolution.hit, "damage": resolution.total_damage(), "defeated": resolution.killed, "chance": resolution.chance, "roll": resolution.roll})
	_append_physical_result_effect(event, resolution.hit, weapon != null)
	_append_reaction_identity(event, action, behind)
	events.append(event)
	if resolution.killed:
		combat.pending_reaction.mover_killed = true
		var death_macro_requested := _request_monster_death_macro(monster_target, target_definition, events)
		_remove_defeated_position(combat, monster_target.id, not death_macro_requested)
		return REACTION_DEATH_MACRO if death_macro_requested else REACTION_MOVER_DEFEATED
	return REACTION_COMPLETED

func _guarding_hostiles(state: GameState, mover_id: String, anchor_override: Vector2i = Vector2i(-1, -1)) -> Array[String]:
	var result: Array[String] = []
	for attacker_id: String in _hostile_adjacent_ids(state, mover_id, anchor_override):
		if state.combat.is_guarding(attacker_id) and not _combatant_is_helpless(state, attacker_id):
			result.append(attacker_id)
	return result

func _withdrawal_hostiles(state: GameState, reaction: CombatReactionState) -> Array[String]:
	var result: Array[String] = []
	if _combatant_is_invisible(state, reaction.mover_id):
		return result
	var after := _rules.battlefield.adjacent_actor_ids(state.combat.battlefield, reaction.mover_id, reaction.destination)
	for attacker_id: String in reaction.origin_hostiles():
		if not after.has(attacker_id) and not _combatant_is_helpless(state, attacker_id):
			result.append(attacker_id)
	return result

func _guarding_actor_ids(state: GameState, actor_ids: Array[String]) -> Array[String]:
	var result: Array[String] = []
	for actor_id: String in actor_ids:
		if state.combat.is_guarding(actor_id) and not _combatant_is_helpless(state, actor_id):
			result.append(actor_id)
	return result

func _combatant_is_alive(state: GameState, actor_id: String) -> bool:
	var character := state.party.character_by_id(actor_id)
	if character != null:
		return character.current_health > 0
	var monster := state.combat.monster_by_id(actor_id) if state.combat != null else null
	return monster != null and monster.current_health > 0

func _combatant_is_helpless(state: GameState, actor_id: String) -> bool:
	var character := state.party.character_by_id(actor_id)
	if character != null:
		return character.conditions.is_active(ConditionRules.HELPLESS)
	var monster := state.combat.monster_by_id(actor_id) if state.combat != null else null
	return monster != null and monster.conditions.is_active(ConditionRules.HELPLESS)

func _combatant_is_invisible(state: GameState, actor_id: String) -> bool:
	var character := state.party.character_by_id(actor_id)
	if character != null:
		return character.conditions.is_active(ConditionRules.INVISIBLE)
	var monster := state.combat.monster_by_id(actor_id) if state.combat != null else null
	return monster != null and monster.conditions.is_active(ConditionRules.INVISIBLE)

func cause_active_fumble(state: GameState, content: RealmzContent, actor_id: String) -> CombatFlowResult:
	if state == null or content == null or state.combat == null or state.combat.completed:
		return CombatFlowResult.failed(&"no_active_battle", "No Realmz battle can receive a fumble operation.")
	if actor_id.is_empty():
		actor_id = state.combat.active_actor_id()
	if actor_id != state.combat.active_actor_id():
		return CombatFlowResult.failed(&"invalid_fumble_actor", "Classic opcode 122 can affect only the active physical combatant.")
	if state.combat.active_turn == null or not state.combat.active_turn.physical_action_committed:
		return CombatFlowResult.succeeded([DomainEvent.new(&"combat_fumble_skipped", {"combatantId": actor_id, "reason": "no-physical-action", "source": "classic"})])
	var events: Array[DomainEvent] = []
	var character := state.party.character_by_id(actor_id)
	# Castle's outer q[up] < 10 guard excludes monster initiative IDs (10+).
	# The monster branch nested below that guard is therefore unreachable.
	if character == null:
		return CombatFlowResult.succeeded([DomainEvent.new(&"combat_fumble_skipped", {"combatantId": actor_id, "reason": "not-party-actor", "source": "classic"})])
	var equipment := _rules.inventory.combat_equipment(character, content.item_definitions())
	if not equipment.valid:
		return CombatFlowResult.failed(equipment.error_code, equipment.error_message)
	if not equipment.is_armed():
		return CombatFlowResult.succeeded([DomainEvent.new(&"combat_fumble_skipped", {"combatantId": actor_id, "reason": "unarmed", "source": "classic"})])
	if not equipment.melee_weapon.cursed_item_id.is_empty():
		return CombatFlowResult.succeeded([DomainEvent.new(&"combat_fumble_skipped", {"combatantId": actor_id, "reason": "cursed-weapon", "source": "classic"})])
	if not state.combat.can_queue_fumbled_item():
		return CombatFlowResult.succeeded([DomainEvent.new(&"combat_fumble_skipped", {"combatantId": actor_id, "reason": "queue-full", "source": "classic"})])
	if not _commit_character_fumble(state, character, equipment, events):
		return CombatFlowResult.failed(&"invalid_fumble_state", "The active character's melee weapon could not enter the recovery queue.")
	return CombatFlowResult.succeeded(events)

func probe_character_item_spell(state: GameState, content: RealmzContent, caster_id: String, target_id: String, instance_id: String) -> CombatSpellCastProbe:
	if state == null or content == null:
		return CombatSpellCastProbe.blocked(&"invalid_item_turn", "Item use requires an active game session.")
	var combat := state.combat
	if combat == null or combat.completed or combat.battlefield == null or combat.active_actor_id() != caster_id:
		return CombatSpellCastProbe.blocked(&"invalid_item_turn", "Only the active character may use an item in combat.")
	if not combat.pending_spell_death_macro_id().is_empty():
		return CombatSpellCastProbe.blocked(&"spell_death_macro_pending", "A spell-triggered monster death macro must complete before another combat action.")
	var caster := state.party.character_by_id(caster_id)
	var instance := _inventory_instance(caster, instance_id)
	var item: ItemDefinition = null if instance == null else content.item_by_id(instance.definition_id)
	var spell: SpellDefinition = null if item == null else content.spell_by_classic_id(item.special_2)
	var use_probe := _rules.inventory.classic_spell_item_probe(caster, instance, item, spell, content.race_by_id(caster.race_id) if caster != null else null, content.caste_by_id(caster.caste_id) if caster != null else null, true)
	if not use_probe.allowed:
		return CombatSpellCastProbe.blocked(_item_use_reason_code(instance, item, spell), use_probe.reason)
	var power_level := absi(item.special_1)
	if power_level == 8:
		return CombatSpellCastProbe.blocked(&"random_item_power_requires_staging", "A random-power item requires a source-backed staged targeting continuation.")
	if spell.target_type not in [1, 2, 5, 9, 10, 12]:
		return CombatSpellCastProbe.blocked(&"unsupported_combat_item_targeting", "This item's Classic combat target shape is not implemented yet.")
	var healing_spell := _is_source_backed_combat_healing_spell(spell)
	var ordinary_spell := spell.special == 0 and absi(spell.damage_type) >= 1 and absi(spell.damage_type) <= 6 and absi(spell.spell_class) != 9
	if not ordinary_spell and not healing_spell:
		return CombatSpellCastProbe.blocked(&"unsupported_combat_item_effect", "This item's Classic combat spell effect is not implemented yet.")
	if spell.queue_icon != 0:
		return CombatSpellCastProbe.blocked(&"queued_spell_field_unresolved", "This item creates a persistent battlefield field whose collision lifecycle is not implemented.")
	if spell.target_type in [9, 10, 12]:
		var group_target_count := 0
		for character: CharacterState in state.party.characters():
			if character.current_health > 0 and combat.battlefield.has_actor(character.id) and _group_target_matches(spell.target_type, character.traitor, caster.traitor):
				group_target_count += 1
		for monster: MonsterState in combat.monsters():
			if monster.current_health <= 0 or not combat.battlefield.has_actor(monster.id) or not _group_target_matches(spell.target_type, monster.traitor, caster.traitor):
				continue
			if content.monster_by_id(monster.definition_id) == null:
				return CombatSpellCastProbe.blocked(&"spell_target_unavailable", "An item spell target has no immutable monster definition.")
			group_target_count += 1
		if group_target_count == 0:
			return CombatSpellCastProbe.blocked(&"invalid_item_target", "The item spell has no available group target.")
		return CombatSpellCastProbe.permitted()
	var effective_target_id := caster_id if spell.target_type == 5 else target_id
	if _spell_target_selection(state, content, effective_target_id) == null:
		return CombatSpellCastProbe.blocked(&"invalid_item_target", "The selected combatant is unavailable.")
	if not _spell_actor_target_is_valid(state, content, caster_id, effective_target_id, spell, power_level):
		return CombatSpellCastProbe.blocked(&"item_target_unavailable", "The target is outside the item's Classic spell range or line of sight.")
	return CombatSpellCastProbe.permitted()

func use_spell_item(state: GameState, content: RealmzContent, caster_id: String, target_id: String, instance_id: String, rng: RealmzRng) -> CombatFlowResult:
	var probe := probe_character_item_spell(state, content, caster_id, target_id, instance_id)
	if not probe.allowed:
		return CombatFlowResult.failed(probe.reason, probe.reason_text)
	var caster := state.party.character_by_id(caster_id)
	var instance := _inventory_instance(caster, instance_id)
	var item := content.item_by_id(instance.definition_id)
	var spell := content.spell_by_classic_id(item.special_2)
	var power_level := absi(item.special_1)
	if not _rules.inventory.use_charge(caster, instance.id, item):
		return CombatFlowResult.failed(&"item_charge_commit_failed", "The validated item charge could not be committed.")
	_prepare_character_turn(state.combat, caster)
	state.combat.invalidate_undo()
	var cast_level := spell.classic_tier()
	var result: CombatFlowResult
	if spell.target_type in [9, 10, 12]:
		var character_targets: Array[CharacterState] = []
		var monster_targets: Array[MonsterState] = []
		var monster_definitions: Array[MonsterDefinition] = []
		for character: CharacterState in state.party.characters():
			if character.current_health > 0 and state.combat.battlefield.has_actor(character.id) and _group_target_matches(spell.target_type, character.traitor, caster.traitor):
				character_targets.append(character)
		for monster: MonsterState in state.combat.monsters():
			if monster.current_health <= 0 or not state.combat.battlefield.has_actor(monster.id) or not _group_target_matches(spell.target_type, monster.traitor, caster.traitor):
				continue
			var definition := content.monster_by_id(monster.definition_id)
			if definition == null:
				return CombatFlowResult.failed(&"spell_target_unavailable", "An item spell target has no immutable monster definition.")
			monster_targets.append(monster)
			monster_definitions.append(definition)
		var group := _rules.magic.resolve_character_group_spell(caster, character_targets, monster_targets, monster_definitions, spell, power_level, cast_level, rng, false, false)
		if group == null or not group.cast:
			return CombatFlowResult.failed(&"item_spell_failed", "The item spell could not be resolved.")
		result = _commit_character_multi_spell(state, content, caster, spell, power_level, cast_level, group, rng, INVALID_COORDINATE, 0, "classic-item", instance_id, false)
	else:
		var effective_target_id := caster_id if spell.target_type == 5 else target_id
		var selection := _spell_target_selection(state, content, effective_target_id)
		var targeted := _rules.magic.resolve_character_targeted_spell(caster, selection, spell, power_level, cast_level, rng, false)
		if targeted == null or not targeted.cast:
			return CombatFlowResult.failed(&"item_spell_failed", "The item spell could not be resolved.")
		result = _commit_character_multi_spell(state, content, caster, spell, power_level, cast_level, targeted, rng, INVALID_COORDINATE, 0, "classic-item", instance_id, false)
	if not result.ok:
		return result
	var events: Array[DomainEvent] = [_item_used_event(caster_id, instance_id, item, spell, power_level, caster)]
	var native_sound_id := item.sound_id + 600
	if item.sound_id != 0:
		events.append(DomainEvent.new(&"sound_requested", {"soundId": absi(native_sound_id), "waitForCompletion": native_sound_id < 0, "source": "classic-item"}))
	events.append_array(result.events)
	result.events = events
	return result

func character_item_spell_options(state: GameState, content: RealmzContent, caster_id: String) -> Array[CombatItemOptionView]:
	var result: Array[CombatItemOptionView] = []
	if state == null or state.combat == null or state.combat.active_actor_id() != caster_id:
		return result
	var caster := state.party.character_by_id(caster_id)
	if caster == null:
		return result
	for instance: ItemInstance in caster.inventory():
		var item := content.item_by_id(instance.definition_id)
		var spell := content.spell_by_classic_id(item.special_2) if item != null else null
		if item == null or spell == null or absi(item.special_1) == 8:
			continue
		if spell.target_type in [9, 10, 12]:
			if probe_character_item_spell(state, content, caster_id, "", instance.id).allowed:
				result.append(CombatItemOptionView.new(instance, item, spell, absi(item.special_1), null, _group_spell_target_label(spell.target_type), &"automatic"))
			continue
		if spell.target_type == 5:
			if probe_character_item_spell(state, content, caster_id, caster_id, instance.id).allowed:
				result.append(CombatItemOptionView.new(instance, item, spell, absi(item.special_1), _spell_target_view(state, content, caster_id)))
			continue
		for target: CombatSpellTargetView in _character_actor_spell_candidates(state, content, caster, spell, absi(item.special_1)):
			if probe_character_item_spell(state, content, caster_id, target.id, instance.id).allowed:
				result.append(CombatItemOptionView.new(instance, item, spell, absi(item.special_1), target))
	return result

func has_line_of_sight(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, from_actor_id: String, to_actor_id: String) -> bool:
	if battlefield == null or terrain_set == null or not battlefield.has_actor(from_actor_id) or not battlefield.has_actor(to_actor_id):
		return false
	return has_line_of_sight_to_coordinate(battlefield, terrain_set, from_actor_id, battlefield.actor_position(to_actor_id))

func coordinate_target_is_valid(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, actor_id: String, destination: Vector2i, maximum_range: int, require_line_of_sight: bool = true) -> bool:
	var distance := classic_coordinate_range(battlefield, actor_id, destination)
	return distance >= 0 and distance <= maximum_range and (not require_line_of_sight or has_line_of_sight_to_coordinate(battlefield, terrain_set, actor_id, destination))

func projectile_target_is_valid(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, first_actor_id: String, second_actor_id: String, maximum_range: int, require_line_of_sight: bool = true) -> bool:
	var distance := classic_range(battlefield, first_actor_id, second_actor_id)
	return distance >= 0 and distance <= maximum_range and (not require_line_of_sight or has_line_of_sight(battlefield, terrain_set, first_actor_id, second_actor_id))

func create_character(character_id: String, character_name: String, race: RaceDefinition, caste: CasteDefinition, gender: int, rng: RealmzRng, include_initial_items: bool = true, starting_level: int = 1) -> CharacterState:
	if race == null or caste == null or rng == null or not STARTING_LEVELS.has(starting_level):
		return null
	var attributes: Array[int] = []
	for index: int in ATTRIBUTE_COUNT:
		var rolled := rng.draw_between(1, 18, StringName("character.create.attribute.%d" % index)) + race.attribute_bonus(index) + caste.attribute_bonus(index)
		rolled = clampi(rolled, caste.attribute_minimum(index), caste.attribute_maximum(index))
		rolled = clampi(rolled, race.attribute_minimum(index), race.attribute_maximum(index))
		attributes.append(rolled)
	# Castle's seven-iteration loop aliases its final profile offset back to Luck,
	# consumes the roll, and never assigns the value. The draw is observable in
	# every later creation roll, so the deterministic session must retain it.
	rng.draw_between(1, 18, &"character.create.attribute.discarded")
	if gender == 2:
		attributes[0] -= 1
		attributes[3] += 1
		attributes[2] += 1
	else:
		attributes[0] += 1
		attributes[3] -= 1
	var save_values: Array[int] = []
	var special_values: Array[int] = []
	for index: int in 8:
		save_values.append(50 + race.save_bonus(index) + caste.save_bonus(index))
		special_values.append(race.hit_modifier(index))
	var age_group_count := clampi(caste.minimum_age_group, 1, 5)
	for age_index: int in age_group_count:
		var age_change := race.age_change(age_index)
		for attribute_index: int in ATTRIBUTE_COUNT:
			attributes[attribute_index] += age_change[attribute_index]
		for save_index: int in 7:
			save_values[save_index] += age_change[8 + save_index]
	for index: int in ATTRIBUTE_COUNT:
		attributes[index] = clampi(attributes[index], caste.attribute_minimum(index), caste.attribute_maximum(index))
		attributes[index] = clampi(attributes[index], race.attribute_minimum(index), race.attribute_maximum(index))
	for threshold: int in [80, 90, 95]:
		if rng.draw(100, StringName("character.create.special-bonus.%d.roll" % threshold)) > threshold:
			var special_index := rng.draw_between(0, 7, StringName("character.create.special-bonus.%d.index" % threshold))
			special_values[special_index] += 1
	var vitality_bonus := maxi(0, attributes[4] - 16)
	vitality_bonus = mini(vitality_bonus, caste.maximum_stamina_bonus)
	var maximum_health := rng.draw(maxi(1, caste.initial_stamina_die()), &"character.create.stamina") + vitality_bonus
	var result := CharacterState.new(character_id, character_name, maximum_health, maximum_health)
	result.race_id = race.id
	result.caste_id = caste.id
	result.gender = gender
	result.prestige_penalty = 10 * (starting_level - 1) * (starting_level - 1)
	result.experience = -caste.victory_threshold(starting_level - 1)
	result.age_group = age_group_count
	result.brawn = attributes[0]
	result.knowledge = attributes[1]
	result.judgment = attributes[2]
	result.agility = attributes[3]
	result.vitality = attributes[4]
	result.luck = attributes[5]
	var strength := strength_bonuses(result.brawn, caste.maximum_damage_bonus())
	result.to_hit = caste.initial_to_hit() + strength.to_hit_bonus
	result.damage_bonus = strength.damage_bonus
	result.dodge = 2 * result.agility + caste.initial_dodge()
	result.armor = 0
	if result.agility > 14:
		result.armor -= 2 * (14 - result.agility)
	result.magic_resistance = int(float(result.knowledge + result.judgment) / 10.0) * caste.magic_resistance_multiplier + race.magic_resistance
	result.two_hand = clampi(race.two_hand_bonus + caste.two_hand_bonus, 0, 100)
	result.missile = race.missile_bonus + caste.initial_missile() if caste.can_use_missile else 0
	result.hand_to_hand = caste.initial_hand_to_hand()
	result.maximum_movement = race.base_movement + caste.movement_bonus
	result.movement = result.maximum_movement
	result.normal_attacks = mini(race.base_attacks + caste.bonus_attacks, 2 * race.maximum_attacks)
	result.attacks_remaining = result.normal_attacks
	result.maximum_load = maxi(500, result.brawn * result.brawn * 20)
	result.money.gold = maxi(0, caste.start_money)
	var selected_age_range := race.age_range(clampi(caste.minimum_age_group - 1, 0, 4))
	if selected_age_range.y >= selected_age_range.x and selected_age_range.y > 0:
		result.age_days = rng.draw_between(selected_age_range.x, selected_age_range.y, &"character.create.age") * 365
	for index: int in 8:
		result.set_save_value(index, save_values[index])
		result.set_special_value(index, special_values[index])
	for index: int in ConditionSet.CHARACTER_COUNT:
		var starting_condition := race.condition_level(index)
		if caste.condition_level(index) == 1:
			starting_condition = -1
		result.conditions.set_value(index, starting_condition)
	_configure_spellcaster(result, caste, rng, starting_level)
	_initialize_abilities(result, race, caste)
	for _index: int in starting_level - 1:
		if level_up(result, race, caste, rng) == null:
			return null
	if include_initial_items:
		add_initial_items(result, caste)
	return result

func add_initial_items(character: CharacterState, caste: CasteDefinition) -> bool:
	if character == null or caste == null or not character.inventory().is_empty():
		return false
	var items: Array[ItemInstance] = []
	for index: int in caste.start_items().size():
		var item_id := caste.start_items()[index]
		items.append(ItemInstance.new("%s.item.%d" % [character.id, index], item_id))
	character.set_inventory(items)
	return true

func infer_age_group(age_days: int, race: RaceDefinition) -> int:
	if race == null:
		return 0
	var age_years := floori(float(age_days) / 365.0)
	for index: int in 5:
		var authored_range := race.age_range(index)
		if age_years >= authored_range.x and age_years <= authored_range.y:
			return index + 1
	return 0

func ensure_age_group(character: CharacterState, race: RaceDefinition, caste: CasteDefinition = null) -> int:
	if character == null or race == null:
		return 0
	if character.age_group >= 1 and character.age_group <= 5:
		return character.age_group
	character.age_group = infer_age_group(character.age_days, race)
	if character.age_group == 0:
		character.age_group = clampi(caste.minimum_age_group if caste != null else 1, 1, 5)
	return character.age_group

func advance_age_days(character: CharacterState, race: RaceDefinition, caste: CasteDefinition, day_change: int) -> CharacterAgingResult:
	if character == null or race == null or caste == null:
		return null
	var previous_days := character.age_days
	var previous_group := ensure_age_group(character, race, caste)
	character.age_days = _signed_32(character.age_days + day_change)
	var target_group := infer_age_group(character.age_days, race)
	if target_group > character.age_group and character.age_group < 5:
		character.age_group += 1
		_apply_age_change(character, race, caste, character.age_group, 1)
		return CharacterAgingResult.new(previous_days, character.age_days, previous_group, character.age_group, 1, character.age_group)
	if target_group > 0 and target_group < character.age_group and character.age_group > 1:
		var erased_group := character.age_group
		_apply_age_change(character, race, caste, erased_group, -1)
		character.age_group -= 1
		return CharacterAgingResult.new(previous_days, character.age_days, previous_group, character.age_group, -1, erased_group)
	return CharacterAgingResult.new(previous_days, character.age_days, previous_group, character.age_group)

func battle_experience(character: CharacterState, race: RaceDefinition, share: int) -> int:
	if character == null or race == null:
		return 0
	if floori(float(character.age_days) / 365.0) >= race.max_age:
		return int(float(share) * 0.6666666)
	return share

func level_up(character: CharacterState, race: RaceDefinition, caste: CasteDefinition, rng: RealmzRng) -> LevelUpResult:
	if character == null or race == null or caste == null or rng == null:
		return null
	character.level += 1
	# Castle consumes this registration-era roll even though the open-source
	# registration branch no longer changes the character.
	rng.draw(100, &"character.level.registration-check")
	character.normal_attacks = race.base_attacks + caste.bonus_attacks
	for required_level: int in caste.attack_levels():
		if required_level > 0 and required_level <= character.level:
			character.normal_attacks += 1
	character.normal_attacks = mini(character.normal_attacks, 2 * race.maximum_attacks)
	character.attacks_remaining = character.normal_attacks
	for index: int in ConditionSet.CHARACTER_COUNT:
		if caste.condition_level(index) == character.level:
			var current_condition := character.conditions.value(index)
			character.conditions.set_value(index, -1 if current_condition > -1 else current_condition - 1)
	character.to_hit += caste.level_to_hit()
	character.dodge += caste.level_dodge()
	character.hand_to_hand += caste.level_hand_to_hand()
	if caste.level_missile() > 0:
		character.missile += rng.draw(caste.level_missile(), &"character.level.missile")
	character.spellcaster_type = _level_spellcaster_type(caste)
	var spell_gain := _level_spell_points(character, caste, rng)
	character.spell_points += spell_gain
	character.maximum_spell_points += spell_gain
	var vitality_bonus := mini(maxi(0, character.vitality - 16), caste.maximum_stamina_bonus)
	var stamina_gain := rng.draw(maxi(1, caste.level_stamina_die()), &"character.level.stamina") + vitality_bonus
	character.current_health += stamina_gain
	character.maximum_health += stamina_gain
	var magic_gain := 1 if rng.draw(100, &"character.level.magic-resistance") <= character.judgment + character.knowledge + character.vitality else 0
	character.magic_resistance += magic_gain
	for index: int in 14:
		var ability_die := caste.level_ability_die(index)
		if ability_die > 0:
			character.set_ability_value(index, character.ability_value(index) + rng.draw(ability_die, StringName("character.level.ability.%d" % index)))
	for index: int in 12:
		character.set_ability_value(index, clampi(character.ability_value(index), 0, 100))
	character.dodge = clampi(character.dodge, 0, 100)
	character.missile = clampi(character.missile, 0, 100)
	character.magic_resistance = clampi(character.magic_resistance, 0, 100)
	character.two_hand = clampi(character.two_hand, 0, 100)
	character.damage_bonus = clampi(character.damage_bonus, 0, 200)
	character.hand_to_hand = clampi(character.hand_to_hand, 0, 200)
	return LevelUpResult.new(stamina_gain, spell_gain, caste.level_to_hit(), magic_gain)

func spell_selection_total(character: CharacterState, caste: CasteDefinition) -> int:
	if character == null or caste == null or character.spellcaster_type < 1:
		return 0
	var start_level_sum := 0
	for row: Vector3i in caste.spellcaster_rows():
		start_level_sum += row.y
	var relative_level := character.level - (start_level_sum - 1)
	if relative_level < 1:
		return 0
	var bonus_attribute := character.judgment if character.spellcaster_type == 2 else character.knowledge
	var total := 3 * relative_level + int(relative_level * (relative_level - 1) / 2.0)
	if bonus_attribute > 15:
		total += relative_level * (bonus_attribute - 15)
	return total

func spell_selection_cost(spell: SpellDefinition) -> int:
	if spell == null:
		return 0
	var tier := spell.classic_tier()
	if tier < 0 or tier > 6:
		return 0
	var level := tier + 1
	return int(level * (level + 1) / 2.0)

func maximum_spell_selection_level(caste: CasteDefinition) -> int:
	if caste == null:
		return 0
	var result := 0
	for row: Vector3i in caste.spellcaster_rows():
		result += row.z
	return clampi(result, 0, 7)

func _configure_spellcaster(character: CharacterState, caste: CasteDefinition, rng: RealmzRng, effective_starting_level: int = 1) -> void:
	var rows := caste.spellcaster_rows()
	for index: int in mini(3, rows.size()):
		var row := rows[index]
		if row.y <= 0:
			continue
		character.spellcaster_type = index + 1
		character.maximum_spell_attacks = 1
		if effective_starting_level >= row.y:
			match character.spellcaster_type:
				1: character.maximum_spell_points = 4 + character.knowledge + rng.draw(maxi(1, character.judgment), &"character.create.spell-points")
				2: character.maximum_spell_points = 4 + character.judgment + rng.draw(maxi(1, character.knowledge), &"character.create.spell-points")
				3: character.maximum_spell_points = 10 + rng.draw(maxi(1, character.judgment + character.knowledge), &"character.create.spell-points")
	character.spell_points = character.maximum_spell_points

func _initialize_abilities(character: CharacterState, race: RaceDefinition, caste: CasteDefinition) -> void:
	for index: int in 14:
		var initial_value := caste.initial_ability_value(index)
		var ability := initial_value + race.ability_bonus(index) if initial_value != 0 else 0
		ability += _ability_attribute_modifier(STRENGTH_ABILITY_MODIFIERS, index, character.brawn) if initial_value != 0 else 0
		ability += _ability_attribute_modifier(AGILITY_ABILITY_MODIFIERS, index, character.agility) if initial_value != 0 else 0
		character.set_ability_value(index, ability)
	for index: int in 12:
		character.set_ability_value(index, clampi(character.ability_value(index), 0, 100))

func _ability_attribute_modifier(table: Dictionary, ability_index: int, attribute: int) -> int:
	if not table.has(ability_index):
		return 0
	var value_index := ABILITY_ATTRIBUTE_VALUES.find(attribute)
	if value_index < 0:
		return 0
	var values: Array = table[ability_index]
	return int(values[value_index])

func _level_spellcaster_type(caste: CasteDefinition) -> int:
	var rows := caste.spellcaster_rows()
	for index: int in mini(3, rows.size()):
		if rows[index].y > 0:
			return index + 1
	return 0

func _apply_age_change(character: CharacterState, race: RaceDefinition, caste: CasteDefinition, age_group: int, direction: int) -> void:
	var change := race.age_change(age_group - 1)
	if change.size() != 15:
		return
	var before_strength := strength_bonuses(character.brawn, caste.maximum_damage_bonus())
	character.to_hit = _signed_16(character.to_hit - before_strength.to_hit_bonus)
	character.damage_bonus = _signed_16(character.damage_bonus - before_strength.damage_bonus)
	character.brawn = _signed_16(character.brawn + direction * change[0])
	var after_strength := strength_bonuses(character.brawn, caste.maximum_damage_bonus())
	character.to_hit = _signed_16(character.to_hit + after_strength.to_hit_bonus)
	character.damage_bonus = _signed_16(character.damage_bonus + after_strength.damage_bonus)
	character.knowledge = _signed_16(character.knowledge + direction * change[1])
	character.judgment = _signed_16(character.judgment + direction * change[2])
	character.agility = _signed_16(character.agility + direction * change[3])
	character.vitality = _signed_16(character.vitality + direction * change[4])
	character.luck = _signed_16(character.luck + direction * change[5])
	character.magic_resistance = _signed_16(character.magic_resistance + direction * change[6])
	character.maximum_movement = maxi(2, _signed_16(character.maximum_movement + direction * change[7]))
	for save_index: int in 7:
		character.set_save_value_raw(save_index, _signed_16(character.save_value(save_index) + direction * change[8 + save_index]))

func recalculate_movement(character: CharacterState, race: RaceDefinition, movement_bonus: int = 0) -> int:
	character.carried_load = maxi(0, character.carried_load)
	character.maximum_load = maxi(500, character.brawn * character.brawn * 20)
	var movement := 1.0 + (float(character.maximum_load - character.carried_load) / float(character.maximum_load)) * float(race.base_movement)
	if character.conditions.is_active(2):
		movement -= character.conditions.value(2)
	if character.conditions.is_active(6):
		movement /= 2.0
	if character.conditions.is_active(23):
		movement *= 2.0
	character.maximum_movement = maxi(2, int(movement)) + movement_bonus
	character.movement = mini(character.movement, character.maximum_movement)
	return character.maximum_movement

static func _inventory_instance(character: CharacterState, instance_id: String) -> ItemInstance:
	if character == null:
		return null
	for instance: ItemInstance in character.inventory():
		if instance.id == instance_id:
			return instance
	return null

func classic_coordinate_range(battlefield: BattlefieldState, actor_id: String, destination: Vector2i) -> int:
	if battlefield == null or not battlefield.has_actor(actor_id) or not BattlefieldState.contains(destination):
		return -1
	return floori(Vector2(destination - battlefield.actor_position(actor_id)).length())

func roll_formation(battlefield: BattlefieldState, battle: BattleDefinition, rng: RealmzRng) -> Dictionary:
	if battlefield == null or battle == null or rng == null:
		return {}
	var direction := rng.draw(360, &"battle.setup.direction")
	var distance := rng.draw_classic(battle.distance, &"battle.setup.distance")
	var degree := float(direction) / 57.3
	var monster_origin := Vector2i(int(cos(degree) * float(distance) - 5.0), int(sin(degree) * float(distance) - 5.0))
	var swap_axes := direction < 45 or direction > 315 or direction > 135 and direction < 225
	var vertical_sign := -1 if direction < 180 else 1
	var horizontal_sign := 1 if direction > 90 and direction < 270 else -1
	battlefield.direction_degrees = direction
	battlefield.rolled_distance = distance
	return {
		"monsterOrigin": monster_origin,
		"swapAxes": swap_axes,
		"verticalSign": vertical_sign,
		"horizontalSign": horizontal_sign,
	}

func place_character(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, actor_id: String, party_index: int, formation: Dictionary) -> bool:
	if battlefield == null or terrain_set == null or actor_id.is_empty() or party_index < 0 or formation.is_empty():
		return false
	var quotient := int(float(party_index) / 3.0)
	var horizontal_sign := int(formation.get("horizontalSign", -1))
	var vertical_sign := int(formation.get("verticalSign", 1))
	var base := Vector2i.ZERO
	if bool(formation.get("swapAxes", false)):
		base = Vector2i(quotient * horizontal_sign, party_index - 3 * absi(quotient) + absi(quotient) * vertical_sign)
	else:
		base = Vector2i(party_index - 3 * absi(quotient) + absi(quotient) * horizontal_sign, quotient * vertical_sign)
	var coordinate := _find_character_cell(battlefield, terrain_set, base)
	return coordinate.x >= 0 and battlefield.place_character(actor_id, coordinate)

func find_monster_position(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, desired_local: Vector2i, size: int) -> Vector2i:
	if battlefield == null or terrain_set == null or size < 0 or size > 3:
		return Vector2i(-1, -1)
	var center := battlefield.party_anchor + desired_local
	for radius: int in range(1, _maximum_useful_radius(center) + 1):
		var start := -radius
		var stop := radius
		for vertical_offset: int in range(start, stop):
			for horizontal_offset: int in range(start, stop):
				var candidate := center + Vector2i(horizontal_offset, vertical_offset)
				if _monster_position_is_legal(battlefield, terrain_set, candidate, size):
					return candidate
	return Vector2i(-1, -1)

func place_monster(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, actor_id: String, desired_local: Vector2i, size: int) -> bool:
	var coordinate := find_monster_position(battlefield, terrain_set, desired_local, size)
	return coordinate.x >= 0 and battlefield.place_monster(actor_id, coordinate, size)

func _find_character_cell(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, base_local: Vector2i) -> Vector2i:
	var center := battlefield.party_anchor + base_local
	for radius: int in range(1, _maximum_useful_radius(center) + 1):
		for vertical_offset: int in range(-radius, radius):
			for horizontal_offset: int in range(-radius, radius):
				var candidate := center + Vector2i(horizontal_offset, vertical_offset)
				if not _inside_good_rect(candidate) or battlefield.is_occupied(candidate):
					continue
				var terrain := terrain_set.tile_by_id(battlefield.terrain_at(candidate))
				if terrain != null and terrain.solid == 0:
					return candidate
	return Vector2i(-1, -1)

func _monster_position_is_legal(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, anchor: Vector2i, size: int) -> bool:
	if not _inside_good_rect(anchor):
		return false
	var footprint := BattlefieldState.footprint_cells(anchor, size)
	for coordinate: Vector2i in footprint:
		if not BattlefieldState.contains(coordinate) or battlefield.is_occupied(coordinate):
			return false
		var terrain := terrain_set.tile_by_id(battlefield.terrain_at(coordinate))
		if terrain == null:
			return false
		if coordinate == anchor:
			if size == 0 and terrain.solid != 0 or terrain.solid == 2:
				return false
		elif terrain.solid > 1:
			return false
	return true

func _land_build(map_id: String, cell: MapCell, world_state: WorldState, terrain_set: BattleTerrainSetDefinition) -> Array:
	var tile := _effective_land_tile(map_id, cell, world_state)
	if tile <= 0 or tile >= 201:
		tile = terrain_set.base_tile
	var definition := terrain_set.tile_by_id(tile)
	if definition == null:
		return []
	return definition.combat_build()

func _dungeon_build(cell: MapCell) -> Array:
	var floor_in_battle := cell.terrain_id != "classic.dungeon.wall"
	for feature: MapFeature in cell.features():
		if feature.kind in [&"door", &"stairs", &"secret", &"no-wall-in-battle"]:
			floor_in_battle = true
			break
	var tile := DUNGEON_FLOOR_TILE if floor_in_battle else DUNGEON_WALL_TILE
	return [[tile, tile, tile], [tile, tile, tile], [tile, tile, tile]]

func _decorate_dungeon(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, rng: RealmzRng) -> String:
	for y: int in range(2, 88):
		for x: int in range(2, 88):
			var coordinate := Vector2i(x, y)
			var roll := rng.draw(100, &"battle.terrain.dungeon-rubble-chance")
			var definition := terrain_set.tile_by_id(battlefield.terrain_at(coordinate))
			if definition == null:
				return "Dungeon battle terrain references an unavailable Combat Data BD tile."
			if roll < 10 and definition.solid == 0:
				battlefield.set_terrain(coordinate, 200 + rng.draw_between(141, 158, &"battle.terrain.dungeon-rubble-tile"))
	return ""

func _decorate_land(battlefield: BattlefieldState, terrain_set: BattleTerrainSetDefinition, rng: RealmzRng) -> String:
	for y: int in range(2, 88):
		for x: int in range(2, 88):
			var coordinate := Vector2i(x, y)
			var bottom := terrain_set.tile_by_id(battlefield.terrain_at(coordinate))
			var top := terrain_set.tile_by_id(battlefield.terrain_at(coordinate + Vector2i.UP))
			if bottom == null or top == null:
				return "Land battle terrain references an unavailable effective mapstats tile."
			if bottom.forest != 0:
				# Castle combatmap.c uses bottom.ispath in both sums. Preserve that observable
				# draw branch until a named fidelity decision adjudicates the apparent typo.
				var bottom_blocked := bottom.solid + int(bottom.shore) + bottom.need_boat + int(bottom.blocks_los) + int(bottom.is_path)
				var top_blocked := top.solid + int(top.shore) + top.need_boat + int(top.blocks_los) + int(bottom.is_path)
				if bottom_blocked == 0 and top_blocked == 0:
					_decorate_forest_cell(battlefield, coordinate, bottom.forest, terrain_set.base_tile, rng)
				else:
					battlefield.set_terrain(coordinate, terrain_set.base_tile)
			elif battlefield.terrain_at(coordinate) == terrain_set.base_tile:
				_decorate_rubble_cell(battlefield, coordinate, terrain_set.landlook, rng)
	return ""

static func _effective_land_tile(map_id: String, cell: MapCell, world_state: WorldState) -> int:
	var terrain_id := world_state.terrain_for(map_id, cell)
	var prefix := "classic.terrain."
	if terrain_id.begins_with(prefix):
		var suffix := terrain_id.trim_prefix(prefix)
		if suffix.is_valid_int():
			return int(suffix)
	return cell.render_tile

static func _maximum_useful_radius(center: Vector2i) -> int:
	var required := maxi(
		maxi(absi(GOOD_MINIMUM - center.x), absi((GOOD_MAXIMUM_EXCLUSIVE - 1) - center.x)),
		maxi(absi(GOOD_MINIMUM - center.y), absi((GOOD_MAXIMUM_EXCLUSIVE - 1) - center.y))
	) + 2
	return mini(required, MAX_SEARCH_RADIUS)

func adjacent_actor_ids(battlefield: BattlefieldState, actor_id: String, anchor_override: Vector2i = Vector2i(-1, -1)) -> Array[String]:
	var result: Array[String] = []
	if battlefield == null or not battlefield.has_actor(actor_id):
		return result
	var anchor := battlefield.actor_position(actor_id) if anchor_override.x < 0 else anchor_override
	var actor_cells := battlefield.actor_footprint_at(actor_id, anchor)
	for candidate_id: String in battlefield.actor_ids():
		if candidate_id == actor_id:
			continue
		if _footprints_are_adjacent(actor_cells, battlefield.actor_footprint(candidate_id)):
			result.append(candidate_id)
	return result

func are_adjacent(battlefield: BattlefieldState, first_actor_id: String, second_actor_id: String) -> bool:
	if battlefield == null or first_actor_id == second_actor_id:
		return false
	return _footprints_are_adjacent(battlefield.actor_footprint(first_actor_id), battlefield.actor_footprint(second_actor_id))

func classic_range(battlefield: BattlefieldState, first_actor_id: String, second_actor_id: String) -> int:
	if battlefield == null or first_actor_id == second_actor_id or not battlefield.has_actor(first_actor_id) or not battlefield.has_actor(second_actor_id):
		return -1
	# getrange.c measures actor anchors and stores sqrt() in a short, truncating
	# the Euclidean distance before comparing it with the spell range.
	return floori(Vector2(battlefield.actor_position(second_actor_id) - battlefield.actor_position(first_actor_id)).length())

func _decorate_forest_cell(battlefield: BattlefieldState, coordinate: Vector2i, forest: int, base_tile: int, rng: RealmzRng) -> void:
	var top_coordinate := coordinate + Vector2i.UP
	match forest:
		1:
			if rng.draw(100, &"battle.terrain.forest-primary") < 20:
				var bottom_tile := 200 + rng.draw_between(67, 71, &"battle.terrain.forest-tile")
				battlefield.set_terrain(coordinate, bottom_tile)
				battlefield.set_terrain(top_coordinate, bottom_tile - 6 if not _between(battlefield.terrain_at(top_coordinate), 267, 271) else 266)
			elif rng.draw(100, &"battle.terrain.forest-secondary") < 10:
				battlefield.set_terrain(coordinate, 200 + rng.draw_between(81, 91, &"battle.terrain.forest-rubble"))
			else:
				battlefield.set_terrain(coordinate, base_tile)
		2:
			if rng.draw(100, &"battle.terrain.forest-primary") < 20:
				battlefield.set_terrain(coordinate, 200 + rng.draw_between(107, 111, &"battle.terrain.forest-tile"))
				battlefield.set_terrain(top_coordinate, 200 + rng.draw_between(101, 105, &"battle.terrain.forest-top") if not _between(battlefield.terrain_at(top_coordinate), 307, 311) else 306)
			elif rng.draw(100, &"battle.terrain.forest-secondary") < 10:
				battlefield.set_terrain(coordinate, 200 + rng.draw_between(121, 131, &"battle.terrain.forest-rubble"))
			else:
				battlefield.set_terrain(coordinate, base_tile)
		3:
			if rng.draw(100, &"battle.terrain.forest-primary") < 20 and not _between(battlefield.terrain_at(top_coordinate), 273, 280):
				var bottom_tile := 200 + rng.draw_between(77, 80, &"battle.terrain.forest-tile")
				battlefield.set_terrain(coordinate, bottom_tile)
				battlefield.set_terrain(top_coordinate, bottom_tile - 4)
			elif rng.draw(100, &"battle.terrain.forest-secondary") < 10:
				battlefield.set_terrain(coordinate, 200 + rng.draw_between(92, 100, &"battle.terrain.forest-rubble"))
			else:
				battlefield.set_terrain(coordinate, base_tile)
		4:
			if rng.draw(100, &"battle.terrain.forest-primary") < 20 and not _between(battlefield.terrain_at(top_coordinate), 381, 391):
				var bottom_tile := 200 + rng.draw_between(186, 190, &"battle.terrain.forest-tile")
				battlefield.set_terrain(coordinate, bottom_tile)
				if not _between(battlefield.terrain_at(top_coordinate), 307, 311):
					battlefield.set_terrain(top_coordinate, bottom_tile - 5)
			elif rng.draw(100, &"battle.terrain.forest-secondary") < 10:
				battlefield.set_terrain(coordinate, 200 + rng.draw_between(159, 171, &"battle.terrain.forest-rubble"))
			else:
				battlefield.set_terrain(coordinate, base_tile)
		5:
			if rng.draw(100, &"battle.terrain.forest-primary") < 20 and not _between(battlefield.terrain_at(top_coordinate), 391, 400):
				var bottom_tile := 200 + rng.draw_between(196, 200, &"battle.terrain.forest-tile")
				battlefield.set_terrain(coordinate, bottom_tile)
				if not _between(battlefield.terrain_at(top_coordinate), 317, 321):
					battlefield.set_terrain(top_coordinate, bottom_tile - 5)
			elif rng.draw(100, &"battle.terrain.forest-secondary") < 10:
				battlefield.set_terrain(coordinate, 200 + rng.draw_between(172, 180, &"battle.terrain.forest-rubble"))
			else:
				battlefield.set_terrain(coordinate, base_tile)

static func _item_use_reason_code(instance: ItemInstance, item: ItemDefinition, spell: SpellDefinition) -> StringName:
	if instance == null or item == null:
		return &"unknown_item_instance"
	if instance.charges == 0:
		return &"item_has_no_charges"
	if item.special_2 <= 1100:
		return &"item_has_no_spell_effect"
	if spell == null:
		return &"unknown_item_spell"
	return &"item_cannot_be_used"

static func _spell_target_selection(state: GameState, content: RealmzContent, target_id: String) -> SpellTargetSelection:
	var character := state.party.character_by_id(target_id)
	if character != null and character.current_health > 0 and state.combat.battlefield.has_actor(character.id):
		return SpellTargetSelection.for_character(character)
	var monster := state.combat.monster_by_id(target_id)
	if monster == null or monster.current_health <= 0 or not state.combat.battlefield.has_actor(monster.id):
		return null
	var definition := content.monster_by_id(monster.definition_id)
	return SpellTargetSelection.for_monster(monster, definition) if definition != null else null

func bandage_candidate_ids(state: GameState) -> Array[String]:
	var result: Array[String] = []
	if state == null or state.combat == null:
		return result
	for character: CharacterState in state.party.characters():
		if state.combat.is_character_bleeding(character.id) and character.current_health > -10:
			result.append(character.id)
	return result

func start_battle(state: GameState, content: RealmzContent, battle: BattleDefinition, rng: RealmzRng, surprise: int = 0) -> CombatFlowResult:
	if state == null or content == null or battle == null or rng == null:
		return CombatFlowResult.failed(&"invalid_battle", "Battle setup requires validated state, content, and randomness.")
	if state.combat != null and not state.combat.completed:
		return CombatFlowResult.failed(&"battle_already_active", "A Realmz battle is already active.")
	var map := content.world.map_by_id(state.party.map_id)
	if map == null or map.topology.width != 90 or map.topology.height != 90:
		return CombatFlowResult.failed(&"invalid_battle_map", "Battle '%s' requires the party's validated 90 by 90 Classic map." % battle.id)
	var terrain_set := content.world.battle_terrain_set_by_id(map.battle_terrain_set_id)
	if terrain_set == null:
		return CombatFlowResult.failed(&"missing_battle_terrain", "Map '%s' has no validated Classic battle-terrain catalog." % map.id)
	var initial_weapon_modes: Dictionary = {}
	for character: CharacterState in state.party.characters():
		if character.current_health <= 0:
			continue
		var equipment := _rules.inventory.combat_equipment(character, content.item_definitions())
		if not equipment.valid:
			return CombatFlowResult.failed(equipment.error_code, equipment.error_message)
		initial_weapon_modes[character.id] = &"missile" if equipment.melee_weapon == null and equipment.missile_weapon != null else &"melee"
	var ally_definitions: Dictionary = {}
	if not state.allies_suspended:
		for ally: MonsterState in state.party.allies():
			if ally.current_health <= 0:
				continue
			var ally_definition := content.monster_by_id(ally.definition_id)
			if ally_definition == null:
				return CombatFlowResult.failed(&"unknown_ally", "Held-over ally '%s' references unavailable monster '%s'." % [ally.id, ally.definition_id])
			ally_definitions[ally.id] = ally_definition
	var authored_slots := battle.monster_slots()
	if authored_slots.is_empty():
		return CombatFlowResult.failed(&"empty_battle", "Battle '%s' has no viable monsters." % battle.id)
	authored_slots.sort_custom(func(left: BattleMonsterSlotDefinition, right: BattleMonsterSlotDefinition) -> bool:
		return left.coordinate.y < right.coordinate.y or left.coordinate.y == right.coordinate.y and left.coordinate.x < right.coordinate.x
	)
	var authored_definitions: Dictionary = {}
	for slot: BattleMonsterSlotDefinition in authored_slots:
		var definition := content.monster_by_id_for_set(slot.monster_id, state.monster_set)
		if definition == null:
			return CombatFlowResult.failed(&"unknown_monster", "Battle '%s' references unavailable monster '%s'." % [battle.id, slot.monster_id])
		authored_definitions[slot.monster_id] = definition

	var rng_checkpoint := rng.checkpoint()
	var instance_checkpoint := state.instance_id_checkpoint()
	var battlefield_builder := BattlefieldBuilder.new()
	var terrain_result := battlefield_builder.build_terrain(map, state.world, terrain_set, state.party.coordinate, rng)
	if not terrain_result.is_ok():
		return _battle_setup_failure(state, instance_checkpoint, rng, rng_checkpoint, terrain_result.error_code, terrain_result.error_message)
	var battlefield := terrain_result.battlefield
	var formation := battlefield_builder.roll_formation(battlefield, battle, rng)
	if formation.is_empty():
		return _battle_setup_failure(state, instance_checkpoint, rng, rng_checkpoint, &"invalid_battle_formation", "Battle '%s' could not derive Castle's opening formation." % battle.id)
	var party_characters := state.party.characters()
	for party_index: int in party_characters.size():
		var character := party_characters[party_index]
		if not battlefield_builder.place_character(battlefield, terrain_set, character.id, party_index, formation):
			return _battle_setup_failure(state, instance_checkpoint, rng, rng_checkpoint, &"character_placement_failed", "Battle '%s' has no legal battlefield cell for '%s'." % [battle.id, character.id])

	var monsters: Array[MonsterState] = []
	var consumed_allies: Array[String] = []
	var consumed_ally_states: Array[MonsterState] = []
	if not state.allies_suspended:
		for ally: MonsterState in state.party.allies():
			if ally.current_health <= 0 or monsters.size() >= MAX_MONSTERS:
				continue
			var ally_definition: MonsterDefinition = ally_definitions[ally.id]
			if not battlefield_builder.place_monster(battlefield, terrain_set, ally.id, Vector2i.ZERO, ally_definition.size):
				return _battle_setup_failure(state, instance_checkpoint, rng, rng_checkpoint, &"ally_placement_failed", "Battle '%s' has no legal battlefield footprint for ally '%s'." % [battle.id, ally.id])
			monsters.append(ally)
			consumed_allies.append(ally.id)
			consumed_ally_states.append(ally)
	var pending_authored: Array[Dictionary] = []
	var monster_origin: Vector2i = formation["monsterOrigin"]
	for slot_index: int in authored_slots.size():
		if monsters.size() + pending_authored.size() >= MAX_MONSTERS:
			break
		var slot: BattleMonsterSlotDefinition = authored_slots[slot_index]
		var definition: MonsterDefinition = authored_definitions[slot.monster_id]
		var pending_id := "pending.authored.%d" % slot_index
		if not battlefield_builder.place_monster(battlefield, terrain_set, pending_id, monster_origin + slot.coordinate, definition.size):
			return _battle_setup_failure(state, instance_checkpoint, rng, rng_checkpoint, &"monster_placement_failed", "Battle '%s' has no legal battlefield footprint for authored monster at %s." % [battle.id, slot.coordinate])
		var pending_monster := _rules.monsters.build_battle_monster(definition, pending_id, slot.invert_traitor, state.difficulty, state.clock.day(), rng)
		if pending_monster == null:
			return _battle_setup_failure(state, instance_checkpoint, rng, rng_checkpoint, &"invalid_monster", "Battle '%s' could not construct monster '%s'." % [battle.id, slot.monster_id])
		pending_authored.append({"placeholderId": pending_id, "monster": pending_monster})
	for character: CharacterState in party_characters:
		if character.current_health <= 0:
			battlefield.remove_character(character.id)
	for pending: Dictionary in pending_authored:
		var monster: MonsterState = pending["monster"]
		var instance_id := state.next_instance_id("combat.monster")
		if not battlefield.replace_monster_id(pending["placeholderId"], instance_id):
			return _battle_setup_failure(state, instance_checkpoint, rng, rng_checkpoint, &"invalid_battlefield_identity", "Battle '%s' could not commit a stable monster identity." % battle.id)
		monster.id = instance_id
		monsters.append(monster)
	var combat := CombatState.new(battle.id, monsters, battle.macro_id, battlefield)
	combat.set_turn_order(_rules.combat.initiative_order(state.party.characters(), monsters, surprise, rng))
	for character: CharacterState in state.party.characters():
		if character.current_health <= 0:
			continue
		var initial_mode := StringName(initial_weapon_modes.get(character.id, &"melee"))
		if not combat.set_character_weapon_mode(character.id, initial_mode):
			return _battle_setup_failure(state, instance_checkpoint, rng, rng_checkpoint, &"invalid_weapon_mode", "Battle '%s' could not initialize '%s' weapon mode." % [battle.id, character.id])
	for ally: MonsterState in consumed_ally_states:
		ally.traitor = false
	if not state.allies_suspended:
		state.party.set_allies([])
	for character: CharacterState in state.party.characters():
		character.traitor = false
		character.attacks_remaining = 0
		character.movement = character.maximum_movement
	state.combat = combat
	var events: Array[DomainEvent] = [DomainEvent.new(&"battle_started", {"battleId": battle.id, "classicId": battle.classic_id, "distance": battle.distance, "rolledDistance": battlefield.rolled_distance, "direction": battlefield.direction_degrees, "mapId": battlefield.map_id, "surprise": surprise, "turnOrder": combat.turn_orde...

func _battle_setup_failure(state: GameState, instance_checkpoint: int, rng: RealmzRng, checkpoint: Dictionary, code: StringName, message: String) -> CombatFlowResult:
	if state == null or not state.rollback_instance_ids(instance_checkpoint) or not rng.rollback(checkpoint):
		return CombatFlowResult.failed(&"battle_setup_rollback_failed", "Battle setup failed and could not restore the deterministic RNG boundary.")
	return CombatFlowResult.failed(code, message)

func submit_action(state: GameState, content: RealmzContent, actor_id: String, action: StringName, target_id: String, rng: RealmzRng) -> CombatFlowResult:
	var combat := state.combat
	if combat == null or combat.completed:
		return CombatFlowResult.failed(&"no_active_battle", "No Realmz battle is accepting combat actions.")
	if combat.active_actor_id() != actor_id:
		return CombatFlowResult.failed(&"wrong_combat_actor", "Combat action actor '%s' does not own the current turn." % actor_id)
	var actor := state.party.character_by_id(actor_id)
	if actor == null or actor.current_health <= 0 or actor.traitor or combat.battlefield == null or not combat.battlefield.has_actor(actor.id):
		return CombatFlowResult.failed(&"invalid_combat_actor", "The current combat actor is unavailable.")
	var events: Array[DomainEvent] = []
	var monster_death_macro_requested := false
	match action:
		&"attack":
			var equipment := _rules.inventory.combat_equipment(actor, content.item_definitions())
			if not equipment.valid:
				return CombatFlowResult.failed(equipment.error_code, equipment.error_message)
			if combat.character_weapon_mode(actor.id) == &"missile":
				return _fire_character_projectile(state, content, actor, equipment, target_id, rng)
			if combat.battlefield == null:
				return CombatFlowResult.failed(&"missing_battlefield", "Melee requires the session-owned Classic battlefield.")
			if not _rules.battlefield.are_adjacent(combat.battlefield, actor.id, target_id):
				return CombatFlowResult.failed(&"combat_target_not_adjacent", "Classic melee can target only an enemy in an adjacent battlefield footprint.")
			var monster_target := combat.monster_by_id(target_id)
			if monster_target != null and monster_target.current_health > 0 and monster_target.traitor != actor.traitor:
				var definition := content.monster_by_id(monster_target.definition_id)
				if definition == null:
					return CombatFlowResult.failed(&"unknown_monster_definition", "The selected monster has no immutable definition.")
				_prepare_character_turn(combat, actor)
				combat.invalidate_undo()
				combat.active_turn.physical_action_committed = true
				var resolution := _rules.combat.resolve_character_attack(actor, equipment, monster_target, definition, rng, state.clock.day(), false, true, combat.can_queue_fumbled_item())
				if resolution.total_damage() > 0:
					combat.mark_attacked(monster_target.id)
				if resolution.fumbled and not _commit_character_fumble(state, actor, equipment, events):
					return CombatFlowResult.failed(&"invalid_fumble_state", "The fumbled melee weapon could not enter the battle recovery queue.")
				_append_character_attack_audio(events, actor, equipment, resolution, &"monster")
				events.append(_character_attack_event(actor.id, monster_target.id, &"monster", resolution, equipment.melee_weapon != null))
				monster_death_macro_requested = resolution.killed and _request_monster_death_macro(monster_target, definition, events)
				_remove_defeated_position(combat, monster_target.id, resolution.killed and not monster_death_macro_requested)
			else:
				var character_target := state.party.character_by_id(target_id)
				if character_target == null or character_target.id == actor.id or character_target.current_health <= 0 or character_target.traitor == actor.traitor:
					return CombatFlowResult.failed(&"invalid_combat_target", "The selected combatant is unavailable to this allegiance.")
				var target_equipment := _rules.inventory.combat_equipment(character_target, content.item_definitions())
				if not target_equipment.valid:
					return CombatFlowResult.failed(target_equipment.error_code, target_equipment.error_message)
				_prepare_character_turn(combat, actor)
				combat.invalidate_undo()
				combat.active_turn.physical_action_committed = true
				var resolution := _rules.combat.resolve_character_attack_character(actor, equipment, character_target, target_equipment, rng, false, true, combat.can_queue_fumbled_item())
				if resolution.total_damage() > 0:
					combat.mark_attacked(character_target.id)
				if resolution.fumbled and not _commit_character_fumble(state, actor, equipment, events):
					return CombatFlowResult.failed(&"invalid_fumble_state", "The fumbled melee weapon could not enter the battle recovery queue.")
				_append_character_attack_audio(events, actor, equipment, resolution, &"character")
				events.append(_character_attack_event(actor.id, character_target.id, &"character", resolution, equipment.melee_weapon != null))
				_mark_character_bleeding(state, character_target, resolution.killed)
				_remove_defeated_position(combat, character_target.id, resolution.killed)
			_consume_character_attack(actor)
			if not _character_can_continue(actor):
				_advance_turn(state, rng, events)
			if monster_death_macro_requested:
				return CombatFlowResult.succeeded(events)
		&"switch_weapon":
			var equipment := _rules.inventory.combat_equipment(actor, content.item_definitions())
			if not equipment.valid:
				return CombatFlowResult.failed(equipment.error_code, equipment.error_message)
			var current_mode := combat.character_weapon_mode(actor.id)
			var next_mode: StringName = &"melee" if current_mode == &"missile" else &"missile"
			if next_mode == &"missile" and equipment.missile_weapon == null:
				return CombatFlowResult.failed(&"missile_weapon_unavailable", "The active character has no equipped Classic type-15 missile weapon.")
			_prepare_character_turn(combat, actor)
			if not combat.set_character_weapon_mode(actor.id, next_mode):
				return CombatFlowResult.failed(&"invalid_weapon_mode", "The active character's battle weapon mode could not be changed.")
			events.append(DomainEvent.new(&"combat_weapon_mode_changed", {"actorId": actor.id, "mode": String(next_mode)}))
		&"defend":
			_prepare_character_turn(combat, actor)
			var guard_roll := rng.draw(100, &"combat.guard-sound")
			var guard_sound := 10121 if guard_roll < 50 else 10123
			combat.set_guarding(actor.id, true)
