func _initialize() -> void:
	var requested_fragments: Array[String] = []
	var requested_cases: Array[String] = []
	var arguments := OS.get_cmdline_user_args()
	var argument_index: int = 0
	while argument_index < arguments.size():
		var argument: String = arguments[argument_index]
		if argument_index + 1 >= arguments.size() or argument not in ["--suite", "--case"]:
			printerr(USAGE)
			quit(2)
			return
		var fragment: String = arguments[argument_index + 1]
		if fragment.is_empty() or fragment.begins_with("--"):
			printerr(USAGE)
			quit(2)
			return
		if argument == "--suite":
			requested_fragments.append(fragment)
		else:
			requested_cases.append(fragment)
		argument_index += 2
	for fragment: String in requested_fragments:
		var fragment_matches_suite: bool = false
		for suite_script: Script in SUITES:
			if suite_script.resource_path.contains(fragment):
				fragment_matches_suite = true
				break
		if not fragment_matches_suite:
			printerr("No test suite matches filter '%s'." % fragment)
			quit(2)
			return
	if not requested_cases.is_empty() and requested_fragments.is_empty():
		printerr("Named case filters require at least one --suite filter so unrelated suites are never instantiated.")
		quit(2)
		return
	var selected_suites: Array[Script] = []
	for suite_script: Script in SUITES:
		if requested_fragments.is_empty():
			selected_suites.append(suite_script)
			continue
		for fragment: String in requested_fragments:
			if suite_script.resource_path.contains(fragment):
				selected_suites.append(suite_script)
				break
	if selected_suites.is_empty():
		printerr("No test suite matches the requested filters.")
		quit(2)
		return
	for case_fragment: String in requested_cases:
		var fragment_matches_case: bool = false
		for suite_script: Script in selected_suites:
			var suite: RealmzTestCase = suite_script.new()
			for method: Dictionary in _test_methods(suite):
				if String(method["name"]).contains(case_fragment):
					fragment_matches_case = true
					break
			if fragment_matches_case:
				break
		if not fragment_matches_case:
			printerr("No test case in the selected suites matches filter '%s'." % case_fragment)
			quit(2)
			return
	var assertion_count: int = 0
	var failure_count: int = 0
	for suite_script: Script in selected_suites:
		var suite_started: int = Time.get_ticks_msec()
		print("RUN SUITE: %s" % suite_script.resource_path)
		var suite: RealmzTestCase = suite_script.new()
		if requested_cases.is_empty():
			suite.run()
		else:
			var selected_methods := _selected_test_methods(suite, requested_cases)
			var shared_arguments: Array = []
			if selected_methods.any(func(method: Dictionary) -> bool: return not (method.get("args", []) as Array).is_empty()):
				shared_arguments = suite.selected_case_arguments()
			for method: Dictionary in selected_methods:
				var method_name := String(method["name"])
				var method_arguments: Array = method.get("args", []) as Array
				if not method_arguments.is_empty() and method_arguments.size() != shared_arguments.size():
					printerr("Test case '%s' needs %d shared argument(s), but its suite prepared %d." % [method_name, method_arguments.size(), shared_arguments.size()])
					quit(2)
					return
				var case_started: int = Time.get_ticks_msec()
				var assertions_before: int = suite.assertions
				print("RUN CASE: %s::%s" % [suite_script.resource_path, method_name])
				if method_arguments.is_empty():
					suite.call(method_name)
				else:
					suite.callv(method_name, shared_arguments)
				print("DONE CASE: %s::%s (%d assertions, %d ms)" % [suite_script.resource_path, method_name, suite.assertions - assertions_before, Time.get_ticks_msec() - case_started])
		print("DONE SUITE: %s (%d assertions, %d ms)" % [suite_script.resource_path, suite.assertions, Time.get_ticks_msec() - suite_started])
		assertion_count += suite.assertions
		for failure: String in suite.failures:
			failure_count += 1
			printerr("FAIL %s: %s" % [suite_script.resource_path, failure])
	if failure_count == 0:
		print("PASS: %d assertions across %d suites" % [assertion_count, selected_suites.size()])
		quit(0)
	else:
		printerr("FAILED: %d failures across %d assertions" % [failure_count, assertion_count])
		quit(1)

func _test_methods(suite: RealmzTestCase) -> Array[Dictionary]:
	var methods: Array[Dictionary] = []
	for method: Dictionary in suite.get_method_list():
		if String(method.get("name", "")).begins_with("_test_"):
			methods.append(method)
	return methods

func _matches_any(value: String, fragments: Array[String]) -> bool:
	for fragment: String in fragments:
		if value.contains(fragment):
			return true
	return false

func _selected_test_methods(suite: RealmzTestCase, fragments: Array[String]) -> Array[Dictionary]:
	var selected: Array[Dictionary] = []
	var methods := _test_methods(suite)
	for fragment: String in fragments:
		for method: Dictionary in methods:
			if String(method["name"]).contains(fragment) and not selected.has(method):
				selected.append(method)
	return selected

func _initialize() -> void:
	var arguments := OS.get_cmdline_user_args()
	if arguments.size() != 1:
		printerr("Usage: godot --headless --path <project> --script res://tools/package_probe.gd -- <package.realmz2>")
		call_deferred("_quit_cleanly", 2)
		return
	var package_path: String = arguments[0]
	var repository := PACKAGE_REPOSITORY_SCRIPT.new()
	var archive := ZIPReader.new()
	var started_at := Time.get_ticks_msec()
	var open_error := archive.open(package_path)
	if open_error != OK:
		printerr("PACKAGE_REJECTED package_open_failed: ZIP error %d" % open_error)
		call_deferred("_quit_cleanly", 1)
		return
	var archive_entries: Array[String] = repository._zip_entries(archive)
	var manifest: Variant = repository._read_document(archive, "manifest.json")
	if manifest == null or not repository._validate_manifest(manifest, archive, archive_entries):
		printerr("PACKAGE_REJECTED manifest: %s" % repository._last_error)
		call_deferred("_quit_cleanly", 1)
		return
	print("PROBE manifest_ms=%d" % (Time.get_ticks_msec() - started_at))
	var documents_started := Time.get_ticks_msec()
	var content_document: Variant = repository._read_document(archive, "content.json")
	var world_document: Variant = repository._read_document(archive, "world.json")
	var scenario_document: Variant = repository._read_document(archive, "scenario.json")
	var asset_document: Variant = repository._read_document(archive, "assets/index.json")
	print("PROBE documents_ms=%d" % (Time.get_ticks_msec() - documents_started))
	if content_document == null or world_document == null or scenario_document == null or asset_document == null:
		printerr("PACKAGE_REJECTED documents: %s" % repository._last_error)
		call_deferred("_quit_cleanly", 1)
		return
	var construction_started := Time.get_ticks_msec()
	var runtime_assets := repository._construct_assets(asset_document)
	var content: Variant = repository.call("_construct_content", manifest, content_document, world_document, scenario_document, runtime_assets)
	print("PROBE construction_ms=%d" % (Time.get_ticks_msec() - construction_started))
	if content == null:
		printerr("PACKAGE_REJECTED construction: %s" % repository._last_error)
		call_deferred("_quit_cleanly", 1)
		return
	var media := PackageMediaCatalog.new(package_path, manifest["packageHash"], runtime_assets)
	archive.close()
	var session := GAME_SESSION_SCRIPT.new()
	var session_started_at := Time.get_ticks_msec()
	var step: Variant = session.call("start", content, 1)
	var session_start_ms := Time.get_ticks_msec() - session_started_at
	if step.state == SessionStep.State.FAILED:
		printerr("SESSION_REJECTED %s: %s" % [step.error_code, step.error_message])
		call_deferred("_quit_cleanly", 1)
		return
	var view_started_at := Time.get_ticks_msec()
	var view := session.view()
	var first_view_ms := Time.get_ticks_msec() - view_started_at
	var repeat_views_started_at := Time.get_ticks_msec()
	for index: int in 10:
		session.view()
	var ten_repeat_views_ms := Time.get_ticks_msec() - repeat_views_started_at
	var blocked_move_started_at := Time.get_ticks_msec()
	var blocked_move := session.submit_intent(PlayerIntent.move(Vector2i.LEFT))
	var blocked_move_ms := Time.get_ticks_msec() - blocked_move_started_at
	var post_move_view_started_at := Time.get_ticks_msec()
	session.view()
	var post_move_view_ms := Time.get_ticks_msec() - post_move_view_started_at
	print(CanonicalJson.encode({
		"blockedMoveError": String(blocked_move.error_code),
		"blockedMoveMs": blocked_move_ms,
		"campaignId": content.campaign_id,
		"firstViewMs": first_view_ms,
		"packageHash": content.package_hash,
		"rulesVersion": content.rules_version,
		"startMapId": view.party_map_id,
		"startX": view.party_coordinate.x,
		"startY": view.party_coordinate.y,
		"partySetupAvailable": view.party_setup_available,
		"pendingInteraction": step.interaction != null,
		"mediaAssets": media.assets().size(),
		"postMoveViewMs": post_move_view_ms,
		"sessionStartMs": session_start_ms,
		"tenRepeatViewsMs": ten_repeat_views_ms,
		"totalMs": Time.get_ticks_msec() - started_at,
	}))
	call_deferred("_quit_cleanly", 0)

func assert_contains(text: String, expected_fragment: String, message: String) -> void:
	assertions += 1
	if not text.contains(expected_fragment):
		failures.append("%s (expected '%s' in '%s')" % [message, expected_fragment, text])

param(
    [string[]]$Suite = @(),
    [string[]]$Case = @(),
    [ValidateRange(1, 3600)]
    [int]$TimeoutSeconds = 120,
    [string]$GodotPath = "",
    [string]$CastleRoot = "",
    [string]$RemakeRoot = "",
    [string]$ProvidenceRoot = ""
)

$ErrorActionPreference = "Stop"
$repoRoot = Split-Path -Parent $PSScriptRoot

if ([string]::IsNullOrWhiteSpace($GodotPath)) {
    $candidate = Get-ChildItem "$env:LOCALAPPDATA\Microsoft\WinGet\Packages" -Recurse -Filter "Godot_v4.7.1-stable_win64_console.exe" -ErrorAction SilentlyContinue |
        Select-Object -First 1 -ExpandProperty FullName
    if (-not $candidate) {
        throw "Godot 4.7.1 console executable was not found. Pass -GodotPath explicitly."
    }
    $GodotPath = $candidate
}

$suiteFragments = @($Suite | ForEach-Object { $_.Trim() } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique)
$caseFragments = @($Case | ForEach-Object { $_.Trim() } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique)
if ($suiteFragments.Count -eq 0 -and $caseFragments.Count -eq 0) {
    throw "At least one non-empty -Suite or -Case fragment is required."
}
if ($suiteFragments.Count -eq 0 -and $caseFragments.Count -gt 0) {
    throw "Named case filters require at least one -Suite fragment."
}

& "$PSScriptRoot\run_tests.ps1" -Suite $suiteFragments -Case $caseFragments -TimeoutSeconds $TimeoutSeconds -GodotPath $GodotPath

& "$PSScriptRoot\ui-assets\verify-classic-application-media.ps1"
if ($LASTEXITCODE -ne 0) { throw "Classic application media verification failed." }

$changedPaths = @(
    git -C $repoRoot status --porcelain=v1 --untracked-files=all |
        ForEach-Object {
            if ($_.Length -lt 4) { return }
            $path = $_.Substring(3)
            if ($path.Contains(" -> ")) { $path = $path.Split(" -> ")[-1] }
            $path.Trim('"') -replace '\\', '/'
        } |
        Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
        Select-Object -Unique
)

if (@($changedPaths | Where-Object { $_ -eq "src" -or $_.StartsWith("src/") -or $_ -eq "project.godot" }).Count -gt 0) {
    & "$PSScriptRoot\verify_architecture.ps1"
    if ($LASTEXITCODE -ne 0) { throw "Architecture boundary verification failed." }
} else {
    Write-Host "Architecture boundary verification skipped: no product source changed."
}

$referenceArguments = @{}
if (-not [string]::IsNullOrWhiteSpace($CastleRoot)) { $referenceArguments.CastleRoot = $CastleRoot }
if (-not [string]::IsNullOrWhiteSpace($RemakeRoot)) { $referenceArguments.RemakeRoot = $RemakeRoot }
if (-not [string]::IsNullOrWhiteSpace($ProvidenceRoot)) { $referenceArguments.ProvidenceRoot = $ProvidenceRoot }

& "$PSScriptRoot\verify_differential_evidence.ps1" @referenceArguments
if ($LASTEXITCODE -ne 0) { throw "Differential evidence verification failed." }

& "$PSScriptRoot\verify_application_workflow_inventory.ps1" -Check @referenceArguments
if ($LASTEXITCODE -ne 0) { throw "Application workflow inventory verification failed." }

git -C $repoRoot diff --check
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed." }

$addedTrackedLines = @(git -C $repoRoot diff --no-ext-diff --unified=0 HEAD -- . | Where-Object { $_ -match '^\+(?!\+\+)' } | ForEach-Object { $_.Substring(1) })
$localPathPattern = '(?i)([a-z]:[\\/](users|documents|realmz|godot)|/(users|home)/[^/\s]+/)'
foreach ($line in $addedTrackedLines) {
    if ($line -match $localPathPattern) {
        throw "Changed text contains a machine-local absolute path: $line"
    }
}

foreach ($path in $changedPaths) {
    $extension = [System.IO.Path]::GetExtension($path).ToLowerInvariant()
    if ($extension -eq ".r2save") {
        throw "Save artifact must not enter a workflow commit: $path"
    }
    if ($extension -eq ".realmz2" -and -not $path.StartsWith("tests/fixtures/packages/")) {
        throw "Campaign package outside the synthetic fixture boundary must not enter a workflow commit: $path"
    }
    $fullPath = Join-Path $repoRoot $path
    if ((git -C $repoRoot ls-files --error-unmatch -- $path 2>$null) -or -not (Test-Path -LiteralPath $fullPath -PathType Leaf)) {
        continue
    }
    try {
        $untrackedText = Get-Content -LiteralPath $fullPath -Raw -ErrorAction Stop
    } catch {
        continue
    }
    if ($untrackedText -match $localPathPattern) {
        throw "Untracked text contains a machine-local absolute path: $path"
    }
}

Write-Host "Workflow verification complete: $($suiteFragments.Count) suite filter(s), $($caseFragments.Count) case filter(s), $($changedPaths.Count) changed path(s)."
exit 0

