func _events(step: SessionStep, kind: StringName) -> Array[DomainEvent]:
	var result: Array[DomainEvent] = []
	for event: DomainEvent in step.events:
		if event.kind == kind:
			result.append(event)
	return result

func _event_position(step: SessionStep, kind: StringName) -> int:
	for index: int in step.events.size():
		if step.events[index].kind == kind:
			return index
	return -1

func selected_case_arguments() -> Array:
	var loaded := PackageRepository.new().load_package(FIXTURE_PATH)
	assert_true(loaded.is_ok(), "money workflow starts from the validated package fixture")
	return [loaded.content] if loaded.is_ok() else []

func _has_event(step: SessionStep, event_kind: StringName) -> bool:
	for event: DomainEvent in step.events:
		if event.kind == event_kind:
			return true
	return false

func _event(step: SessionStep, event_kind: StringName) -> DomainEvent:
	for event: DomainEvent in step.events:
		if event.kind == event_kind:
			return event
	return null

func _event_count(step: SessionStep, event_kind: StringName) -> int:
	var count := 0
	for event: DomainEvent in step.events:
		if event.kind == event_kind:
			count += 1
	return count

func _message_ids(step: SessionStep) -> Array[int]:
	var ids: Array[int] = []
	for event: DomainEvent in step.events:
		if event.kind == &"message_shown":
			ids.append(int(event.payload.get("messageId", -1)))
	return ids

