static func for_viewport(size: Vector2, scale_mode: String) -> UiLayoutProfile:
	var scale := UiLayoutProfile.scale_for(size, scale_mode)
	var effective_width := size.x / scale
	var art_scale := 2 if size.x >= 1600.0 and size.y >= 900.0 and scale_mode in [PresentationSettings.UI_SCALE_AUTO, PresentationSettings.UI_SCALE_150] else 1
	if effective_width < 960.0:
		return UiLayoutProfile.new(COMPACT, scale, 208.0 * scale, 156.0 * scale, 208.0 * scale, 1)
	if effective_width < 1280.0:
		return UiLayoutProfile.new(STANDARD, scale, 256.0 * scale, 176.0 * scale, 256.0 * scale, art_scale)
	return UiLayoutProfile.new(WIDE, scale, 288.0 * scale, 190.0 * scale, 288.0 * scale, art_scale)

func _draw_picture() -> void:
	var texture := _texture_for(_view.picture_asset_id)
	if texture == null:
		return
	var destination := Rect2(_view.picture_rect)
	if destination.size.x <= 0.0 or destination.size.y <= 0.0:
		destination = Rect2(Vector2.ZERO, Vector2(MAP_SIZE, MAP_SIZE))
	draw_texture_rect(texture, destination, false)

func _draw_crop() -> void:
	var cell_size := float(_view.icon_size)
	for cell: MapCellView in _view.cells:
		var destination := Rect2(Vector2(cell.coordinate - _view.start) * cell_size, Vector2.ONE * cell_size)
		_draw_cell(cell, destination)
	for marker: PlayerMapMarkerDefinition in _view.markers:
		var texture := _texture_for(marker.icon_asset_id)
		if texture == null:
			continue
		var marker_size := 32.0 if marker.classic_icon_id in [137, 139] else cell_size
		var center := Vector2(marker.coordinate) * cell_size + Vector2.ONE * cell_size * 0.5
		draw_texture_rect(texture, Rect2(center - Vector2.ONE * marker_size * 0.5, Vector2.ONE * marker_size), false)

func _draw_cell(cell: MapCellView, destination: Rect2) -> void:
	var atlas := _media.asset_by_id(cell.tileset_id)
	var texture := _texture_for(cell.tileset_id)
	if _view.mode == PlayerMapDefinition.DUNGEON_CROP and atlas != null and texture != null and atlas.id == "dungeon-top-down-302":
		_draw_atlas_region(destination, atlas, texture, 16)
		if cell.terrain_id == "classic.dungeon.wall":
			_draw_atlas_region(destination, atlas, texture, 1)
		if cell.has_feature(&"door"):
			_draw_atlas_region(destination, atlas, texture, 3 if cell.feature_orientation(&"door") == &"vertical" else 2)
		var feature_tiles: Dictionary = {&"stairs": 4, &"column": 5, &"note": 6, &"secret": 7}
		for feature_kind: StringName in feature_tiles:
			if cell.has_feature(feature_kind):
				_draw_atlas_region(destination, atlas, texture, int(feature_tiles[feature_kind]))
	else:
		var region := Rect2i() if atlas == null else atlas.region_for(cell.render_tile)
		if texture != null and region.has_area():
			draw_texture_rect_region(texture, destination, Rect2(region))
	var overlay := _texture_for(cell.overlay_asset_id)
	if overlay != null:
		draw_texture_rect(overlay, destination, false)

func _draw_atlas_region(destination: Rect2, atlas: PackageMediaAsset, texture: Texture2D, tile_id: int) -> void:
	var region := atlas.region_for(tile_id)
	if region.has_area():
		draw_texture_rect_region(texture, destination, Rect2(region))

func _draw_party_marker() -> void:
	if not _view.party_marker_visible:
		return
	var texture := _texture_for(_view.party_marker_asset_id)
	if texture == null:
		return
	var origin := Vector2(_view.party_coordinate - _view.start) * float(_view.icon_size)
	draw_texture_rect(texture, Rect2(origin - Vector2(20.0, 24.0), Vector2(64.0, 64.0)), false)

func _texture_for(asset_id: String) -> Texture2D:
	if asset_id.is_empty() or _media == null:
		return null
	if _textures.has(asset_id):
		return _textures[asset_id] as Texture2D
	var asset := _media.asset_by_id(asset_id)
	if asset == null or not asset.is_picture():
		return null
	var bytes := _media.read_bytes(asset)
	if bytes.is_empty():
		return null
	var image := Image.new()
	var error := ERR_FILE_UNRECOGNIZED
	match asset.mime_type:
		"image/png":
			error = image.load_png_from_buffer(bytes)
		"image/jpeg":
			error = image.load_jpg_from_buffer(bytes)
		"image/webp":
			error = image.load_webp_from_buffer(bytes)
	if error != OK:
		return null
	var texture := ImageTexture.create_from_image(image)
	_textures[asset_id] = texture
	return texture

func present(view: PlayerMapView, media: ClassicMediaCatalog) -> void:
	for child: Node in get_children():
		remove_child(child)
		child.queue_free()
	if view == null:
		return
	var title := Label.new()
	title.text = view.name
	title.add_theme_font_size_override("font_size", 18)
	title.add_theme_color_override("font_color", Color("d5b45d"))
	add_child(title)
	if view.mode == PlayerMapDefinition.SCROLLING_TEXT:
		var text := RichTextLabel.new()
		text.name = "PlayerMapScrollingText"
		text.custom_minimum_size = Vector2(320, 320)
		text.fit_content = false
		text.bbcode_enabled = false
		var asset: PackageMediaAsset = media.asset_by_id(view.scrolling_text_asset_id) if media != null else null
		text.text = media.read_bytes(asset).get_string_from_utf8() if asset != null else "Scrolling map text is unavailable."
		add_child(text)
	else:
		var canvas := PlayerMapCanvas.new()
		canvas.name = "PlayerMapCanvas"
		canvas.present(view, media)
		add_child(canvas)
		if not view.note.is_empty():
			var note := Label.new()
			note.name = "PlayerMapNote"
			note.text = view.note
			note.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
			add_child(note)

func _draw() -> void:
	draw_rect(Rect2(Vector2.ZERO, Vector2(MAP_SIZE, MAP_SIZE)), Color.BLACK, true)
	if _view == null or _media == null:
		return
	if _view.mode == PlayerMapDefinition.PICTURE:
		_draw_picture()
	elif _view.mode in [PlayerMapDefinition.LAND_CROP, PlayerMapDefinition.DUNGEON_CROP]:
		_draw_crop()
	else:
		return
	_draw_party_marker()

func _select_tab(tab_id: StringName) -> void:
	if tab_id == _active_tab:
		return
	_active_tab = tab_id
	tab_changed.emit(tab_id)
	_rebuild()

func _selected_character() -> CharacterView:
	for character: CharacterView in _characters:
		if character.id == _selected_character_id:
			return character
	return null

func _tab_exists(tab_id: StringName) -> bool:
	for tab: Dictionary in TABS:
		if StringName(tab["id"]) == tab_id:
			return true
	return false

func _appearance(asset_id: String, fallback_text: String, role: String) -> PanelContainer:
	var frame := PanelContainer.new()
	frame.custom_minimum_size = Vector2(68, 68)
	var texture := _textures.get(asset_id) as Texture2D
	if texture != null:
		var image := TextureRect.new()
		image.texture = texture
		image.expand_mode = TextureRect.EXPAND_IGNORE_SIZE
		image.stretch_mode = TextureRect.STRETCH_KEEP_ASPECT_CENTERED
		image.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
		image.tooltip_text = role
		frame.add_child(image)
	else:
		var fallback := _label(fallback_text if not fallback_text.is_empty() else "?", MUTED, 18)
		fallback.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER
		fallback.vertical_alignment = VERTICAL_ALIGNMENT_CENTER
		fallback.tooltip_text = "%s media unavailable." % role
		frame.add_child(fallback)
	return frame

func _add_metric_views(parent: Container, metrics: Array[CharacterMetricView]) -> void:
	var grid := GridContainer.new()
	grid.columns = 2
	grid.add_theme_constant_override("h_separation", 14)
	grid.add_theme_constant_override("v_separation", 3)
	grid.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	for metric: CharacterMetricView in metrics:
		var name_label := _label(metric.name, MUTED, 14)
		name_label.size_flags_horizontal = Control.SIZE_EXPAND_FILL
		if not metric.detail.is_empty():
			name_label.tooltip_text = metric.detail
		grid.add_child(name_label)
		var value_text := metric.detail if metric.value in [0, 1] and metric.detail in ["Yes", "No"] else "%+d" % metric.value if metric.value > 0 else str(metric.value)
		if not metric.detail.is_empty() and metric.name in ["Attacks / Round", "Movement"]:
			value_text = metric.detail
		elif metric.detail == "Permanent":
			value_text = "Permanent"
		var value_label := _label(value_text, GOOD if metric.value > 0 else BAD if metric.value < 0 else Color("e0e2e5"), 14)
		value_label.horizontal_alignment = HORIZONTAL_ALIGNMENT_RIGHT
		if not metric.detail.is_empty():
			value_label.tooltip_text = metric.detail
		grid.add_child(value_label)
	parent.add_child(grid)

func _add_heading(parent: Container, title: String, detail: String = "") -> void:
	var row := HBoxContainer.new()
	var heading := _label(title, GOLD, 18)
	heading.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	row.add_child(heading)
	if not detail.is_empty():
		var note := _label(detail, MUTED, 13)
		note.name = "HeadingDetail"
		note.size_flags_horizontal = Control.SIZE_EXPAND_FILL
		note.size_flags_stretch_ratio = 0.75
		note.horizontal_alignment = HORIZONTAL_ALIGNMENT_RIGHT
		note.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
		row.add_child(note)
	parent.add_child(row)

static func route(route_id: StringName) -> Dictionary:
	for definition: Dictionary in ROUTES:
